# ══════════════════════════════════════════════════════════════════════════════
#  WINDOWED-MODE STDIO SAFETY NET — must run before ANY print()/logging call.
#  When packaged with PyInstaller --windowed (no console), Windows gives this
#  process sys.stdout/sys.stderr = None. Every print() in this file (the
#  bootstrap banner, the startup ASCII box, ~600 status lines) would then
#  crash with AttributeError on the very first call, killing the server
#  before the HTTP listener ever binds. This is why "making it invisible"
#  broke self-hosting. Fix: redirect to a real log file instead of crashing,
#  and strip ANSI color codes so the log file is readable in Notepad rather
#  than full of "\033[38;2;..." garbage.
# ══════════════════════════════════════════════════════════════════════════════
import sys as _bsys0, os as _bos0, re as _bre0

class _AnsiStrippedFile:
    """Wraps a real file handle and strips ANSI color codes before writing,
    since a log file isn't a terminal and shouldn't contain escape codes."""
    _ANSI_RE = _bre0.compile(r"\033\[[0-9;]*m")
    def __init__(self, fh):
        self._fh = fh
    def write(self, s):
        try:
            return self._fh.write(self._ANSI_RE.sub("", s))
        except Exception:
            return 0
    def flush(self):
        try: self._fh.flush()
        except Exception: pass
    def isatty(self):
        return False

def _butler_log_file_path():
    base = _bos0.environ.get("LOCALAPPDATA") or _bos0.path.expanduser("~")
    log_dir = _bos0.path.join(base, "ButlerAI", "logs")
    _bos0.makedirs(log_dir, exist_ok=True)
    return _bos0.path.join(log_dir, "butler_server.log")

def _ensure_safe_stream(stream, shared_holder):
    """Returns a stream guaranteed to be writable. If the given stream is
    None or broken (the --windowed case), falls back to a shared log file
    so stdout and stderr don't each open their own handle."""
    try:
        if stream is None:
            raise OSError("no stream attached (windowed/noconsole build)")
        stream.write("")  # probe — some frozen builds give a fake stream that raises on write
        return stream
    except Exception:
        if shared_holder["fh"] is None:
            try:
                shared_holder["fh"] = open(_butler_log_file_path(), "a", buffering=1,
                                            encoding="utf-8", errors="replace")
            except Exception:
                shared_holder["fh"] = open(_bos0.devnull, "w")
        return _AnsiStrippedFile(shared_holder["fh"])

_BUTLER_LOG_HOLDER = {"fh": None}
_bsys0.stdout = _ensure_safe_stream(_bsys0.stdout, _BUTLER_LOG_HOLDER)
_bsys0.stderr = _ensure_safe_stream(_bsys0.stderr, _BUTLER_LOG_HOLDER)
BUTLER_LOG_PATH = _butler_log_file_path()
del _bsys0, _bos0, _bre0

# ══════════════════════════════════════════════════════════════════════════════
#  SELF-BOOTSTRAP — zero setup, works for anyone, anywhere, automatically
#  Runs before everything else. Installs missing packages, then re-launches.
# ══════════════════════════════════════════════════════════════════════════════
import sys as _sys, subprocess as _sp, os as _os

def _bootstrap():
    _CY = "\033[38;2;68;200;255m"; _GR = "\033[38;2;80;220;120m"
    _AM = "\033[38;2;255;194;68m"; _RD = "\033[38;2;255;61;92m"; _RS = "\033[0m"

    # ── Python version guard (3.8+ required) ─────────────────────────────────
    if _sys.version_info < (3, 8):
        print(f"\n{_RD}  Butler AI requires Python 3.8 or newer.{_RS}")
        print(f"  You have: Python {_sys.version.split()[0]}")
        print(f"  Download: https://www.python.org/downloads/\n")
        _sys.exit(1)

    # ── Package manifest: (import_name, pip_install_name) ────────────────────
    _PKGS = [
        ("psutil",       "psutil"),
        ("qrcode",       "qrcode[pil]"),
        ("PIL",          "Pillow"),
        ("cryptography", "cryptography"),
        ("pystray",      "pystray"),   # system tray icon for windowed/no-console builds
    ]

    _missing = []
    for _mod, _pkg in _PKGS:
        try:
            __import__(_mod)
        except ImportError:
            _missing.append((_mod, _pkg))

    if not _missing:
        return  # all packages present — nothing to do

    # ── Locate pip ───────────────────────────────────────────────────────────
    _pip = None
    for _cand in ([_sys.executable, "-m", "pip"], ["pip3"], ["pip"]):
        try:
            if _sp.run(_cand + ["--version"], capture_output=True, timeout=10).returncode == 0:
                _pip = _cand; break
        except Exception:
            continue

    if _pip is None:
        # Last resort: bootstrap pip via ensurepip (ships with CPython)
        try:
            _sp.run([_sys.executable, "-m", "ensurepip", "--upgrade"],
                    capture_output=True, timeout=30)
            _pip = [_sys.executable, "-m", "pip"]
        except Exception:
            pass

    if _pip is None:
        _pkgs_str = " ".join(p for _, p in _missing)
        print(f"\n{_AM}  Butler AI — first-time setup needed.{_RS}")
        print(f"  Missing: {', '.join(m for m, _ in _missing)}")
        print(f"  Run once:  pip install {_pkgs_str}\n")
        return  # continue anyway — server degrades gracefully for missing pkgs

    # ── Banner ────────────────────────────────────────────────────────────────
    print(f"\n{_CY}  Butler AI — first-time setup ({len(_missing)} package(s)){_RS}")
    print(f"  This only happens once on a new machine.\n")

    _failed = []
    for _mod, _pkg in _missing:
        print(f"  {_CY}▸{_RS} Installing {_pkg} ...", end="", flush=True)
        try:
            _r = _sp.run(
                _pip + ["install", "--upgrade", "--quiet", _pkg],
                capture_output=True, timeout=180,
            )
            if _r.returncode == 0:
                print(f"\r  {_GR}✓{_RS} {_pkg:<30}  installed")
            else:
                _err = (_r.stderr or b"").decode(errors="replace").strip()[:120]
                print(f"\r  {_AM}~{_RS} {_pkg:<30}  warning: {_err or 'non-zero exit'}")
                _failed.append(_pkg)
        except Exception as _e:
            print(f"\r  {_RD}✗{_RS} {_pkg:<30}  error: {_e}")
            _failed.append(_pkg)

    if _failed:
        print(f"\n  {_AM}Could not install: {', '.join(_failed)}{_RS}")
        print(f"  Server will start with reduced features — that's OK.\n")
    else:
        print(f"\n  {_GR}✓ Setup complete — launching Butler AI...{_RS}\n")
        # ── Re-exec so Python's import system sees the new packages ──────────
        # (importlib.invalidate_caches() isn't reliable cross-platform after pip)
        try:
            _os.execv(_sys.executable, [_sys.executable] + _sys.argv)
        except Exception:
            pass  # execv not available (e.g. Windows frozen exe) — just continue

_bootstrap()
del _bootstrap

import urllib.parse

# ── v9: safe urlretrieve with timeout (default 30s) ─────────────────────────
def _safe_urlretrieve(url: str, dest: str, timeout: int = 30) -> None:
    """Download *url* to *dest* with a per-request timeout.

    Uses urllib.request.urlopen(timeout=N) which is fully thread-safe — unlike
    the old socket.setdefaulttimeout() approach which was process-global and
    could corrupt concurrent downloads.  Chunked write avoids loading the entire
    file into memory for large installers.
    """
    import urllib.request as _ur_inner
    req = _ur_inner.Request(url, headers={"User-Agent": "ButlerAI/9"})
    with _ur_inner.urlopen(req, timeout=timeout) as resp:
        with open(dest, "wb") as fh:
            while True:
                chunk = resp.read(65536)
                if not chunk:
                    break
                fh.write(chunk)

