# ── LOGGING: must be defined before _load_state() ────────────────────────────
class _ColorFormatter(logging.Formatter):
    """Level-aware ANSI color formatter for a cleaner terminal."""
    _FMT = "%(asctime)s  %(levelname)-5s  %(message)s"
    _COLORS = {
        logging.DEBUG:    "\033[38;2;28;61;82m",    # dim
        logging.INFO:     "\033[38;2;120;170;200m",  # muted white
        logging.WARNING:  "\033[38;2;255;194;68m",   # amber
        logging.ERROR:    "\033[38;2;255;61;92m",    # red
        logging.CRITICAL: "\033[38;2;255;61;92m\033[1m",
    }
    _RS = "\033[0m"
    def format(self, record):
        col = self._COLORS.get(record.levelno, "")
        base = logging.Formatter(self._FMT, datefmt="%H:%M:%S").format(record)
        return f"{col}{base}{self._RS}"

_log_handler = logging.StreamHandler(sys.stdout)
_log_handler.setFormatter(_ColorFormatter())
logging.basicConfig(level=logging.INFO, handlers=[_log_handler])
log = logging.getLogger("boter")
