# ── CRASH PROTECTION ── Keeps Windows console open on fatal error
def _crash_handler(exc_type, exc_value, exc_tb):
    import traceback
    _CR = "\033[38;2;255;61;92m"   # red
    _RS = "\033[0m"
    W   = 62
    print()
    print(_CR + "╭" + "─" * W + "╮" + _RS)
    print(_CR + "│" + _RS + "  BUTLER AI SERVER  —  CRASH REPORT" + " " * (W - 36) + _CR + "│" + _RS)
    print(_CR + "├" + "─" * W + "┤" + _RS)
    traceback.print_exception(exc_type, exc_value, exc_tb)
    print(_CR + "├" + "─" * W + "┤" + _RS)
    print(_CR + "│" + _RS + "  Copy this traceback and send it to the developer." + " " * (W - 52) + _CR + "│" + _RS)
    print(_CR + "│" + _RS + "  Common fix:  pip install psutil qrcode pillow requests" + " " * (W - 56) + _CR + "│" + _RS)
    print(_CR + "╰" + "─" * W + "╯" + _RS)
    # FIX CODE-1 (audit): non-interactive (service/headless) shouldn't block 15s
    try:
        if sys.stdin and sys.stdin.isatty():
            input("\n  Press Enter to exit…")
        else:
            time.sleep(3)   # brief delay so logs can flush
    except Exception:
        time.sleep(3)
sys.excepthook = _crash_handler
