#  CHAT HISTORY FUNCTIONS
# ══════════════════════════════════════════════════════════════════

def _chat_save(device_id: str, role: str, content: str) -> None:
    """Save a chat message to history (AES-128-GCM encrypted). Auto-prunes to 200 per device."""
    # Bug 4 fix: reject invalid roles before they corrupt history
    if role not in ("user", "assistant"):
        log.warning(f"[CHAT] Ignoring invalid role in _chat_save: {role!r}")
        return
    # FIX BUG-8: normalize device_id ONCE here so both INSERT and DELETE
    # use the same value. Previously INSERT used "anon" but DELETE used raw
    # None → WHERE device_id=NULL matched nothing → 200-msg limit never enforced.
    device_id = device_id or "anon"
    try:
        stored = _enc(str(content)[:10000]) if _ENC_KEY else str(content)[:10000]
        _db_run(
            "INSERT INTO chat_history(device_id, role, content) VALUES(?,?,?)",
            (device_id, role, stored)
        )
        # Keep only last 200 messages per device — prevents unbounded growth
        _db_run(
            "DELETE FROM chat_history WHERE device_id=? AND id NOT IN "
            "(SELECT id FROM chat_history WHERE device_id=? ORDER BY id DESC LIMIT 200)",
            (device_id, device_id)
        )
    except Exception as e:
        log.debug(f"[CHAT] Save failed: {e}")

def _chat_clear(device_id: str) -> None:
    """Delete all chat history for a device."""
    try:
        _db_run("DELETE FROM chat_history WHERE device_id=?", (device_id or "anon",))
    except Exception as e:
        log.debug(f"[CHAT] Clear failed: {e}")

def _chat_history_budgeted(device_id: str,
                            limit: int = 20,
                            max_chars: int = 5000) -> list:
    """
    Bug 8 fix: Load and decrypt history respecting a character budget.
    Loads newest messages first, stops when budget is exhausted.
    Prevents context overflow on conversations with large code blocks.
    """
    try:
        rows = _db_q(
            "SELECT role, content FROM chat_history WHERE device_id=? "
            "ORDER BY id DESC LIMIT ?",
            (device_id or "anon", limit)
        )
        rows = [r for r in rows if r["role"] in ("user", "assistant")]
        kept  = []
        total = 0
        for r in rows:            # newest first
            decrypted = _dec(r["content"])
            chunk     = len(decrypted)
            # FIX H-2: Always include at least one message even if it alone exceeds budget.
            # Old code broke immediately, returning [], giving AI zero context.
            if total + chunk > max_chars and kept:
                break
            kept.append({"role": r["role"], "content": decrypted})
            total += chunk
        return list(reversed(kept))   # back to chronological order
    except Exception as e:
        log.debug(f"[CHAT] History budgeted load failed: {e}")
        return []

def _chat_clear_dedup(device_id: str) -> None:
    """Bug 5 fix: Clear dedup so the user can immediately retry after an error."""
    with _chat_dedup_lock:
        _chat_last_hash.pop(device_id, None)

# ══════════════════════════════════════════════════════════════════
# ══  v11 INTENT CLASSIFICATION ENGINE  ═══════════════════════════
# ══  Maps user message → intent category for smarter routing     ══
# ══════════════════════════════════════════════════════════════════

# Intent categories and what they mean for the AI
# greeting  : "hi", "hello", "how are you" — warm + brief reply
# casual    : chitchat, opinions, jokes — conversational, no code
# question  : factual "what is X", "how does Y work" — explain + optionally brief example
# script    : "write a script", "create automation", "python code for" — full code output
# troubleshoot: "fix", "error", "not working", "slow", "crash" — diagnostic steps + fix
# install   : "install X", "set up Y", "download Z" — step-by-step + optional winget
# explain   : "explain", "what is", "how does", "why" + complex topic — teaching mode
# general   : everything else — balanced, medium detail

_INTENT_GREETING_WORDS = {
    "hey","hi","hello","howdy","sup","yo","greetings","hiya","heya","mornin",
    "morning","evening","night","afternoon","wassup","whats up","what's up",
}
_INTENT_CASUAL_WORDS = {
    "thanks","thank","bye","goodbye","ok","okay","cool","great","nice","awesome",
    "wow","lol","haha","fine","alright","sure","good","doing","man","bro","dude",
    "buddy","friend","mate","later","cheers","np","no problem","welcome","lmk",
}
_INTENT_SCRIPT_KEYWORDS = {
    "script","automate","automation","code","write code","python","powershell",
    "batch","function","program","bot","macro","create a script","make a script",
    "generate code","write me","build me",
}
_INTENT_TROUBLESHOOT_KEYWORDS = {
    "fix","error","crash","not working","broken","issue","problem","fail","failed",
    "bsod","blue screen","slow","freezing","hang","stuck","corrupt","missing",
    "cant","can't","won't","doesn't work","not responding","restarting",
}
_INTENT_INSTALL_KEYWORDS = {
    "install","setup","set up","download","get","add","winget","chocolatey",
    "choco","uninstall","remove app","how to get",
}
_INTENT_EXPLAIN_KEYWORDS = {
    "what is","what are","explain","how does","how do","why does","why is",
    "tell me about","describe","difference between","compare","versus","vs",
}

_Q_STARTS = frozenset(("what","when","where","who","which","is","are","can","could",
                        "does","do","should","would","will","has","have"))

def _classify_intent(msg: str) -> str:
    """
    v11: Classify user message into one of 8 intent categories.
    Returns: 'greeting' | 'casual' | 'script' | 'troubleshoot' |
             'install' | 'explain' | 'question' | 'general'
    Fast O(1) keyword matching — no ML needed.
    FIX BUG-1: lru_cache removed — it was process-global and shared across all
    devices/sessions. The same message from two different devices would always
    return the cached intent from the first caller, ignoring any device-specific
    context differences. Classification is microseconds; no cache needed.
    """
    if not msg: return "general"
    low = msg.lower().strip()
    words = low.split()
    word_set = {w.strip("?!.,;:'\"") for w in words}

    # Greeting: short message with greeting words, no tech context
    if len(words) <= 8 and word_set & _INTENT_GREETING_WORDS and \
       not (word_set & _INTENT_TROUBLESHOOT_KEYWORDS) and \
       not (word_set & _INTENT_SCRIPT_KEYWORDS):
        return "greeting"

    # Pure casual (very short, no tech intent)
    if len(words) <= 5 and word_set <= (_INTENT_CASUAL_WORDS | _INTENT_GREETING_WORDS):
        return "casual"

    # Script request (explicit code/automation ask)
    if any(kw in low for kw in _INTENT_SCRIPT_KEYWORDS):
        return "script"

    # Install request
    if any(kw in low for kw in _INTENT_INSTALL_KEYWORDS):
        return "install"

    # Troubleshooting (errors, fixes)
    if any(kw in low for kw in _INTENT_TROUBLESHOOT_KEYWORDS):
        return "troubleshoot"

    # Explanation / conceptual question
    if any(kw in low for kw in _INTENT_EXPLAIN_KEYWORDS):
        return "explain"

    # Generic question — _Q_STARTS is a module-level frozenset for O(1) lookup
    # FIX: guard words[0] — all-whitespace input produces empty words list
    if low.endswith("?") or (words and words[0] in _Q_STARTS):
        return "question"

    return "general"

