# GUI state dict
_gui: dict = {}
# HEAL-13 (audit): bounded deque — O(1) trim, no pop(0) cost under heavy logging.
from collections import deque as _deque
_log_lines = _deque(maxlen=2000)
_log_lock = threading.Lock()
OLLAMA_URL     = os.environ.get("OLLAMA_URL", "http://localhost:11434")
DEFAULT_MODEL  = os.environ.get("BUTLER_MODEL", "qwen2.5-coder:1.5b")  # updated at startup by _ensure_model

# ── PERF: Persistent HTTP connection pool for Ollama (localhost) ─────────────
# Each new urllib.request.urlopen() does: DNS lookup → TCP connect → TLS (none
# here) → send → receive → close. For localhost this is ~1-3ms per call wasted.
# A persistent http.client.HTTPConnection reuses the TCP socket across calls.
# Thread-local so each worker thread gets its own connection without locking.
import http.client as _http_client
_ol_conn_local = threading.local()

def _ol_get_conn() -> _http_client.HTTPConnection:
    """Return or create a persistent thread-local HTTPConnection to Ollama."""
    conn = getattr(_ol_conn_local, "conn", None)
    if conn is None:
        host = OLLAMA_URL.replace("http://", "").split("/")[0]
        conn = _http_client.HTTPConnection(host, timeout=120)
        _ol_conn_local.conn = conn
    return conn

def _ol_post_json(path: str, payload: dict, timeout: int = 120) -> dict:
    """POST JSON to Ollama, reusing the persistent connection. Falls back to
    a fresh connection on any socket error (broken pipe, server restart, etc.)."""
    body = json.dumps(payload, separators=(',', ':')).encode()
    headers = {"Content-Type": "application/json", "Content-Length": str(len(body))}
    for attempt in range(2):
        try:
            conn = _ol_get_conn()
            conn.request("POST", path, body=body, headers=headers)
            resp = conn.getresponse()
            data = resp.read()
            if resp.status == 200:
                return json.loads(data)
            # FIX BUG-C8 (audit): HTTP-level errors must NOT trigger reconnect+retry.
            raise _http_client.HTTPException(f"Ollama {resp.status}: {data[:200]}")
        except _http_client.HTTPException:
            raise  # don't waste a round-trip reconnecting for HTTP errors
        except (ConnectionError, OSError, BrokenPipeError, _http_client.HTTPException.__bases__[0] if False else OSError):
            # Discard broken socket; next call gets a fresh one
            _ol_conn_local.conn = None
            if attempt == 0:
                continue
            raise

def _get_active_model() -> str:
    """
    Bulletproof model resolver — 5-level fallback chain.
    Never returns empty string. Always returns a usable model name.
    """
    # 1. Saved active_model — matches something actually installed
    saved = _gs("active_model")
    if saved:
        installed = _ol_models()
        if installed:
            base = saved.lower().split(":")[0]
            matched = next(
                (n for n in installed
                 if n.lower() == saved.lower() or n.lower().startswith(base)),
                None
            )
            if matched:
                if matched != saved:           # update if name drifted (e.g. tag changed)
                    _ss("active_model", matched)
                return matched
            # saved model no longer installed — clear it so we fall through
            log.info(f"[MODEL] Saved model '{saved}' not found in installed list — clearing")
            _ss("active_model", None)
        else:
            return saved   # Ollama not running yet — return saved anyway, chat will retry

    # 2. Live cache model (picked by _ol_cache_refresh)
    if _ol_ok():
        cached = _ol_model()
        if cached:
            # FIX 7: Only write state to disk if the value actually changed.
            # Previously wrote on every chat that reached this branch, hammering
            # the JSON state file under concurrent load.
            if _gs("active_model") != cached:
                _ss("active_model", cached)
            return cached

    # 3. Any installed model — lightest one
    installed = _ol_models()
    if installed:
        chosen = _select_lightest(installed)
        if chosen:
            if _gs("active_model") != chosen:  # FIX 7: only write if changed
                _ss("active_model", chosen)
            log.info(f"[MODEL] Auto-selected lightest model: {chosen}")
            return chosen

    # 4. Best model for this PC's RAM (name only — not a pull)
    try:
        preferred = _best_model_for_pc()
        if preferred:
            return preferred
    except Exception:
        pass

    # 5. Hard fallback
    return DEFAULT_MODEL
STATE_FILE     = Path.home() / ".butler_server_state_v6.json"
SECRET_FILE    = Path.home() / ".butler_server_secret_v6.bin"

IS_WINDOWS = platform.system() == "Windows"
IS_MAC     = platform.system() == "Darwin"
IS_LINUX   = platform.system() == "Linux"

def _get_desktop_path():
    """Find the real Desktop path on any OS/language."""
    # Windows: use shell API to get localized Desktop path
    if IS_WINDOWS:
        try:
            import ctypes.wintypes
            CSIDL_DESKTOP = 0
            buf = ctypes.create_unicode_buffer(ctypes.wintypes.MAX_PATH)
            ctypes.windll.shell32.SHGetFolderPathW(None, CSIDL_DESKTOP, None, 0, buf)
            if buf.value: return Path(buf.value)
        except: pass
    # Fallback: try common Desktop paths
    for name in ["Desktop", "desktop", "Schreibtisch", "Bureau", "Escritorio", "Рабочий стол"]:
        p = Path.home() / name
        if p.exists(): return p
    # Last resort: save next to the server script itself
    return Path(os.path.dirname(os.path.abspath(sys.argv[0])))

def get_downloads_dir() -> Path:
    """
    Return the real Downloads folder path for the current user on any OS/locale.
    Works on Windows (localized names via CSIDL), Linux (XDG), and macOS.
    Always creates the directory if it doesn't exist, so callers can write safely.
    """
    # Windows: CSIDL_PERSONAL→Downloads via SHGetFolderPath
    if IS_WINDOWS:
        try:
            import ctypes.wintypes
            # FIX L-5: removed pointless CSIDL_DOWNLOADS = None (immediately overwritten)
            import ctypes
            buf = ctypes.create_unicode_buffer(ctypes.wintypes.MAX_PATH)
            # 0x0033 = CSIDL_MYDOWNLOADS (unofficial but works on XP+)
            if ctypes.windll.shell32.SHGetFolderPathW(None, 0x0033, None, 0, buf) == 0:
                p = Path(buf.value)
                if p.exists(): return p
        except: pass
        # Fallback: registry key
        try:
            import winreg
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                r"Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders")
            val, _ = winreg.QueryValueEx(key, "{374DE290-123F-4565-9164-39C4925E467B}")
            winreg.CloseKey(key)
            p = Path(val)
            if p.exists(): return p
        except: pass

    # Linux: XDG user-dirs spec
    if IS_LINUX:
        try:
            import subprocess as _sp
            result = _sp.run(["xdg-user-dir", "DOWNLOAD"],
                             capture_output=True, text=True, timeout=2)
            p = Path(result.stdout.strip())
            if p.exists() and p != Path.home(): return p
        except: pass
        # Parse ~/.config/user-dirs.dirs directly
        try:
            ud = Path.home() / ".config" / "user-dirs.dirs"
            if ud.exists():
                for line in ud.read_text(errors="replace").splitlines():
                    if line.startswith("XDG_DOWNLOAD_DIR="):
                        val = line.split("=", 1)[1].strip().strip('"')
                        val = val.replace("$HOME", str(Path.home()))
                        p = Path(val)
                        if p.exists(): return p
        except: pass

    # macOS and universal fallback: ~/Downloads (most common)
    for name in ["Downloads", "downloads", "Téléchargements", "下载", "Загрузки"]:
        p = Path.home() / name
        if p.exists(): return p

    # Last resort: create ~/Downloads — safer than failing
    # FIX BUG-C1 (audit): replaced recursive self-call with concrete fallback path.
    p = Path.home() / "Downloads"
    try: p.mkdir(parents=True, exist_ok=True)
    except Exception: pass
    return p

