# ══════════════════════════════════════════════════════
#  GUARD 1: ADMIN ELEVATION
# ══════════════════════════════════════════════════════
def _is_admin():
    try:
        if IS_WINDOWS:
            import ctypes
            return bool(ctypes.windll.shell32.IsUserAnAdmin())
        return os.geteuid() == 0
    except: return False

def _check_pyautogui() -> bool:
    """Return True if pyautogui is importable (keyboard_supported capability)."""
    try:
        import pyautogui  # noqa: F401
        return True
    except ImportError:
        return False

def _elevate():
    """Request admin rights via UAC on Windows."""
    try:
        import ctypes
        script = os.path.abspath(sys.argv[0])
        params = " ".join(f'"{a}"' for a in sys.argv[1:])
        ret = ctypes.windll.shell32.ShellExecuteW(None, "runas", sys.executable, f'"{script}" {params}', None, 1)
        if ret > 32: sys.exit(0)
    except Exception as e:
        print(f"  [WARN] Admin elevation failed: {e} - continuing without admin")

if IS_WINDOWS and not _is_admin() and "--no-admin" not in sys.argv:
    print("  [INIT] Requesting admin rights for firewall & port access...")
    _elevate()

# ══════════════════════════════════════════════════════
#  REQUIREMENTS SCANNER & AUTO-INSTALLER
# ══════════════════════════════════════════════════════
REQUIRED_PACKAGES = [
    {"import": "psutil",       "pip": "psutil",        "purpose": "CPU / RAM / Disk metrics",    "critical": True},
    {"import": "qrcode",       "pip": "qrcode[pil]",   "purpose": "QR code generation",          "critical": False},
    {"import": "PIL",          "pip": "pillow",         "purpose": "QR image rendering",          "critical": False},
    {"import": "requests",     "pip": "requests",       "purpose": "Ollama HTTP client",          "critical": True},
    {"import": "cryptography", "pip": "cryptography",   "purpose": "AES-GCM field encryption",   "critical": False},
]

def _scan_requirements(verbose=False):
    """Check all required packages using importlib.util.find_spec (no import side-effects).
    Results are cached for the process lifetime so repeated calls are free."""
    if hasattr(_scan_requirements, "_cache"):
        return _scan_requirements._cache
    import importlib.util as _ilu
    results = []
    for pkg in REQUIRED_PACKAGES:
        spec = _ilu.find_spec(pkg["import"])
        if spec is not None:
            # Get version without importing the full module
            try:
                import importlib.metadata as _im
                pip_name = pkg["pip"].split("[")[0]   # strip extras e.g. qrcode[pil]
                ver = _im.version(pip_name)
            except Exception:
                ver = "installed"
            results.append({
                "package": pkg["pip"], "import": pkg["import"],
                "purpose": pkg["purpose"], "critical": pkg.get("critical", False),
                "status": "OK", "version": ver,
            })
            if verbose:
                print(f"  \033[38;2;0;232;122m✓\033[0m  {pkg['pip']:<22} {ver}")
        else:
            results.append({
                "package": pkg["pip"], "import": pkg["import"],
                "purpose": pkg["purpose"], "critical": pkg.get("critical", False),
                "status": "MISSING", "version": None,
            })
            if verbose:
                flag = "CRITICAL" if pkg.get("critical") else "optional"
                print(f"  \033[38;2;255;194;68m✗\033[0m  {pkg['pip']:<22} missing  ({flag})")
    _scan_requirements._cache = results
    return results

def _auto_install(verbose=True):
    """Install any missing required packages, then write a version-stamp lockfile
    so subsequent cold-starts skip pip entirely.

    Strategy:
      1. Fast path: lockfile present + version matches + critical imports OK → instant return.
      2. Per-package install with progress output and isolated error handling.
      3. On PermissionError fall back to --user install automatically.
    """
    _C  = "\033[38;2;0;200;245m"    # cyan
    _G  = "\033[38;2;0;232;122m"    # green
    _AM = "\033[38;2;255;194;68m"   # amber
    _RD = "\033[38;2;255;61;92m"    # red
    _MT = "\033[38;2;120;170;200m"  # muted
    _RS = "\033[0m"

    _stamp = Path(__file__).parent / ".butler_deps_ok"

    # ── Fast path ─────────────────────────────────────────────────
    try:
        if _stamp.exists() and _stamp.read_text().strip() == VERSION:
            import importlib.util as _ilu
            if all(_ilu.find_spec(p["import"]) for p in REQUIRED_PACKAGES if p.get("critical")):
                return True   # all critical packages present, stamp valid → instant boot
    except Exception:
        pass

    # ── Invalidate cache so we get fresh results ──────────────────
    if hasattr(_scan_requirements, "_cache"):
        del _scan_requirements._cache

    scan    = _scan_requirements(verbose=False)
    missing = [r for r in scan if r["status"] == "MISSING"]

    if not missing:
        try: _stamp.write_text(VERSION)
        except Exception: pass
        return True

    if verbose:
        print()
        print(f"  {_C}┄{_RS}  {_MT}Auto-installing {len(missing)} package(s)…{_RS}")

    all_ok = True
    for pkg in missing:
        # FIX v19.0.1: _scan_requirements() returns result dictionaries with
        # key "package", while REQUIRED_PACKAGES uses key "pip".  The old
        # code indexed pkg["pip"] here and crashed with KeyError before the
        # server could start whenever any package was missing.
        pkg_name = pkg.get("pip") or pkg.get("package")
        if not pkg_name:
            if verbose:
                print(f"  {_RD}✗{_RS}  dependency entry missing package name: {pkg}")
            if pkg.get("critical"):
                all_ok = False
            continue
        label   = f"{pkg_name:<22}"
        pip_cmd = [sys.executable, "-m", "pip", "install", "--quiet", pkg_name]
        try:
            r = subprocess.run(pip_cmd, capture_output=True, timeout=180)
            if r.returncode == 0:
                if verbose:
                    print(f"  {_G}✓{_RS}  {label} installed")
            else:
                # Retry with --user (handles no-admin environments)
                r2 = subprocess.run(pip_cmd + ["--user"], capture_output=True, timeout=180)
                if r2.returncode == 0:
                    if verbose:
                        print(f"  {_G}✓{_RS}  {label} installed (--user)")
                else:
                    err = (r2.stderr or r.stderr or b"").decode(errors="ignore")[:120].strip()
                    if verbose:
                        print(f"  {_RD}✗{_RS}  {label} failed — {err or 'unknown error'}")
                        print(f"       Fix: pip install {pkg_name}")
                    if pkg.get("critical"):
                        all_ok = False
        except subprocess.TimeoutExpired:
            if verbose:
                print(f"  {_AM}⚠{_RS}  {label} timed out — try: pip install {pkg_name}")
            if pkg.get("critical"):
                all_ok = False
        except Exception as e:
            if verbose:
                print(f"  {_RD}✗{_RS}  {label} error — {e}")
            if pkg.get("critical"):
                all_ok = False

    # Invalidate spec cache so re-imports work
    import importlib
    importlib.invalidate_caches()
    if hasattr(_scan_requirements, "_cache"):
        del _scan_requirements._cache

    if all_ok:
        try: _stamp.write_text(VERSION)
        except Exception: pass
        # PERF: write a separate deps-ok stamp so module-level check can skip next scan
        try:
            (Path.home() / ".butler_deps_ok").write_text(VERSION)
        except Exception: pass
        if verbose: print()
    return all_ok

# PERF: Skip _auto_install if a version-stamp file says deps are current.
# Saves a full pip importlib.find_spec scan (~50-200ms) on every restart.
_DEPS_STAMP = Path.home() / ".butler_deps_ok"
_stamp_ok = False
try:
    if _DEPS_STAMP.exists() and _DEPS_STAMP.read_text().strip() == VERSION:
        _stamp_ok = True
except Exception:
    pass
if not _stamp_ok:
    _auto_install(verbose=True)

