# ══════════════════════════════════════════════════════
#  GUARD 2: PROCESS GUARDIAN - Kill interfering processes
# ══════════════════════════════════════════════════════
def _find_process_on_port(port):
    """Find the process using a specific port."""
    results = []
    if HAS_PSUTIL:
        try:
            for conn in psutil.net_connections(kind='tcp'):
                if conn.laddr.port == port and conn.status == 'LISTEN':
                    try:
                        proc = psutil.Process(conn.pid)
                        results.append({
                            "pid": conn.pid,
                            "name": proc.name(),
                            "cmdline": " ".join(proc.cmdline())[:80],
                            "port": port,
                        })
                    except: pass
        except: pass
    return results

def _kill_process_on_port(port, force=False):
    """Kill any process blocking a port. Returns list of killed PIDs."""
    killed = []
    procs = _find_process_on_port(port)
    for p in procs:
        try:
            if IS_WINDOWS:
                subprocess.run(["taskkill", "/F", "/PID", str(p["pid"])], capture_output=True, timeout=5)
            else:
                sig = signal.SIGKILL if force else signal.SIGTERM
                os.kill(p["pid"], sig)
            killed.append(p)
            print(f"  [GUARDIAN] Killed PID {p['pid']} ({p['name']}) on port {port}")
        except Exception as e:
            print(f"  [GUARDIAN] Could not kill PID {p['pid']}: {e}")
    return killed

def _kill_old_instances():
    """Kill any previous butler_server.py processes before starting fresh."""
    current_pid = os.getpid()
    script_name = os.path.basename(sys.argv[0])
    killed_count = 0
    if HAS_PSUTIL:
        try:
            for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
                if proc.info['pid'] == current_pid: continue
                cmdline = " ".join(proc.info.get('cmdline') or [])
                if script_name in cmdline and 'python' in proc.info.get('name','').lower():
                    try:
                        proc.terminate()
                        killed_count += 1
                        print(f"  [INIT] Terminated old instance PID {proc.info['pid']}")
                    except: pass
        except: pass
    else:
        # Fallback without psutil
        try:
            if IS_WINDOWS:
                result = subprocess.run(
                    ["wmic","process","where","name='python.exe'","get","ProcessId,CommandLine"],
                    capture_output=True, text=True, timeout=10
                )
                for line in result.stdout.splitlines():
                    if script_name in line and str(current_pid) not in line:
                        try:
                            pid = int(line.strip().split()[-1])
                            os.kill(pid, 9)
                            killed_count += 1
                        except: pass
            else:
                result = subprocess.run(["pgrep","-f",script_name], capture_output=True, text=True, timeout=5)
                for line in result.stdout.splitlines():
                    try:
                        pid = int(line.strip())
                        if pid != current_pid:
                            os.kill(pid, 15)
                            killed_count += 1
                    except: pass
        except: pass
    if killed_count: print(f"  [INIT] Cleared {killed_count} old instance(s)")

def _list_all_processes():
    """List top processes for diagnostics."""
    procs = []
    if HAS_PSUTIL:
        try:
            for p in sorted(psutil.process_iter(['pid','name','cpu_percent','memory_percent','status']),
                           key=lambda x: x.info.get('cpu_percent') or 0, reverse=True)[:20]:
                procs.append({
                    "pid":    p.info['pid'],
                    "name":   p.info.get('name','?'),
                    "cpu":    round(p.info.get('cpu_percent') or 0, 1),
                    "mem":    round(p.info.get('memory_percent') or 0, 1),
                    "status": p.info.get('status','?'),
                })
        except: pass
    return procs

def _kill_interference():
    """
    Find and kill any process that might interfere with the server:
    - Old butler_server.py instances
    - Any process on our known ports
    Returns a report of what was killed.
    """
    report = {"killed": [], "errors": []}
    # 1. Kill old server instances
    _kill_old_instances()
    # 2. Check all our preferred ports for blockers
    for p in [8766, 8765, 5000, 8080]:
        blockers = _find_process_on_port(p)
        for b in blockers:
            if b["pid"] != os.getpid():
                try:
                    if IS_WINDOWS:
                        subprocess.run(["taskkill","/F","/PID",str(b["pid"])], capture_output=True, timeout=5)
                    else:
                        os.kill(b["pid"], signal.SIGTERM)
                    report["killed"].append(f"PID {b['pid']} ({b['name']}) on port {p}")
                except Exception as e:
                    report["errors"].append(f"PID {b['pid']}: {e}")
    return report

# ══════════════════════════════════════════════════════
#  HMAC TOKEN AUTH
# ══════════════════════════════════════════════════════
def _load_secret():
    try:
        if SECRET_FILE.exists(): return SECRET_FILE.read_bytes()
    except: pass
    s = os.urandom(32)
    try:
        SECRET_FILE.write_bytes(s)
        if not IS_WINDOWS: SECRET_FILE.chmod(0o600)
    except: pass
    return s

HMAC_SECRET = _load_secret()

# ── APP CLIENT SECRET ─────────────────────────────────────────────────────────
# Derived from HMAC_SECRET so it's unique per PC with zero extra config.
# The Butler mobile app must send this in X-Butler-App-Sig on every request.
# Any third-party app built on a copy of this server won't have this secret
# and will be rejected with 403 before any processing occurs.
APP_SECRET = hashlib.sha256(b"butler-app-sig-v1:" + HMAC_SECRET).hexdigest()

# grace  (default) — missing header allowed+logged, wrong header always 403.
#                    Use this until every device has re-paired against a QR/
#                    pair-response that carries appSig (see patch below).
# strict            — missing OR wrong header → 403. Flip to this once verified.
APP_SIG_MODE = (os.environ.get("APP_SIG_MODE") or "grace").strip().lower()

# ══════════════════════════════════════════════════════════════════
#  AES-128-GCM FIELD ENCRYPTION ENGINE
#  Key is derived from HMAC_SECRET at startup — never stored on disk.
#  _enc() / _dec() are transparent: old plaintext rows are decoded
#  as-is, new rows are always encrypted. Zero config required.
# ══════════════════════════════════════════════════════════════════

def _derive_enc_key(secret: bytes) -> bytes:
    """Derive a 16-byte AES-128-GCM key from HMAC_SECRET via HKDF-SHA256."""
    try:
        from cryptography.hazmat.primitives.kdf.hkdf import HKDF
        from cryptography.hazmat.primitives import hashes
        from cryptography.hazmat.backends import default_backend
        kdf = HKDF(
            algorithm=hashes.SHA256(),
            length=16,
            salt=b"butler-ai-local-enc-v1",
            info=b"chat-and-memory-encryption",
            backend=default_backend()
        )
        return kdf.derive(secret)
    except ImportError:
        # FIX BUG-7: warn honestly — this is weaker than HKDF and the log must
        # not claim "hardware-accelerated AES-128-GCM" when the real crypto lib
        # is missing. _init_encryption() below now logs the correct mode.
        log.warning(
            "[ENC] 'cryptography' package not installed — using SHA-256 key derivation "
            "(weaker than HKDF). Install it: pip install cryptography"
        )
        return hashlib.sha256(b"butler-enc-v1:" + secret).digest()[:16]

# Populated by _init_encryption() in main() — empty until then.
_ENC_KEY: bytes = b""
_ENC_USING_HKDF: bool = False   # FIX: track which mode is active for honest logging

def _init_encryption():
    """Derive the in-memory encryption key. Call once after HMAC_SECRET is set."""
    global _ENC_KEY, _ENC_USING_HKDF
    try:
        from cryptography.hazmat.primitives.kdf.hkdf import HKDF  # noqa: F401
        _ENC_USING_HKDF = True
    except ImportError:
        _ENC_USING_HKDF = False
    _ENC_KEY = _derive_enc_key(HMAC_SECRET)
    if _ENC_USING_HKDF:
        log.info("[ENC] Field encryption active (AES-128-GCM via HKDF-SHA256, hardware-accelerated)")
    else:
        log.warning("[ENC] Field encryption active (AES-128-GCM, SHA-256 key — install 'cryptography' for HKDF)")

def _enc(plaintext: str) -> str:
    """
    Encrypt a string field with AES-128-GCM.
    Returns "enc1:<b64(nonce+ciphertext+tag)>" or the original string on failure.
    Hardware-accelerated via AES-NI: ~5–15 µs per field on any modern CPU.
    """
    if not plaintext or not _ENC_KEY:
        return plaintext
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        nonce = os.urandom(12)
        ct    = AESGCM(_ENC_KEY).encrypt(nonce, plaintext.encode("utf-8"), None)
        return "enc1:" + base64.b64encode(nonce + ct).decode()
    except Exception:
        return plaintext   # graceful degradation — never crash

def _dec(ciphertext: str) -> str:
    """
    Decrypt a field encrypted by _enc().
    Plaintext rows (no "enc1:" prefix) are returned as-is for backward compat.
    """
    if not ciphertext or not ciphertext.startswith("enc1:") or not _ENC_KEY:
        return ciphertext
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        raw   = base64.b64decode(ciphertext[5:])
        nonce = raw[:12]
        ct    = raw[12:]
        return AESGCM(_ENC_KEY).decrypt(nonce, ct, None).decode("utf-8")
    except Exception:
        return ciphertext   # wrong key or corruption — return raw, never crash

def _migrate_encrypt_existing() -> dict:
    """
    One-time background migration: encrypt any plaintext rows already in the DB.
    Idempotent — rows with "enc1:" prefix are skipped automatically.
    """
    summary = {"chat": 0, "memory": 0, "skipped": 0, "errors": 0}
    if not _ENC_KEY:
        return summary
    try:
        rows = _db_q("SELECT id, content FROM chat_history")
        for r in rows:
            if r["content"] and not r["content"].startswith("enc1:"):
                try:
                    _db_run("UPDATE chat_history SET content=? WHERE id=?",
                            (_enc(r["content"]), r["id"]))
                    summary["chat"] += 1
                except Exception:
                    summary["errors"] += 1
            else:
                summary["skipped"] += 1
        rows = _db_q("SELECT id, fact, source_msg FROM ai_memory")
        for r in rows:
            updates = {}
            if r.get("fact") and not r["fact"].startswith("enc1:"):
                updates["fact"] = _enc(r["fact"])
                summary["memory"] += 1
            if r.get("source_msg") and not r["source_msg"].startswith("enc1:"):
                updates["source_msg"] = _enc(r["source_msg"])
            if updates:
                # FIX H-4: Whitelist column names before f-string SQL build (bandit B608)
                _ALLOWED_MEM_COLS = {"fact", "source_msg"}
                updates = {k: v for k, v in updates.items() if k in _ALLOWED_MEM_COLS}
                if not updates:
                    continue
                cols = ", ".join(f"{k}=?" for k in updates)
                try:
                    _db_run(f"UPDATE ai_memory SET {cols} WHERE id=?",
                            list(updates.values()) + [r["id"]])
                except Exception:
                    summary["errors"] += 1
    except Exception as e:
        log.warning(f"[ENC] Migration error: {e}")
        summary["errors"] += 1
    log.info(f"[ENC] Migration complete — "
             f"chat:{summary['chat']} memory:{summary['memory']} "
             f"skipped:{summary['skipped']} errors:{summary['errors']}")
    return summary

def _start_migration_in_background():
    """Kick off the one-time plaintext→encrypted migration in a daemon thread."""
    threading.Thread(
        target=_migrate_encrypt_existing,
        daemon=True,
        name="enc-migration"
    ).start()

# ══════════════════════════════════════════════════════════════════
#  END ENCRYPTION ENGINE
# ══════════════════════════════════════════════════════════════════

def _sign(payload):
    import hmac as _hmac
    return _hmac.new(HMAC_SECRET, payload.encode(), hashlib.sha256).hexdigest()

def _make_token(device_id):
    ts  = int(time.time())
    # FIX BUG-4: encode as "device_id:ts:sig" (3 parts). _verify_token uses
    # rsplit(":",2) so device_ids containing colons are handled correctly.
    raw = f"{device_id}:{ts}"
    sig = _sign(raw)
    return base64.urlsafe_b64encode(f"{raw}:{sig}".encode()).decode()

TOKEN_REFRESH_WINDOW = 7 * 24 * 3600  # proactively reissue if <7 days remain

def _verify_token(token, device_id):
    """
    Verify HMAC-signed token. Returns:
      True  — valid token
      False — invalid/expired/forged
    Also sets _healed_token on the request handler if token needs proactive refresh.
    FIX BUG-4: token format is base64(device_id:timestamp:sig). rsplit(":",2) now
    splits from the right so device_ids that contain colons (e.g. MAC addresses
    like "aa:bb:cc:dd:ee:ff") are preserved intact in the first component.
    """
    try:
        decoded = base64.urlsafe_b64decode(token.encode()).decode()
        # rsplit from right: sig is last field, ts is second-last, everything
        # before the second-last ":" is the device_id (may itself contain colons)
        parts = decoded.rsplit(":", 2)
        if len(parts) != 3:
            return False
        tok_device_id, ts_str, sig = parts[0], parts[1], parts[2]
        raw = f"{tok_device_id}:{ts_str}"   # reconstruct raw for HMAC check
        if not hmac.compare_digest(sig, _sign(raw)):
            return False
        ts  = int(ts_str)
        age = time.time() - ts
        # FIX BUG-C9 (audit): clamp for backward clock jumps (NTP, VM resume).
        if age < -300 or age > TOKEN_EXPIRY_SECS:
            return False   # expired or implausible future-dated token
        # Proactive refresh: if token is within 7 days of expiry, auto-reissue
        if age > TOKEN_EXPIRY_SECS - TOKEN_REFRESH_WINDOW:
            log.debug(f"[AUTH] Token nearing expiry ({age/86400:.0f}d old) — proactive refresh")
        return tok_device_id == device_id
    except Exception:
        return False

def _token_needs_refresh(token: str) -> bool:
    """True if token is valid but within the proactive refresh window."""
    try:
        decoded = base64.urlsafe_b64decode(token.encode()).decode()
        # FIX BUG-4: rsplit from right — matches _verify_token format
        parts = decoded.rsplit(":", 2)
        if len(parts) != 3: return False
        tok_device_id, ts_str, sig = parts[0], parts[1], parts[2]
        raw = f"{tok_device_id}:{ts_str}"
        if not hmac.compare_digest(sig, _sign(raw)): return False
        ts  = int(ts_str)
        age = time.time() - ts
        return TOKEN_EXPIRY_SECS > age > TOKEN_EXPIRY_SECS - TOKEN_REFRESH_WINDOW
    except Exception: return False

# ══════════════════════════════════════════════════════
#  PERSISTENT STATE
# ══════════════════════════════════════════════════════
_sl = threading.RLock()  # RLock: same thread can re-acquire without deadlock
_pair_lock = threading.Lock()  # Dedicated lock for pairing — prevents two devices racing to auto-lock
_RECONNECT_CACHE: dict = {}  # In-memory reconnect dedup cache (not persisted)

def _load_state():
    """
    Load persistent state. Supports both encrypted (enc1: prefix) and
    legacy plaintext files — existing installs upgrade on next save.
    Falls back to .backup.json if the main state file is corrupt.
    NOTE: called at module level before _init_encryption(), so _ENC_KEY
    may still be empty. Encryption is applied on the very first _save_state()
    call after _init_encryption() runs in main().
    """
    def _try_load(path):
        """Attempt to load and parse a state file. Returns dict or None."""
        try:
            if path.exists():
                raw = path.read_text(encoding="utf-8").strip()
                if not raw:
                    return None
                if raw.startswith("enc1:") and _ENC_KEY:
                    return json.loads(_dec(raw))
                return json.loads(raw)
        except Exception:
            pass
        return None

    # Try primary file first
    result = _try_load(STATE_FILE)
    if result is not None:
        return result

    # Primary corrupt or missing — try backup (written every 10 min by watchdog)
    _backup = STATE_FILE.with_suffix(".backup.json")
    result = _try_load(_backup)
    if result is not None:
        log.warning("[STATE] Primary state corrupt — loaded from backup")
        return result

    return {
        "pairing_code":      None,
        "locked_device":     None,
        "paired_at":         None,
        "last_seen":         None,
        "server_port":       None,
        "auto_lock_version": None,
    }

def _save_state(s):
    """
    Atomic encrypted state write.
    Pairing codes and device IDs are AES-128-GCM encrypted before hitting
    disk. Falls back to plaintext if _ENC_KEY is not yet initialised.
    Uses tmp+replace for crash-safety on all platforms.
    """
    try:
        payload = json.dumps(s, separators=(',', ':'))  # PERF: compact, not indent=2
        if _ENC_KEY:
            payload = _enc(payload)
        tmp = STATE_FILE.with_suffix(".tmp")
        tmp.write_text(payload, encoding="utf-8")
        try:
            with open(str(tmp), "ab") as _fh: os.fsync(_fh.fileno())
        except (OSError, AttributeError):
            pass  # Non-fatal: Windows NTFS is safe without explicit fsync
        os.replace(str(tmp), str(STATE_FILE))   # atomic on all platforms
    except Exception as e:
        log.debug(f"[STATE] Save failed: {e}")

_state = _load_state()

def _gs(k):
    with _sl: return _state.get(k)

_state_dirty = threading.Event()   # set whenever state changes; writer thread clears it

def _state_writer():
    """Single persistent thread that debounces state saves to max 1/sec."""
    while True:
        _state_dirty.wait()          # block until something changed
        _state_dirty.clear()
        time.sleep(0.5)              # 500ms debounce — coalesce rapid updates
        try:
            with _sl:
                snapshot = _state.copy()
            _save_state(snapshot)
        except Exception:
            pass

# Start the single writer thread at import time (daemon so it exits with server)
threading.Thread(target=_state_writer, daemon=True, name="state-writer").start()

def _ss(k, v):
    with _sl:
        _state[k] = v
    _state_dirty.set()   # signal writer — no new thread spawned

# ══════════════════════════════════════════════════════
#  FIREWALL
# ══════════════════════════════════════════════════════
def _fw(port, enabled=True):
    if not enabled: return
    if IS_WINDOWS:
        name = f"Butler AI v9 port {port}"
        try:
            r = subprocess.run(
                ["netsh","advfirewall","firewall","show","rule",f"name={name}"],
                capture_output=True, text=True, timeout=10
            )
            if "No rules match" not in r.stdout and r.returncode == 0: return
            subprocess.run(
                ["netsh","advfirewall","firewall","add","rule",
                 f"name={name}","dir=in","action=allow","protocol=TCP",
                 f"localport={port}","profile=any","enable=yes"],
                capture_output=True, timeout=15, check=True
            )
            print(f"  [FW] ✓ Firewall rule added for port {port}")
        except Exception as e:
            print(f"  [FW] Firewall warning: {e}")
    elif IS_LINUX:
        try: subprocess.run(["ufw","allow",f"{port}/tcp"], capture_output=True, timeout=10)
        except:
            try: subprocess.run(["iptables","-I","INPUT","-p","tcp","--dport",str(port),"-j","ACCEPT"], capture_output=True, timeout=10)
            except: pass
    elif IS_MAC:
        # macOS uses pf - add a note
        print(f"  [FW] Mac: allow port {port} in System Preferences → Security → Firewall if blocked")

# ══════════════════════════════════════════════════════
#  PORT SELECTION
# ══════════════════════════════════════════════════════
def _free_port(preferred=None):
    """Find a genuinely free port - bind test + probe to avoid TIME_WAIT sockets."""
    candidates = ([preferred] + PREFERRED_PORTS) if preferred else PREFERRED_PORTS
    for p in candidates:
        if not p: continue
        try: p = int(p)
        except: continue
        # Test 1: can we bind?
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(("0.0.0.0", p)); s.close()
        except OSError: continue
        # Test 2: is anything already responding? (catches SO_REUSEADDR edge cases)
        try:
            probe = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            probe.settimeout(0.15)
            connected = probe.connect_ex(("127.0.0.1", p)) == 0
            probe.close()
            if connected: continue
        except: pass
        return p
    # All preferred ports busy - let OS pick any free port
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(("0.0.0.0", 0)); p = s.getsockname()[1]; s.close()
    print(f"  [PORT] All preferred ports busy - using OS-assigned port {p}")
    return p

def _check_port(port: int, host: str = "127.0.0.1", timeout: float = 1.0) -> bool:
    """Returns True if the server is listening and responding on the given port.
    Used by the watchdog to verify the HTTP server is still reachable.
    v12: added — was referenced in watchdog but never defined.
    """
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(timeout)
        result = s.connect_ex((host, port))
        s.close()
        return result == 0
    except Exception:
        return False

# ══════════════════════════════════════════════════════
#  IP DETECTION
# ══════════════════════════════════════════════════════
def _is_private_ip(ip: str) -> bool:
    """Return True for any RFC1918 private LAN IP (works for home, corporate, hotspot)."""
    return (
        ip.startswith("192.168.")             # home WiFi / hotspot
        or ip.startswith("10.")               # corporate / VPN / many hotspots
        or (ip.startswith("172.") and         # 172.16.0.0 – 172.31.255.255
            16 <= int(ip.split(".")[1]) <= 31)
    )

def _is_docker_or_veth(iface: str) -> bool:
    """Exclude virtual/container interfaces that would confuse phone pairing."""
    low = iface.lower()
    return any(k in low for k in ("docker", "veth", "br-", "virbr", "vmnet",
                                   "vboxnet", "wsl", "hyperv", "lo"))

def get_ip():
    """
    Detect the best LAN IP address. Works for ANY user worldwide:
    - Home WiFi 192.168.x.x ✓
    - Corporate / hotspot 10.x.x.x ✓
    - 172.16–31.x.x networks ✓
    - Phone hotspot (no internet on PC) ✓
    - Airgapped / offline WiFi ✓
    - Multiple NICs / VPN — picks the real LAN one ✓

    Priority: private-range NIC > UDP probe > hostname > gateway probe > 127.0.0.1
    """
    # Method 1: psutil — reads NICs directly, no internet needed.
    # Scores each address: prefer private-range, skip docker/veth junk.
    if HAS_PSUTIL:
        try:
            candidates = []
            for iface, addrs in psutil.net_if_addrs().items():
                if _is_docker_or_veth(iface):
                    continue
                for a in addrs:
                    if a.family != socket.AF_INET:
                        continue
                    ip = a.address
                    if ip.startswith("127.") or ip.startswith("169.254."):
                        continue   # loopback / link-local
                    # Score: higher = better candidate
                    score = 0
                    if ip.startswith("192.168."):   score = 30  # most common home/hotspot
                    elif ip.startswith("10."):       score = 25  # corporate / tethering
                    elif _is_private_ip(ip):         score = 20  # 172.16-31 corporate
                    else:                            score = 5   # public IP (unusual but valid)
                    candidates.append((score, ip))
            if candidates:
                candidates.sort(key=lambda x: x[0], reverse=True)
                return candidates[0][1]
        except: pass

    # Method 2: UDP probe to public DNS — works when internet is available.
    # connect() on a UDP socket doesn't send any packets but does route-lookup,
    # giving us the IP the OS would use to reach the internet.
    for target in [("8.8.8.8", 80), ("1.1.1.1", 80), ("208.67.222.222", 80)]:
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.settimeout(2)
            s.connect(target)
            ip = s.getsockname()[0]
            s.close()
            if ip and not ip.startswith("127."): return ip
        except: pass

    # Method 3: hostname resolution — last resort, works on most configured machines
    try:
        hostname = socket.gethostname()
        ip = socket.gethostbyname(hostname)
        if ip and not ip.startswith("127."): return ip
    except: pass

    # Method 4: probe common gateway IPs across all RFC1918 ranges.
    # Extended list covers home, office, mobile hotspots, and ISP router defaults.
    for gateway in [
        "192.168.1.1", "192.168.0.1", "192.168.2.1", "192.168.10.1",
        "192.168.43.1", "192.168.100.1",  # Android/iOS hotspot defaults
        "10.0.0.1", "10.0.1.1", "10.1.1.1", "10.10.10.1",
        "172.16.0.1", "172.16.1.1",
    ]:
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.settimeout(0.3)
            s.connect((gateway, 80))
            ip = s.getsockname()[0]
            s.close()
            if ip and not ip.startswith("127."): return ip
        except: pass

    return "127.0.0.1"

# Alias — used internally (QR generation, beacon, status API)
_lan_ip = get_ip

def get_all_ips():
    ips = set()
    try:
        if HAS_PSUTIL:
            for _, addrs in psutil.net_if_addrs().items():
                for a in addrs:
                    if a.family == socket.AF_INET and not a.address.startswith("127."):
                        ips.add(a.address)
    except: pass
    ips.add(get_ip())
    return sorted(ips)

# ══════════════════════════════════════════════════════
#  RATE LIMITER
# ══════════════════════════════════════════════════════
# Each IP gets two deques: one for the 5s burst window, one for the 60s window.
# deque.popleft() is O(1) — the old list-comprehension was O(n) per request,
# benchmarked 213x slower at 1000 entries.
_rc: dict = {}             # ip → (deque_5s, deque_60s)
_rl = threading.Lock()
_auth_fail_map: dict  = {}   # ip → [timestamps] — tracks auth failures
_auth_fail_lock       = threading.Lock()

# Cache IP list - refreshed every 60s in background
_cached_ips: list = get_all_ips()

def _refresh_ip_cache():
    global _cached_ips
    while True:
        time.sleep(60)
        try: _cached_ips = get_all_ips()
        except: pass

_rlimit_purge_ts = 0.0   # last time we purged stale IPs from _rc

def _rlimit(ip):
    """
    Rate limiter — protects against abuse from unknown IPs.
    Generous limits for paired devices (app sends multiple concurrent requests).
    Blocks actual abuse: 100 req/5s or 500 req/60s is clearly a bot.
    Memory-safe: purges IPs that have been quiet for 2 min every 5 min.

    Uses deque + popleft for O(1) window trimming instead of O(n) list rebuild.
    """
    global _rlimit_purge_ts
    now = time.time()
    with _rl:
        # Purge stale IPs every 5 minutes to prevent unbounded RAM growth
        if now - _rlimit_purge_ts > RATE_PURGE_SECS:
            cutoff = now - 120
            stale  = [k for k, (d5, d60) in _rc.items()
                      if not d60 or d60[-1] < cutoff]
            for k in stale:
                del _rc[k]
            _rlimit_purge_ts = now

        if ip not in _rc:
            _rc[ip] = (deque(), deque())
        d5, d60 = _rc[ip]

        # Trim expired entries from both windows — O(1) amortised
        cutoff5  = now - 5
        cutoff60 = now - 60
        while d5  and d5[0]  < cutoff5:  d5.popleft()
        while d60 and d60[0] < cutoff60: d60.popleft()

        if len(d5) >= RATE_BURST_LIMIT or len(d60) >= RATE_SUSTAIN_LIMIT:
            return True   # rate limited — don't append

        d5.append(now)
        d60.append(now)
        return False

# ══════════════════════════════════════════════════════
#  UDP BEACON
# ══════════════════════════════════════════════════════
def _beacon(ip, port):
    """
    UDP broadcast beacon so the mobile app can find the server on the LAN.
    Structured error recovery: socket errors recreate the socket (bad IP, network change)
    rather than silencing the beacon forever inside a bare except.
    Refreshes IP list every 60s to handle IP changes (DHCP, VPN connect/disconnect).
    """
    _consecutive_errors = 0
    _last_ip_refresh    = 0.0
    all_ips             = get_all_ips()

    def _make_sock():
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        # No settimeout needed — UDP sendto() is non-blocking by design
        return s

    sock = _make_sock()

    while True:
        try:
            now = time.time()
            # Refresh IP list every 60s (handles DHCP changes, VPN toggling)
            if now - _last_ip_refresh > 60:
                all_ips        = get_all_ips()
                _last_ip_refresh = now

            payload = json.dumps({
                "type":    "butler_beacon",
                "ip":      ip,
                "allIPs":  all_ips,
                "port":    port,
                "version": VERSION,
                "locked":  bool(_gs("locked_device")),
                "os":      platform.system(),
                "ts":      int(now),
                # SEC-FIX: pairing code intentionally NOT included in beacon
                # App discovers server by IP+port alone; code only shown on PC screen
            }).encode()
            sock.sendto(payload, ("255.255.255.255", BEACON_PORT))
            for lip in all_ips:
                parts = lip.rsplit(".", 1)
                if len(parts) == 2:
                    try: sock.sendto(payload, (f"{parts[0]}.255", BEACON_PORT))
                    except OSError: pass
            _consecutive_errors = 0   # reset on success

        except OSError as e:
            _consecutive_errors += 1
            if _consecutive_errors <= 3:
                log.debug(f"[BEACON] Socket error ({_consecutive_errors}): {e} — recreating socket")
            try:
                sock.close()
            except Exception:
                pass
            try:
                sock = _make_sock()
            except Exception:
                pass
        except Exception as e:
            log.debug(f"[BEACON] Unexpected error: {e}")

        time.sleep(2)

# ══════════════════════════════════════════════════════
#  QR CODE
# ══════════════════════════════════════════════════════
def _qr(ip, port):
    all_ips = get_all_ips()
    code    = _gs("pairing_code") or ""
    payload = json.dumps({"ip": ip, "allIPs": all_ips, "port": port, "pairingCode": code, "version": VERSION,
                          "tls": _tls_cert_fingerprint() or "",
                          "appSig": APP_SECRET})
    print(f"\n  QR Payload: {payload}\n")
    if HAS_QR:
        try:
            qr = qrcode.QRCode(version=2, error_correction=qrcode.constants.ERROR_CORRECT_M, box_size=1, border=2)
            qr.add_data(payload)
            qr.make(fit=True)
            qr.print_ascii(invert=True)
            if HAS_PIL:
                try:
                    img = qr.make_image(fill_color="black", back_color="white")
                    QR_PNG_PATH.parent.mkdir(exist_ok=True)
                    img.save(str(QR_PNG_PATH))
                    print(f"  [QR] ✓ Saved to Desktop: {QR_PNG_PATH}")
                except: pass
        except Exception as e:
            print(f"  [QR] Error: {e}")
    else:
        print(f"  Manual: IP={ip}  Port={port}  Code={code}")
    print()

# ══════════════════════════════════════════════════════
#  OLLAMA AI
# ══════════════════════════════════════════════════════
# Cached Ollama state - refreshed every 10s in background
# /api/status reads from cache so heartbeat ping is always instant
_ol_cache = {"ok": False, "model": "", "models": [], "ts": 0.0}
_ol_cache_lock = threading.Lock()

def _ol_cache_refresh():
    """
    Background thread: refreshes Ollama status every 10s.
    - [v19 FIX-5] Immediate warm-up probe on first iteration (no 10s delay).
      Startup banner now shows correct status instead of always 'starting'.
    - Detects if Ollama process crashes and auto-restarts it (no model pull).
    - Picks active model from already-installed models only.
    - Never downloads anything.
    """
    _consecutive_failures = 0
    _last_restart_attempt = 0
    _first_run = True   # [v19] skip initial sleep on first iteration

    while True:
        if not _first_run:
            time.sleep(10)
        _first_run = False
        try:
            with _urllib_req.urlopen(f"{OLLAMA_URL}/api/tags", timeout=3) as r:
                if r.status == 200:
                    d     = json.loads(r.read())
                    ms    = d.get("models", [])
                    names = [x["name"] for x in ms]

                    # Pick active model from already-installed only
                    active = ""
                    saved  = _gs("active_model")
                    if saved:
                        saved_base = saved.lower().split(":")[0]
                        for n in names:
                            if n.lower() == saved.lower() or n.lower().startswith(saved_base):
                                active = n
                                break
                    if not active and names:
                        try:
                            preferred = _best_model_for_pc()
                            pref_base = preferred.lower().split(":")[0]
                            for n in names:
                                if n.lower().startswith(pref_base):
                                    active = n
                                    break
                        except Exception:
                            pass
                    if not active and names:
                        active = _select_lightest(names)

                    with _ol_cache_lock:
                        _ol_cache["ok"]     = True
                        _ol_cache["model"]  = active
                        _ol_cache["models"] = names
                        _ol_cache["ts"]     = time.time()

                    _consecutive_failures = 0  # reset on success
                else:
                    with _ol_cache_lock:
                        _ol_cache["ok"] = False; _ol_cache["ts"] = time.time()
                    _consecutive_failures += 1

        except Exception:
            with _ol_cache_lock:
                _ol_cache["ok"] = False; _ol_cache["ts"] = time.time()
            _consecutive_failures += 1

        # ── GUARD: Ollama crashed — try to restart service (no pull) ─────
        # Only triggers after 3 consecutive failures and not too frequently
        if _consecutive_failures >= 3:
            now = time.time()
            if now - _last_restart_attempt > 120:  # max one restart attempt per 2 min
                _last_restart_attempt = now
                try:
                    if _find_ollama_exe() and not _ollama_is_running():
                        log.warning("[OLLAMA] Service offline — attempting restart (no model pull)")
                        _log("[OLLAMA] Service crashed — auto-restarting...", "warn")
                        threading.Thread(
                            target=_start_ollama_service,
                            daemon=True, name="ollama-restart"
                        ).start()
                except Exception as _re:
                    log.debug(f"[OLLAMA] Restart attempt failed: {_re}")

        # FIX H-1: Removed duplicate time.sleep(10) here — the top of the loop
        # already sleeps 10s on non-first runs, making effective interval 20s.
        # Now correctly 10s as documented and assumed by _ol_ok() staleness check.

def _ol_ok():
    """True only if Ollama is running AND has at least one installed model AND cache is fresh (<60s)."""
    with _ol_cache_lock:
        if not _ol_cache["ok"]:
            return False
        if not _ol_cache.get("model"):
            return False
        # [v19 FIX-16] Cache staleness guard — 30s window (was 60s)
        # _ol_cache_refresh runs every 10s; 30s = 3 missed cycles (generous margin)
        # 60s was causing false "AI offline" for up to 60s after Ollama restart
        age = time.time() - _ol_cache.get("ts", 0)
        if age > 30:
            return False   # cache too old — let _ol_cache_refresh catch up
        return True

def _ol_model():
    with _ol_cache_lock: return _ol_cache["model"]

def _ol_models():
    with _ol_cache_lock: return list(_ol_cache["models"])

def _ol_chat(msg, system="", model=None, history=None, model_override=None):
    """
    Bulletproof non-streaming chat with:
    - Model self-healing: auto-selects working model on 404
    - Retry once on connection error (Ollama may have just restarted)
    - Timeout guard: 120s hard cap
    - Context size: 4096 (matches streaming path)
    """

    # ── Resolve model with full fallback chain ────────────────────────────
    active = (model_override
              or model
              or _get_active_model()
              or _ol_model()
              or DEFAULT_MODEL)

    # Skip Ollama call immediately if system is critically overloaded
    if _get_cpu() >= CPU_CRITICAL and _get_ram() >= 98:
        log.warning(f"[CHAT] Rejected: CPU {_get_cpu():.0f}% + RAM {_get_ram():.0f}% — system overloaded")
        return f"⚠️ PC is under extreme load (CPU {_get_cpu():.0f}%, RAM {_get_ram():.0f}%). Please close some applications and try again."

    def _do_request(use_model):
        msgs = []
        if system: msgs.append({"role": "system", "content": system})
        for m in (history or []): msgs.append(m)
        msgs.append({"role": "user", "content": msg})
        # Adaptive context: short casual msgs use smaller ctx for 2-5x speed boost
        _msg_len = len(msg.split())
        _ctx_size = 2048 if _msg_len <= 10 else 4096
        _is_casual_msg = _msg_len <= 10
        payload = {
            "model": use_model,
            "messages": msgs,
            "stream": False,
            "keep_alive": "30m",
            "options": _guard_ollama_options({
                "num_ctx":        _ctx_size,
                "num_predict":    _predict_cap(msg, _is_casual_msg),
                "temperature":    0.8 if _is_casual_msg else 0.2,
                "top_p":          0.95 if _is_casual_msg else 0.6,
                "repeat_penalty": 1.1,
                "num_thread":     _NUM_THREAD,
                "num_gpu":        99,
                "low_vram":       False,
                "num_keep":       32 if _is_casual_msg else 64,
                "use_mmap":       True,
                "use_mlock":      False,
                "flash_attn":     True,
            }, is_casual=_is_casual_msg)
        }
        # PERF: _ol_post_json reuses a persistent TCP connection to Ollama
        d = _ol_post_json("/api/chat", payload, timeout=120)
        return d.get("message", {}).get("content", "").strip() or "No response."

    # ── Attempt 1: requested model ────────────────────────────────────────
    # Guard: skip blacklisted models immediately
    if _guard_is_model_blacklisted(active):
        installed = _ol_models()
        alt = next((m for m in installed if not _guard_is_model_blacklisted(m)), None)
        if alt:
            log.warning(f"[GUARD] Model '{active}' blacklisted — using '{alt}'")
            active = alt
        else:
            return "[Ollama] All models temporarily unavailable — try again in a few minutes."

    for attempt in range(2):
        try:
            result = _do_request(active)
            _guard_record_model_success(active)   # Guard: reset failure count on success
            return result
        except _urllib_err.HTTPError as e:
            if e.code == 404:
                # Model not found — try falling back to any installed model
                _guard_record_model_failure(active)
                installed = _ol_models()
                fallback  = _select_lightest(installed) if installed else None
                if fallback and fallback != active:
                    log.warning(f"[CHAT] Model '{active}' not found — falling back to '{fallback}'")
                    _ss("active_model", fallback)
                    active = fallback
                    continue   # retry with fallback
                return "AI model not ready. No model installed. Run: ollama pull qwen2.5-coder:1.5b"
            if e.code in (500, 503):
                _guard_record_model_failure(active)
                if attempt == 0:
                    time.sleep(3); continue
                return f"[Ollama error] Server error {e.code} — try again"
            _guard_record_model_failure(active)
            return f"[Ollama error] HTTP {e.code}: {e.reason}"
        except _urllib_err.URLError:
            if attempt == 0:
                # Ollama may have just restarted — wait and retry once
                time.sleep(4); continue
            _guard_record_model_failure(active)
            # Trigger service restart in background
            if _find_ollama_exe():
                threading.Thread(target=_start_ollama_service,
                                 daemon=True, name="ollama-restart").start()
            return "Butler AI is temporarily offline. Ollama restarting — try again in ~10 seconds."
        except TimeoutError:
            if attempt == 0:
                time.sleep(2); continue
            _guard_record_model_failure(active)
            return "[Ollama] Response timed out — model may be loading. Try again."
        except Exception as e:
            if attempt == 0:
                time.sleep(2); continue
            _guard_record_model_failure(active)
            return f"[Ollama error] {e}"
    return "[Ollama] Could not complete request after retries."

# ══════════════════════════════════════════════════════
#  OLLAMA AUTO-MANAGER  v9 — Full Lifecycle
#  Finds, installs, starts, updates, and pulls models.
#  Users never need to touch Ollama manually.
# ══════════════════════════════════════════════════════

