# ── Ollama executable search paths (ordered: fastest finds first) ─────────────
_OLLAMA_EXE_PATHS = [
    # Windows — user-level install (most common)
    r"C:\Users\{user}\AppData\Local\Programs\Ollama\ollama.exe",
    # Windows — system-wide installs
    r"C:\Program Files\Ollama\ollama.exe",
    r"C:\Program Files (x86)\Ollama\ollama.exe",
    # Linux — official install script target
    "/usr/local/bin/ollama",
    "/usr/bin/ollama",
    "/opt/ollama/ollama",
    # macOS — Homebrew and app bundle
    "/opt/homebrew/bin/ollama",      # Apple Silicon Homebrew
    "/usr/local/bin/ollama",         # Intel Homebrew
    "/Applications/Ollama.app/Contents/MacOS/ollama",
]

# ── Version cache (GitHub API, refreshed every hour) ─────────────────────────
_OLLAMA_LATEST_CACHE: dict = {"version": "", "ts": 0.0}
_OLLAMA_LATEST_LOCK  = threading.Lock()
_OLLAMA_LATEST_TTL   = 3600   # seconds

def _find_ollama_exe() -> str:
    """Return the full path to the Ollama executable, or '' if not found."""
    import shutil as _shutil, getpass as _gp
    # PATH first — covers most custom install locations and Linux/macOS
    found = _shutil.which("ollama")
    if found:
        return found
    user = ""
    try: user = _gp.getuser()
    except Exception: pass
    for p in _OLLAMA_EXE_PATHS:
        try:
            expanded = p.format(user=user) if "{user}" in p else p
            if os.path.isfile(expanded):
                return expanded
        except Exception:
            pass
    return ""

def _ollama_is_running() -> bool:
    """Return True if the Ollama HTTP API is reachable on OLLAMA_URL."""
    try:
        with _urllib_req.urlopen(f"{OLLAMA_URL}/api/tags", timeout=2) as r:
            return r.status == 200
    except Exception:
        return False

def _get_installed_ollama_version() -> str:
    """Return the installed Ollama version string (e.g. '0.3.14'), or '' if absent."""
    exe = _find_ollama_exe()
    if not exe:
        return ""
    try:
        kw: dict = {}
        if IS_WINDOWS:
            kw["creationflags"] = subprocess.CREATE_NO_WINDOW
        r = subprocess.run(
            [exe, "--version"],
            capture_output=True, text=True, timeout=10,
            stdin=subprocess.DEVNULL, **kw
        )
        # stdout: "ollama version is 0.3.14"
        m = _RE_VERSION.search((r.stdout or "") + (r.stderr or ""))
        if m:
            return m.group(1)
    except Exception as e:
        log.debug(f"[OLLAMA] version check failed: {e}")
    return ""

def _fetch_latest_ollama_version() -> str:
    """Fetch the latest Ollama release version from GitHub. Cached for 1 hour.
    Returns version string like '0.3.14', or '' if GitHub is unreachable."""
    with _OLLAMA_LATEST_LOCK:
        now = time.time()
        if _OLLAMA_LATEST_CACHE["version"] and now - _OLLAMA_LATEST_CACHE["ts"] < _OLLAMA_LATEST_TTL:
            return _OLLAMA_LATEST_CACHE["version"]
    try:
        req = _urllib_req.Request(
            "https://api.github.com/repos/ollama/ollama/releases/latest",
            headers={"User-Agent": "ButlerAI/9",
                     "Accept":     "application/vnd.github.v3+json"}
        )
        with _urllib_req.urlopen(req, timeout=8) as r:
            tag = json.loads(r.read()).get("tag_name", "")   # e.g. "v0.3.14"
        version = tag.lstrip("v")
        if re.match(r"^\d+\.\d+\.\d+", version):
            with _OLLAMA_LATEST_LOCK:
                _OLLAMA_LATEST_CACHE["version"] = version
                _OLLAMA_LATEST_CACHE["ts"]      = time.time()
            log.debug(f"[OLLAMA] Latest release: v{version}")
            return version
    except Exception as e:
        log.debug(f"[OLLAMA] GitHub version check failed: {e}")
    return ""

def _ollama_needs_update() -> tuple:
    """Return (needs_update, installed_ver, latest_ver).
    needs_update is False when Ollama is not installed or GitHub is unreachable."""
    installed = _get_installed_ollama_version()
    if not installed:
        return False, "", ""
    latest = _fetch_latest_ollama_version()
    if not latest:
        return False, installed, ""
    try:
        def _v(s): return tuple(int(x) for x in s.split("."))
        return _v(latest) > _v(installed), installed, latest
    except Exception:
        return False, installed, latest

# ── OS-specific installers ────────────────────────────────────────────────────

def _install_ollama_windows(version: str = "") -> bool:
    """Download and silently install (or upgrade) Ollama for Windows."""
    import tempfile as _tmp
    try:
        ver = version or _fetch_latest_ollama_version()
        if ver:
            url = f"https://github.com/ollama/ollama/releases/download/v{ver}/OllamaSetup.exe"
        else:
            # Fallback: Ollama's redirect URL always points to the latest
            url = "https://ollama.com/download/OllamaSetup.exe"
            ver = "latest"

        dest = Path(_tmp.gettempdir()) / "OllamaSetup.exe"
        log.info(f"[OLLAMA] Downloading installer v{ver}: {url}")
        _log(f"[OLLAMA] Downloading Ollama v{ver} installer...", "info")
        _safe_urlretrieve(url, str(dest))

        log.info("[OLLAMA] Running silent installer...")
        _log("[OLLAMA] Installing Ollama — takes ~30 seconds...", "info")
        kw: dict = {"creationflags": subprocess.CREATE_NO_WINDOW}
        result = subprocess.run(
            [str(dest), "/SILENT", "/NORESTART"],
            timeout=300, **kw
        )
        try: dest.unlink(missing_ok=True)
        except Exception: pass

        if result.returncode in (0, 3010):   # 3010 = success, reboot optional
            log.info(f"[OLLAMA] ✓ Ollama v{ver} installed on Windows")
            _log("[OLLAMA] ✓ Ollama installed — starting service...", "info")
            return True
        log.warning(f"[OLLAMA] Installer exited with code {result.returncode}")
        return False
    except Exception as e:
        log.warning(f"[OLLAMA] Windows install failed: {e}")
        _log("[OLLAMA] Install failed — download manually: https://ollama.com", "warn")
        return False

def _install_ollama_linux(version: str = "") -> bool:
    """Install Ollama on Linux via official install script or direct binary."""
    try:
        # Method 1: official install script (recommended, handles systemd service)
        import shutil as _sh
        if _sh.which("curl"):
            log.info("[OLLAMA] Installing via official install.sh...")
            _log("[OLLAMA] Running Ollama install script...", "info")
            r = subprocess.run(
                ["bash", "-c", "curl -fsSL https://ollama.com/install.sh | sh"],
                timeout=300, text=True, capture_output=True
            )
            if r.returncode == 0:
                log.info("[OLLAMA] ✓ Ollama installed via install.sh")
                return True
            log.debug(f"[OLLAMA] install.sh stderr: {r.stderr[:300]}")
        else:
            log.debug("[OLLAMA] curl not available — using direct binary download")

        # Method 2: official manual package fallback.
        # The old GitHub URL pattern `ollama-linux-{arch}` no longer exists for
        # current releases and returns 404. Ollama's supported Linux packages are
        # published at ollama.com/download as .tar.zst archives.
        arch = "arm64" if platform.machine().lower() in ("arm64", "aarch64") else "amd64"
        pkg_url = f"https://ollama.com/download/ollama-linux-{arch}.tar.zst"
        log.info(f"[OLLAMA] Downloading official Linux package ({arch}): {pkg_url}")
        _log("[OLLAMA] Running fallback package install...", "info")
        sudo = "sudo " if os.geteuid() != 0 and _sh.which("sudo") else ""
        r = subprocess.run(
            ["bash", "-c", f"curl -fL --retry 3 --retry-delay 2 --retry-all-errors {pkg_url} | {sudo}tar x -C /usr"],
            timeout=300, text=True, capture_output=True
        )
        if r.returncode == 0:
            log.info("[OLLAMA] ✓ Ollama installed from official Linux package")
            return True
        log.warning(f"[OLLAMA] Package fallback failed: {(r.stderr or r.stdout)[:300]}")
        _log("[OLLAMA] Install manually: curl -fsSL https://ollama.com/install.sh | sh", "warn")
        return False

    except PermissionError:
        log.warning("[OLLAMA] Permission denied writing to /usr/local/bin — try sudo")
        _log("[OLLAMA] Need root: sudo python3 butler_server.py to install Ollama", "warn")
        return False
    except Exception as e:
        log.warning(f"[OLLAMA] Linux install failed: {e}")
        _log("[OLLAMA] Install failed — run: curl -fsSL https://ollama.com/install.sh | sh", "warn")
        return False

def _install_ollama_mac(version: str = "") -> bool:
    """Install Ollama on macOS via Homebrew (preferred) or direct download."""
    import shutil as _sh, tempfile as _tmp
    try:
        # Method 1: Homebrew
        brew = _sh.which("brew")
        if brew:
            log.info("[OLLAMA] Installing via Homebrew...")
            _log("[OLLAMA] Installing Ollama via Homebrew...", "info")
            r = subprocess.run(
                [brew, "install", "ollama"],
                timeout=300, text=True, capture_output=True
            )
            if r.returncode == 0:
                log.info("[OLLAMA] ✓ Ollama installed via Homebrew")
                return True
            log.debug(f"[OLLAMA] brew install failed: {r.stderr[:300]}")

        # Method 2: download .zip app bundle
        ver = version or _fetch_latest_ollama_version()
        if not ver:
            log.warning("[OLLAMA] Cannot determine version for Mac download")
            _log("[OLLAMA] Install manually: https://ollama.com/download/mac", "warn")
            return False

        url  = f"https://github.com/ollama/ollama/releases/download/v{ver}/Ollama-darwin.zip"
        dest = Path(_tmp.gettempdir()) / "Ollama-darwin.zip"
        log.info(f"[OLLAMA] Downloading Mac app v{ver}: {url}")
        _safe_urlretrieve(url, str(dest))

        subprocess.run(
            ["unzip", "-o", str(dest), "-d", "/Applications"],
            check=True, timeout=60, capture_output=True
        )
        try: dest.unlink(missing_ok=True)
        except Exception: pass

        log.info("[OLLAMA] ✓ Ollama.app installed to /Applications")
        _log("[OLLAMA] ✓ Ollama.app installed — launch from /Applications", "info")
        return True
    except Exception as e:
        log.warning(f"[OLLAMA] Mac install failed: {e}")
        _log("[OLLAMA] Install failed — download: https://ollama.com/download/mac", "warn")
        return False

def _install_ollama(version: str = "") -> bool:
    """Install Ollama for the current OS. Returns True if successful."""
    log.info(f"[OLLAMA] Auto-installing Ollama (OS={platform.system()})...")
    _log("[OLLAMA] Starting Ollama auto-install...", "info")
    if IS_WINDOWS: return _install_ollama_windows(version)
    if IS_MAC:     return _install_ollama_mac(version)
    if IS_LINUX:   return _install_ollama_linux(version)
    log.warning(f"[OLLAMA] Unsupported OS for auto-install: {platform.system()}")
    _log("Install Ollama manually: https://ollama.com", "warn")
    return False

def _upgrade_ollama() -> bool:
    """Upgrade Ollama to the latest release if one is available.
    Returns True if an upgrade was performed."""
    import shutil as _sh
    needs, installed, latest = _ollama_needs_update()
    if not needs:
        if installed:
            log.info(f"[OLLAMA] Already up to date (v{installed})")
        return False

    log.info(f"[OLLAMA] Upgrading v{installed} → v{latest}")
    _log(f"[OLLAMA] Updating Ollama {installed} → {latest}...", "info")

    ok = False
    if IS_WINDOWS:
        ok = _install_ollama_windows(latest)
    elif IS_MAC:
        brew = _sh.which("brew")
        if brew:
            try:
                r = subprocess.run([brew, "upgrade", "ollama"],
                                   timeout=300, text=True, capture_output=True)
                ok = r.returncode == 0
            except Exception:
                pass
        if not ok:
            ok = _install_ollama_mac(latest)
    elif IS_LINUX:
        ok = _install_ollama_linux(latest)

    if ok:
        log.info(f"[OLLAMA] ✓ Upgraded to v{latest}")
        _log(f"[OLLAMA] ✓ Ollama updated to v{latest}", "info")
    else:
        log.warning(f"[OLLAMA] Upgrade failed — still on v{installed}")
    return ok

# ── Service launcher ──────────────────────────────────────────────────────────

def _start_ollama_service() -> bool:
    """Start the Ollama server process. Returns True once the API is reachable."""
    if _ollama_is_running():
        return True

    exe = _find_ollama_exe()
    if not exe:
        log.warning("[OLLAMA] Executable not found — cannot start service")
        return False

    log.info(f"[OLLAMA] Starting service: {exe}")
    try:
        env = os.environ.copy()
        try:
            total_cores = os.cpu_count() or 4
            # Leave 2 cores for OS + Butler; give the rest to Ollama inference
            ollama_threads = max(2, total_cores - 2)
            env["OLLAMA_NUM_PARALLEL"] = "1"
            env.setdefault("OLLAMA_NUM_THREAD", str(ollama_threads))
            log.info(f"[OLLAMA] CPU limit: {ollama_threads}/{total_cores} threads")
        except Exception:
            pass

        kw: dict = {}
        if IS_WINDOWS:
            kw["creationflags"] = subprocess.CREATE_NO_WINDOW | subprocess.DETACHED_PROCESS
        subprocess.Popen(
            [exe, "serve"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            env=env, **kw
        )
        # [v19 FIX-9] Poll up to 30s for /api/tags HTTP readiness (not just process existence)
        # Process can be running but API not yet accepting connections (especially on first start)
        _deadline = time.time() + 30
        while time.time() < _deadline:
            time.sleep(0.5)
            try:
                with _urllib_req.urlopen(f"{OLLAMA_URL}/api/tags", timeout=2) as _r:
                    if _r.status == 200:
                        log.info("[OLLAMA] ✓ Service started and API ready")
                        _log("[OLLAMA] ✓ Service ready", "ok")
                        return True
            except Exception:
                pass   # not ready yet — keep polling
        log.warning("[OLLAMA] Process launched but /api/tags not reachable within 30s")
        _log("[OLLAMA] Service slow to start — will retry in background", "warn")
        return False
    except Exception as e:
        log.warning(f"[OLLAMA] Could not start service: {e}")
        return False

def _get_ollama_models_dir() -> Path:
    """Return the Ollama models directory; falls back to home drive."""
    import getpass
    candidates = [
        Path.home() / ".ollama" / "models",
        Path(f"C:/Users/{getpass.getuser()}/.ollama/models"),
        Path("C:/Users/Public/.ollama/models"),
    ]
    for p in candidates:
        if p.exists():
            return p
    return Path.home() / ".ollama" / "models"

def _get_disk_info() -> dict:
    """Disk usage for the Ollama models directory (and total drive stats)."""
    import shutil as _shutil
    models_dir = _get_ollama_models_dir()
    check = models_dir
    while not check.exists() and check != check.parent:
        check = check.parent
    try:
        usage    = _shutil.disk_usage(str(check))
        free_gb  = round(usage.free  / 1e9, 2)
        total_gb = round(usage.total / 1e9, 2)
        used_gb  = round(usage.used  / 1e9, 2)
    except Exception:
        free_gb = total_gb = used_gb = 0.0
    models_size_gb = 0.0
    if models_dir.exists():
        try:
            total_bytes    = sum(f.stat().st_size for f in models_dir.rglob("*") if f.is_file())
            models_size_gb = round(total_bytes / 1e9, 2)
        except Exception:
            pass
    return {
        "free_gb":            free_gb,
        "total_gb":           total_gb,
        "used_gb":            used_gb,
        "ollama_models_path": str(models_dir),
        "models_dir_size_gb": models_size_gb,
    }

def _check_disk_space_for_model(model: str) -> tuple:
    """Returns (ok: bool, free_gb: float, required_gb: float)."""
    key         = (model or "").lower().strip()
    required_gb = _MODEL_DISK_GB.get(key, _MODEL_DISK_GB_DEFAULT)
    info        = _get_disk_info()
    free_gb     = info["free_gb"]
    return (free_gb >= required_gb * 1.1), free_gb, required_gb

def _pick_best_model() -> str:
    """
    Single source of truth for which model to use.
    Delegates to _best_model_for_pc() so _ensure_model, _ol_chat,
    and the startup auto-manager all agree on the same model.
    BUTLER_MODEL env var overrides everything.
    """
    if os.environ.get("BUTLER_MODEL"):
        return os.environ["BUTLER_MODEL"]
    # Use RAM-aware selection — falls back to qwen2.5-coder:1.5b on low-RAM machines
    try:
        return _best_model_for_pc()
    except Exception:
        return "qwen2.5-coder:1.5b"

def _model_size_label(model: str) -> str:
    """Human-readable size label for every model Butler can install."""
    try:
        m = (model or "").lower()
        if "0.5b"      in m: return "0.5B · 0.5 GB"
        if "tinyllama" in m: return "1.1B · 0.6 GB"
        if "1b"        in m: return "1B   · 0.8 GB"
        if "1.5b"      in m: return "1.5B · 1.1 GB"
        if "2b"        in m: return "2B   · 1.6 GB"
        if "3b"        in m: return "3B   · 2.0 GB"
        if "phi4-mini" in m: return "3.8B · 2.5 GB"
        if "phi3"      in m: return "3.8B · 2.3 GB"
        if "7b"        in m: return "7B   · 4.7 GB"
        if "8b"        in m: return "8B   · 5.5 GB"
        if "13b"       in m: return "13B  · 8.0 GB"
        if "14b"       in m: return "14B  · 9.0 GB"
        if ":" in model:     return model.split(":")[-1].upper()
    except Exception:
        pass
    return ""

def _model_tier(model: str) -> str:
    """UI color coding: light / balanced / heavy."""
    try:
        m = (model or "").lower()
        if any(x in m for x in ("0.5b", "tinyllama", "1b:", ":1b", "1.5b")):
            return "light"
        if any(x in m for x in ("2b", "3b", "4b", "phi3", "phi4-mini")):
            return "balanced"  # [v19 FIX-22] added 4b (gemma3:4b, phi4:4b, etc.)
        if any(x in m for x in ("7b", "8b", "13b", "14b")):
            return "heavy"
    except Exception:
        pass
    return "light"   # default to light rather than "unknown"

def _cleanup_unused_models(keep_model: str):
    """
    Remove ALL Ollama models except the active one.
    [v19 FIX-10] Respects 'keep_all_models' state flag — if the user has
    manually pulled multiple models via the app, we don't delete them.
    Queries Ollama API directly (not stale cache) so it works immediately
    after a fresh pull. Saves 1–9 GB per removed model.
    """
    if not keep_model:
        return
    # [v19 FIX-10] Honour user preference: if they explicitly pulled extra models, keep them
    if _gs("keep_all_models"):
        log.info("[MODEL] keep_all_models=True — skipping cleanup (keeping all installed models)")
        return
    try:
        # Query live — cache may be up to 10s stale right after a pull
        try:
            with _urllib_req.urlopen(f"{OLLAMA_URL}/api/tags", timeout=5) as r:
                installed = [x["name"] for x in json.loads(r.read()).get("models", [])]
        except Exception:
            installed = _ol_models()   # fall back to cache if API unreachable

        if len(installed) <= 1:
            return

        keep      = keep_model.lower().strip()
        exe       = _find_ollama_exe() or "ollama"

        for m in installed:
            ml = m.lower().strip()
            # Exact match OR same base name with same tag → keep
            if ml == keep:
                continue
            # Different tag of the same base model → also remove
            # e.g. keep="qwen2.5-coder:1.5b", remove="qwen2.5-coder:7b"
            try:
                kw = {}
                if IS_WINDOWS: kw["creationflags"] = subprocess.CREATE_NO_WINDOW
                result = subprocess.run(
                    [exe, "rm", m], timeout=30, capture_output=True, **kw
                )
                if result.returncode == 0:
                    log.info(f"[MODEL] Removed: {m}")
                    _log(f"[MODEL] Removed {m} (keeping {keep_model})", "info")
                else:
                    log.warning(f"[MODEL] rm {m} returned {result.returncode}")
            except Exception as ex:
                log.warning(f"[MODEL] Could not remove {m}: {ex}")
    except Exception as ex:
        log.warning(f"[MODEL] cleanup error: {ex}")

def _ensure_model(model: str = "") -> bool:
    """Pull *model* (or the best model for this PC) if none are installed.

    This is the single entry-point for "make sure Butler has something to talk
    with".  It is called:
      • At startup by _start_ollama_auto() after the service comes up
      • By the watchdog when it detects Ollama is running but has no models
      • Never called during an active chat — _pull_bg handles explicit pulls

    Returns True if at least one model is available when this function exits.
    """
    try:
        installed = _ol_models()
        if installed:
            log.info(f"[MODEL] {len(installed)} model(s) already installed: {installed}")
            return True

        target = model or _pick_best_model()
        # [v19 FIX-17] Log the full selection rationale
        specs = _get_pc_specs()
        tier  = _choose_tier(specs)
        log.info(f"[MODEL] No models found — auto-pulling {target} "
                 f"(tier={tier}, RAM={specs['ram_free_gb']}GB free, "
                 f"GPU={specs.get('gpu_name','none') or 'none'})")
        _log(f"[MODEL] Pulling {target} for first-run setup "
             f"(tier={tier}, {specs['ram_free_gb']}GB RAM free)...", "info")

        # Disk space guard before committing to the download
        ok_space, free_gb, req_gb = _check_disk_space_for_model(target)
        if not ok_space:
            # Try the lightest possible model as a last resort
            fallback = "tinyllama:latest"
            ok2, _, _ = _check_disk_space_for_model(fallback)
            if ok2:
                log.warning(f"[MODEL] Low disk ({free_gb:.1f} GB) — falling back to {fallback}")
                _log(f"[MODEL] Low disk — pulling {fallback} instead", "warn")
                target = fallback
            else:
                log.warning(f"[MODEL] Insufficient disk: need {req_gb:.1f} GB, have {free_gb:.1f} GB")
                _log(f"[MODEL] Not enough disk space ({free_gb:.1f} GB free, need {req_gb:.1f} GB)", "warn")
                return False

        exe = _find_ollama_exe() or "ollama"
        # [v19 FIX-3] Retry pull up to 3 times with exponential backoff
        # Handles transient network errors (DNS hiccup, brief timeout, etc.)
        _pull_wait = 15   # seconds between retries (doubles each time)
        success = False
        for _attempt in range(1, 4):
            if _attempt > 1:
                log.info(f"[MODEL] Pull retry {_attempt}/3 for {target} (waiting {_pull_wait}s)...")
                _log(f"[MODEL] Pull retry {_attempt}/3 — waiting {_pull_wait}s...", "info")
                time.sleep(_pull_wait)
                _pull_wait = min(_pull_wait * 2, 120)
            success = _stream_pull(target, exe)
            if success:
                break
            log.warning(f"[MODEL] Pull attempt {_attempt} failed for {target}")

        if success:
            global _pc_best_model
            with _pc_best_lock:
                _pc_best_model = target
            _ss("active_model", target)
            _set_pull_progress(model=target, status="complete", percent=100,
                               active=False, finished_at=time.time())
            log.info(f"[MODEL] ✓ {target} ready")
            _log(f"[MODEL] ✓ {target} installed and ready", "info")
            # Clean up any duplicate models that may have been left from prior runs
            threading.Thread(target=_cleanup_unused_models, args=(target,),
                             daemon=True, name="model-cleanup").start()
            return True
        else:
            log.warning(f"[MODEL] Pull failed after 3 attempts for {target}")
            _log(f"[MODEL] Pull failed after 3 attempts — run: ollama pull {target}", "warn")
            return False
    except Exception as e:
        log.warning(f"[MODEL] _ensure_model error: {e}")
        return False

def _start_ollama_auto() -> None:
    """Full Ollama lifecycle manager — runs in a daemon thread at startup.

    Pipeline:
      1. Already running?              → ensure a model, done.
      2. Installed but not running?    → start service → ensure model.
      3. Not installed?                → install → start → ensure model.
      4. Service starts, is outdated?  → schedule background upgrade.
    Every step is logged to the activity feed so the user can see progress.
    """
    def _worker():
        try:
            # ── Step 1: Already running ───────────────────────────────────
            if _ollama_is_running():
                log.info("[OLLAMA] ✓ Service already running — checking models")
                _log("[OLLAMA] ✓ Service already running — checking models", "ok")
                _ensure_model()
                return

            # ── Step 2: Installed but stopped ─────────────────────────────
            exe = _find_ollama_exe()
            if exe:
                ver = _get_installed_ollama_version()
                log.info(f"[OLLAMA] Found v{ver or '?'} at {exe} — starting service...")
                _log(f"[OLLAMA] Starting Ollama v{ver or '?'}...", "info")

                if _start_ollama_service():
                    _ensure_model()
                    _schedule_upgrade_check()
                    return

                # [v19 FIX-4] Retry up to 3× with exponential backoff (15s→30s→60s)
                _retry_wait = 15
                for attempt in range(1, 4):
                    log.info(f"[OLLAMA] Waiting {_retry_wait}s before retry {attempt}/3...")
                    time.sleep(_retry_wait)
                    _retry_wait = min(_retry_wait * 2, 60)
                    if _ollama_is_running():
                        log.info(f"[OLLAMA] Service came online (attempt {attempt})")
                        _log(f"[OLLAMA] ✓ Service came online on retry {attempt}", "ok")
                        _ensure_model()
                        _schedule_upgrade_check()
                        return
                    if _start_ollama_service():
                        log.info(f"[OLLAMA] Started on attempt {attempt+1}")
                        _log(f"[OLLAMA] ✓ Service started on retry {attempt+1}", "ok")
                        _ensure_model()
                        _schedule_upgrade_check()
                        return

                log.warning("[OLLAMA] Installed but not responding after 3 retries")
                _log("[OLLAMA] Not responding — try: ollama serve", "warn")
                return

            # ── Step 3: Not installed — auto-install ──────────────────────
            log.info(f"[OLLAMA] Not found — starting auto-install (OS={platform.system()})")
            _log("[OLLAMA] Ollama not found — auto-installing...", "info")

            installed_ok = _install_ollama()
            if not installed_ok:
                log.warning("[OLLAMA] Auto-install failed")
                _log("[OLLAMA] Auto-install failed — download from https://ollama.com", "warn")
                return

            # Give the installer a moment to register the binary
            time.sleep(3)

            # Verify the exe is now discoverable
            exe = _find_ollama_exe()
            if not exe:
                log.warning("[OLLAMA] Installed but executable not found in PATH yet — "
                            "restart server or reopen terminal")
                _log("[OLLAMA] Restart the server after install to detect Ollama", "warn")
                return

            if _start_ollama_service():
                log.info("[OLLAMA] ✓ Service started after fresh install")
                _log("[OLLAMA] ✓ Installed and started successfully", "ok")
                _ensure_model()
            else:
                log.warning("[OLLAMA] Service didn't start after install — try restarting server")
                _log("[OLLAMA] Start failed — restart butler_server.py to retry", "warn")

        except Exception as e:
            log.warning(f"[OLLAMA] Auto-manager error: {e}")
            _log(f"[OLLAMA] Auto-manager error: {e}", "warn")

    threading.Thread(target=_worker, daemon=True, name="ollama-auto").start()

def _schedule_upgrade_check() -> None:
    """Check for an Ollama update in the background (non-blocking, low priority).
    Upgrades only happen while Ollama is idle (no active pull/chat)."""
    def _check():
        try:
            # Wait a few minutes after startup before hitting GitHub
            time.sleep(300)
            if _pull_progress.get("active"):
                return   # busy — skip this cycle
            needs, installed, latest = _ollama_needs_update()
            if needs:
                log.info(f"[OLLAMA] Update available: v{installed} → v{latest}")
                _log(f"[OLLAMA] Update available: v{installed} → v{latest} (will upgrade when idle)", "info")
                # Only upgrade if Ollama is completely idle
                if not _pull_progress.get("active") and not _ollama_busy:
                    _upgrade_ollama()
            else:
                log.debug(f"[OLLAMA] Up to date (v{installed})")
        except Exception as e:
            log.debug(f"[OLLAMA] Upgrade check error: {e}")
    threading.Thread(target=_check, daemon=True, name="ollama-upgrade-check").start()

# ══════════════════════════════════════════════════════
#  SYSTEM METRICS
# ══════════════════════════════════════════════════════
def _metrics():
    if not HAS_PSUTIL:
        return {"error": "psutil not installed", "install": "pip install psutil"}
    try:
        cpu  = psutil.cpu_percent(interval=0.3)
        mem  = psutil.virtual_memory()
        disk = psutil.disk_usage(str(Path.home()))
        nio  = psutil.net_io_counters()
        procs = []
        try:
            for p in sorted(
                psutil.process_iter(["pid","name","cpu_percent","memory_percent"]),
                key=lambda x: x.info.get("cpu_percent") or 0, reverse=True
            )[:8]:
                procs.append({
                    "name": p.info.get("name","?"),
                    "cpu":  round(p.info.get("cpu_percent") or 0, 1),
                    "mem":  round(p.info.get("memory_percent") or 0, 1),
                })
        except: pass
        # CPU frequency (may not be available on all systems)
        try:
            freq = psutil.cpu_freq()
            freq_mhz = round(freq.current, 0) if freq else 0
        except: freq_mhz = 0
        # Build response matching app's ServerMetrics TypeScript interface exactly
        return {
            "cpu":     {"percent": round(cpu, 1), "cores": psutil.cpu_count(logical=False) or 1, "logical": psutil.cpu_count(), "freq_mhz": freq_mhz},
            "memory":  {"total": mem.total, "used": mem.used, "percent": round(mem.percent, 1),
                        "total_gb": round(mem.total / (1024**3), 1), "used_gb": round(mem.used / (1024**3), 1)},
            "ram":     {"total": mem.total, "used": mem.used, "percent": round(mem.percent, 1),
                        "total_gb": round(mem.total / (1024**3), 1), "used_gb": round(mem.used / (1024**3), 1)},
            "disk":    {"total": disk.total, "used": disk.used, "free": disk.free, "percent": round(disk.percent, 1),
                        "total_gb": round(disk.total / (1024**3), 1), "used_gb": round(disk.used / (1024**3), 1), "free_gb": round(disk.free / (1024**3), 1)},
            "network": {"bytes_sent": nio.bytes_sent, "bytes_recv": nio.bytes_recv,
                        "bytes_sent_mb": round(nio.bytes_sent / (1024**2), 1), "bytes_recv_mb": round(nio.bytes_recv / (1024**2), 1)},
            "system":  {"os": f"{platform.system()} {platform.release()}", "hostname": socket.gethostname(),
                        "uptime_hrs": round((time.time() - psutil.boot_time()) / 3600, 1), "python_version": platform.python_version()},
            "processes": {"total": len(procs), "top": procs},
            # Flat aliases for backward compatibility
            "uptime":  int(time.time() - psutil.boot_time()),
            "hostname": socket.gethostname(),
            "os":      f"{platform.system()} {platform.release()}",
        }
    except Exception as e:
        return {"error": str(e)}

# ══════════════════════════════════════════════════════
#  LOGGING (GUI-aware)
# ══════════════════════════════════════════════════════
# NOTE: logging.basicConfig and 'log' are already configured at the top of the file.
# Do NOT re-initialize here — it would clobber handlers and cause duplicate log lines.

def _log(msg, tag="info"):
    with _log_lock:
        _log_lines.append((tag, msg))   # deque(maxlen=2000) auto-trims
    _refresh_log()
    if tag == "ok":    log.info(msg)
    elif tag in ("warn", "warning"): log.warning(msg)
    elif tag in ("err", "error"):    log.error(msg)
    elif tag == "guard":
        log.warning(msg)
        try: _nb_record_guard_trigger()   # count for Rules Engine
        except Exception: pass
    elif tag == "heal":  log.info(msg)
    else: log.info(msg)

# ══════════════════════════════════════════════════════
#  KNOWLEDGE BASE (SQLite)
# ══════════════════════════════════════════════════════
_db_lock  = threading.Lock()
_db_local = threading.local()   # PERF: one persistent connection per thread

# ── PERF: Pre-compiled regex patterns (compiled once at startup, reused everywhere) ──
_RE_SCRIPT_ID     = re.compile(r'[^a-zA-Z0-9_\-]')
_RE_FILENAME_SAFE = re.compile(r'[^A-Za-z0-9_.-]')
_RE_WHITESPACE    = re.compile(r'\s+')
_RE_STEPS         = re.compile(r'^\s*(\d+[.)]\s|\*\s|-\s)', re.MULTILINE)
_RE_PY_BLOCKS     = re.compile(r'```python\s*\n(.*?)```', re.DOTALL)
_RE_IMPORTS       = re.compile(r'^(?:import|from) (\w+)', re.MULTILINE)
_RE_PCT           = re.compile(r'(\d{1,3})%')
_RE_DL_SIZE       = re.compile(r'([\d.]+)\s*(GB|MB|KB)\s*/\s*([\d.]+)\s*(GB|MB|KB)', re.I)
_RE_DL_SPEED      = re.compile(r'([\d.]+)\s*(GB|MB|KB)/s', re.I)
_RE_VERSION       = re.compile(r'(\d+\.\d+\.\d+)')
_RE_PKG_NAME      = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9._-]*[A-Za-z0-9])?(\[[\w,]+\])?([><=!]=?[\w.]+)?$')

# Per-language script size limits — module-level so they're not rebuilt on every request
_SCRIPT_LIMITS: dict = {
    "python":     100_000,
    "powershell": 200_000,
    "bash":       200_000,
    "sh":         200_000,
    "cmd":        200_000,
    "batch":      200_000,
}

def _db_get_conn() -> sqlite3.Connection:
    """Return a cached, WAL-mode connection for this thread.
    Creates it on first call; reuses it on every subsequent call.
    PRAGMAs are set once — not on every query like before."""
    conn = getattr(_db_local, "conn", None)
    if conn is None:
        conn = sqlite3.connect(str(DB_PATH), timeout=10, check_same_thread=False)
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA synchronous=NORMAL")
        conn.execute("PRAGMA cache_size=10000")   # ~40 MB page cache
        conn.execute("PRAGMA temp_store=MEMORY")
        conn.row_factory = sqlite3.Row
        _db_local.conn = conn
        _db_register_conn(conn)   # Fix: register for orphan sweeper
    return conn

def _db_invalidate_conn():
    """Discard the thread-local connection (used after corruption detection)."""
    try:
        c = getattr(_db_local, "conn", None)
        if c:
            try: c.close()
            except: pass
    finally:
        _db_local.conn = None

# Fix: orphaned thread-local connection sweeper — on long-running servers, dead
# threads leave SQLite connections open in their thread-local storage.  Python will
# eventually GC them, but that is non-deterministic.  This sweeper runs every 5 min
# and closes connections whose threads are no longer alive.
_db_thread_registry: dict = {}   # thread ident → (thread_obj, conn)
_db_registry_lock = threading.Lock()

def _db_register_conn(conn: sqlite3.Connection):
    """Register the current thread's DB connection so the sweeper can track it."""
    t = threading.current_thread()
    with _db_registry_lock:
        _db_thread_registry[t.ident] = (t, conn)

def _db_sweep_orphaned_conns():
    """Close DB connections whose threads are no longer alive."""
    with _db_registry_lock:
        dead = [ident for ident, (t, _) in _db_thread_registry.items() if not t.is_alive()]
        for ident in dead:
            _, conn = _db_thread_registry.pop(ident)
            try:
                conn.close()
                log.debug(f"[DB] Closed orphaned connection from dead thread {ident}")
            except Exception:
                pass

def _db_sweep_loop():
    """Background sweeper: close orphaned thread-local DB connections every 5 min."""
    while True:
        time.sleep(300)
        try:
            _db_sweep_orphaned_conns()
        except Exception as _se:
            log.debug(f"[DB] Sweep error: {_se}")

def _db_init():
    with _db_lock:
        c = sqlite3.connect(str(DB_PATH))
        try:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS knowledge_base(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                url TEXT UNIQUE,
                title TEXT,
                category TEXT DEFAULT 'General',
                clean_text TEXT,
                keywords TEXT DEFAULT '[]',
                word_count INTEGER DEFAULT 0,
                crawled_at REAL DEFAULT 0);

            CREATE TABLE IF NOT EXISTS chat_history(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                device_id TEXT,
                role TEXT,
                content TEXT,
                ts REAL DEFAULT(strftime('%s','now')));  -- [v19 FIX-21] strftime('%s') works on SQLite 3.37+ unlike unixepoch()

            -- Persistent learning queue: survives restarts, resumes where left off
            CREATE TABLE IF NOT EXISTS learn_queue(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                url TEXT UNIQUE,
                category TEXT DEFAULT 'General',
                keywords TEXT DEFAULT '[]',
                priority INTEGER DEFAULT 5,
                source TEXT DEFAULT 'auto',
                added_at REAL DEFAULT 0,
                status TEXT DEFAULT 'pending',
                attempts INTEGER DEFAULT 0,
                last_attempt REAL DEFAULT 0);

            -- Learning checkpoint: stats saved every 15 min for resume
            CREATE TABLE IF NOT EXISTS learn_checkpoint(
                id INTEGER PRIMARY KEY DEFAULT 1,
                articles_total INTEGER DEFAULT 0,
                articles_session INTEGER DEFAULT 0,
                last_save REAL DEFAULT 0,
                last_url TEXT DEFAULT '',
                queue_size INTEGER DEFAULT 0,
                session_start REAL DEFAULT 0,
                uptime_mins REAL DEFAULT 0);

            -- User topics extracted from chat - learning personalization
            CREATE TABLE IF NOT EXISTS user_topics(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                topic TEXT UNIQUE,
                asks INTEGER DEFAULT 1,
                last_asked REAL DEFAULT 0,
                kb_coverage INTEGER DEFAULT 0);

            CREATE INDEX IF NOT EXISTS idx_kb_url      ON knowledge_base(url);
            CREATE INDEX IF NOT EXISTS idx_lq_status   ON learn_queue(status, priority DESC);
            CREATE INDEX IF NOT EXISTS idx_ut_topic    ON user_topics(asks DESC);
            CREATE INDEX IF NOT EXISTS idx_ch_device   ON chat_history(device_id, id DESC);
        """)
            # WAL mode: allows readers to proceed while writer is active
            # ── ΣNET GROWTH LOG — proprietary growth tracking for graph ──
            c.execute("""
                CREATE TABLE IF NOT EXISTS sigma_growth_log(
                    id         INTEGER PRIMARY KEY AUTOINCREMENT,
                    ts         REAL NOT NULL,
                    total      INTEGER NOT NULL,
                    added      INTEGER DEFAULT 0,
                    category   TEXT DEFAULT 'mixed',
                    source     TEXT DEFAULT 'SIGMA-NET'
                )
            """)
            c.execute("CREATE INDEX IF NOT EXISTS idx_sgl_ts ON sigma_growth_log(ts)")
            # ── ΣNET CATEGORY STATS — fast lookup per category ────────
            c.execute("""
                CREATE TABLE IF NOT EXISTS sigma_category_stats(
                    category   TEXT PRIMARY KEY,
                    count      INTEGER DEFAULT 0,
                    last_added REAL DEFAULT 0
                );
            """)
            # Add new columns if upgrading from old schema
            for col_sql in [
                "ALTER TABLE learn_queue ADD COLUMN worker_id INTEGER DEFAULT 0",
                "ALTER TABLE learn_queue ADD COLUMN started_at REAL DEFAULT 0",
                "ALTER TABLE learn_queue ADD COLUMN finished_at REAL DEFAULT 0",
            ]:
                try: c.execute(col_sql)
                except sqlite3.OperationalError: pass  # column already exists
            # ── UNDO JOURNAL ──
            c.execute("""CREATE TABLE IF NOT EXISTS undo_journal(
                id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, expires_at REAL,
                script TEXT, language TEXT DEFAULT 'python', user_req TEXT DEFAULT '',
                snapshot TEXT DEFAULT '{}', output TEXT DEFAULT '', status TEXT DEFAULT 'pending',
                undone INTEGER DEFAULT 0)""")
            try: _butler_purge_old_sessions(14)
            except Exception: pass
            c.execute("""CREATE TABLE IF NOT EXISTS pc_stats(
                key TEXT PRIMARY KEY, value REAL DEFAULT 0)""")
            for _k in ("files_cleaned","space_recovered_bytes","files_organized",
                        "duplicates_found","scripts_run","scripts_undone","threats_blocked"):
                c.execute("INSERT OR IGNORE INTO pc_stats(key,value) VALUES(?,0)", (_k,))
            c.execute("""CREATE TABLE IF NOT EXISTS pc_stats_log(
                ts REAL, key TEXT, value REAL DEFAULT 0)""")
            # Trick 18: per-device chat stats (upserted after every chat)
            c.execute("""
                CREATE TABLE IF NOT EXISTS chat_stats(
                    device_id   TEXT PRIMARY KEY,
                    total_msgs  INTEGER DEFAULT 0,
                    total_ms    INTEGER DEFAULT 0,
                    avg_ms      REAL    DEFAULT 0,
                    last_msg_ts REAL    DEFAULT 0,
                    errors      INTEGER DEFAULT 0
                )
            """)
            # ── AI PERMANENT MEMORY — survives restarts ───────────────────────
            # Butler learns facts about users from conversations and remembers them forever.
            # Facts are auto-extracted, stored per-device, and injected into system prompts.
            # fact_hash: deterministic SHA-256[:32] of the plaintext fact — used as the
            # dedup key so ON CONFLICT works even when `fact` is AES-GCM encrypted.
            c.execute("""CREATE TABLE IF NOT EXISTS ai_memory(
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                device_id   TEXT    NOT NULL DEFAULT 'anon',
                category    TEXT    NOT NULL DEFAULT 'general',
                fact        TEXT    NOT NULL,
                fact_hash   TEXT    NOT NULL DEFAULT '',
                confidence  REAL    DEFAULT 1.0,
                source_msg  TEXT    DEFAULT '',
                created_at  REAL    DEFAULT 0,
                last_seen   REAL    DEFAULT 0,
                times_seen  INTEGER DEFAULT 1
            )""")
            c.execute("CREATE INDEX IF NOT EXISTS idx_mem_device ON ai_memory(device_id, category)")
            # Unique index on (device_id, fact_hash) — stable even when fact is encrypted
            try:
                c.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_mem_fact_hash ON ai_memory(device_id, fact_hash)")
            except Exception: pass
            # Keep the old plaintext index for backward compat (will be a no-op on new DBs)
            try:
                c.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_mem_fact ON ai_memory(device_id, fact)")
            except Exception: pass
            # Add fact_hash column to existing DBs that don't have it yet
            try:
                c.execute("ALTER TABLE ai_memory ADD COLUMN fact_hash TEXT NOT NULL DEFAULT ''")
            except Exception: pass  # column already exists — ignore
            # ── SCRIPT FEEDBACK — tracks run outcomes for AI learning ─────────
            # When a script succeeds or fails, the result is recorded here.
            # Butler checks this table when generating new scripts — avoiding
            # patterns that have failed before and favouring patterns that worked.
            c.execute("""CREATE TABLE IF NOT EXISTS script_feedback(
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                device_id   TEXT    DEFAULT 'anon',
                user_req    TEXT    DEFAULT '',
                script_hash TEXT    NOT NULL,          -- sha256[:16] of script text
                script_snip TEXT    DEFAULT '',        -- first 300 chars for context
                language    TEXT    DEFAULT 'python',
                exit_code   INTEGER DEFAULT -1,
                output_snip TEXT    DEFAULT '',        -- first 500 chars of output/error
                ran_at      REAL    DEFAULT 0,
                success     INTEGER DEFAULT 0          -- 1 = success, 0 = failure
            )""")
            c.execute("CREATE INDEX IF NOT EXISTS idx_sf_hash ON script_feedback(script_hash)")
            c.execute("CREATE INDEX IF NOT EXISTS idx_sf_req  ON script_feedback(user_req)")
            # ── USER SCRIPTS — AI-generated scripts saved from chat or builder ─
            # Created here so /api/scripts/list never crashes on first launch
            c.execute("""CREATE TABLE IF NOT EXISTS user_scripts(
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                name        TEXT    NOT NULL,
                category    TEXT    DEFAULT 'Custom',
                language    TEXT    DEFAULT 'python',
                description TEXT    DEFAULT '',
                code        TEXT    NOT NULL,
                created_at  REAL    DEFAULT 0
            )""")
            c.execute("CREATE INDEX IF NOT EXISTS idx_us_cat ON user_scripts(category)")
            # Commit schema, apply PRAGMAs, then close this temp connection.
            # Thread-local connections created later by _db_get_conn() will
            # inherit WAL mode automatically (it's per-file, not per-connection).
            c.commit()
            c.execute("PRAGMA journal_mode=WAL")
            c.execute("PRAGMA synchronous=NORMAL")
            c.execute("PRAGMA cache_size=10000")
            c.execute("PRAGMA temp_store=MEMORY")
            c.execute("PRAGMA journal_size_limit=67108864")  # Fix: cap WAL at 64 MB — prevents checkpoint starvation from filling disk
        finally:
            c.close()
        # Invalidate any existing thread-local connections so they reopen in WAL mode
        _db_invalidate_conn()
    # v19.0.19: run provenance + compression migration (idempotent, safe on every boot)
    try: _kb_migrate_provenance()
    except Exception as _me: log.debug(f"[KB-MIGRATE] {_me}")

# ══════════════════════════════════════════════════════════════════
#  AI PERMANENT MEMORY — Local, private, persists across restarts
#  Butler learns facts from chat and remembers them forever.
#  No cloud. All data stays in the SQLite DB on the user's PC.
# ══════════════════════════════════════════════════════════════════

def _memory_save(device_id: str, category: str, fact: str, source_msg: str = "") -> None:
    """
    Upsert a memory fact (AES-128-GCM encrypted at rest).
    Because AES-GCM uses a random nonce, identical plaintexts produce different
    ciphertexts — the UNIQUE index on `fact` cannot dedup them. We work around
    this by using a deterministic SHA-256 hash of the plaintext as the conflict
    key stored alongside the encrypted blob.
    """
    if not fact or len(fact) < 5 or len(fact) > 300:
        return
    try:
        now       = time.time()
        plain     = fact.strip()
        enc_fact  = _enc(plain)            if _ENC_KEY else plain
        enc_src   = _enc(source_msg[:200]) if _ENC_KEY else source_msg[:200]
        # SHA-256 of the plaintext used as the stable dedup key
        fact_hash = hashlib.sha256(plain.lower().encode("utf-8")).hexdigest()[:32]

        # Upsert on (device_id, fact_hash) instead of (device_id, fact)
        _db_run(
            """INSERT INTO ai_memory
               (device_id, category, fact, source_msg, created_at, last_seen, times_seen, fact_hash)
               VALUES(?, ?, ?, ?, ?, ?, 1, ?)
               ON CONFLICT(device_id, fact_hash)
               DO UPDATE SET last_seen=excluded.last_seen,
                             times_seen=times_seen+1,
                             category=excluded.category,
                             fact=excluded.fact""",
            (device_id or "anon", category, enc_fact, enc_src, now, now, fact_hash)
        )
    except Exception as e:
        log.debug(f"[MEMORY] Save failed: {e}")

def _memory_load(device_id: str, max_facts: int = 12) -> list:
    """Load and decrypt top remembered facts for a device, sorted by recency and frequency.
    Returns full fields needed by the Memory Manager UI (id, times_seen, last_seen, created_at).
    """
    try:
        rows = _db_q(
            """SELECT id, category, fact, times_seen, last_seen, created_at FROM ai_memory
               WHERE device_id=?
               ORDER BY (times_seen * 0.6 + (last_seen / 1e9) * 0.4) DESC
               LIMIT ?""",
            (device_id or "anon", max_facts)
        )
        return [{
            "id":         r["id"],
            "category":   r["category"],
            "fact":       _dec(r["fact"]),
            "times_seen": r["times_seen"],
            "last_seen":  r["last_seen"],
            "created_at": r["created_at"],
        } for r in rows]
    except Exception:
        return []

def _memory_forget(device_id: str, fact_fragment: str = "") -> int:
    """Delete memories for a device. If fact_fragment given, delete only matching facts."""
    try:
        if fact_fragment:
            rows = _db_q(
                "DELETE FROM ai_memory WHERE device_id=? AND fact LIKE ? RETURNING id",
                (device_id or "anon", f"%{fact_fragment}%")
            )
            return len(rows)
        else:
            _db_run("DELETE FROM ai_memory WHERE device_id=?", (device_id or "anon",))
            return -1
    except Exception:
        return 0

def _memory_extract_and_save(device_id: str, user_msg: str, ai_reply: str) -> None:
    """
    Parse user message AND AI reply for memorable facts and save them.
    Runs in a background thread — never blocks the chat response.

    v12 additions:
    - More life-pattern categories: job, location, language, hobby, family
    - Extract facts AI learned from the conversation (from its own replies)
    - Dedup check: skip saving if identical fact already exists

    Categories detected:
      name        — user's name
      preference  — likes/dislikes/preferences
      hardware    — their PC specs/hardware
      goal        — what they're trying to achieve long-term
      context     — general useful facts (OS, location, job, etc.)
      job         — profession/role
      location    — city/country they mention
      language    — programming languages they use
      hobby       — hobbies and interests
      family      — family context (kids, partner)
    """
    try:
        msg_lower = user_msg.lower()
        facts_to_save = []

        # ── NAME detection ─────────────────────────────────────────────────
        name_patterns = [
            r"(?:my name is|i'm|i am|call me|they call me)\s+([A-Z][a-z]{1,20})",
            r"(?:name's)\s+([A-Z][a-z]{1,20})",
        ]
        for pat in name_patterns:
            m = re.search(pat, user_msg, re.IGNORECASE)
            if m:
                facts_to_save.append(("name", f"User's name is {m.group(1).capitalize()}"))
                break

        # ── HARDWARE / PC SPECS ────────────────────────────────────────────
        hw_patterns = [
            (r"i (?:have|own|use|run|got)\s+(?:a\s+)?([A-Za-z0-9 ]{4,40}(?:gpu|cpu|rtx|gtx|rx\s*\d|ryzen|intel|amd|nvidia|geforce|radeon)[A-Za-z0-9 ]{0,30})",
             "hardware", "User has {}"),
            (r"my (?:pc|computer|machine|rig|setup) (?:has|is|runs?|uses?)\s+(.{5,60})",
             "hardware", "User's PC has {}"),
            (r"(\d+)\s*(?:gb|gigs?)\s*(?:of\s+)?(?:ram|memory|vram)",
             "hardware", "User has {} RAM"),
            (r"windows\s+(\d+)",
             "hardware", "User runs Windows {}"),
            (r"(?:running|using|on)\s+(ubuntu|debian|fedora|arch|manjaro|mint|pop[_\s]?os)",
             "hardware", "User runs {} Linux"),
            (r"(?:macbook|mac\s+(?:mini|pro|air|studio))",
             "hardware", "User has a Mac"),
        ]
        for pat, cat, fmt in hw_patterns:
            m = re.search(pat, user_msg, re.IGNORECASE)
            if m:
                facts_to_save.append((cat, fmt.format(m.group(1).strip())))

        # ── PREFERENCES ────────────────────────────────────────────────────
        pref_patterns = [
            r"i (?:prefer|like|love|hate|dislike|always|never)\s+(.{5,60})",
            r"i(?:'m| am) (?:a |an )?(.{5,50})\s+(?:user|person|developer|gamer|fan)",
        ]
        for pat in pref_patterns:
            m = re.search(pat, msg_lower)
            if m:
                facts_to_save.append(("preference", f"User {user_msg[m.start():m.end()].strip()[:120]}"))
                break

        # ── GOALS ──────────────────────────────────────────────────────────
        goal_patterns = [
            r"i(?:'m| am) (?:trying to|working on|building|making|creating|learning)\s+(.{5,80})",
            r"i want to\s+(.{5,80})",
            r"i need (?:to|a|an)\s+(.{5,80})",
            r"i(?:'m| am) (?:developing|designing|writing|coding)\s+(.{5,80})",
        ]
        for pat in goal_patterns:
            m = re.search(pat, msg_lower)
            if m:
                snippet = user_msg[m.start():m.end()].strip()[:150]
                if len(snippet) > 15:
                    facts_to_save.append(("goal", snippet))
                break

        # ── JOB / PROFESSION ───────────────────────────────────────────────
        job_patterns = [
            r"i(?:'m| am) (?:a |an )?(\w+\s+(?:engineer|developer|analyst|manager|designer|architect|admin|technician|consultant|scientist))",
            r"i work (?:at|for|as)\s+(.{4,50})",
            r"my (?:job|role|position|title) is\s+(.{4,50})",
        ]
        for pat in job_patterns:
            m = re.search(pat, msg_lower)
            if m:
                facts_to_save.append(("job", f"User's job: {user_msg[m.start():m.end()].strip()[:100]}"))
                break

        # ── LOCATION ───────────────────────────────────────────────────────
        loc_patterns = [
            r"i(?:'m| am| live)? (?:based in|from|in|located in)\s+([A-Z][a-z]{2,20}(?:\s+[A-Z][a-z]{2,20})?)",
        ]
        for pat in loc_patterns:
            m = re.search(pat, user_msg, re.IGNORECASE)
            if m:
                place = m.group(1).strip().title()
                if len(place) > 3 and place not in ("The", "And", "For", "But"):
                    facts_to_save.append(("location", f"User is located in {place}"))
                break

        # ── PROGRAMMING LANGUAGES ──────────────────────────────────────────
        lang_keywords = {
            "python": "Python", "javascript": "JavaScript", "typescript": "TypeScript",
            "rust": "Rust", "go": "Go", "java": "Java", "c#": "C#", "c++": "C++",
            "php": "PHP", "ruby": "Ruby", "swift": "Swift", "kotlin": "Kotlin",
            "react": "React", "vue": "Vue", "angular": "Angular",
        }
        for kw, display in lang_keywords.items():
            if kw in msg_lower and any(p in msg_lower for p in ("using", "write", "code", "script", "work with", "develop")):
                facts_to_save.append(("language", f"User uses {display}"))
                break  # one language per message to avoid noise

        # ── HOBBY / INTEREST ───────────────────────────────────────────────
        hobby_keywords = [
            ("gaming",       "User is a gamer"),
            ("game",         "User is a gamer"),
            ("3d printing",  "User does 3D printing"),
            ("homelab",      "User runs a homelab"),
            ("home lab",     "User runs a homelab"),
            ("raspberry pi", "User uses Raspberry Pi"),
            ("arduino",      "User uses Arduino"),
            ("streaming",    "User streams content"),
            ("photography",  "User is into photography"),
            ("music",        "User is interested in music"),
            ("crypto",       "User is interested in crypto"),
            ("trading",      "User does trading/investing"),
        ]
        for kw, fact in hobby_keywords:
            if kw in msg_lower:
                facts_to_save.append(("hobby", fact))
                break

        # ── GENERAL CONTEXT ────────────────────────────────────────────────
        if "developer" in msg_lower or "programmer" in msg_lower or "coder" in msg_lower:
            facts_to_save.append(("context", "User is a developer/programmer"))
        if "gamer" in msg_lower or "gaming" in msg_lower:
            facts_to_save.append(("context", "User is a gamer"))
        if "student" in msg_lower:
            facts_to_save.append(("context", "User is a student"))
        if "small business" in msg_lower or "my business" in msg_lower or "my company" in msg_lower:
            facts_to_save.append(("context", "User runs a business"))

        # ── FAMILY CONTEXT ─────────────────────────────────────────────────
        if "my kids" in msg_lower or "my children" in msg_lower or "my son" in msg_lower or "my daughter" in msg_lower:
            facts_to_save.append(("family", "User has children"))
        if "my wife" in msg_lower or "my husband" in msg_lower or "my partner" in msg_lower or "my spouse" in msg_lower:
            facts_to_save.append(("family", "User has a partner/spouse"))

        # ── EXTRACT FROM AI REPLY (v12 new) ────────────────────────────────
        # When AI confirms facts it learned ("I see you're using...", "Since you're on Windows..."),
        # save those as confirmed context too
        if ai_reply and len(ai_reply) > 20:
            ai_context_patterns = [
                (r"(?:you(?:'re| are) (?:using|running|on))\s+([A-Za-z0-9 ]{3,30})", "context"),
                (r"(?:since you(?:'re| are) (?:a|an))\s+([A-Za-z0-9 ]{3,30})", "context"),
                (r"(?:as a|being a|given you(?:'re| are) a)\s+([A-Za-z0-9 ]{3,30})", "context"),
            ]
            for pat, cat in ai_context_patterns:
                m = re.search(pat, ai_reply, re.IGNORECASE)
                if m:
                    snippet = m.group(1).strip()[:80]
                    if len(snippet) > 5 and snippet.lower() not in ("user", "person", "developer"):
                        facts_to_save.append((cat, f"AI confirmed: {snippet}"))
                    break  # one AI-extracted fact per reply

        for category, fact in facts_to_save:
            _memory_save(device_id, category, fact, user_msg[:100])

        if facts_to_save:
            log.debug(f"[MEMORY] Saved {len(facts_to_save)} facts for device={device_id}")

    except Exception as e:
        log.debug(f"[MEMORY] Extract failed: {e}")

def _memory_build_context(device_id: str) -> str:
    """Build a concise memory block to inject into the system prompt."""
    facts = _memory_load(device_id, max_facts=10)
    if not facts:
        return ""
    lines = [f"  • [{f['category'].upper()}] {f['fact']}" for f in facts]
    return (
        "\n\n[BUTLER MEMORY — What I remember about this user]\n"
        + "\n".join(lines)
        + "\nUse this context naturally in responses. Don't announce that you're using memory."
    )

def _db_q(sql, p=()):
    """Query the DB and return rows as a list of dicts. Read-only safe.
    PERF: uses a persistent thread-local connection; PRAGMAs set once at connect time.
    FIX H-3: Removed global _db_lock from reads — WAL mode allows concurrent readers.
    Lock is kept only in _db_run() for writes to avoid write-write races."""
    for attempt in range(4):
        try:
            c = _db_get_conn()
            rows = c.execute(sql, p).fetchall()
            return [dict(r) for r in rows]
        except sqlite3.OperationalError as e:
            if "locked" in str(e) and attempt < 3: time.sleep(0.15 * (attempt+1)); continue
            break
        except sqlite3.DatabaseError as db_err:
            if "not a database" in str(db_err).lower() or "malformed" in str(db_err).lower():
                log.warning(f"[DB] Corrupt DB detected — reinitializing: {db_err}")
                with _db_lock: _db_invalidate_conn()
                try: _db_init()
                except: pass
            break
        except Exception as _e: log.debug(f"[DB] Unexpected error: {_e}"); break
    return []

def _db_run(sql, p=()):
    """Execute a write statement.
    PERF: uses a persistent thread-local connection; no open/PRAGMA/close overhead."""
    for attempt in range(4):
        try:
            with _db_lock:
                c = _db_get_conn()
                c.execute(sql, p); c.commit(); return
        except sqlite3.OperationalError as e:
            if "locked" in str(e) and attempt < 3: time.sleep(0.15 * (attempt+1)); continue
            break
        except Exception as _e: log.debug(f"[DB] Unexpected error: {_e}"); break

def _syntax_check_python(code: str) -> dict:
    """
    Run ast.parse() on a Python code block.
    Returns {"ok": True} or {"ok": False, "error": "SyntaxError: ...", "line": N}.
    Fast — no subprocess, no exec, pure compile check.
    """
    try:
        import ast as _ast
        _ast.parse(code)
        return {"ok": True}
    except SyntaxError as e:
        return {"ok": False, "error": f"SyntaxError: {e.msg}", "line": e.lineno or 0}
    except Exception as e:
        return {"ok": False, "error": str(e), "line": 0}

def _extract_python_blocks(text: str) -> list:
    """Extract all ```python ... ``` code blocks from an AI reply."""
    import re as _re
    return _re.findall(r"```python\s*\n(.*?)```", text, _re.DOTALL)

def _script_feedback_save(device_id: str, user_req: str, script: str,
                           language: str, exit_code: int, output: str) -> None:
    """Record a script run outcome in script_feedback for AI learning.
    Call this after every /api/execute result — success or failure.
    Butler's chat handler queries this table to avoid known-bad patterns."""
    try:
        import hashlib as _hlib
        h = _hlib.sha256(script.encode("utf-8", errors="ignore")).hexdigest()[:16]
        _db_run(
            """INSERT INTO script_feedback
               (device_id, user_req, script_hash, script_snip, language,
                exit_code, output_snip, ran_at, success)
               VALUES(?,?,?,?,?,?,?,?,?)""",
            (
                device_id or "anon",
                (user_req or "")[:200],
                h,
                script[:300],
                language,
                exit_code,
                output[:500],
                time.time(),
                1 if exit_code == 0 else 0,
            )
        )
    except Exception as _e:
        log.debug(f"[FEEDBACK] Save failed: {_e}")

# KB quality thresholds
_KB_MIN_WORDS    = 40    # reject pages with fewer words (nav/404/login pages)
_KB_MAX_TEXT     = 12000 # char cap stored per article (prevents DB bloat)

# ── v19.0.19: Provenance + compression infrastructure ────────────────────
# Permissive licenses we accept for SEED persistence. Crawled content from
# unknown sources is still saved (tagged "unknown") for ordinary user-driven
# crawls — only the SEEDER refuses unknown/copyrighted sources.
_PERMISSIVE_LICENSES = {
    "PSF", "MIT", "BSD", "Apache-2.0", "CC-BY-4.0", "CC-BY-SA-3.0", "CC-BY-SA-4.0",
    "CC0", "GFDL", "PostgreSQL", "public-domain", "OPL", "GPL-docs",
}
_DOMAIN_LICENSE = {
    "docs.python.org":               "PSF",
    "peps.python.org":               "PSF",
    "developer.mozilla.org":         "CC-BY-SA-4.0",
    "learn.microsoft.com":           "CC-BY-4.0",   # MS Learn content reusable under CC-BY-4.0
    "docs.microsoft.com":            "CC-BY-4.0",
    "wiki.archlinux.org":            "GFDL",
    "tldp.org":                      "OPL",
    "man7.org":                      "GPL-docs",
    "nodejs.org":                    "MIT",
    "www.sqlite.org":                "public-domain",
    "sqlite.org":                    "public-domain",
    "www.postgresql.org":            "PostgreSQL",
    "postgresql.org":                "PostgreSQL",
    "cheatsheetseries.owasp.org":    "CC-BY-SA-4.0",
    "owasp.org":                     "CC-BY-SA-4.0",
    "datatracker.ietf.org":          "public-domain",  # RFCs are freely redistributable
    "docs.docker.com":               "Apache-2.0",
    "kubernetes.io":                 "CC-BY-4.0",
    "github.com":                    "unknown",       # per-repo varies — caller can override
    "stackoverflow.com":             "CC-BY-SA-4.0",  # user contribs CC-BY-SA
}

def _infer_license(url: str):
    """Return (license_tag, permissive_bool). Defaults to ('unknown', False)."""
    try:
        host = ""
        try:
            from urllib.parse import urlparse
            host = (urlparse(url).hostname or "").lower()
        except Exception:
            host = url.split("/")[2].split(":")[0].lower() if "/" in url else ""
        tag = _DOMAIN_LICENSE.get(host, "unknown")
        return tag, (tag in _PERMISSIVE_LICENSES)
    except Exception:
        return "unknown", False

def _kb_migrate_provenance():
    """
    Idempotent schema migration: add provenance + compression columns and
    helpful indexes. Wrapped per-statement so partial success is safe.
    """
    stmts = [
        "ALTER TABLE knowledge_base ADD COLUMN license_tag TEXT DEFAULT 'unknown'",
        "ALTER TABLE knowledge_base ADD COLUMN source_type TEXT DEFAULT 'crawl'",
        "ALTER TABLE knowledge_base ADD COLUMN content_z BLOB",
        "ALTER TABLE knowledge_base ADD COLUMN content_full_len INTEGER DEFAULT 0",
        "CREATE INDEX IF NOT EXISTS idx_kb_keywords    ON knowledge_base(keywords)",
        "CREATE INDEX IF NOT EXISTS idx_kb_category    ON knowledge_base(category)",
        "CREATE INDEX IF NOT EXISTS idx_kb_crawled_at  ON knowledge_base(crawled_at)",
        "CREATE INDEX IF NOT EXISTS idx_kb_license     ON knowledge_base(license_tag)",
        "CREATE INDEX IF NOT EXISTS idx_kb_source_type ON knowledge_base(source_type)",
    ]
    for s in stmts:
        try: _db_run(s)
        except Exception: pass  # column/index already exists or older sqlite — fine

# zlib compression helpers — store full body in content_z, keep clean_text as
# a fast search/snippet preview. Saves typically 60-75% on doc pages.
import zlib as _zlib
_KB_COMPRESS_THRESHOLD = 4000  # chars

def _kb_pack(text: str):
    """Return (preview_text, compressed_blob_or_None, original_len)."""
    if not isinstance(text, str): text = str(text or "")
    n = len(text)
    if n <= _KB_COMPRESS_THRESHOLD:
        return text[:_KB_MAX_TEXT], None, n
    try:
        blob = _zlib.compress(text.encode("utf-8", errors="replace"), 6)
        # keep first ~6000 chars in clean_text for LIKE-based search/snippet
        preview = text[:6000]
        return preview, blob, n
    except Exception:
        return text[:_KB_MAX_TEXT], None, n

def _kb_unpack(row) -> str:
    """Return the full article text for a KB row — decompresses if needed."""
    try:
        if not row: return ""
        blob = row.get("content_z") if hasattr(row, "get") else None
        if blob:
            try: return _zlib.decompress(blob).decode("utf-8", errors="replace")
            except Exception: pass
        return (row.get("clean_text") if hasattr(row, "get") else "") or ""
    except Exception:
        return ""

def _kb_save(url, title, text, cat="General", kw=None, source_type: str = "crawl"):
    """
    Save article to KB with quality gate + provenance tagging + compression.
    v19.0.19: rejects unknown-license sources only when source_type starts with
    'public-seed' (ordinary crawls remain tagged 'unknown' but persisted).
    Returns True if saved, False if rejected.
    """
    words = len(text.split())
    # Quality gate: reject pages that are clearly useless
    if words < _KB_MIN_WORDS:
        log.debug(f"[KB] Rejected (too short, {words} words): {url[:50]}")
        return False
    # Reject obvious boilerplate/error pages
    ltext = text.lower()
    if any(p in ltext[:300] for p in ["404 not found","page not found","access denied",
           "403 forbidden","you are being redirected","enable javascript","cookies must"]):
        log.debug(f"[KB] Rejected (boilerplate): {url[:50]}")
        return False
    # Provenance: infer license, enforce permissive-only for seed writes
    try:
        license_tag, permissive = _infer_license(url)
    except Exception:
        license_tag, permissive = "unknown", False
    if isinstance(source_type, str) and source_type.startswith("public-seed") and not permissive:
        log.debug(f"[KB] Rejected (seed requires permissive license, got {license_tag}): {url[:60]}")
        return False
    preview, blob, orig_len = _kb_pack(text)
    try:
        _db_run(
            """INSERT INTO knowledge_base
               (url,title,category,clean_text,keywords,word_count,crawled_at,
                license_tag,source_type,content_z,content_full_len)
               VALUES(?,?,?,?,?,?,?,?,?,?,?)
               ON CONFLICT(url) DO UPDATE SET
               title=excluded.title, clean_text=excluded.clean_text,
               word_count=excluded.word_count, crawled_at=excluded.crawled_at,
               license_tag=excluded.license_tag, source_type=excluded.source_type,
               content_z=excluded.content_z, content_full_len=excluded.content_full_len""",
            (url, title, cat, preview, json.dumps(kw or []),
             words, time.time(),
             license_tag, source_type or "crawl", blob, orig_len)
        )
    except Exception:
        # Fallback for pre-migration schemas — keep core save working
        _db_run(
            """INSERT INTO knowledge_base
               (url,title,category,clean_text,keywords,word_count,crawled_at)
               VALUES(?,?,?,?,?,?,?)
               ON CONFLICT(url) DO UPDATE SET
               title=excluded.title, clean_text=excluded.clean_text,
               word_count=excluded.word_count, crawled_at=excluded.crawled_at""",
            (url, title, cat, preview, json.dumps(kw or []), words, time.time())
        )
    return True

# ── v19.0.20: KB export/import (versioned, persists across deployments) ──
_KB_DUMP_SCHEMA_VERSION = 2  # bump whenever the row shape changes

def _kb_export_dict() -> dict:
    """Return a portable, versioned snapshot of the knowledge_base table."""
    rows_out = []
    try:
        try:
            rows = _db_q(
                "SELECT url,title,category,clean_text,keywords,word_count,crawled_at,"
                "       license_tag,source_type,content_z,content_full_len "
                "FROM knowledge_base"
            )
        except Exception:
            rows = _db_q("SELECT url,title,category,clean_text,keywords,word_count,crawled_at FROM knowledge_base")
        for r in rows:
            d = {
                "url":         r.get("url"),
                "title":       r.get("title"),
                "category":    r.get("category"),
                "clean_text":  r.get("clean_text"),
                "keywords":    r.get("keywords"),
                "word_count":  r.get("word_count"),
                "crawled_at":  r.get("crawled_at"),
                "license_tag": r.get("license_tag"),
                "source_type": r.get("source_type"),
                "content_full_len": r.get("content_full_len"),
            }
            cz = r.get("content_z")
            if cz:
                try: d["content_z_b64"] = base64.b64encode(cz).decode("ascii")
                except Exception: pass
            rows_out.append(d)
    except Exception as _e:
        try: log.debug(f"[kb/export] guarded: {_e}")
        except Exception: pass
    return {
        "schemaVersion": _KB_DUMP_SCHEMA_VERSION,
        "serverVersion": VERSION,
        "exportedAt":    int(time.time()),
        "rowCount":      len(rows_out),
        "rows":          rows_out,
    }

def _kb_import_dict(dump, mode: str = "merge") -> dict:
    """Restore from a dump produced by _kb_export_dict.
       mode='merge' upserts by URL; 'replace' wipes the table first."""
    if not isinstance(dump, dict): raise ValueError("dump must be a JSON object")
    schema = int(dump.get("schemaVersion") or 0)
    if schema and schema > _KB_DUMP_SCHEMA_VERSION:
        raise ValueError(f"dump schemaVersion {schema} newer than server ({_KB_DUMP_SCHEMA_VERSION})")
    rows = dump.get("rows") or []
    if not isinstance(rows, list): raise ValueError("dump.rows must be a list")
    imported = skipped = errors = 0
    if mode == "replace":
        try: _db_run("DELETE FROM knowledge_base")
        except Exception: pass
    for r in rows:
        try:
            if not isinstance(r, dict): skipped += 1; continue
            url = r.get("url");  title = r.get("title") or ""
            if not (isinstance(url, str) and url.startswith(("http://","https://"))):
                skipped += 1; continue
            kw_raw = r.get("keywords")
            kw_str = kw_raw if isinstance(kw_raw, str) else json.dumps(kw_raw or [])
            blob = None
            if r.get("content_z_b64"):
                try: blob = base64.b64decode(r["content_z_b64"])
                except Exception: blob = None
            try:
                _db_run(
                    """INSERT INTO knowledge_base
                       (url,title,category,clean_text,keywords,word_count,crawled_at,
                        license_tag,source_type,content_z,content_full_len)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?)
                       ON CONFLICT(url) DO UPDATE SET
                       title=excluded.title, clean_text=excluded.clean_text,
                       word_count=excluded.word_count, crawled_at=excluded.crawled_at,
                       license_tag=excluded.license_tag, source_type=excluded.source_type,
                       content_z=excluded.content_z, content_full_len=excluded.content_full_len""",
                    (url, title, r.get("category") or "General",
                     r.get("clean_text") or "", kw_str,
                     int(r.get("word_count") or 0),
                     float(r.get("crawled_at") or time.time()),
                     r.get("license_tag") or "unknown",
                     r.get("source_type") or "import",
                     blob, int(r.get("content_full_len") or 0))
                )
            except Exception:
                _db_run(
                    """INSERT INTO knowledge_base
                       (url,title,category,clean_text,keywords,word_count,crawled_at)
                       VALUES(?,?,?,?,?,?,?)
                       ON CONFLICT(url) DO UPDATE SET
                       title=excluded.title, clean_text=excluded.clean_text,
                       word_count=excluded.word_count, crawled_at=excluded.crawled_at""",
                    (url, title, r.get("category") or "General",
                     r.get("clean_text") or "", kw_str,
                     int(r.get("word_count") or 0),
                     float(r.get("crawled_at") or time.time()))
                )
            imported += 1
        except Exception:
            errors += 1
    return {"imported": imported, "skipped": skipped, "errors": errors,
            "schemaVersion": schema or _KB_DUMP_SCHEMA_VERSION,
            "totalAfter":    _kb_count(force=True)}


_KB_SEARCH_CACHE: dict = {}
_KB_SEARCH_CACHE_TTL = 300         # 5 minutes — KB changes slowly
_KB_SEARCH_CACHE_MAX = 256
_KB_SEARCH_CACHE_LOCK = threading.Lock()
_KB_SEARCH_CACHE_STATS = {"hits": 0, "misses": 0, "sets": 0, "evicted": 0,
                          "started_at": time.time()}

def _kb_cache_get(q: str, limit: int):
    try:
        k = f"{(q or '').lower().strip()}|{int(limit)}"
        with _KB_SEARCH_CACHE_LOCK:
            entry = _KB_SEARCH_CACHE.get(k)
        if entry and (time.time() - entry[0] < _KB_SEARCH_CACHE_TTL):
            try: _KB_SEARCH_CACHE_STATS["hits"] += 1
            except Exception: pass
            return list(entry[1])
        try: _KB_SEARCH_CACHE_STATS["misses"] += 1
        except Exception: pass
    except Exception: pass
    return None

def _kb_cache_set(q: str, limit: int, results: list):
    try:
        k = f"{(q or '').lower().strip()}|{int(limit)}"
        with _KB_SEARCH_CACHE_LOCK:
            if len(_KB_SEARCH_CACHE) >= _KB_SEARCH_CACHE_MAX:
                try:
                    drop = sorted(_KB_SEARCH_CACHE.items(), key=lambda kv: kv[1][0])[:16]
                    for kk, _ in drop: _KB_SEARCH_CACHE.pop(kk, None)
                    _KB_SEARCH_CACHE_STATS["evicted"] += len(drop)
                except Exception:
                    _KB_SEARCH_CACHE.clear()
            _KB_SEARCH_CACHE[k] = (time.time(), list(results))
        try: _KB_SEARCH_CACHE_STATS["sets"] += 1
        except Exception: pass
    except Exception: pass

def _kb_cache_invalidate():
    """Called when KB is mutated (import, contribute, crawl save) so callers
    never get stale results."""
    try:
        with _KB_SEARCH_CACHE_LOCK:
            _KB_SEARCH_CACHE.clear()
    except Exception: pass

def _kb_search(q, limit=8):
    """
    Multi-signal KB search: title match > keyword match > text match.
    Returns most relevant articles first.
    v19.0.16: bulletproof — never raises, always returns a list.
    v19.0.20: per-query cache (TTL=300s) — repeats are free.
    """
    try:
        # v19.0.21: fuzz/sanitize + loop guard (defined later — guarded so
        # early-boot callers before helper definition still work)
        try: _qs = _kb_fuzz_check(q)
        except Exception: _qs = (q if isinstance(q, str) else "").strip()
        if not _qs: return []
        try:
            if not _loop_guard_check("kb_search"): return []
        except Exception: pass
        q = _qs
        try: limit = max(1, min(int(limit), 50))
        except Exception: limit = 8
        # cache short-circuit
        _c = _kb_cache_get(q, limit)
        if _c is not None: return _c
        words = [w for w in q.lower().split() if len(w) > 2][:8]
        if not words: return []
        _out = _kb_search_impl(q, limit, words) or []
        if _out: _kb_cache_set(q, limit, _out)
        return _out
    except Exception as _kbe:
        try: log.debug(f"[kb] guarded fallback: {_kbe}")
        except Exception: pass
        return []

def _kb_search_impl(q, limit, words):
    seen   = {}   # url → score
    rows_d = {}   # url → row dict

    # Score each article by number of matching keywords
    # v19.0.19: also pull provenance + compressed body (best-effort — old DBs
    # without these columns silently fall back via the except branch).
    _select_new = ("SELECT title, url, clean_text, category, crawled_at, "
                   "       license_tag, source_type, content_z, content_full_len "
                   "FROM knowledge_base "
                   "WHERE lower(clean_text) LIKE ? OR lower(title) LIKE ? LIMIT ?")
    _select_old = ("SELECT title, url, clean_text, category, crawled_at "
                   "FROM knowledge_base "
                   "WHERE lower(clean_text) LIKE ? OR lower(title) LIKE ? LIMIT ?")
    for w in words:
        try:
            rows = _db_q(_select_new, (f"%{w}%", f"%{w}%", limit * 3))
        except Exception:
            rows = _db_q(_select_old, (f"%{w}%", f"%{w}%", limit * 3))
        for r in rows:
            url = r["url"]
            seen[url]   = seen.get(url, 0) + 1
            rows_d[url] = r

    # Sort by score (keyword overlap + recency boost), trim, format.
    _now = time.time()
    def _recency_bonus(r):
        try:
            ts = r.get("crawled_at")
            if isinstance(ts, (int, float)):
                age_days = (_now - float(ts)) / 86400.0
                if age_days <= 7:  return 2
                if age_days <= 30: return 1
        except Exception:
            pass
        return 0
    sorted_urls = sorted(seen, key=lambda u: seen[u] + _recency_bonus(rows_d[u]), reverse=True)[:limit]
    out = []
    for url in sorted_urls:
        r = rows_d[url]
        # Prefer the full (decompressed) body for snippets when available
        try: full = _kb_unpack(r)
        except Exception: full = r.get("clean_text", "") or ""
        text = full or (r.get("clean_text") or "")
        r.pop("clean_text", None)
        r.pop("content_z", None)  # never leak raw blob to JSON
        r["snippet"]   = text[:1500] + ("…" if len(text) > 1500 else "")
        r["relevance"] = round((seen[url] + _recency_bonus(r)) / max(len(words), 1), 2)
        out.append(r)
    return out

