    {"id": "tcp_traceroute", "name": "TCP Traceroute", "category": "Tools", "description": "Trace the network path to a host using TCP (bypasses ICMP-blocking firewalls).", "tags": ["tools", "network", "traceroute", "tcp", "debug"], "icon": "route", "code": "import socket, time, struct, select\nhost = input('Target host [8.8.8.8]: ').strip() or '8.8.8.8'\ntry:\n    dest_ip = socket.gethostbyname(host)\nexcept Exception as e:\n    print(f'DNS resolve failed: {e}'); raise SystemExit\nprint(f'TCP Traceroute to {host} ({dest_ip}):\\n')\nfor ttl in range(1, 31):\n    for _ in range(3):\n        sender = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n        sender.setsockopt(socket.IPPROTO_IP, socket.IP_TTL, struct.pack('I', ttl))\n        sender.settimeout(1)\n        t0 = time.time()\n        try:\n            sender.connect((dest_ip, 80))\n            rtt = (time.time()-t0)*1000\n            print(f'  {ttl:2}  {dest_ip}  {rtt:.1f}ms  [REACHED]')\n            sender.close()\n            raise SystemExit\n        except socket.timeout:\n            print(f'  {ttl:2}  *  timeout')\n        except OSError as e:\n            hop = str(e)\n            rtt = (time.time()-t0)*1000\n            print(f'  {ttl:2}  {rtt:.1f}ms  {hop[:60]}')\n        finally:\n            sender.close()\n        break\n"},
