# ══════════════════════════════════════════════════════════════════════
#  BUTLER AI — DIGITAL TWIN SECURITY ENGINE  v1.0
#  • Snapshots the full PC state at baseline
#  • Monitors continuously for drift (processes, ports, registry, files)
#  • Alerts phone via push notification on any anomaly
#  • Phone Proximity Lock: locks PC when paired phone goes silent
# ══════════════════════════════════════════════════════════════════════

import hashlib as _ht_hashlib
import struct  as _ht_struct

# ── TWIN STATE ────────────────────────────────────────────────────────
_TWIN_LOCK        = threading.Lock()
_TWIN_BASELINE    : dict = {}          # Saved baseline snapshot
_TWIN_ALERTS      : list = []          # Ring buffer of recent alerts (max 200)
_TWIN_ENABLED     : bool = False       # Master on/off (persisted in state)
_TWIN_ALERT_COUNT : int  = 0           # Total alerts since last baseline

# ── PROXIMITY LOCK STATE ──────────────────────────────────────────────
_PROX_LOCK           = threading.Lock()
_PROX_ENABLED        : bool  = False    # Master on/off
_PROX_LAST_SEEN      : float = 0.0     # epoch of last phone heartbeat
_PROX_TIMEOUT_SEC    : int   = 60      # seconds of silence → lock PC
_PROX_LOCKED_BY_PROX : bool  = False   # True if WE locked the PC


# ── HELPERS ───────────────────────────────────────────────────────────

def _twin_send_alert(category: str, severity: str, title: str, detail: str) -> None:
    """Push a security alert to phone + local ring buffer. Fire-and-forget."""
    global _TWIN_ALERT_COUNT
    entry = {
        "ts":       time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "category": category,
        "severity": severity,   # "LOW" | "MEDIUM" | "HIGH" | "CRITICAL"
        "title":    title,
        "detail":   detail[:400],
    }
    with _TWIN_LOCK:
        _TWIN_ALERTS.append(entry)
        if len(_TWIN_ALERTS) > 200:
            _TWIN_ALERTS.pop(0)
        _TWIN_ALERT_COUNT += 1

    # Log locally
    log.warning(f"[TWIN-ALERT] [{severity}] {title}: {detail[:120]}")

    # Push to phone via Expo push (best-effort, non-blocking)
    def _push():
        try:
            rows = _db_q("SELECT token FROM push_tokens LIMIT 1")
            if not rows:
                return
            token = rows[0]["token"]
            ICONS = {"LOW": "🔵", "MEDIUM": "🟡", "HIGH": "🔴", "CRITICAL": "🚨"}
            icon  = ICONS.get(severity, "🔔")
            payload = json.dumps({
                "to":    token,
                "title": f"{icon} Butler Security: {title}",
                "body":  detail[:100],
                "data":  {"category": category, "severity": severity},
                "sound": "default",
                "priority": "high",
            }).encode()
            req = _urllib_req.Request(
                "https://exp.host/--/api/v2/push/send",
                data=payload,
                headers={"Content-Type": "application/json",
                         "Accept": "application/json",
                         "Accept-Encoding": "gzip, deflate"},
            )
            with _urllib_req.urlopen(req, timeout=8) as r:
                pass   # fire-and-forget
        except Exception as _pe:
            log.debug(f"[TWIN] Push failed: {_pe}")
    threading.Thread(target=_push, daemon=True, name="twin-push").start()


def _twin_take_snapshot() -> dict:
    """Capture a full security-relevant snapshot of the current PC state."""
    snap: dict = {"ts": time.time(), "sections": {}}

    # 1. Running processes (name + pid + exe hash for critical ones)
    try:
        import psutil as _psu
        procs = {}
        for p in _psu.process_iter(["pid", "name", "exe", "username", "ppid"]):
            try:
                info = p.info
                procs[str(info["pid"])] = {
                    "name":  info.get("name","?"),
                    "exe":   info.get("exe") or "",
                    "user":  info.get("username") or "",
                    "ppid":  info.get("ppid"),
                }
            except Exception:
                pass
        snap["sections"]["processes"] = procs
    except Exception as _e:
        snap["sections"]["processes"] = {"_error": str(_e)}

    # 2. Open listening ports
    try:
        import psutil as _psu
        ports = {}
        for conn in _psu.net_connections(kind="tcp"):
            if conn.status == "LISTEN" and conn.laddr:
                ports[str(conn.laddr.port)] = {
                    "ip":  conn.laddr.ip,
                    "pid": conn.pid,
                }
        snap["sections"]["listening_ports"] = ports
    except Exception as _e:
        snap["sections"]["listening_ports"] = {"_error": str(_e)}

    # 3. Startup registry keys
    try:
        import winreg as _wr
        startup_keys = {}
        for hive, hive_name in [(_wr.HKEY_LOCAL_MACHINE, "HKLM"), (_wr.HKEY_CURRENT_USER, "HKCU")]:
            try:
                k = _wr.OpenKey(hive,
                    r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
                    access=_wr.KEY_READ | _wr.KEY_WOW64_64KEY)
                i = 0
                while True:
                    try:
                        name, val, _ = _wr.EnumValue(k, i)
                        startup_keys[f"{hive_name}\\{name}"] = val
                        i += 1
                    except OSError:
                        break
                _wr.CloseKey(k)
            except Exception:
                pass
        snap["sections"]["startup_registry"] = startup_keys
    except Exception as _e:
        snap["sections"]["startup_registry"] = {"_error": str(_e)}

    # 4. Scheduled tasks (count + names only — fast)
    try:
        r = subprocess.run(
            ["schtasks", "/query", "/fo", "CSV", "/nh"],
            capture_output=True, text=True, timeout=15
        )
        tasks = {}
        for line in r.stdout.splitlines()[:200]:
            parts = line.strip('"').split('","')
            if len(parts) >= 3:
                tasks[parts[0]] = parts[2]  # name → status
        snap["sections"]["scheduled_tasks"] = tasks
    except Exception as _e:
        snap["sections"]["scheduled_tasks"] = {"_error": str(_e)}

    # 5. Hosts file hash
    try:
        hosts_path = r"C:\Windows\System32\drivers\etc\hosts"
        h = _ht_hashlib.sha256(open(hosts_path, "rb").read()).hexdigest()
        snap["sections"]["hosts_file_hash"] = h
    except Exception as _e:
        snap["sections"]["hosts_file_hash"] = {"_error": str(_e)}

    # 6. Network adapters + MACs
    try:
        r = subprocess.run(["getmac", "/fo", "CSV", "/nh", "/v"],
                           capture_output=True, text=True, timeout=8)
        adapters = {}
        for line in r.stdout.splitlines():
            parts = line.strip('"').split('","')
            if len(parts) >= 2:
                adapters[parts[0]] = parts[1]
        snap["sections"]["network_adapters"] = adapters
    except Exception as _e:
        snap["sections"]["network_adapters"] = {"_error": str(_e)}

    # 7. Installed software count (quick — just count)
    try:
        r = subprocess.run(
            ["wmic", "product", "get", "name", "/format:csv"],
            capture_output=True, text=True, timeout=30
        )
        count = len([l for l in r.stdout.splitlines() if l.strip() and l.strip() != "Name"])
        snap["sections"]["installed_software_count"] = count
    except Exception as _e:
        snap["sections"]["installed_software_count"] = 0

    # 8. Active user sessions
    try:
        r = subprocess.run(["query", "session"], capture_output=True, text=True, timeout=8)
        sessions = [l.strip() for l in r.stdout.splitlines() if l.strip()]
        snap["sections"]["user_sessions"] = sessions
    except Exception as _e:
        snap["sections"]["user_sessions"] = {"_error": str(_e)}

    # 9. Windows Defender status
    try:
        r = subprocess.run(
            ["powershell", "-NoProfile", "-Command",
             "Get-MpComputerStatus | Select-Object AMRunningMode,RealTimeProtectionEnabled,AntivirusEnabled | ConvertTo-Json"],
            capture_output=True, text=True, timeout=10
        )
        snap["sections"]["defender_status"] = r.stdout.strip()[:500]
    except Exception as _e:
        snap["sections"]["defender_status"] = {"_error": str(_e)}

    return snap


def _twin_compare(baseline: dict, current: dict) -> list:
    """
    Compare two snapshots. Returns list of drift items:
    {"category", "severity", "title", "detail"}
    """
    drifts = []
    bs = baseline.get("sections", {})
    cs = current.get("sections", {})

    # ── Processes: new processes that appeared ──────────────────────
    b_procs = bs.get("processes", {})
    c_procs = cs.get("processes", {})
    if isinstance(b_procs, dict) and isinstance(c_procs, dict):
        b_names = {v.get("name","") for v in b_procs.values() if isinstance(v, dict)}
        c_names = {v.get("name","") for v in c_procs.values() if isinstance(v, dict)}
        new_procs = c_names - b_names
        gone_procs = b_names - c_names
        # Filter out common transient processes
        _IGNORE = {"conhost.exe","RuntimeBroker.exe","svchost.exe","csrss.exe",
                   "WmiPrvSE.exe","taskhostw.exe","SearchIndexer.exe","dllhost.exe",
                   "audiodg.exe","spoolsv.exe","services.exe","lsass.exe"}
        new_suspicious = new_procs - _IGNORE
        if new_suspicious:
            drifts.append({
                "category": "processes",
                "severity": "MEDIUM",
                "title": f"{len(new_suspicious)} new process(es) since baseline",
                "detail": "New: " + ", ".join(sorted(new_suspicious)[:10]),
            })

    # ── Ports: new listening ports ───────────────────────────────────
    b_ports = bs.get("listening_ports", {})
    c_ports = cs.get("listening_ports", {})
    if isinstance(b_ports, dict) and isinstance(c_ports, dict):
        new_ports = set(c_ports.keys()) - set(b_ports.keys())
        if new_ports:
            drifts.append({
                "category": "ports",
                "severity": "HIGH",
                "title": f"New open port(s): {', '.join(sorted(new_ports)[:8])}",
                "detail": "A process opened new listening ports after baseline was taken.",
            })

    # ── Startup registry: new entries ────────────────────────────────
    b_start = bs.get("startup_registry", {})
    c_start = cs.get("startup_registry", {})
    if isinstance(b_start, dict) and isinstance(c_start, dict):
        new_entries = {k: v for k, v in c_start.items() if k not in b_start}
        removed_entries = {k for k in b_start if k not in c_start}
        if new_entries:
            for k, v in list(new_entries.items())[:5]:
                drifts.append({
                    "category": "persistence",
                    "severity": "CRITICAL",
                    "title": f"New startup entry: {k.split(chr(92))[-1]}",
                    "detail": f"Registry: {k} → {str(v)[:120]}",
                })

    # ── Hosts file: hash changed ──────────────────────────────────────
    b_hosts = bs.get("hosts_file_hash")
    c_hosts = cs.get("hosts_file_hash")
    if b_hosts and c_hosts and b_hosts != c_hosts and not isinstance(b_hosts, dict):
        drifts.append({
            "category": "network",
            "severity": "CRITICAL",
            "title": "Hosts file was modified!",
            "detail": "The Windows hosts file changed since baseline — possible DNS hijack.",
        })

    # ── Defender: real-time protection disabled ───────────────────────
    b_def = bs.get("defender_status", "")
    c_def = cs.get("defender_status", "")
    if isinstance(c_def, str):
        if "false" in c_def.lower() and ("realtime" in c_def.lower() or "antivirus" in c_def.lower()):
            drifts.append({
                "category": "defense",
                "severity": "HIGH",
                "title": "Windows Defender appears disabled",
                "detail": "Real-time protection or AV engine turned off since baseline.",
            })

    return drifts


# ── BACKGROUND MONITOR THREAD ─────────────────────────────────────────
_TWIN_SCAN_INTERVAL = 120   # seconds between scans (2 min)
_twin_thread_started = False

def _twin_monitor_loop():
    """Background thread: periodic drift detection + push alerts."""
    global _TWIN_ENABLED, _TWIN_BASELINE
    log.info("[TWIN] Security baseline monitor started")
    while True:
        try:
            time.sleep(_TWIN_SCAN_INTERVAL)
            with _TWIN_LOCK:
                enabled   = _TWIN_ENABLED
                baseline  = dict(_TWIN_BASELINE)
            if not enabled or not baseline:
                continue
            current = _twin_take_snapshot()
            drifts  = _twin_compare(baseline, current)
            for d in drifts:
                _twin_send_alert(d["category"], d["severity"], d["title"], d["detail"])
        except Exception as _te:
            log.debug(f"[TWIN] Monitor loop error: {_te}")


# ── PROXIMITY LOCK LOOP ───────────────────────────────────────────────
_PROX_THREAD_STARTED = False

def _proximity_lock_loop():
    """
    Background thread: if phone hasn't sent a heartbeat within
    _PROX_TIMEOUT_SEC seconds, lock the workstation.
    When phone reconnects, optionally unlock.
    """
    global _PROX_ENABLED, _PROX_LAST_SEEN, _PROX_LOCKED_BY_PROX
    log.info("[PROX] Phone proximity lock monitor started")
    while True:
        try:
            time.sleep(10)   # check every 10 sec
            with _PROX_LOCK:
                enabled   = _PROX_ENABLED
                last_seen = _PROX_LAST_SEEN
                timeout   = _PROX_TIMEOUT_SEC
                locked    = _PROX_LOCKED_BY_PROX

            if not enabled:
                continue

            age = time.time() - last_seen
            if age > timeout and not locked:
                # Phone gone — lock the PC
                log.warning(f"[PROX] Phone silent for {age:.0f}s — locking workstation")
                try:
                    import ctypes as _ct
                    _ct.windll.user32.LockWorkStation()
                except Exception as _le:
                    subprocess.run(["rundll32.exe", "user32.dll,LockWorkStation"], timeout=5)
                with _PROX_LOCK:
                    _PROX_LOCKED_BY_PROX = True
                _twin_send_alert(
                    "proximity", "HIGH",
                    "PC Locked — Phone Out of Range",
                    f"No heartbeat from phone for {int(age)}s. Workstation auto-locked."
                )

            elif age <= timeout and locked:
                # Phone came back — unlock notice (can't auto-unlock Windows, just notify)
                log.info("[PROX] Phone reconnected — proximity lock cleared")
                with _PROX_LOCK:
                    _PROX_LOCKED_BY_PROX = False
                _twin_send_alert(
                    "proximity", "LOW",
                    "Phone Reconnected",
                    "Your phone is back in range. PC proximity lock cleared."
                )

        except Exception as _pe:
            log.debug(f"[PROX] Proximity loop error: {_pe}")


def _twin_start_if_needed():
    """Start background threads lazily on first enable — safe to call multiple times."""
    global _twin_thread_started, _PROX_THREAD_STARTED
    if not _twin_thread_started:
        threading.Thread(target=_twin_monitor_loop, daemon=True, name="twin-monitor").start()
        _twin_thread_started = True
    if not _PROX_THREAD_STARTED:
        threading.Thread(target=_proximity_lock_loop, daemon=True, name="prox-lock").start()
        _PROX_THREAD_STARTED = True


# ══════════════════════════════════════════════════════════════════════
#  API HANDLER HELPER — called from the main HTTP handler
#  Returns True if the path was handled (so caller can return early)
# ══════════════════════════════════════════════════════════════════════

def _handle_twin_api(handler, path: str, body: dict) -> bool:
    """
    Routes:
      POST /api/security/twin/baseline/take    — capture new baseline
      POST /api/security/twin/baseline/clear   — wipe baseline
      GET  /api/security/twin/status           — full status JSON
      POST /api/security/twin/enable           — enable monitoring
      POST /api/security/twin/disable          — disable monitoring
      GET  /api/security/twin/alerts           — list recent alerts
      POST /api/security/twin/scan             — manual on-demand scan
      POST /api/security/proximity/enable      — enable phone proximity lock
      POST /api/security/proximity/disable     — disable
      POST /api/security/proximity/heartbeat   — phone sends this every ~20s
      GET  /api/security/proximity/status      — status
    """
    global _TWIN_ENABLED, _TWIN_BASELINE, _PROX_ENABLED, _PROX_LAST_SEEN, _PROX_TIMEOUT_SEC, _PROX_LOCKED_BY_PROX

    TWIN_PATHS = {
        "/api/security/twin/baseline/take",
        "/api/security/twin/baseline/clear",
        "/api/security/twin/status",
        "/api/security/twin/enable",
        "/api/security/twin/disable",
        "/api/security/twin/alerts",
        "/api/security/twin/scan",
        "/api/security/proximity/enable",
        "/api/security/proximity/disable",
        "/api/security/proximity/heartbeat",
        "/api/security/proximity/status",
    }

    if path not in TWIN_PATHS:
        return False

    # ──────────────────────────────────────────────────────────────────────────────────
    # INTENTIONAL AUTH EXEMPTION: /api/security/proximity/heartbeat has NO auth requirement.
    #
    # Why: The phone sends heartbeats from a background process, even when the screen is
    # locked and the Butler app is not in the foreground. If heartbeat required a valid
    # Bearer token, the token would expire after 30 days, the background heartbeat process
    # would start getting 401, proximity lock would fire 60s later, and the PC would lock
    # itself permanently with no way to recover without physical access.
    #
    # Security analysis:
    #   - The heartbeat payload is: {} (empty body) — no sensitive data transmitted
    #   - The heartbeat only resets _PROX_LAST_SEEN — it does NOT unlock the PC, does NOT
    #     expose any data, does NOT trigger any state change other than resetting the timeout
    #   - Any IP on the same LAN subnet can send fake heartbeats — this is acceptable because:
    #     (a) a fake heartbeat only PREVENTS the PC from locking, not unlocks it
    #     (b) the PC subnet is already implicitly trusted (same LAN as the paired phone)
    #   - Denial-of-service via heartbeat flooding is mitigated by the standard rate limiter
    #     (RATE_BURST_LIMIT=100 req/5s — a 20s heartbeat interval is well within bounds)
    #
    # DO NOT add auth to this endpoint. If you believe this is a security issue, re-read
    # the analysis above. The trade-off is intentional.
    # ──────────────────────────────────────────────────────────────────────────────────
    if path != "/api/security/proximity/heartbeat":
        if not handler._authed(body):
            handler._err("AUTH_REQUIRED")
            return True

    # ── Take baseline ──────────────────────────────────────────────
    if path == "/api/security/twin/baseline/take":
        def _bg():
            global _TWIN_BASELINE
            log.info("[TWIN] Taking baseline snapshot...")
            snap = _twin_take_snapshot()
            with _TWIN_LOCK:
                _TWIN_BASELINE = snap
            # Persist to DB
            try:
                _db_run("CREATE TABLE IF NOT EXISTS twin_baseline(id INTEGER PRIMARY KEY, data TEXT, ts INTEGER)")
                _db_run("DELETE FROM twin_baseline")
                _db_run("INSERT INTO twin_baseline(data, ts) VALUES(?,?)",
                        (json.dumps(snap), int(time.time())))
            except Exception as _e:
                log.debug(f"[TWIN] Baseline persist error: {_e}")
            log.info("[TWIN] Baseline snapshot complete")
        threading.Thread(target=_bg, daemon=True, name="twin-baseline").start()
        handler._json({"ok": True, "msg": "Baseline snapshot started in background"})
        return True

    # ── Clear baseline ─────────────────────────────────────────────
    elif path == "/api/security/twin/baseline/clear":
        global _TWIN_BASELINE
        with _TWIN_LOCK:
            _TWIN_BASELINE = {}
        try:
            _db_run("DELETE FROM twin_baseline")
        except Exception:
            pass
        handler._json({"ok": True, "msg": "Baseline cleared"})
        return True

    # ── Enable / disable twin ──────────────────────────────────────
    elif path == "/api/security/twin/enable":
        # Load persisted baseline if in-memory is empty
        if not _TWIN_BASELINE:
            try:
                rows = _db_q("SELECT data FROM twin_baseline ORDER BY id DESC LIMIT 1")
                if rows:
                    _TWIN_BASELINE = json.loads(rows[0]["data"])
            except Exception:
                pass
        _TWIN_ENABLED = True
        _twin_start_if_needed()
        handler._json({"ok": True, "enabled": True, "hasBaseline": bool(_TWIN_BASELINE)})
        return True

    elif path == "/api/security/twin/disable":
        _TWIN_ENABLED = False
        handler._json({"ok": True, "enabled": False})
        return True

    # ── Status ─────────────────────────────────────────────────────
    elif path == "/api/security/twin/status":
        with _TWIN_LOCK:
            has_bl = bool(_TWIN_BASELINE)
            bl_ts  = _TWIN_BASELINE.get("ts", 0) if has_bl else 0
            alerts = list(_TWIN_ALERTS[-10:])
            count  = _TWIN_ALERT_COUNT
        handler._json({
            "enabled":      _TWIN_ENABLED,
            "hasBaseline":  has_bl,
            "baselineTakenAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(bl_ts)) if bl_ts else None,
            "scanIntervalSec": _TWIN_SCAN_INTERVAL,
            "totalAlerts":  count,
            "recentAlerts": alerts,
            "proximity": {
                "enabled":     _PROX_ENABLED,
                "lastSeenSec": int(time.time() - _PROX_LAST_SEEN) if _PROX_LAST_SEEN else None,
                "timeoutSec":  _PROX_TIMEOUT_SEC,
                "lockedByProx": _PROX_LOCKED_BY_PROX,
            }
        })
        return True

    # ── Alerts list ────────────────────────────────────────────────
    elif path == "/api/security/twin/alerts":
        limit = min(int(body.get("limit", 50)), 200)
        with _TWIN_LOCK:
            alerts = list(_TWIN_ALERTS[-limit:])
        handler._json({"alerts": alerts, "total": _TWIN_ALERT_COUNT})
        return True

    # ── Manual scan ────────────────────────────────────────────────
    elif path == "/api/security/twin/scan":
        with _TWIN_LOCK:
            baseline = dict(_TWIN_BASELINE)
        if not baseline:
            handler._json({"error": "No baseline — take a baseline first"}, 400)
            return True
        def _scan_bg():
            current = _twin_take_snapshot()
            drifts  = _twin_compare(baseline, current)
            for d in drifts:
                _twin_send_alert(d["category"], d["severity"], d["title"], d["detail"])
            # Return result via a temp DB flag
            try:
                _db_run("CREATE TABLE IF NOT EXISTS twin_scan_result(id INTEGER PRIMARY KEY, data TEXT, ts INTEGER)")
                _db_run("DELETE FROM twin_scan_result")
                _db_run("INSERT INTO twin_scan_result(data,ts) VALUES(?,?)",
                        (json.dumps({"drifts": drifts, "ts": time.time()}), int(time.time())))
            except Exception:
                pass
        threading.Thread(target=_scan_bg, daemon=True, name="twin-scan").start()
        handler._json({"ok": True, "msg": "Scan started — check /api/security/twin/alerts for results"})
        return True

    # ── Proximity enable ───────────────────────────────────────────
    elif path == "/api/security/proximity/enable":
        timeout = int(body.get("timeoutSec", 60))
        _PROX_ENABLED       = True
        _PROX_TIMEOUT_SEC   = max(20, min(600, timeout))
        _PROX_LAST_SEEN     = time.time()   # reset clock on enable
        _twin_start_if_needed()
        handler._json({"ok": True, "enabled": True, "timeoutSec": _PROX_TIMEOUT_SEC})
        return True

    elif path == "/api/security/proximity/disable":
        _PROX_ENABLED = False
        with _PROX_LOCK:
            _PROX_LOCKED_BY_PROX = False
        handler._json({"ok": True, "enabled": False})
        return True

    # ── Proximity heartbeat ────────────────────────────────────────
    elif path == "/api/security/proximity/heartbeat":
        with _PROX_LOCK:
            _PROX_LAST_SEEN = time.time()
        handler._json({"ok": True, "ts": int(_PROX_LAST_SEEN)})
        return True

    # ── Proximity status ───────────────────────────────────────────
    elif path == "/api/security/proximity/status":
        with _PROX_LOCK:
            age = int(time.time() - _PROX_LAST_SEEN) if _PROX_LAST_SEEN else None
        handler._json({
            "enabled":      _PROX_ENABLED,
            "timeoutSec":   _PROX_TIMEOUT_SEC,
            "lastSeenSec":  age,
            "lockedByProx": _PROX_LOCKED_BY_PROX,
            "phoneOnline":  (age is not None and age < _PROX_TIMEOUT_SEC),
        })
        return True

    return False   # unhandled

# ── DB RESTORE: load persisted baseline at startup ────────────────────
def _twin_restore_baseline():
    """Called once at startup to reload persisted baseline into memory."""
    global _TWIN_BASELINE, _TWIN_ENABLED
    try:
        _db_run("CREATE TABLE IF NOT EXISTS twin_baseline(id INTEGER PRIMARY KEY, data TEXT, ts INTEGER)")
        rows = _db_q("SELECT data FROM twin_baseline ORDER BY id DESC LIMIT 1")
        if rows:
            _TWIN_BASELINE = json.loads(rows[0]["data"])
            log.info(f"[TWIN] Restored baseline from DB (taken at {time.strftime('%H:%M:%S', time.gmtime(_TWIN_BASELINE.get('ts',0)))})")
    except Exception as _e:
        log.debug(f"[TWIN] Restore baseline error: {_e}")


# ── BUTLER TOAST NOTIFICATION ─────────────────────────────────────────────────
def _butler_toast(title: str, message: str, duration_ms: int = 3000) -> None:
    """
    Show a non-intrusive, non-blocking toast popup when a script finishes.
    Strategy (tries each in order until one works, never blocks the server):
      1. Windows 10/11 native toast via PowerShell (win10toast-click / PowerShell)
      2. plyer cross-platform notification
      3. Tkinter frameless overlay (always works, auto-dismisses)
    All methods run in a daemon thread so the server is never blocked.
    """
    import threading
    def _show():
        try:
            # ── Method 1: PowerShell Windows Toast (Win10/11) ────────────────
            import subprocess as _sp, sys as _sys
            if _sys.platform == "win32":
                ps_script = (
                    "[Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, "
                    "ContentType = WindowsRuntime] | Out-Null; "
                    "[Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom.XmlDocument, "
                    "ContentType = WindowsRuntime] | Out-Null; "
                    "$template = [Windows.UI.Notifications.ToastTemplateType]::ToastText02; "
                    "$xml = [Windows.UI.Notifications.ToastNotificationManager]::GetTemplateContent($template); "
                    "$xml.GetElementsByTagName('text')[0].AppendChild($xml.CreateTextNode('" + title.replace("'", "") + "')) | Out-Null; "
                    "$xml.GetElementsByTagName('text')[1].AppendChild($xml.CreateTextNode('" + message.replace("'", "") + "')) | Out-Null; "
                    "$toast = [Windows.UI.Notifications.ToastNotification]::new($xml); "
                    "$notifier = [Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier('Butler AI'); "
                    "$notifier.Show($toast)"
                )
                r = _sp.run(
                    ["powershell", "-NoProfile", "-WindowStyle", "Hidden", "-Command", ps_script],
                    capture_output=True, timeout=5
                )
                if r.returncode == 0:
                    return
        except Exception:
            pass
        try:
            # ── Method 2: plyer ──────────────────────────────────────────────
            from plyer import notification
            notification.notify(
                title=title,
                message=message,
                app_name="Butler AI",
                timeout=duration_ms // 1000,
            )
            return
        except Exception:
            pass
        try:
            # ── Method 3: Tkinter frameless overlay ─────────────────────────
            import tkinter as _tk, threading as _th, time as _ti
            root = _tk.Tk()
            root.overrideredirect(True)          # no title bar
            root.attributes("-topmost", True)    # always on top
            root.attributes("-alpha", 0.92)      # slight transparency
            root.configure(bg="#1a1a2e")
            sw = root.winfo_screenwidth()
            sh = root.winfo_screenheight()
            w, h = 320, 72
            x = sw - w - 18
            y = sh - h - 60                      # bottom-right corner
            root.geometry(f"{w}x{h}+{x}+{y}")
            _tk.Label(root, text="🤖 " + title, bg="#1a1a2e", fg="#00e5ff",
                      font=("Segoe UI", 11, "bold"), anchor="w", padx=12).pack(fill="x", pady=(10,0))
            _tk.Label(root, text=message, bg="#1a1a2e", fg="#b0bec5",
                      font=("Segoe UI", 9), anchor="w", padx=14).pack(fill="x")
            root.after(duration_ms, root.destroy)
            root.mainloop()
        except Exception:
            pass   # toast is best-effort — never raise
    _t = threading.Thread(target=_show, daemon=True)
    _t.start()

def _load_builtin_library() -> list:
    """
    Load built-in scripts. Priority:
      1. butler_scripts_library.json next to this file (user-editable override)
      2. Embedded library baked into the server (always works out-of-box)
    Returns list of script dicts.
    """
    lib_file = Path(__file__).parent / "butler_scripts_library.json"
    # 1) On-disk override
    if lib_file.exists():
        try:
            data = json.loads(lib_file.read_text(encoding='utf-8'))
            scripts = data.get('scripts', [])
            log.info(f"[SCRIPTS] Loaded {len(scripts)} built-in scripts from on-disk library")
            return scripts
        except Exception as e:
            log.warning(f"[SCRIPTS] On-disk library load error: {e} — falling back to embedded")
    # 2) Embedded fallback
    try:
        data = json.loads(_EMBEDDED_LIBRARY_JSON)
        scripts = data.get('scripts', [])
        log.info(f"[SCRIPTS] Loaded {len(scripts)} built-in scripts from EMBEDDED library")
        return scripts
    except Exception as e:
        log.warning(f"[SCRIPTS] Embedded library load error: {e}")
        return []

def _seed_builtin_scripts():
    """
    Write all built-in scripts to butler_scripts/ directory.
    Called once at startup after _pc_scripts_init().
    Guards:
    - Never overwrites user-modified scripts (checks file exists)
    - Validates each script has id, name, code before writing
    - Logs count of written vs skipped
    - Safe to call on every restart
    """
    global _BUILTIN_SCRIPTS
    if not _BUILTIN_SCRIPTS:
        _BUILTIN_SCRIPTS = _load_builtin_library()
    if not _BUILTIN_SCRIPTS:
        _log("[SCRIPTS] No built-in library found — skipping seed", "warn")
        return

    try:
        _PC_SCRIPTS_DIR.mkdir(parents=True, exist_ok=True)
        written = skipped = errors = 0
        for s in _BUILTIN_SCRIPTS:
            # Guard: validate required fields
            sid  = s.get('id', '').strip()
            code = s.get('code', '').strip()
            name = s.get('name', '').strip()
            if not sid or not code or not name:
                log.debug(f"[SCRIPTS] Skipping invalid entry: {sid or '?'}")
                errors += 1
                continue
            # Guard: sanitize script ID
            sid = _RE_SCRIPT_ID.sub('_', sid)[:80]
            py_file   = _PC_SCRIPTS_DIR / f"{sid}.py"
            meta_file = _PC_SCRIPTS_DIR / f"{sid}.meta.json"
            # Guard: never overwrite user modifications
            if py_file.exists():
                skipped += 1
                continue
            try:
                py_file.write_text(code, encoding='utf-8')
                meta = {
                    "name":        name,
                    "description": s.get('description', ''),
                    "category":    s.get('category', 'General'),
                    "tags":        s.get('tags', []),
                    "icon":        s.get('icon', 'terminal'),
                    "created_at":  time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                    "builtin":     True,
                }
                meta_file.write_text(json.dumps(meta, indent=2), encoding='utf-8')
                written += 1
            except Exception as e:
                log.debug(f"[SCRIPTS] Seed write error {sid}: {e}")
                errors += 1

        _log(f"[SCRIPTS] Library seeded: {written} new, {skipped} existing, {errors} errors", "ok")
    except Exception as e:
        log.warning(f"[SCRIPTS] seed error: {e}")

