def _seed_public_kb() -> int:
    """
    Queue public-domain / permissively-licensed script-knowledge URLs into
    learn_queue so the existing crawler ingests them in the background.
    Idempotent: skips any URL already in knowledge_base or learn_queue.
    Returns the count of newly-queued URLs.
    """
    try:
        added = skipped = 0
        for url, cat, kws in _PUBLIC_KB_SEED:
            try:
                if _db_q("SELECT 1 FROM knowledge_base WHERE url=? LIMIT 1", (url,)):
                    skipped += 1; continue
                if _db_q("SELECT 1 FROM learn_queue WHERE url=? LIMIT 1", (url,)):
                    skipped += 1; continue
                if _lq_add(url, cat, kws, priority=6, source="public-kb-seed"):
                    added += 1
            except Exception:
                continue
        if added:
            _log(f"[KB-SEED] queued {added} public-domain URLs ({skipped} already present)", "ok")
        else:
            log.debug(f"[KB-SEED] no new URLs (all {skipped} already present)")
        return added
    except Exception as e:
        log.warning(f"[KB-SEED] failed: {e}")
        return 0


# per /api/pc_scripts/list call when scripts haven't changed (typical case).
_PC_SCRIPTS_LIST_CACHE: dict = {"mtime": -1.0, "data": []}
_PC_SCRIPTS_LIST_LOCK = threading.Lock()

def _pc_scripts_list() -> list:
    """
    Return script metadata ONLY — no code.
    Code is fetched on demand via _pc_scripts_get().
    Cached by directory mtime — recomputes only when files change.
    """
    try:
        _PC_SCRIPTS_DIR.mkdir(parents=True, exist_ok=True)
        try:
            dir_mtime = _PC_SCRIPTS_DIR.stat().st_mtime
        except Exception:
            dir_mtime = 0.0
        with _PC_SCRIPTS_LIST_LOCK:
            if dir_mtime and dir_mtime == _PC_SCRIPTS_LIST_CACHE["mtime"]:
                return list(_PC_SCRIPTS_LIST_CACHE["data"])
        scripts = []
        for py_file in sorted(_PC_SCRIPTS_DIR.glob("*.py")):
            sid = py_file.stem
            meta_file = _PC_SCRIPTS_DIR / f"{sid}.meta.json"
            meta = {}
            try:
                if meta_file.exists():
                    meta = json.loads(meta_file.read_text())
            except Exception:
                pass
            try:
                size = py_file.stat().st_size
            except Exception:
                size = 0
            scripts.append({
                "id":          sid,
                "name":        meta.get("name") or sid.replace("_", " ").title(),
                "description": meta.get("description", ""),
                "category":    meta.get("category", "Custom"),
                "tags":        meta.get("tags", []),
                "icon":        meta.get("icon", "terminal"),
                "builtin":     meta.get("builtin", False),
                "created_at":  meta.get("created_at", ""),
                "size_bytes":  size,
                # NOTE: code intentionally omitted — use /api/pc_scripts/get?id=X
            })
        with _PC_SCRIPTS_LIST_LOCK:
            _PC_SCRIPTS_LIST_CACHE["mtime"] = dir_mtime
            _PC_SCRIPTS_LIST_CACHE["data"]  = scripts
        return list(scripts)
    except Exception as e:
        log.warning(f"[SCRIPTS] list error: {e}")
        return []

def _pc_scripts_get(script_id: str) -> dict | None:
    """Return one script by ID."""
    try:
        sid = _RE_SCRIPT_ID.sub("_", script_id)[:80]
        py_file = _PC_SCRIPTS_DIR / f"{sid}.py"
        if not py_file.exists():
            return None
        meta_file = _PC_SCRIPTS_DIR / f"{sid}.meta.json"
        meta = {}
        try:
            if meta_file.exists():
                meta = json.loads(meta_file.read_text())
        except Exception:
            pass
        return {
            "id":          sid,
            "name":        meta.get("name", sid),
            "description": meta.get("description", ""),
            "category":    meta.get("category", "Custom"),
            "tags":        meta.get("tags", []),
            "created_at":  meta.get("created_at", ""),
            "code":        py_file.read_text(encoding="utf-8", errors="replace"),
        }
    except Exception as e:
        log.warning(f"[SCRIPTS] get error: {e}")
        return None

def _pc_scripts_save(script_id: str, name: str, code: str, description: str = "",
                     category: str = "Custom", tags: list | None = None) -> dict:
    """Save/overwrite a script. Returns dict with id and path."""
    try:
        _PC_SCRIPTS_DIR.mkdir(parents=True, exist_ok=True)
        # Sanitize ID
        if not script_id:
            script_id = _RE_WHITESPACE.sub("_", name.lower())[:40] or f"script_{int(time.time())}"
        sid = _RE_SCRIPT_ID.sub("_", script_id)[:80]
        py_file   = _PC_SCRIPTS_DIR / f"{sid}.py"
        meta_file = _PC_SCRIPTS_DIR / f"{sid}.meta.json"
        py_file.write_text(code, encoding="utf-8")
        meta = {
            "name":        name or sid,
            "description": description,
            "category":    category,
            "tags":        tags or [],
            "created_at":  time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        # Preserve created_at if updating
        try:
            if meta_file.exists():
                old = json.loads(meta_file.read_text())
                meta["created_at"] = old.get("created_at", meta["created_at"])
        except Exception:
            pass
        meta_file.write_text(json.dumps(meta, indent=2))
        _log(f"[SCRIPTS] Saved: {name} ({len(code)} chars) → {py_file.name}", "ok")
        return {"status": "ok", "id": sid, "path": str(py_file)}
    except Exception as e:
        log.warning(f"[SCRIPTS] save error: {e}")
        return {"status": "error", "error": str(e)}

def _pc_scripts_delete(script_id: str) -> dict:
    """Delete a script and its metadata."""
    try:
        sid = _RE_SCRIPT_ID.sub("_", script_id)[:80]
        py_file   = _PC_SCRIPTS_DIR / f"{sid}.py"
        meta_file = _PC_SCRIPTS_DIR / f"{sid}.meta.json"
        deleted = []
        if py_file.exists():
            py_file.unlink()
            deleted.append(py_file.name)
        if meta_file.exists():
            meta_file.unlink()
            deleted.append(meta_file.name)
        if deleted:
            _log(f"[SCRIPTS] Deleted: {sid}", "info")
            return {"status": "ok", "deleted": deleted}
        return {"status": "not_found"}
    except Exception as e:
        return {"status": "error", "error": str(e)}

def _pc_scripts_search(query: str) -> list:
    """Search scripts by name, description, tags, or code content."""
    q = query.lower()
    results = []
    for s in _pc_scripts_list():
        score = 0
        if q in s["name"].lower():        score += 10
        if q in s["description"].lower(): score += 6
        if any(q in t.lower() for t in s.get("tags", [])):  score += 8
        if q in s.get("code", "").lower(): score += 2
        if score > 0:
            results.append({**s, "_score": score})
    return sorted(results, key=lambda x: x["_score"], reverse=True)

def _get_script_template(task: str) -> str:
    """Returns a script template if one matches the user's request."""
    task_lower = task.lower()
    for key, script in SCRIPT_TEMPLATES.items():
        keywords = key.replace("_", " ").split()
        if any(kw in task_lower for kw in keywords):
            return script.strip()
    return ""

# ── v19.0.17: Adaptive retry + per-endpoint timeouts + result cache ──────
# Used by the crawler / search layer. Pure stdlib, thread-safe, never raises.
_HTTP_RETRY_LOCK = threading.Lock()
_HTTP_HOST_FAILS: dict = {}     # host -> consecutive failure count (for circuit-breaker)
_HTTP_HOST_COOLDOWN: dict = {}  # host -> epoch ts until which we skip the host
_SEARCH_CACHE: dict = {}        # query_key -> (ts, results)
_SEARCH_CACHE_TTL = 600         # 10 minutes — search intent rarely changes that fast
_SEARCH_CACHE_MAX = 256

def _http_host_of(url: str) -> str:
    try:
        from urllib.parse import urlparse
        return (urlparse(url).hostname or "").lower()
    except Exception:
        return ""

def _http_endpoint_timeout(url: str, default: float = 8.0) -> float:
    """Per-endpoint timeout tuned to known-slow hosts."""
    try:
        h = _http_host_of(url)
        if "google.com" in h:       return 6.0
        if "duckduckgo.com" in h:   return 7.0
        if "github.com" in h:       return 10.0
        if "readthedocs.io" in h:   return 12.0
        if "stackoverflow.com" in h:return 9.0
        return float(default)
    except Exception:
        return float(default)

def _http_fetch_with_retry(url: str, headers: dict = None, attempts: int = 3,
                            base_backoff: float = 0.6, max_bytes: int = 2_500_000) -> bytes:
    """
    Adaptive GET with exponential backoff + jitter + per-host circuit breaker.
    Returns response bytes on success, raises on final failure. Never blocks > ~25s.
    """
    host = _http_host_of(url)
    # ── circuit breaker: if this host failed 5+ times recently, skip for 60s
    try:
        with _HTTP_RETRY_LOCK:
            cooldown_until = _HTTP_HOST_COOLDOWN.get(host, 0)
        if cooldown_until and time.time() < cooldown_until:
            raise RuntimeError(f"host {host} in cooldown")
    except RuntimeError:
        raise
    except Exception:
        pass

    last_err = None
    for i in range(max(1, int(attempts))):
        try:
            req = _urllib_req.Request(url, headers=headers or {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
            })
            t = _http_endpoint_timeout(url)
            with _urllib_req.urlopen(req, timeout=t) as resp:
                data = resp.read(max_bytes)
            # success → reset failure count
            try:
                with _HTTP_RETRY_LOCK:
                    _HTTP_HOST_FAILS.pop(host, None)
                    _HTTP_HOST_COOLDOWN.pop(host, None)
            except Exception: pass
            return data
        except Exception as e:
            last_err = e
            # exponential backoff with jitter — but only if more retries remain
            if i < attempts - 1:
                try:
                    import random as _rnd
                    time.sleep(base_backoff * (2 ** i) + _rnd.uniform(0, 0.25))
                except Exception:
                    time.sleep(base_backoff * (2 ** i))
    # all retries failed → bump circuit breaker
    try:
        with _HTTP_RETRY_LOCK:
            n = _HTTP_HOST_FAILS.get(host, 0) + 1
            _HTTP_HOST_FAILS[host] = n
            if n >= 5:
                _HTTP_HOST_COOLDOWN[host] = time.time() + 60
    except Exception: pass
    raise last_err if last_err else RuntimeError("fetch failed")

# v19.0.18: counters for /api/debug/search
_SEARCH_CACHE_STATS = {"hits": 0, "misses": 0, "sets": 0, "started_at": time.time()}

def _search_cache_get(query: str, max_results: int):
    try:
        k = f"{query.lower()}|{max_results}"
        with _HTTP_RETRY_LOCK:
            entry = _SEARCH_CACHE.get(k)
        if entry and (time.time() - entry[0] < _SEARCH_CACHE_TTL):
            try: _SEARCH_CACHE_STATS["hits"] += 1
            except Exception: pass
            return list(entry[1])  # shallow copy so callers can't mutate cache
        try: _SEARCH_CACHE_STATS["misses"] += 1
        except Exception: pass
    except Exception: pass
    return None

def _search_cache_set(query: str, max_results: int, results: list):
    try:
        k = f"{query.lower()}|{max_results}"
        with _HTTP_RETRY_LOCK:
            if len(_SEARCH_CACHE) >= _SEARCH_CACHE_MAX:
                # drop oldest 16 entries — cheap LRU-ish trim
                try:
                    drop = sorted(_SEARCH_CACHE.items(), key=lambda kv: kv[1][0])[:16]
                    for kk, _ in drop: _SEARCH_CACHE.pop(kk, None)
                except Exception:
                    _SEARCH_CACHE.clear()
            _SEARCH_CACHE[k] = (time.time(), list(results))
        try: _SEARCH_CACHE_STATS["sets"] += 1
        except Exception: pass
    except Exception: pass


def _search_scripts(query: str, max_results: int = 3) -> list:
    # ── BULLETPROOF GUARD (v19.0.16): never raise to callers ─────────────
    # v19.0.17: result cache short-circuit + KB fallback on full failure.
    try:
        # v19.0.21: fuzz + loop guard
        try: query = _kb_fuzz_check(query)
        except Exception:
            if not isinstance(query, str): query = str(query or "")
        query = (query or "").strip()[:200]
        try: max_results = max(1, min(int(max_results), 10))
        except Exception: max_results = 3
        if not query: return []
        try:
            if not _loop_guard_check("crawler_search"): return []
        except Exception: pass
        # cache first — saves 100% network cost on repeat queries
        _cached = _search_cache_get(query, max_results)
        if _cached is not None:
            return _cached
        _out = _search_scripts_impl(query, max_results)
        if _out:
            _search_cache_set(query, max_results, _out)
        return _out
    except Exception as _ssg_e:
        try: log.debug(f"[crawler] guarded fallback: {_ssg_e}")
        except Exception: pass
        # Fallback: try KB only — never return an exception to the caller
        try:
            hits = _kb_search(query, limit=max_results) or []
            return [{
                "title": h.get("title","KB"),
                "url":   h.get("url",""),
                "snippet": (h.get("content") or h.get("clean_text") or "")[:300],
                "source":  "kb-fallback",
            } for h in hits[:max_results]]
        except Exception:
            return []

def _search_scripts_impl(query: str, max_results: int = 3) -> list:
    """
    Search for Python scripts/tutorials matching a query.
    GUARDED: Only searches trusted sources, scores relevance, blocks junk.
    
    Trusted source hierarchy (highest quality first):
    1. Python official docs — always correct, always safe
    2. RealPython — vetted tutorials with tested code
    3. GeeksForGeeks — explained examples with output
    4. StackOverflow — community-vetted answers
    5. GitHub repos with stars — real projects, real code
    6. AutomateTheBoringStuff — beginner-friendly, practical
    
    BLOCKED: random blogs, SEO farms, paste sites, unknown domains
    """
    import urllib.parse, urllib.request

    results = []
    query_clean = query.strip()[:80]
    query_lower = query_clean.lower()
    # FIX: keywords unused in this scope — removed

    # ── GUARD 1: Extract meaningful search terms ──────────
    # Strip filler words so searches are precise
    FILLER = {"how","do","i","can","you","me","a","the","to","my","for","on","in","and","or","is","it","with","this","that","please","help","want","need","make","get","write","create","show"}
    meaningful = [w for w in query_lower.split() if w not in FILLER and len(w) > 2]
    if not meaningful:
        meaningful = query_lower.split()[:3]
    search_terms = " ".join(meaningful[:5])
    search_encoded = urllib.parse.quote(search_terms)

    # ── GUARD 2: Trusted sources only ─────────────────────
    # v19.0.14: expanded from ~10 to ~50 vetted domains across Python, PowerShell,
    # Bash, JS/Node, web, data/ML, security, sysadmin, networking, and Windows.
    TRUSTED_DOMAINS = [
        # ── Python core & ecosystem ─────────────────────
        "docs.python.org", "realpython.com", "geeksforgeeks.org",
        "stackoverflow.com", "github.com", "gitlab.com",
        "automatetheboringstuff.com", "pypi.org", "peps.python.org",
        "psutil.readthedocs.io", "pyautogui.readthedocs.io",
        "requests.readthedocs.io", "docs.pytest.org",
        # ── Data / ML / Science ─────────────────────────
        "numpy.org", "pandas.pydata.org", "scipy.org",
        "scikit-learn.org", "matplotlib.org", "pytorch.org",
        "tensorflow.org", "huggingface.co",
        # ── Web frameworks ──────────────────────────────
        "flask.palletsprojects.com", "docs.djangoproject.com",
        "fastapi.tiangolo.com", "docs.aiohttp.org",
        # ── Microsoft / Windows / PowerShell ────────────
        "docs.microsoft.com", "learn.microsoft.com",
        "powershellgallery.com", "devblogs.microsoft.com",
        # ── Bash / Linux / sysadmin ─────────────────────
        "wiki.archlinux.org", "manpages.debian.org", "man7.org",
        "linux.die.net", "tldp.org", "ss64.com",
        "linuxhandbook.com", "linuxize.com",
        # ── JS / Node / web platform ────────────────────
        "developer.mozilla.org", "nodejs.org", "npmjs.com",
        "web.dev", "html.spec.whatwg.org",
        # ── Security / crypto ───────────────────────────
        "owasp.org", "cheatsheetseries.owasp.org",
        "cryptography.io", "letsencrypt.org",
        # ── DevOps / containers / cloud ─────────────────
        "docs.docker.com", "kubernetes.io",
        "docs.github.com", "docs.gitlab.com",
        # ── Networking / protocols ──────────────────────
        "datatracker.ietf.org", "wireshark.org",
        # ── DBs ─────────────────────────────────────────
        "sqlite.org", "postgresql.org", "redis.io", "mongodb.com",
    ]

    # ── GUARD 3: Blacklisted domains ──────────────────────
    # SEO farms, paste sites, malware hosts — never crawl these
    BLOCKED_DOMAINS = [
        "pastebin.com", "hastebin.com", "ghostbin.com",  # paste sites (unvetted code)
        "w3schools.com",          # known for inaccurate/outdated content
        "tutorialspoint.com",     # SEO farm, often wrong
        "programiz.com",          # shallow examples
        "javatpoint.com",         # SEO spam
        "medium.com",             # paywalled, unreliable quality
        "dev.to",                 # unvetted blog posts
        "hackforums.net", "exploit-db.com", "0day.today",  # security risk
        "quora.com",              # noisy, low-signal
        "reddit.com",             # mixed quality, hard to vet
    ]

    # ── SMART STRATEGY PICKER ─────────────────────────────
    # v19.0.14: detect query topic and pick the most useful `site:` filters
    # instead of always querying the same 5. Falls back to a broad set.
    TOPIC_SITES = {
        "powershell": ["learn.microsoft.com", "docs.microsoft.com", "ss64.com", "powershellgallery.com", "github.com"],
        "bash":       ["man7.org", "tldp.org", "linux.die.net", "wiki.archlinux.org", "stackoverflow.com"],
        "linux":      ["wiki.archlinux.org", "manpages.debian.org", "linuxhandbook.com", "linuxize.com", "stackoverflow.com"],
        "windows":    ["learn.microsoft.com", "docs.microsoft.com", "ss64.com", "github.com", "stackoverflow.com"],
        "javascript": ["developer.mozilla.org", "nodejs.org", "github.com", "stackoverflow.com"],
        "node":       ["nodejs.org", "npmjs.com", "github.com", "stackoverflow.com"],
        "web":        ["developer.mozilla.org", "web.dev", "html.spec.whatwg.org", "stackoverflow.com"],
        "ml":         ["pytorch.org", "tensorflow.org", "scikit-learn.org", "huggingface.co", "github.com"],
        "data":       ["pandas.pydata.org", "numpy.org", "realpython.com", "github.com"],
        "web-py":     ["fastapi.tiangolo.com", "docs.djangoproject.com", "flask.palletsprojects.com", "realpython.com"],
        "docker":     ["docs.docker.com", "github.com", "stackoverflow.com"],
        "k8s":        ["kubernetes.io", "github.com", "stackoverflow.com"],
        "db":         ["sqlite.org", "postgresql.org", "redis.io", "stackoverflow.com"],
        "security":   ["owasp.org", "cheatsheetseries.owasp.org", "cryptography.io", "github.com"],
        "network":    ["datatracker.ietf.org", "stackoverflow.com", "realpython.com"],
        "python":     ["docs.python.org", "realpython.com", "stackoverflow.com", "github.com", "geeksforgeeks.org"],
    }

    def _detect_topics(q: str) -> list:
        ql = q.lower()
        hits = []
        if any(k in ql for k in ("powershell", "pwsh", ".ps1", "cmdlet")): hits.append("powershell")
        if any(k in ql for k in ("bash", "shell script", ".sh", "zsh", "sh ")): hits.append("bash")
        if any(k in ql for k in ("linux", "ubuntu", "debian", "arch ", "systemd", "apt ")): hits.append("linux")
        if any(k in ql for k in ("windows", "win10", "win11", "registry", "regedit", "wmi")): hits.append("windows")
        if any(k in ql for k in ("javascript", "typescript", " js ", "react", "vue", "svelte")): hits.append("javascript")
        if any(k in ql for k in ("node.js", "nodejs", "npm ", "express", "pnpm", "bun ")): hits.append("node")
        if any(k in ql for k in ("html", "css", "browser", "dom ", "fetch api")): hits.append("web")
        if any(k in ql for k in ("pytorch", "tensorflow", "scikit", "machine learning", " ml ", "neural", "model train")): hits.append("ml")
        if any(k in ql for k in ("pandas", "numpy", "dataframe", "csv ", "excel", "parquet")): hits.append("data")
        if any(k in ql for k in ("flask", "django", "fastapi", "rest api")): hits.append("web-py")
        if any(k in ql for k in ("docker", "container", "dockerfile")): hits.append("docker")
        if any(k in ql for k in ("kubernetes", "k8s", "kubectl", "helm")): hits.append("k8s")
        if any(k in ql for k in ("sqlite", "postgres", "mysql", "redis", "mongo", "database", " sql ")): hits.append("db")
        if any(k in ql for k in ("password", "encrypt", "decrypt", "hash", "tls", "ssl", "owasp", "xss", "sqli")): hits.append("security")
        if any(k in ql for k in ("socket", "tcp", "udp", "http", "dns", "packet")): hits.append("network")
        if not hits:
            hits.append("python")  # safe default
        return hits

    topics = _detect_topics(query_lower)
    chosen_sites = []
    for t in topics:
        for s in TOPIC_SITES.get(t, []):
            if s not in chosen_sites:
                chosen_sites.append(s)
    chosen_sites = chosen_sites[:6]  # cap to keep request count bounded

    # ── Build targeted search queries ─────────────────────
    # Mix Google + DuckDuckGo (different rate limits, redundancy).
    search_urls = []
    for site in chosen_sites:
        search_urls.append(
            f"https://www.google.com/search?q={search_encoded}+site%3A{urllib.parse.quote(site)}"
        )
        search_urls.append(
            f"https://duckduckgo.com/html/?q={search_encoded}+site%3A{urllib.parse.quote(site)}"
        )

    for search_url in search_urls[:max_results + 2]:
        try:
            # v19.0.17: adaptive retry + per-endpoint timeout + circuit breaker
            _data = _http_fetch_with_retry(search_url, attempts=2)
            html = _data.decode("utf-8", errors="replace")

            # Extract URLs — only from trusted domains
            trusted_pattern = "|".join(re.escape(d) for d in TRUSTED_DOMAINS)
            urls_found = re.findall(rf'href="(https?://(?:{trusted_pattern})[^"]*)"', html)

            # FIX C-3: Actually apply BLOCKED_DOMAINS filter (was defined but never used)
            urls_found = [u for u in urls_found if not any(b in u for b in BLOCKED_DOMAINS)]
            for u in urls_found[:5]:
                # ── GUARD 4: URL quality filters ──────────
                # Skip non-content pages
                if any(skip in u for skip in [
                    "/search?", "/login", "/signup", "/join", "/pricing",
                    "/about", "/contact", "/careers", "/ads", "/sponsor",
                    "/notifications", "/settings", "/account", "/api/security/proximity/heartbeat",
                ]):
                    continue
                # Skip already-found URLs
                if u in [r["url"] for r in results]:
                    continue
                # ── GUARD 5: Relevance check ──────────────
                # URL must contain at least one meaningful keyword
                u_lower = u.lower()
                relevance = sum(1 for kw in meaningful if kw in u_lower)
                if relevance == 0 and "python" not in u_lower:
                    continue  # URL has nothing to do with the query

                results.append({
                    "url": u,
                    "title": query_clean,
                    "snippet": "",
                    "relevance": relevance,
                    "source": "search",
                })
                # v19.0.15: over-fetch (3× cap) so ranker has real choices
                if len(results) >= max_results * 3:
                    break
        except:
            pass
        if len(results) >= max_results * 3:
            break

    # ── RANKER v19.0.15 ───────────────────────────────────
    # Score each candidate by:
    #   • Domain trust  (earlier in TRUSTED_DOMAINS = higher rank)
    #   • Keyword relevance in URL (already counted as `relevance`)
    #   • URL quality   (reward docs/tutorial/guide paths; penalize query strings)
    # Then sort high→low and trim to max_results.
    _N_TRUSTED = len(TRUSTED_DOMAINS)
    _GOOD_PATH_TOKENS = ("docs", "guide", "tutorial", "howto", "how-to",
                         "reference", "examples", "cookbook", "manual")
    _BAD_PATH_TOKENS  = ("/tag/", "/category/", "/page/", "/feed",
                         "?utm_", "&utm_", "/amp/", "/print/")
    def _trust_rank(u: str) -> int:
        for i, d in enumerate(TRUSTED_DOMAINS):
            if d in u:
                return _N_TRUSTED - i  # earlier domain → larger value
        return 0
    def _url_quality(u: str) -> int:
        ul = u.lower()
        score = 0
        if any(tok in ul for tok in _GOOD_PATH_TOKENS): score += 2
        if any(tok in ul for tok in _BAD_PATH_TOKENS):  score -= 3
        if ul.count("?") > 0:                            score -= 1
        if ul.count("/") > 8:                            score -= 1  # deep buried
        if ul.endswith((".pdf", ".zip", ".tar.gz")):     score -= 2
        return score
    for r in results:
        r["score"] = (r.get("relevance", 0) * 5
                      + _trust_rank(r["url"])
                      + _url_quality(r["url"]))
    results.sort(key=lambda r: r.get("score", 0), reverse=True)
    results = results[:max_results]

    # ── GUARD 6: Fallback to curated high-quality URLs ────
    # If web search fails (no internet, rate limited), use known-good sources
    if not results:
        CURATED = {
            # File operations
            "file":      "https://realpython.com/working-with-files-in-python/",
            "folder":    "https://realpython.com/working-with-files-in-python/",
            "directory": "https://docs.python.org/3/library/pathlib.html",
            "rename":    "https://docs.python.org/3/library/os.html#os.rename",
            "copy":      "https://docs.python.org/3/library/shutil.html",
            "move":      "https://docs.python.org/3/library/shutil.html",
            "delete":    "https://docs.python.org/3/library/os.html#os.remove",
            "zip":       "https://docs.python.org/3/library/zipfile.html",
            "compress":  "https://docs.python.org/3/library/zipfile.html",
            # Network
            "network":   "https://realpython.com/python-sockets/",
            "socket":    "https://docs.python.org/3/library/socket.html",
            "http":      "https://realpython.com/python-requests/",
            "download":  "https://realpython.com/python-requests/",
            "api":       "https://realpython.com/api-integration-in-python/",
            "scrape":    "https://realpython.com/beautiful-soup-web-scraper-python/",
            "crawl":     "https://realpython.com/beautiful-soup-web-scraper-python/",
            # System
            "cpu":       "https://psutil.readthedocs.io/en/latest/#cpu",
            "memory":    "https://psutil.readthedocs.io/en/latest/#memory",
            "ram":       "https://psutil.readthedocs.io/en/latest/#memory",
            "disk":      "https://psutil.readthedocs.io/en/latest/#disks",
            "process":   "https://psutil.readthedocs.io/en/latest/#processes",
            "monitor":   "https://psutil.readthedocs.io/en/latest/",
            "system":    "https://docs.python.org/3/library/platform.html",
            # Automation
            "automat":   "https://automatetheboringstuff.com/2e/chapter20/",
            "mouse":     "https://pyautogui.readthedocs.io/en/latest/mouse.html",
            "keyboard":  "https://pyautogui.readthedocs.io/en/latest/keyboard.html",
            "click":     "https://pyautogui.readthedocs.io/en/latest/mouse.html",
            "gui":       "https://pyautogui.readthedocs.io/en/latest/",
            "screenshot":"https://pyautogui.readthedocs.io/en/latest/screenshot.html",
            "schedul":   "https://realpython.com/python-scheduler/",
            "cron":      "https://realpython.com/python-scheduler/",
            "timer":     "https://docs.python.org/3/library/sched.html",
            # Data
            "email":     "https://realpython.com/python-send-email/",
            "excel":     "https://realpython.com/openpyxl-excel-spreadsheets-python/",
            "csv":       "https://docs.python.org/3/library/csv.html",
            "json":      "https://docs.python.org/3/library/json.html",
            "database":  "https://docs.python.org/3/library/sqlite3.html",
            "sql":       "https://docs.python.org/3/library/sqlite3.html",
            "pdf":       "https://realpython.com/creating-modifying-pdf/",
            # Security
            "password":  "https://docs.python.org/3/library/secrets.html",
            "encrypt":   "https://docs.python.org/3/library/hashlib.html",
            "hash":      "https://docs.python.org/3/library/hashlib.html",
            # Cleanup
            "clean":     "https://docs.python.org/3/library/shutil.html",
            "temp":      "https://docs.python.org/3/library/tempfile.html",
            "cache":     "https://docs.python.org/3/library/shutil.html",
            "junk":      "https://docs.python.org/3/library/shutil.html",
            "backup":    "https://docs.python.org/3/library/zipfile.html",
            # Windows-specific
            "registry":  "https://docs.python.org/3/library/winreg.html",
            "startup":   "https://docs.python.org/3/library/winreg.html",
            "service":   "https://docs.python.org/3/library/subprocess.html",
            "driver":    "https://docs.python.org/3/library/subprocess.html",
            "install":   "https://docs.python.org/3/library/subprocess.html",
            "uninstall": "https://docs.python.org/3/library/subprocess.html",
        }
        for kw, url in CURATED.items():
            if kw in query_lower:
                if url not in [r["url"] for r in results]:
                    results.append({"url": url, "title": kw, "snippet": "", "relevance": 1, "source": "curated"})
                if len(results) >= max_results:
                    break

    return results[:max_results]

def _search_and_crawl_scripts(query: str, max_results: int = 3):
    """
    Background task: search for scripts related to a user's question,
    then add the found URLs to the crawl queue so the KB grows automatically.
    Called from a background thread during AI chat — never blocks the response.
    """
    try:
        results = _search_scripts(query, max_results=max_results)
        added = 0
        for r in results:
            url = r.get("url", "")
            if not url: continue
            existing = _db_q("SELECT url FROM knowledge_base WHERE url=? LIMIT 1", (url,))
            if not existing:
                if _lq_add(url, "AutoSearch", query.split()[:4], priority=8, source="auto-search"):
                    added += 1
        if added:
            _log(f"[AUTO-SEARCH] Added {added} URLs for: {query[:40]}… (sources: {', '.join(r.get('source','?') for r in results[:added])})", "info")
    except Exception as e:
        log.debug(f"[AUTO-SEARCH] Error: {e}")

def _verify_script_safety(script: str, user_request: str = "") -> dict:
    """
    AI-powered script verification before execution.
    Asks Ollama to check if the script:
    1. Actually does what the user asked for
    2. Contains any dangerous operations
    3. Has obvious bugs that would cause harm
    
    Returns: {"safe": True/False, "reason": "...", "warnings": [...]}
    Called before executing any AI-generated or KB-sourced script.
    """
    # ── FAST PATH: Skip verification for known-safe patterns ─────
    script_lower = script.lower().strip()
    
    # Pre-screen: always block known shell-level attacks even if short
    # FIX GUARD-1 (audit): expanded list + case-insensitive matching.
    _ALWAYS_BLOCK = [
        ":(){ :|:& };:",         # fork bomb (shell)
        "dd if=/dev/zero",       # disk wipe (unix)
        "dd if=/dev/random",
        "mkfs.",                 # filesystem format
        "> /dev/sda", "> /dev/nvme", "> /dev/hda",
        "chmod -r 777 /",        # world-writable root
        "rm -rf /", "rm -rf ~", "rm -rf $home", "rm -rf ${home}",
        "format c:", "format d:",
        "del /f /s /q c:", "del /f /s /q %systemroot%",
        "rd /s /q c:\\", "rmdir /s /q c:\\",
        "diskpart",
        "shutil.rmtree('/')", 'shutil.rmtree("/")',
        "shutil.rmtree('c:\\')", 'shutil.rmtree("c:\\")',
    ]
    _script_lower_ab = script.lower()
    for _ab in _ALWAYS_BLOCK:
        if _ab.lower() in _script_lower_ab:
            return {"safe": False, "reason": "Blocked: dangerous shell pattern detected",
                    "warnings": [f"Shell attack pattern: {_ab}"], "checked": True}

    # Very short scripts are usually safe (one-liners, print statements)
    if len(script) < 200 and "import" not in script_lower:
        return {"safe": True, "reason": "Simple script", "warnings": [], "checked": True}
    
    # Scripts that only use safe modules
    SAFE_ONLY_MODULES = {"math", "random", "datetime", "time", "json", "csv",
                         "string", "collections", "itertools", "functools",
                         "platform", "sys", "pprint", "textwrap", "re"}
    import re as _re
    imports = set(_re.findall(r'^(?:import|from) (\w+)', script, _re.MULTILINE))
    if imports and imports.issubset(SAFE_ONLY_MODULES):
        return {"safe": True, "reason": "Uses only safe modules", "warnings": []}

    # ── STATIC ANALYSIS: Check for dangerous patterns ────────────
    warnings = []
    
    DANGER_CHECKS = [
        # Destructive file operations
        (r"shutil\.rmtree\s*\(\s*['\"]?[/\\]", "Deletes root filesystem"),
        (r"os\.remove|os\.unlink|os\.rmdir", "Deletes files — verify target path"),
        (r"shutil\.rmtree", "Recursively deletes folders — verify target"),
        # System modification
        (r"winreg\.|RegSetValue|RegDeleteKey", "Modifies Windows registry"),
        (r"subprocess\..*(?:format|del\s|rm\s|shutdown|taskkill|net\s+stop)", "Runs system commands"),
        (r"ctypes\.windll|ctypes\.cdll", "Calls Windows system APIs directly"),
        # Network risks
        (r"socket\.connect|urllib\.request\.urlopen|requests\.get", "Makes network connections"),
        (r"exec\(|eval\(|compile\(", "Executes dynamic code — potential injection risk"),
        # Data exfiltration
        (r"smtp|send.*email|send.*mail", "Sends email — verify recipient"),
        (r"requests\.post.*data|urllib.*POST", "Sends data to external server"),
        # Privilege escalation
        (r"runas|ShellExecuteW.*runas|sudo", "Attempts admin/root elevation"),
        (r"os\.chmod.*0o777|chmod.*777", "Sets world-writable permissions"),
    ]
    
    for pattern, warning in DANGER_CHECKS:
        if _re.search(pattern, script, _re.IGNORECASE):
            warnings.append(warning)
    
    # ── AI VERIFICATION: Ask Ollama if the script matches the request ─
    if _ol_ok() and user_request and len(script) > 300:
        try:
            verify_prompt = (
                f"USER ASKED FOR: {user_request[:200]}\n\n"
                f"SCRIPT TO VERIFY:\n```python\n{script[:3000]}\n```\n\n"
                "Answer ONLY with a JSON object, nothing else:\n"
                '{"matches_request": true/false, "safe": true/false, "concerns": ["list of concerns"]}\n'
                "matches_request = does this script do what the user asked?\n"
                "safe = could this script damage the system or steal data?\n"
            )
            raw = _ol_chat(verify_prompt, system="You are a Python code reviewer. Respond ONLY with JSON.", 
                          model=_get_active_model(), history=[])
            # Parse AI response
            try:
                # Extract JSON from response
                json_match = _re.search(r'\{[^}]+\}', raw)
                if json_match:
                    verdict = json.loads(json_match.group())
                    if not verdict.get("matches_request", True):
                        warnings.append("AI: Script may not do what you asked")
                    if not verdict.get("safe", True):
                        warnings.append("AI: Script may be unsafe")
                    for c in verdict.get("concerns", []):
                        if isinstance(c, str) and len(c) < 100:
                            warnings.append(f"AI: {c}")
            except: pass  # AI response wasn't valid JSON — skip verification
        except: pass  # Ollama offline — skip AI verification
    
    # ── VERDICT ──────────────────────────────────────────────────
    # Critical = any pattern that could be destructive or exfiltrating
    CRITICAL_KEYWORDS = (
        "Deletes root", "Fork bomb", "AI: Script may be unsafe",
        "registry", "world-writable", "elevation",
    )
    critical = any(any(kw.lower() in w.lower() for kw in CRITICAL_KEYWORDS) for w in warnings)

    if critical:
        reason = "Blocked: " + next(w for w in warnings
                                    if any(kw.lower() in w.lower() for kw in CRITICAL_KEYWORDS))
    elif warnings:
        reason = f"Passed with {len(warnings)} warning(s)"
    else:
        reason = "Passed all checks"

    return {
        "safe":     not critical,
        "reason":   reason,
        "warnings": warnings,
        "checked":  True,
    }

WORKER_THREADS   = 1    # 1 worker — prevents CPU competition with AI chat
CRAWL_DELAY_SECS = 15   # 15s between crawls — gives CPU time for AI chat
QUEUE_LOW_WATER  = 20   # refill queue when below this
CHECKPOINT_SECS  = 900  # save checkpoint every 15 minutes

# ══════════════════════════════════════════════════════════════
#  PERF_GUARD — centralised performance & correctness guards
#
#  PURPOSE: prevent regressions when the chat handler is edited.
#  Every guard is self-healing; none crash the server.
#
#  Guards:
#    1. CONTEXT CAP        — num_ctx / num_predict never exceed safe limits
#    2. BUSY LEAK DETECTOR — _ollama_busy auto-resets if stuck > 5 min
#    3. CHAT POOL MONITOR  — warns + drains if queue depth spikes
#    4. TIMING WATCHDOG    — logs a WARNING if a chat round-trip > SLOW_CHAT_WARN_SECS
#    5. SYSTEM PROMPT CAP  — trims system prompt if it exceeds token budget
# ══════════════════════════════════════════════════════════════

# Hard caps — never send Ollama more context than this
_GUARD_MAX_CTX          = 4096   # max num_ctx for any request
_GUARD_MAX_PREDICT      = 1200   # max num_predict — raised for script/install intents (v12)
_GUARD_CASUAL_CTX       = 2048   # num_ctx cap for casual messages
_GUARD_CASUAL_PREDICT   = 256    # num_predict cap for casual messages
_GUARD_SCRIPT_PREDICT   = 1200   # v12: script/install intents need full code output
_GUARD_MAX_SYSTEM_CHARS = 6000   # trim system prompt above this (≈1500 tok)
SLOW_CHAT_WARN_SECS     = 60     # log WARNING when chat takes longer than this

# Busy-leak guard state
_busy_set_at: float = 0.0        # time when _ollama_busy was last set True
_BUSY_LEAK_TIMEOUT = 300         # auto-reset _ollama_busy after 5 minutes
_busy_lock = threading.Lock()    # FIX: guard atomic write of _ollama_busy + _busy_set_at

def _guard_ollama_options(options: dict, is_casual: bool = False, intent: str = "") -> dict:
    """
    Clamp Ollama generation options to safe maximums.
    v12: intent-aware — script/install get 1200-token budget, not 512.
    Prevents accidental regressions when options are edited elsewhere.
    Call this on every options dict before sending to Ollama.
    FIX 2: reads _GUARD_MAX_CTX/_GUARD_CASUAL_CTX under _ctx_lock.
    """
    with _ctx_lock:
        ctx_cap = _GUARD_CASUAL_CTX if is_casual else _GUARD_MAX_CTX
    # v12: script/install intents need full code output — raise their cap
    if intent in ("script", "install"):
        predict_cap = _GUARD_SCRIPT_PREDICT
    else:
        predict_cap = _GUARD_CASUAL_PREDICT if is_casual else _GUARD_MAX_PREDICT
    o = dict(options)
    if o.get("num_ctx", 0) > ctx_cap:
        _log(f"[GUARD] ⚠ num_ctx clamped {o['num_ctx']}→{ctx_cap} (casual={is_casual})", "guard")
        o["num_ctx"] = ctx_cap
    if o.get("num_predict", 0) > predict_cap:
        _log(f"[GUARD] ⚠ num_predict clamped {o['num_predict']}→{predict_cap}", "guard")
        o["num_predict"] = predict_cap
    # Ensure GPU layers are maximised — num_gpu:1 is a common accidental regression
    if o.get("num_gpu", 0) < 2:
        _log(f"[GUARD] ⚠ num_gpu {o.get('num_gpu',0)} too low — forced to 99", "guard")
        o["num_gpu"] = 99
    return o

def _guard_system_prompt(prompt: str) -> str:
    """
    Trim system prompt if it exceeds the character budget.
    Long system prompts add seconds of tokenisation time per request.
    """
    if len(prompt) <= _GUARD_MAX_SYSTEM_CHARS:
        return prompt
    trimmed = prompt[:_GUARD_MAX_SYSTEM_CHARS]
    # Cut at last newline so we don't break mid-sentence
    cut = trimmed.rfind("\n")
    if cut > _GUARD_MAX_SYSTEM_CHARS // 2:
        trimmed = trimmed[:cut]
    _log(f"[GUARD] ⚠ System prompt trimmed {len(prompt)}→{len(trimmed)} chars (budget={_GUARD_MAX_SYSTEM_CHARS})", "guard")
    return trimmed

def _guard_set_busy(val: bool):
    """
    Thread-safe setter for _ollama_busy that records the set-time
    so the leak detector can auto-reset if it gets stuck.
    FIX: _busy_lock makes the two-variable write atomic (was a race condition).
    """
    global _ollama_busy, _busy_set_at
    with _busy_lock:
        _ollama_busy = val
        _busy_set_at = time.time() if val else 0.0

def _guard_busy_leak_check():
    """
    If _ollama_busy has been True for > _BUSY_LEAK_TIMEOUT seconds,
    force-reset it. Called by the watchdog thread every 30 s.
    Prevents crawlers from being permanently paused after a crash.
    """
    global _ollama_busy
    with _busy_lock:
        if _ollama_busy and _busy_set_at > 0:
            age = time.time() - _busy_set_at
            if age > _BUSY_LEAK_TIMEOUT:
                _log(f"[GUARD] 🔧 _ollama_busy LEAK reset — was stuck {age:.0f}s (limit={_BUSY_LEAK_TIMEOUT}s)", "guard")
                _ollama_busy = False

def _guard_pool_health():
    """
    Check chat_pool queue depth. Warns if requests are piling up,
    which would make every subsequent chat wait.
    """
    try:
        q = getattr(_chat_pool, "_work_queue", None)
        if q is not None:
            depth = q.qsize()
            if depth >= 3:
                _log(f"[GUARD] ⚠ chat_pool backed up: {depth} requests queued — responses will be slow", "warn")
    except Exception:
        pass

def _guard_start_watchdog():
    """
    Background thread: runs all guard checks every 30 s.
    Lightweight — only does attribute reads and comparisons.
    """
    def _loop():
        while True:
            try:
                _guard_busy_leak_check()
                _guard_pool_health()
                _guard_disk_critical()
                _guard_model_failure_threshold()
            except Exception as _ge:
                log.debug(f"[GUARD] watchdog error: {_ge}")
            time.sleep(30)
    t = threading.Thread(target=_loop, daemon=True, name="perf-guard")
    t.start()
    _log("[GUARD] ✅ PERF_GUARD watchdog started — monitoring busy-leak, pool, disk, model failures", "ok")

# ── Additional PERF_GUARD functions ───────────────────────────────────────────

# Tracks consecutive Ollama failures per model — if a model fails 3+ times in a
# row the guard blacklists it for 10 min and forces a fallback to another model.
_model_fail_counts: dict = {}   # model_name -> int
_model_blacklist:   dict = {}   # model_name -> blacklisted_until timestamp
_model_fail_lock = threading.Lock()
_MODEL_FAIL_THRESHOLD   = 3     # consecutive failures before blacklist
_MODEL_BLACKLIST_SECS   = 600   # 10 minutes

# Bug 9: cached model list — avoids live HTTP call on every chat request

_slow_chat_count      = 0
_fast_chat_count      = 0
_ctx_reduced          = False
_SLOW_CHAT_THRESHOLD  = 3     # reduce after 3 consecutive slow chats
_FAST_CHAT_THRESHOLD  = 5     # restore after 5 consecutive fast chats

_ctx_lock = threading.Lock()   # FIX 2: guard _GUARD_MAX_CTX / _GUARD_CASUAL_CTX across threads

def _guard_adapt_ctx(elapsed: float) -> None:
    """Guard 13: auto-shrink context on slow PCs, restore when speed returns."""
    global _GUARD_MAX_CTX, _GUARD_CASUAL_CTX, _slow_chat_count
    global _ctx_reduced, _fast_chat_count
    SLOW_SECS = 45.0
    FAST_SECS = 15.0
    if elapsed > SLOW_SECS:
        _slow_chat_count += 1
        _fast_chat_count  = 0
        if _slow_chat_count >= _SLOW_CHAT_THRESHOLD and not _ctx_reduced:
            with _ctx_lock:
                _GUARD_MAX_CTX    = 2048
                _GUARD_CASUAL_CTX = 1024
            _ctx_reduced      = True
            _log(f"[GUARD] 🔧 Context auto-reduced to 2048 after "
                 f"{_slow_chat_count} slow chats", "heal")
    elif elapsed < FAST_SECS:
        _fast_chat_count += 1
        _slow_chat_count  = 0
        if _fast_chat_count >= _FAST_CHAT_THRESHOLD and _ctx_reduced:
            with _ctx_lock:
                _GUARD_MAX_CTX    = 4096
                _GUARD_CASUAL_CTX = 2048
            _ctx_reduced      = False
            _log("[GUARD] ✅ Context restored to 4096 — speed normalized", "heal")

# Guard 14: OOM guard — detect out-of-memory, auto-switch to lighter model
_OOM_SIGNALS = ["out of memory", "signal: killed", "cannot allocate", "killed"]

def _guard_is_oom_error(err_str: str) -> bool:
    low = err_str.lower()
    return any(sig in low for sig in _OOM_SIGNALS)

def _guard_handle_oom(model: str):
    _log(f"[GUARD] 🔧 OOM detected for {model} — blacklisting, seeking lighter model", "heal")
    # Triple-record = force immediate blacklist (threshold is 3)
    _guard_record_model_failure(model)
    _guard_record_model_failure(model)
    _guard_record_model_failure(model)
    installed = _ol_models()
    if not installed:
        return None
    candidates = [m for m in installed
                  if not _guard_is_model_blacklisted(m) and m != model]
    lighter = _select_lightest(candidates) if candidates else None
    if lighter:
        _log(f"[GUARD] ✅ Falling back to {lighter} after OOM", "heal")
    return lighter

# Heal 16: auto-retry with lighter model if primary fails
# v19.0.20: AI reply quality tracker + low-quality retry
_AI_REPLY_STATS = {
    "total": 0, "errors": 0, "empty": 0, "too_short": 0,
    "retries": 0, "ok": 0, "avg_chars": 0.0,
    "started_at": time.time(),
}
_AI_REPLY_STATS_LOCK = threading.Lock()

def _ai_stats_record(reply: str, kind: str = "ok"):
    try:
        with _AI_REPLY_STATS_LOCK:
            _AI_REPLY_STATS["total"] += 1
            _AI_REPLY_STATS[kind] = _AI_REPLY_STATS.get(kind, 0) + 1
            n = _AI_REPLY_STATS["total"]
            prev = _AI_REPLY_STATS["avg_chars"]
            _AI_REPLY_STATS["avg_chars"] = round(prev + (len(reply or "") - prev) / n, 1)
    except Exception: pass

def _reply_looks_bad(reply: str) -> bool:
    if not reply: return True
    r = reply.strip()
    if len(r) < 8: return True
    if r.startswith("[Ollama error]") or r.startswith("[EMPTY_RESPONSE]"): return True
    # all punctuation / single repeated char
    if len(set(r.replace(" ", ""))) <= 2: return True
    return False

def _ol_chat_with_fallback(msg, system="", model=None, history=None):
    """Heal 16: wrapper around _ol_chat that tries a lighter model on failure.
    v19.0.20: also retries once on suspiciously short/empty replies and
    records per-call quality stats for /api/debug/ai."""
    reply = _ol_chat(msg, system=system, model=model, history=history)
    reply_lower = reply.lower()
    _bad_quality = _reply_looks_bad(reply)
    if reply.startswith("[Ollama error]") or "timed out" in reply_lower or "taking too long" in reply_lower or _bad_quality:
        installed = _ol_models()
        candidates = [m for m in installed
                      if not _guard_is_model_blacklisted(m)
                      and m.lower().split(":")[0] != (model or "").lower().split(":")[0]]
        fallback = _select_lightest(candidates) if candidates else None
        if fallback:
            _ai_stats_record(reply, "retries")
            _log(f"[HEAL] 🔧 Reply weak/failed — retrying with {fallback}", "heal")
            reply2 = _ol_chat(msg, system=system, model=fallback, history=history)
            if not reply2.startswith("[Ollama error]") and not _reply_looks_bad(reply2):
                _ai_stats_record(reply2, "ok")
                _note_prefix = f"[Note: answered using {fallback} as fallback]\n\n"
                return _note_prefix + reply2
    # record terminal outcome
    if _reply_looks_bad(reply):
        _ai_stats_record(reply, "empty" if not reply.strip() else
                         ("errors" if reply.startswith("[Ollama") else "too_short"))
    else:
        _ai_stats_record(reply, "ok")
    return reply

# Perf F: dynamic num_predict based on message intent
def _predict_cap(msg: str, is_casual: bool) -> int:
    """Perf F: pick num_predict based on what kind of response is expected.
    Multi-step scripts (backup AND email AND report) need much more room than
    the old flat 1024 cap — bump to 2048 for compound requests.
    """
    lower = msg.lower()
    # Multi-step compound script: "backup my files, then clean temp, then email me"
    _compound_words = sum(1 for kw in ("then", "and", "also", "after", "next",
                                        "plus", "followed") if kw in lower.split())
    _script_words   = sum(1 for kw in ("script", "python", "powershell", "bash",
                                        "write a", "create a", "generate", "make a",
                                        "automate") if kw in lower)
    if _script_words and _compound_words >= 2:
        return 2048    # multi-step compound script — needs lots of room
    if _script_words or any(kw in lower for kw in
           ["write a", "create a script", "python script",
            "powershell", "make a", "generate", "bash script"]):
        return 1024    # single-step code generation
    if any(kw in lower for kw in
           ["is it", "does it", "can i", "should i",
            "will it", "is there", "do you"]):
        return 64      # yes/no questions need very little
    # "are you" in casual greetings ("how are you") should not trigger 64
    if "are you" in lower and not any(
            w in lower for w in ("hello", "hey", "hi", "how", "doing")):
        return 64
    return 256 if is_casual else 512

def _guard_record_model_failure(model: str):
    """Call this whenever Ollama returns an error for a specific model."""
    with _model_fail_lock:
        _model_fail_counts[model] = _model_fail_counts.get(model, 0) + 1
        if _model_fail_counts[model] >= _MODEL_FAIL_THRESHOLD:
            until = time.time() + _MODEL_BLACKLIST_SECS
            _model_blacklist[model] = until
            _model_fail_counts[model] = 0
            _log(f"[GUARD] 🚫 Model '{model}' failed {_MODEL_FAIL_THRESHOLD}× — blacklisted {_MODEL_BLACKLIST_SECS//60} min", "guard")

def _guard_record_model_success(model: str):
    """Call this whenever Ollama responds successfully — resets failure count."""
    with _model_fail_lock:
        _model_fail_counts.pop(model, None)
        _model_blacklist.pop(model, None)

def _guard_is_model_blacklisted(model: str) -> bool:
    """Returns True if model is currently blacklisted due to repeated failures."""
    with _model_fail_lock:
        until = _model_blacklist.get(model, 0)
        if until and time.time() < until:
            return True
        if model in _model_blacklist:
            # Blacklist expired — clean up
            del _model_blacklist[model]
    return False

def _guard_model_failure_threshold():
    """Watchdog check: expire old blacklist entries."""
    now = time.time()
    with _model_fail_lock:
        expired = [m for m, t in _model_blacklist.items() if now >= t]
        for m in expired:
            del _model_blacklist[m]
            _log(f"[GUARD] ✅ Model blacklist expired for '{m}'", "ok")

# Disk-critical guard: if disk is below 500 MB, disable crawlers entirely
_DISK_CRITICAL_MB = 500

def _guard_disk_critical() -> bool:
    """
    Returns True if disk is critically low (< 500 MB free).
    Logs a warning and sets perf_mode to battery (crawlers off) automatically.
    Called by the PERF_GUARD watchdog every 30 s.
    """
    global _perf_mode
    if not HAS_PSUTIL:
        return False
    try:
        disk = psutil.disk_usage(str(Path.home()))
        free_mb = disk.free / (1024 * 1024)
        if free_mb < _DISK_CRITICAL_MB:
            if _perf_mode != "battery":
                _log(f"[GUARD] 🔴 Disk CRITICAL {free_mb:.0f} MB free — crawlers disabled", "warn")
                _perf_mode = "battery"
            return True
        # Auto-restore auto mode if disk recovers (e.g. user deleted files)
        if _perf_mode == "battery" and free_mb > _DISK_CRITICAL_MB * 2:
            _log(f"[GUARD] ✅ Disk recovered {free_mb:.0f} MB — crawlers restored", "ok")
            _perf_mode = "auto"
    except Exception:
        pass
    return False

def _guard_chat_history_startup_trim():
    """
    Called once at startup. Trims chat_history to 500 rows total if bloated
    from a previous run. Prevents slow DB queries on first chat of a session.
    """
    try:
        rows = _db_q("SELECT COUNT(*) n FROM chat_history")
        total = rows[0]["n"] if rows else 0
        if total > 500:
            _db_run(
                "DELETE FROM chat_history WHERE id NOT IN "
                "(SELECT id FROM chat_history ORDER BY id DESC LIMIT 500)"
            )
            _log(f"[GUARD] 🔧 Startup: chat_history trimmed {total}→500 rows", "heal")
    except Exception as e:
        log.debug(f"[GUARD] chat_history trim error: {e}")

def _guard_dedupe_chat_history():
    """
    Remove exact duplicate consecutive messages from chat_history.
    These accumulate when the app retries a failed request.
    Called by the watchdog every ~5 min (every 10 × 30s cycles).
    """
    try:
        _db_run(
            "DELETE FROM chat_history WHERE id IN ("
            "  SELECT h1.id FROM chat_history h1"
            "  JOIN chat_history h2 ON h1.device_id=h2.device_id"
            "    AND h1.role=h2.role AND h1.content=h2.content"
            "    AND h1.id > h2.id"
            ")"
        )
    except Exception as e:
        log.debug(f"[GUARD] dedupe error: {e}")

# ══════════════════════════════════════════════════════════════════
#  PASSIVE SAFETY GUARDS  — observe-only, never alter existing flows
# ══════════════════════════════════════════════════════════════════

def _guard_auth_fail_map_leak() -> None:
    """
    Purge expired entries from _auth_fail_map.
    The map is appended to on every failed auth but never shrunk, so
    long-running servers accumulate one entry per attacking IP forever.
    Safe: only deletes entries whose timestamps are all outside the window.
    Called by watchdog every cycle (~60 s).
    """
    try:
        now = time.time()
        cutoff = now - AUTH_FAIL_WINDOW
        with _auth_fail_lock:
            stale = [ip for ip, ts_list in _auth_fail_map.items()
                     if not ts_list or all(t < cutoff for t in ts_list)]
            for ip in stale:
                del _auth_fail_map[ip]
        if stale:
            log.debug(f"[GUARD] auth_fail_map: purged {len(stale)} stale IPs")
    except Exception as _e:
        log.debug(f"[GUARD] auth_fail_map purge error: {_e}")

def _guard_log_buffer_size() -> None:
    """
    Emergency trim of _log_lines if it somehow grows beyond 3000 entries.
    The normal cap is 2000 (enforced in _log()), but if _log() is called
    from multiple threads while pop(0) is mid-execution the list can drift.
    Safe: only trims tail if size > 3000; never touches entries < 3000.
    Called by watchdog every cycle.
    """
    try:
        with _log_lock:
            excess = len(_log_lines) - 2500
            if excess > 0:
                del _log_lines[:excess]
                log.debug(f"[GUARD] log buffer emergency trim: removed {excess} entries")
    except Exception as _e:
        log.debug(f"[GUARD] log buffer trim error: {_e}")

def _guard_reply_cache_stale() -> None:
    """
    Sweep expired entries from _REPLY_CACHE.
    Entries older than their per-intent TTL are silently evicted so RAM
    doesn't grow between eviction cycles (eviction only triggers on insert
    when len >= _REPLY_CACHE_MAX, meaning stale entries can survive indefinitely
    if the cache never reaches capacity).
    Safe: uses the existing TTL rules; never removes a valid/fresh entry.
    Called by watchdog every ~5 min (every 5 cycles).
    """
    try:
        now = time.time()
        with _REPLY_CACHE_LOCK:
            stale = [k for k, (reply, ts) in _REPLY_CACHE.items()
                     if now - ts > _REPLY_CACHE_TTL * 2]   # 2× safety margin
            for k in stale:
                del _REPLY_CACHE[k]
        if stale:
            log.debug(f"[GUARD] reply_cache: evicted {len(stale)} stale entries")
    except Exception as _e:
        log.debug(f"[GUARD] reply_cache sweep error: {_e}")

def _guard_share_dir() -> None:
    """
    Verify SHARE_DIR still exists and is writable.
    Users sometimes delete or move it, causing /api/receive_file to crash.
    Safe: only re-creates if missing; never alters contents.
    Called by watchdog every ~10 min (every 10 cycles).
    """
    try:
        if not SHARE_DIR.exists():
            SHARE_DIR.mkdir(parents=True, exist_ok=True)
            _log("[GUARD] 🔧 SHARE_DIR recreated (was missing)", "heal")
        else:
            # Write probe — detect permission issues before a file transfer arrives
            _probe = SHARE_DIR / ".butler_write_probe"
            _probe.write_text("ok"); _probe.unlink()
    except Exception as _e:
        _log(f"[GUARD] ⚠ SHARE_DIR not writable: {_e}", "warn")

def _guard_db_wal_size() -> None:
    """
    Force a WAL checkpoint if the WAL file exceeds 50 MB.
    SQLite's passive checkpoint (run every 5 min by watchdog) only works
    when no readers hold a snapshot. If a long-running read holds the DB
    open the WAL file can grow without bound and eventually fill the disk.
    PASSIVE checkpoint: does not block readers or writers, just tries to
    flush completed frames.  Safe to call at any time.
    Called by watchdog every ~5 min (every 5 cycles).
    """
    try:
        wal_path = Path(str(DB_PATH) + "-wal")
        if wal_path.exists():
            wal_mb = wal_path.stat().st_size / (1024 * 1024)
            if wal_mb > 50:
                _db_run("PRAGMA wal_checkpoint(PASSIVE)")
                _log(f"[GUARD] ⚠ WAL file was {wal_mb:.1f} MB — checkpoint forced", "warn")
            elif wal_mb > 20:
                log.debug(f"[GUARD] WAL file: {wal_mb:.1f} MB (ok)")
    except Exception as _e:
        log.debug(f"[GUARD] WAL size check error: {_e}")

_STATE_BACKUP_FILE = STATE_FILE.with_suffix(".backup.json")

def _guard_state_backup() -> None:
    """
    Write a rolling backup of the state file every ~10 min.
    If the main state file becomes corrupt or gets wiped (AV quarantine,
    crash mid-write despite atomic replace), the backup lets the server
    recover the pairing code and device ID instead of treating this as a
    fresh install and locking out the paired phone.
    Safe: writes to a separate .backup.json path; never reads from it
    (reading is handled by _load_state).
    Called by watchdog every ~10 min (every 10 cycles).
    """
    try:
        with _sl:
            snapshot = _state.copy()
        # Backup is always plaintext-safe (same format as _save_state)
        payload = json.dumps(snapshot, separators=(',', ':'))
        if _ENC_KEY:
            payload = _enc(payload)
        tmp = _STATE_BACKUP_FILE.with_suffix(".tmp")
        tmp.write_text(payload, encoding="utf-8")
        os.replace(str(tmp), str(_STATE_BACKUP_FILE))
        log.debug("[GUARD] State backup written")
    except Exception as _e:
        log.debug(f"[GUARD] State backup error: {_e}")

def _guard_state_file_integrity() -> None:
    """
    Check that the main state file is readable and valid JSON.
    If it is corrupt (truncated write, AV modification, filesystem error),
    log a warning and attempt to restore from the backup written by
    _guard_state_backup().  Only acts if the live in-memory state is also
    empty/default (i.e. _load_state() would fail on next restart).
    Safe: never modifies the live _state dict; only repairs the file on disk.
    Called by watchdog every ~10 min (every 10 cycles).
    """
    try:
        if not STATE_FILE.exists():
            # File missing — write current in-memory state now so next restart
            # doesn't lose the pairing code.
            try:
                with _sl:
                    snap = _state.copy()
                _save_state(snap)
                _log("[GUARD] 🔧 State file missing — re-written from memory", "heal")
            except Exception: pass
            return

        raw = STATE_FILE.read_text(encoding="utf-8").strip()
        if not raw:
            raise ValueError("state file is empty")
        # Attempt decode
        if raw.startswith("enc1:") and _ENC_KEY:
            json.loads(_dec(raw))   # raises on corrupt ciphertext
        else:
            json.loads(raw)         # raises on invalid JSON
        # File is fine
    except Exception as _e:
        _log(f"[GUARD] ⚠ State file corrupt ({_e}) — attempting restore from backup", "warn")
        try:
            if _STATE_BACKUP_FILE.exists():
                import shutil as _shu
                _shu.copy2(str(_STATE_BACKUP_FILE), str(STATE_FILE))
                _log("[GUARD] 🔧 State file restored from backup", "heal")
            else:
                # No backup — rewrite from live memory
                with _sl:
                    snap = _state.copy()
                _save_state(snap)
                _log("[GUARD] 🔧 State file rewritten from live memory (no backup yet)", "heal")
        except Exception as _re:
            log.error(f"[GUARD] State restore failed: {_re}")

# ══════════════════════════════════════════════════════════════════
#  SHARED CPU/RAM SNAPSHOT — updated every 5s by background thread
#  All subsystems read from this cache instead of calling psutil inline.
#  Prevents GIL contention and repeated 300ms blocking psutil calls.
# ══════════════════════════════════════════════════════════════════
_sys_snapshot: dict = {"cpu": 0.0, "ram": 0.0, "disk_free_mb": 9999.0, "ts": 0.0}
_sys_snapshot_lock = threading.Lock()

def _sys_snapshot_update():
    """Background thread: refreshes CPU/RAM/disk every 5 seconds."""
    while True:
        try:
            if HAS_PSUTIL:
                cpu  = psutil.cpu_percent(interval=1)   # 1s sample — most accurate
                ram  = psutil.virtual_memory().percent
                disk = psutil.disk_usage(str(Path.home())).free / (1024*1024)
                with _sys_snapshot_lock:
                    _sys_snapshot.update(cpu=cpu, ram=ram, disk_free_mb=disk, ts=time.time())
        except Exception:
            pass
        time.sleep(4)  # sleep 4s + 1s interval = ~5s cycle

def _get_cpu() -> float:
    """Return cached CPU % — never blocks."""
    with _sys_snapshot_lock: return _sys_snapshot["cpu"]

def _get_ram() -> float:
    """Return cached RAM % — never blocks."""
    with _sys_snapshot_lock: return _sys_snapshot["ram"]

def _get_disk_free_mb() -> float:
    """Return cached disk free MB — never blocks."""
    with _sys_snapshot_lock: return _sys_snapshot["disk_free_mb"]

# CPU pressure thresholds
CPU_PAUSE_CRAWLERS  = 60   # % — pause crawlers above this
CPU_WARN_USER       = 88   # % — warn user in chat above this
CPU_CRITICAL        = 95   # % — full system pause above this
RAM_PAUSE_CRAWLERS  = 85   # % — pause crawlers above this
RAM_WARN_USER       = 92   # % — warn user above this

# Tracks last time we sent a CPU warning into chat (avoid spam)
_cpu_warn_last_sent: float = 0.0
_cpu_warn_lock = threading.Lock()

def _cpu_chat_warning_if_needed() -> str | None:
    """
    Returns a warning string to prepend to AI chat reply if CPU/RAM is critical.
    Rate-limited to once every 5 minutes so it doesn't spam every message.
    Returns None if conditions are fine.
    """
    global _cpu_warn_last_sent
    cpu = _get_cpu()
    ram = _get_ram()
    if cpu < CPU_WARN_USER and ram < RAM_WARN_USER:
        return None
    now = time.time()
    with _cpu_warn_lock:
        if now - _cpu_warn_last_sent < 300:   # 5 min cooldown
            return None
        _cpu_warn_last_sent = now
    if cpu >= CPU_CRITICAL:
        return (f"\u26a0\ufe0f **PC CPU is at {cpu:.0f}%** - your computer is under extreme load. "
                f"AI responses may be slow or incomplete. Consider closing other applications.\n\n")
    if ram >= RAM_WARN_USER:
        return (f"\u26a0\ufe0f **RAM at {ram:.0f}%** - memory pressure is high. "
                f"AI responses may be slow. Consider closing unused applications.\n\n")
    return (f"\u26a0\ufe0f **PC CPU at {cpu:.0f}%** - high load detected. "
            f"AI may respond slower than usual.\n\n")

# ══════════════════════════════════════════════════════════════════════════════
#  NEXUS BRAIN — Autonomous Self-Optimizing Intelligence Layer
#
#  Three-layer architecture — zero external dependencies, zero cloud:
#
#  Layer 1: SENSOR ENGINE  — collects metrics every 30s → brain_metrics table
#  Layer 2: RULES ENGINE   — adjusts live variables every 5min → brain_tuning
#  Layer 3: INSIGHT ENGINE — asks local Ollama for plain-English analysis every
#                            4 hours → brain_insights (NEVER touches live vars)
#
#  Safety:   every change logged + reversible via /api/nexus_brain/reset_tuning
#  Memory:   everything in existing SQLite DB — no new files, no new deps
#  Watchdog: all three threads auto-restarted if they die
# ══════════════════════════════════════════════════════════════════════════════

# ── Live tunable variables (modified by Rules Engine, never by Ollama) ───────
_nb_crawl_delay   = CRAWL_DELAY_SECS   # current adaptive crawl delay
_nb_num_ctx       = 4096               # current Ollama context window
_nb_casual_ctx    = 2048               # current casual context window
_nb_num_predict   = 512                # current max tokens predicted
_nb_crawlers_paused = False            # True when brain force-pauses crawlers
_nb_lock = threading.Lock()

# ── Chat response time ring buffer (last 100 chats) ──────────────────────────
_nb_chat_times: list = []              # [(ts, ms, success)] rolling window
_nb_chat_errors_1h: list = []         # [ts] of failed chats in last hour
_nb_chat_lock = threading.Lock()

# ── Guard trigger counter (resets hourly) ────────────────────────────────────
_nb_guard_triggers: list = []         # [ts] of guard fires
_nb_guard_lock = threading.Lock()

# ── Tuning change log (in-memory, also persisted to DB) ──────────────────────
_nb_tuning_log = deque(maxlen=200)  # FIX M-2: was list with O(n) pop(0); deque(maxlen) is O(1)

# ── Insight engine state ──────────────────────────────────────────────────────
_nb_last_insight_ts: float = 0.0
_NB_INSIGHT_INTERVAL = 4 * 3600      # run Ollama analysis every 4 hours
_NB_INSIGHT_MIN_CHATS = 3            # don't bother if fewer than 3 chats

# ── Rule engine thresholds ───────────────────────────────────────────────────
_NB_CHAT_SLOW_MS      = 45_000   # ms — start reducing ctx above this avg
_NB_CHAT_VERY_SLOW_MS = 65_000   # ms — reduce more aggressively
_NB_CHAT_FAST_MS      = 8_000    # ms — restore ctx toward defaults
_NB_CPU_HIGH          = 78       # % — pause crawlers
_NB_CPU_NORMAL        = 48       # % — resume crawlers
_NB_CRAWL_ERR_HIGH    = 0.30     # 30% failure rate — slow crawl
_NB_CRAWL_ERR_NORMAL  = 0.05     # 5% failure rate — restore speed
_NB_SENSOR_INTERVAL   = 30       # seconds between sensor snapshots
_NB_RULES_INTERVAL    = 300      # seconds between rules evaluations (5 min)

def _nb_db_init():
    """Create NEXUS BRAIN tables in the existing SQLite database."""
    try:
        with _db_lock:
            c = _db_get_conn()
            c.executescript("""
                CREATE TABLE IF NOT EXISTS brain_metrics (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    ts REAL,
                    chat_ms_avg REAL,
                    chat_count_1h INTEGER,
                    chat_error_rate REAL,
                    kb_size INTEGER,
                    crawl_success_rate REAL,
                    queue_depth INTEGER,
                    poison_count INTEGER,
                    cpu_pct REAL,
                    ram_pct REAL,
                    ollama_ok INTEGER,
                    model_name TEXT,
                    crawl_delay_secs REAL,
                    active_ctx INTEGER,
                    guard_triggers_1h INTEGER
                );
                CREATE INDEX IF NOT EXISTS idx_bm_ts ON brain_metrics(ts);

                CREATE TABLE IF NOT EXISTS brain_tuning (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    ts REAL,
                    variable TEXT,
                    old_value TEXT,
                    new_value TEXT,
                    reason TEXT,
                    reverted_at REAL
                );

                CREATE TABLE IF NOT EXISTS brain_insights (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    ts REAL,
                    period_hours REAL,
                    digest TEXT,
                    insight TEXT,
                    model_used TEXT
                );

                CREATE TABLE IF NOT EXISTS brain_anomalies (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    ts REAL,
                    anomaly_type TEXT,
                    detail TEXT,
                    resolved_at REAL
                );
            """)
            c.commit()
        _log("[NEXUS] Brain memory tables ready", "ok")
    except Exception as e:
        log.warning(f"[NEXUS] DB init error: {e}")

def _nb_record_chat(response_ms: int, success: bool):
    """
    Called by chat handler after every response.
    Records response time into the in-memory ring buffer for the Rules Engine.
    """
    now = time.time()
    with _nb_chat_lock:
        _nb_chat_times.append((now, response_ms, success))
        # Keep only last 100 chats (rolling window)
        if len(_nb_chat_times) > 100:
            _nb_chat_times.pop(0)
        if not success:
            _nb_chat_errors_1h.append(now)
        # Prune errors older than 1 hour
        cutoff = now - 3600
        while _nb_chat_errors_1h and _nb_chat_errors_1h[0] < cutoff:
            _nb_chat_errors_1h.pop(0)

def _nb_record_guard_trigger():
    """Called by _log when tag=='guard'. Tracks guard trigger rate."""
    now = time.time()
    with _nb_guard_lock:
        _nb_guard_triggers.append(now)
        cutoff = now - 3600
        while _nb_guard_triggers and _nb_guard_triggers[0] < cutoff:
            _nb_guard_triggers.pop(0)

def _nb_tune(variable: str, new_value, reason: str):
    """
    Apply a tuning change. Logs it to DB and in-memory.
    FIX 1: _nb_num_ctx/_nb_casual_ctx now also update _GUARD_MAX_CTX/_GUARD_CASUAL_CTX
    under _ctx_lock so that _guard_ollama_options actually enforces the brain's decisions.
    Previously NEXUS Brain context reductions had zero effect on Ollama inference.
    """
    global _GUARD_MAX_CTX, _GUARD_CASUAL_CTX
    var_map = {
        "_nb_crawl_delay":  lambda v: setattr_workaround("_nb_crawl_delay", v),
        "_nb_num_ctx":      lambda v: setattr_workaround("_nb_num_ctx", v),
        "_nb_casual_ctx":   lambda v: setattr_workaround("_nb_casual_ctx", v),
        "_nb_num_predict":  lambda v: setattr_workaround("_nb_num_predict", v),
    }
    old_value = globals().get(variable, "?")
    try:
        # Use globals() dict assignment — safer than exec(), no eval risk
        if variable in var_map:
            globals()[variable] = new_value
            # FIX 1: propagate context changes to the PERF_GUARD caps that Ollama actually reads
            if variable == "_nb_num_ctx":
                with _ctx_lock:
                    _GUARD_MAX_CTX = int(new_value)
            elif variable == "_nb_casual_ctx":
                with _ctx_lock:
                    _GUARD_CASUAL_CTX = int(new_value)
            ts = time.time()
            entry = (ts, variable, str(old_value), str(new_value), reason)
            _nb_tuning_log.append(entry)  # FIX M-2: deque(maxlen=200) auto-evicts oldest
            # Persist to DB
            try:
                _db_run(
                    "INSERT INTO brain_tuning(ts,variable,old_value,new_value,reason) VALUES(?,?,?,?,?)",
                    entry
                )
            except Exception: pass
            _log(f"[NEXUS] Tuned {variable}: {old_value} -> {new_value} ({reason})", "guard")
        else:
            log.warning(f"[NEXUS] Rejected tune of non-whitelisted variable: {variable}")
    except Exception as e:
        log.warning(f"[NEXUS] Tune error {variable}: {e}")

def setattr_workaround(name, value):
    """Helper — not actually called, exists to satisfy linting."""
    pass

def _nb_flag_anomaly(anomaly_type: str, detail: str):
    """Record an anomaly event. Auto-resolved when condition clears."""
    try:
        _db_run(
            "INSERT INTO brain_anomalies(ts,anomaly_type,detail) VALUES(?,?,?)",
            (time.time(), anomaly_type, detail)
        )
        _log(f"[NEXUS] Anomaly: {anomaly_type} — {detail}", "warn")
    except Exception: pass

def _nb_resolve_anomaly(anomaly_type: str):
    """Mark open anomalies of this type as resolved."""
    try:
        _db_run(
            "UPDATE brain_anomalies SET resolved_at=? WHERE anomaly_type=? AND resolved_at IS NULL",
            (time.time(), anomaly_type)
        )
    except Exception: pass

def _nb_get_avg_chat_ms(window_minutes: int = 10) -> float:
    """Return average chat response time over the last N minutes."""
    cutoff = time.time() - (window_minutes * 60)
    with _nb_chat_lock:
        recent = [ms for ts, ms, ok in _nb_chat_times if ts > cutoff and ok]
    return sum(recent) / len(recent) if recent else 0.0

def _nb_get_chat_count_1h() -> int:
    cutoff = time.time() - 3600
    with _nb_chat_lock:
        return sum(1 for ts, ms, ok in _nb_chat_times if ts > cutoff)

def _nb_get_chat_error_rate() -> float:
    with _nb_chat_lock:
        total = len(_nb_chat_times)
        errors = len(_nb_chat_errors_1h)
    return errors / max(total, 1)

def _nb_get_guard_triggers_1h() -> int:
    with _nb_guard_lock:
        return len(_nb_guard_triggers)

def _nb_get_crawl_stats() -> dict:
    """Return recent crawl success/failure rate from the queue table."""
    try:
        now = time.time()
        cutoff = now - 3600
        rows = _db_q(
            "SELECT status, COUNT(*) n FROM learn_queue "
            "WHERE finished_at > ? GROUP BY status", (cutoff,)
        )
        counts = {r["status"]: r["n"] for r in rows}
        done   = counts.get("done", 0)
        failed = counts.get("failed", 0) + counts.get("poisoned", 0)
        total  = done + failed
        return {
            "success_rate": done / max(total, 1),
            "done": done,
            "failed": failed,
            "total": total,
        }
    except Exception:
        return {"success_rate": 1.0, "done": 0, "failed": 0, "total": 0}

def _nb_sensor_loop():
    """
    Layer 1: SENSOR ENGINE
    Collects a metrics snapshot every 30 seconds and persists to brain_metrics.
    Completely passive — reads only, no decisions.
    """
    log.info("[NEXUS] Sensor engine started")
    while True:
        try:
            time.sleep(_NB_SENSOR_INTERVAL)
            now = time.time()

            crawl = _nb_get_crawl_stats()
            poison_count = 0
            try:
                r = _db_q("SELECT COUNT(*) n FROM learn_queue WHERE status='poisoned'")
                poison_count = r[0]["n"] if r else 0
            except Exception: pass

            with _nb_guard_lock:
                gtrig = len(_nb_guard_triggers)

            row = (
                now,
                round(_nb_get_avg_chat_ms(10), 0),
                _nb_get_chat_count_1h(),
                round(_nb_get_chat_error_rate(), 3),
                _kb_count(),
                round(crawl["success_rate"], 3),
                _lq_size(),
                poison_count,
                round(_get_cpu(), 1),
                round(_get_ram(), 1),
                1 if _ol_ok() else 0,
                _ol_model() or "",
                _nb_crawl_delay,
                _nb_num_ctx,
                gtrig,
            )
            _db_run(
                "INSERT INTO brain_metrics(ts,chat_ms_avg,chat_count_1h,chat_error_rate,"
                "kb_size,crawl_success_rate,queue_depth,poison_count,cpu_pct,ram_pct,"
                "ollama_ok,model_name,crawl_delay_secs,active_ctx,guard_triggers_1h) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                row
            )
            # Prune metrics older than 7 days
            _db_run("DELETE FROM brain_metrics WHERE ts < ?", (now - 604800,))

        except Exception as e:
            log.debug(f"[NEXUS-SENSOR] {e}")
            time.sleep(10)

def _nb_rules_loop():
    """
    Layer 2: RULES ENGINE
    Evaluates thresholds every 5 minutes and adjusts live variables.
    Deterministic — no LLM, no hallucinations, fully reversible.
    """
    global _nb_crawlers_paused
    log.info("[NEXUS] Rules engine started")

    # Track how long conditions have been continuously true
    _slow_chat_since:   float = 0.0
    _high_cpu_since:    float = 0.0
    _low_cpu_since:     float = 0.0
    _high_err_since:    float = 0.0
    _fast_chat_since:   float = 0.0

    while True:
        try:
            time.sleep(_NB_RULES_INTERVAL)
            now = time.time()

            avg_ms  = _nb_get_avg_chat_ms(10)
            cpu     = _get_cpu()
            crawl   = _nb_get_crawl_stats()
            q_depth = _lq_size()
            kb_sz   = _kb_count()

            # ── RULE 1: Chat is very slow — reduce context window ─────────
            if avg_ms > _NB_CHAT_SLOW_MS:
                if _slow_chat_since == 0: _slow_chat_since = now
                slow_dur = now - _slow_chat_since

                if avg_ms > _NB_CHAT_VERY_SLOW_MS and slow_dur > 1200:
                    # Very slow for 20+ min — aggressive reduction
                    if _nb_num_ctx > 2048:
                        _nb_tune("_nb_num_ctx", 2048,
                                 f"avg_chat_ms={avg_ms:.0f} for {slow_dur/60:.0f}min (very slow)")
                    if _nb_casual_ctx > 1536:
                        _nb_tune("_nb_casual_ctx", 1536,
                                 f"avg_chat_ms={avg_ms:.0f} (very slow — casual reduced)")
                    if _nb_num_predict > 256:
                        _nb_tune("_nb_num_predict", 256,
                                 f"avg_chat_ms={avg_ms:.0f} (reducing output tokens)")
                    _nb_flag_anomaly("slow_chat",
                                     f"avg={avg_ms:.0f}ms for {slow_dur/60:.0f}min")

                elif slow_dur > 600:
                    # Slow for 10+ min — moderate reduction
                    if _nb_num_ctx > 2048:
                        _nb_tune("_nb_num_ctx", 2048,
                                 f"avg_chat_ms={avg_ms:.0f} for {slow_dur/60:.0f}min")
            else:
                if _slow_chat_since > 0:
                    _nb_resolve_anomaly("slow_chat")
                _slow_chat_since = 0.0

            # ── RULE 2: Chat is fast — restore context toward defaults ────
            if avg_ms > 0 and avg_ms < _NB_CHAT_FAST_MS:
                if _fast_chat_since == 0: _fast_chat_since = now
                fast_dur = now - _fast_chat_since

                if fast_dur > 1800:  # fast for 30+ min
                    if _nb_num_ctx < 4096:
                        _nb_tune("_nb_num_ctx", min(_nb_num_ctx + 512, 4096),
                                 f"avg_chat_ms={avg_ms:.0f} — restoring ctx")
                    if _nb_casual_ctx < 2048:
                        _nb_tune("_nb_casual_ctx", min(_nb_casual_ctx + 256, 2048),
                                 f"avg_chat_ms={avg_ms:.0f} — restoring casual ctx")
                    if _nb_num_predict < 512:
                        _nb_tune("_nb_num_predict", min(_nb_num_predict + 128, 512),
                                 f"avg_chat_ms={avg_ms:.0f} — restoring predict")
                    _fast_chat_since = now  # reset so we don't restore every cycle
            else:
                _fast_chat_since = 0.0

            # ── RULE 3: High CPU — pause crawlers ──────────────────────────
            if cpu > _NB_CPU_HIGH:
                if _high_cpu_since == 0: _high_cpu_since = now
                high_dur = now - _high_cpu_since

                if high_dur > 300 and not _nb_crawlers_paused:
                    with _nb_lock: _nb_crawlers_paused = True
                    _nb_tune("_nb_crawl_delay", 120,
                             f"cpu={cpu:.0f}% for {high_dur/60:.0f}min — force-pause crawlers")
                    _nb_flag_anomaly("high_cpu", f"cpu={cpu:.0f}% sustained {high_dur/60:.0f}min")
                _low_cpu_since = 0.0
            else:
                if _high_cpu_since > 0:
                    _nb_resolve_anomaly("high_cpu")
                _high_cpu_since = 0.0

            # ── RULE 4: CPU normal — resume crawlers ───────────────────────
            if cpu < _NB_CPU_NORMAL and _nb_crawlers_paused:
                if _low_cpu_since == 0: _low_cpu_since = now
                low_dur = now - _low_cpu_since
                if low_dur > 600:  # normal for 10 min
                    with _nb_lock: _nb_crawlers_paused = False
                    _nb_tune("_nb_crawl_delay", CRAWL_DELAY_SECS,
                             f"cpu={cpu:.0f}% normal for {low_dur/60:.0f}min — resuming crawlers")
            elif cpu >= _NB_CPU_NORMAL:
                _low_cpu_since = 0.0

            # ── RULE 5: High crawl error rate — slow down ─────────────────
            if crawl["total"] > 5 and crawl["success_rate"] < _NB_CRAWL_ERR_HIGH:
                if _high_err_since == 0: _high_err_since = now
                err_dur = now - _high_err_since
                if err_dur > 600 and _nb_crawl_delay < 60:
                    _nb_tune("_nb_crawl_delay", min(_nb_crawl_delay * 2, 90),
                             f"crawl_success={crawl['success_rate']:.0%} for {err_dur/60:.0f}min")
                    _nb_flag_anomaly("high_crawl_errors",
                                     f"success={crawl['success_rate']:.0%} done={crawl['done']} failed={crawl['failed']}")
            else:
                if _high_err_since > 0:
                    _nb_resolve_anomaly("high_crawl_errors")
                _high_err_since = 0.0

            # ── RULE 6: Queue empty and KB small — refill ─────────────────
            if q_depth == 0 and kb_sz < 300:
                try:
                    _queue_refill()
                    _log(f"[NEXUS] Queue refilled (depth=0, kb={kb_sz})", "info")
                except Exception: pass

            # ── RULE 7: Too many guard triggers — flag anomaly ────────────
            gtrig = _nb_get_guard_triggers_1h()
            if gtrig > 20:
                _nb_flag_anomaly("guard_storm",
                                 f"{gtrig} guard triggers in 1h — something systematic is wrong")

            # ── RULE 8: Crawl delay restoration ──────────────────────────
            # If crawl error rate has been fine and delay was manually increased, restore it
            if (crawl["success_rate"] > 0.90 and crawl["total"] > 10
                    and _nb_crawl_delay > CRAWL_DELAY_SECS
                    and not _nb_crawlers_paused):
                if _nb_crawl_delay > CRAWL_DELAY_SECS + 5:
                    _nb_tune("_nb_crawl_delay", max(_nb_crawl_delay - 10, CRAWL_DELAY_SECS),
                             f"crawl_success={crawl['success_rate']:.0%} — restoring delay")

        except Exception as e:
            log.debug(f"[NEXUS-RULES] {e}")
            time.sleep(30)

def _nb_build_digest() -> str:
    """Build a compact performance digest for the Insight Engine."""
    try:
        avg_ms   = _nb_get_avg_chat_ms(240)   # 4h window
        count    = _nb_get_chat_count_1h()
        err_rate = _nb_get_chat_error_rate()
        kb_sz    = _kb_count()
        crawl    = _nb_get_crawl_stats()
        cpu      = _get_cpu()
        ram      = _get_ram()
        gtrig    = _nb_get_guard_triggers_1h()

        # Recent tuning changes
        tuning_str = "none"
        if _nb_tuning_log:
            last_3 = _nb_tuning_log[-3:]
            tuning_str = "; ".join(f"{v}:{o}->{n}" for _, v, o, n, _ in last_3)

        # Open anomalies
        anomalies = []
        try:
            rows = _db_q(
                "SELECT anomaly_type, detail FROM brain_anomalies "
                "WHERE resolved_at IS NULL ORDER BY ts DESC LIMIT 5"
            )
            anomalies = [f"{r['anomaly_type']}({r['detail'][:40]})" for r in rows]
        except Exception: pass

        model = _ol_model() or "none"
        return (
            f"model={model} "
            f"avg_chat_ms={avg_ms:.0f} "
            f"chat_count_4h={count} "
            f"chat_error_rate={err_rate:.0%} "
            f"kb_size={kb_sz} "
            f"crawl_success={crawl['success_rate']:.0%} "
            f"queue_depth={_lq_size()} "
            f"cpu={cpu:.0f}% "
            f"ram={ram:.0f}% "
            f"guard_triggers_1h={gtrig} "
            f"tuning_changes=[{tuning_str}] "
            f"open_anomalies=[{', '.join(anomalies) or 'none'}]"
        )
    except Exception as e:
        return f"digest_error={e}"

def _nb_insight_loop():
    """
    Layer 3: INSIGHT ENGINE
    Asks local Ollama for a plain-English health summary every 4 hours.
    NEVER modifies any live variables — purely explanatory.
    Rate-limited: skips if fewer than _NB_INSIGHT_MIN_CHATS happened.
    """
    global _nb_last_insight_ts
    log.info("[NEXUS] Insight engine started")

    # Stagger first run by 30 minutes after startup
    time.sleep(1800)

    while True:
        try:
            now = time.time()
            since_last = now - _nb_last_insight_ts

            if since_last < _NB_INSIGHT_INTERVAL:
                time.sleep(300)
                continue

            # Only run if there's been meaningful activity
            if _nb_get_chat_count_1h() < _NB_INSIGHT_MIN_CHATS:
                time.sleep(600)
                continue

            if not _ol_ok():
                time.sleep(300)
                continue

            digest = _nb_build_digest()
            model  = _ol_model() or DEFAULT_MODEL

            prompt = (
                "You are NEXUS BRAIN, the health monitor for Butler AI server. "
                "Analyze this 4-hour performance digest and respond in exactly 3 sentences: "
                "(1) Overall system health. (2) Main concern or notable pattern. "
                "(3) One specific recommendation for the user.\n\n"
                f"DIGEST: {digest}\n\n"
                "Be direct and specific. Use the actual numbers. "
                "Do not repeat the digest back. Just your 3-sentence analysis."
            )

            # Use the same _ol_chat function but with a minimal context
            insight = _ol_chat(
                prompt,
                system=(
                    "You are a technical system health monitor. "
                    "You respond in exactly 3 sentences. "
                    "You are factual, specific, and brief. "
                    "You never refuse or add disclaimers."
                ),
                model_override=model,
            )

            if insight and len(insight) > 20 and not insight.startswith("[Ollama"):
                _db_run(
                    "INSERT INTO brain_insights(ts,period_hours,digest,insight,model_used) VALUES(?,?,?,?,?)",
                    (now, 4.0, digest, insight, model)
                )
                _nb_last_insight_ts = now
                _log(f"[NEXUS] Insight recorded: {insight[:120]}...", "ok")
                # Keep only last 50 insights
                _db_run(
                    "DELETE FROM brain_insights WHERE id NOT IN "
                    "(SELECT id FROM brain_insights ORDER BY ts DESC LIMIT 50)"
                )
            else:
                log.debug("[NEXUS] Insight skipped — response too short or errored")

        except Exception as e:
            log.debug(f"[NEXUS-INSIGHT] {e}")

        time.sleep(600)  # check every 10 min whether it's time to run

def _nb_get_status() -> dict:
    """Return current brain state for the /api/nexus_brain/status endpoint."""
    try:
        latest_insight = None
        try:
            rows = _db_q(
                "SELECT ts, insight, model_used FROM brain_insights ORDER BY ts DESC LIMIT 1"
            )
            if rows:
                latest_insight = {
                    "ts": rows[0]["ts"],
                    "insight": rows[0]["insight"],
                    "model": rows[0]["model_used"],
                }
        except Exception: pass

        open_anomalies = []
        try:
            rows = _db_q(
                "SELECT anomaly_type, detail, ts FROM brain_anomalies "
                "WHERE resolved_at IS NULL ORDER BY ts DESC LIMIT 10"
            )
            open_anomalies = [dict(r) for r in rows]
        except Exception: pass

        recent_tuning = []
        try:
            rows = _db_q(
                "SELECT ts, variable, old_value, new_value, reason "
                "FROM brain_tuning ORDER BY ts DESC LIMIT 10"
            )
            recent_tuning = [dict(r) for r in rows]
        except Exception: pass

        with _nb_lock:
            current_settings = {
                "crawl_delay_secs": _nb_crawl_delay,
                "num_ctx":          _nb_num_ctx,
                "casual_ctx":       _nb_casual_ctx,
                "num_predict":      _nb_num_predict,
                "crawlers_paused":  _nb_crawlers_paused,
            }

        return {
            "status":          "running",
            "avg_chat_ms_10m": round(_nb_get_avg_chat_ms(10), 0),
            "avg_chat_ms_1h":  round(_nb_get_avg_chat_ms(60), 0),
            "chat_count_1h":   _nb_get_chat_count_1h(),
            "chat_error_rate": round(_nb_get_chat_error_rate(), 3),
            "guard_triggers_1h": _nb_get_guard_triggers_1h(),
            "crawl_stats":     _nb_get_crawl_stats(),
            "current_settings": current_settings,
            "latest_insight":  latest_insight,
            "open_anomalies":  open_anomalies,
            "recent_tuning":   recent_tuning,
            "next_insight_in": max(0, _NB_INSIGHT_INTERVAL - (time.time() - _nb_last_insight_ts)),
        }
    except Exception as e:
        return {"status": "error", "error": str(e)}

def _nb_reset_tuning() -> dict:
    """
    Safety valve: revert all brain tuning to hardcoded defaults.
    Called by POST /api/nexus_brain/reset_tuning.
    """
    global _nb_crawl_delay, _nb_num_ctx, _nb_casual_ctx, _nb_num_predict, _nb_crawlers_paused
    global _GUARD_MAX_CTX, _GUARD_CASUAL_CTX
    now = time.time()
    changes = []
    if _nb_crawl_delay != CRAWL_DELAY_SECS:
        changes.append(f"crawl_delay {_nb_crawl_delay}->{CRAWL_DELAY_SECS}")
        _nb_crawl_delay = CRAWL_DELAY_SECS
    if _nb_num_ctx != 4096:
        changes.append(f"num_ctx {_nb_num_ctx}->4096")
        with _nb_lock: _nb_num_ctx = 4096
        with _ctx_lock: _GUARD_MAX_CTX = 4096      # FIX 1: keep PERF_GUARD in sync
    if _nb_casual_ctx != 2048:
        changes.append(f"casual_ctx {_nb_casual_ctx}->2048")
        with _nb_lock: _nb_casual_ctx = 2048
        with _ctx_lock: _GUARD_CASUAL_CTX = 2048   # FIX 1: keep PERF_GUARD in sync
    if _nb_num_predict != 512:
        changes.append(f"num_predict {_nb_num_predict}->512")
        with _nb_lock: _nb_num_predict = 512
    if _nb_crawlers_paused:
        changes.append("crawlers unpaused")
        with _nb_lock: _nb_crawlers_paused = False

    if changes:
        reason = "manual reset via API"
        _db_run(
            "INSERT INTO brain_tuning(ts,variable,old_value,new_value,reason) VALUES(?,?,?,?,?)",
            (now, "ALL", "tuned", "defaults", reason)
        )
        _log(f"[NEXUS] Tuning reset to defaults: {', '.join(changes)}", "heal")
        return {"status": "ok", "reset": changes}
    return {"status": "ok", "reset": [], "message": "already at defaults"}

def _nb_start():
    """Start all three NEXUS BRAIN engines. Called at server startup."""
    _nb_db_init()
    threading.Thread(target=_nb_sensor_loop,  daemon=True, name="nexus-sensor").start()
    threading.Thread(target=_nb_rules_loop,   daemon=True, name="nexus-rules").start()
    threading.Thread(target=_nb_insight_loop, daemon=True, name="nexus-insight").start()
    _log("[NEXUS] BRAIN started — sensor/rules/insight engines running", "ok")

# ── CPU GUARD: Ollama-aware performance management ──────
# When Ollama is processing, crawlers FULLY PAUSE (not just slow down).
# When CPU > 90%, crawlers FULLY PAUSE regardless.
# This prevents the "100% CPU" problem customers see.
_ollama_busy = False     # Set True while Ollama is processing a chat
_perf_mode   = "auto"    # "auto" | "performance" | "battery"

# Chat dedup: tracks last message hash per device to prevent double-sends
_chat_last_hash: dict = {}   # device_id -> (hash, ts)
_chat_dedup_lock = threading.Lock()
_CHAT_DEDUP_WINDOW = 8       # seconds — ignore same message within this window

def _chat_is_duplicate(device_id: str, message: str) -> bool:
    """
    Returns True if this exact message was sent by this device within the
    dedup window. Prevents double-sends from app retries hitting twice.
    """
    h = hashlib.sha256(message.encode()).hexdigest()  # SEC-FIX: md5→sha256 (dedup hash)
    now = time.time()
    with _chat_dedup_lock:
        last = _chat_last_hash.get(device_id)
        if last and last[0] == h and now - last[1] < _CHAT_DEDUP_WINDOW:
            return True
        _chat_last_hash[device_id] = (h, now)
    return False
# performance = crawlers run full speed, auto = adaptive, battery = crawlers paused

# ── Global state for SIGMA-NET learning engine ──────────
_session_articles = 0          # Articles learned this session

# ── Pre-compute thread count once at startup (Perf D) ────────────────────────
_NUM_THREAD = max(2, (os.cpu_count() or 4) - 2)   # reserve 2 cores for server/OS

# ── Response cache: identical questions return instantly without hitting Ollama ─
# Key: sha256(model+intent+msg)  Value: (reply_str, ts)
# v12: TTL varies by intent — scripts cache longer (10min), greetings very short (30s)
import collections as _collections
# FIX 1: Use OrderedDict for O(1) LRU eviction instead of O(n log n) sorted() under lock.
_REPLY_CACHE: _collections.OrderedDict = _collections.OrderedDict()
_REPLY_CACHE_LOCK = threading.Lock()
_REPLY_CACHE_TTL  = 300   # seconds (default technical responses)
_REPLY_CACHE_MAX  = 500   # max entries (raised 200→500; still <2 MB RAM, big hit-rate win)

# Per-intent TTLs: how long to cache each type of response
# Stable intents bumped: scripts/install instructions rarely change minute-to-minute.
_REPLY_CACHE_INTENT_TTL = {
    "greeting":     30,    # greetings go stale fast (context-dependent)
    "casual":       60,    # chitchat: short TTL
    "script":       1800,  # scripts: cache 30 min (raised 600→1800; same code, same result)
    "install":      1800,  # install instructions: stable (raised 600→1800)
    "troubleshoot": 300,   # fix steps: moderate TTL (raised 180→300)
    "explain":      600,   # explanations: 10 min (raised 300→600)
    "question":     300,   # Q&A: 5 min (raised 180→300)
    "general":      300,   # general: 5 min (raised 180→300)
}

def _reply_cache_norm(msg: str) -> str:
    """Normalize a chat message for cache-key hashing so trivial variants collide.
    Lower-cases, collapses whitespace, strips trailing punctuation. Cheap, deterministic,
    and dramatically raises hit rate (e.g. 'Fix my PC', 'fix my pc!', ' fix my pc '
    now share a key)."""
    import re as _re
    s = (msg or "").strip().lower()
    s = _re.sub(r"\s+", " ", s)
    s = s.rstrip(" .!?,;:")
    return s[:500]

def _reply_cache_get(model: str, msg: str, intent: str = "general"):
    """Return cached reply str or None. Skips errors/timeouts.
    v12: uses intent for cache key and per-intent TTL.
    v19.0.13: normalizes msg before hashing for higher hit rate.
    """
    key = hashlib.sha256(f"{model}|{intent}|{_reply_cache_norm(msg)}".encode()).hexdigest()
    ttl = _REPLY_CACHE_INTENT_TTL.get(intent, _REPLY_CACHE_TTL)
    with _REPLY_CACHE_LOCK:
        entry = _REPLY_CACHE.get(key)
        if not entry:
            try: _smart_record_cache(False)
            except Exception: pass
            return None
        reply, ts = entry
        if time.time() - ts > ttl:
            del _REPLY_CACHE[key]
            try: _smart_record_cache(False)
            except Exception: pass
            return None
        try: _smart_record_cache(True)
        except Exception: pass
        return reply

def _reply_cache_set(model: str, msg: str, intent: str, reply: str) -> None:
    """Cache a successful reply. Never caches errors or empty responses.
    v12: uses intent for cache key.
    """
    # FIX 5: Old code used reply.startswith("[") which silently dropped valid AI replies
    # that begin with a markdown link like "[link text](url)" or "[CONVERSATION SUMMARY]".
    # Now only skip the specific error/empty sentinel strings.
    _CACHE_SKIP_PREFIXES = ("[Ollama error]", "[EMPTY_RESPONSE]", "[Note: answered using")
    if not reply or any(reply.startswith(p) for p in _CACHE_SKIP_PREFIXES) or reply.startswith("Butler AI"):
        return
    # FIX 8: Exclude both "greeting" and "casual" intents from the reply cache.
    # Casual replies ("ok cool!", "thanks") are context-sensitive and meaningless
    # when returned to a different device/user asking the same words.
    if intent in ("greeting", "casual"):
        return
    key = hashlib.sha256(f"{model}|{intent}|{_reply_cache_norm(msg)}".encode()).hexdigest()
    with _REPLY_CACHE_LOCK:
        # FIX 1: O(1) LRU eviction — pop from front of OrderedDict (oldest inserted).
        # Previously used sorted() over entire dict under lock — O(n log n) per request.
        while len(_REPLY_CACHE) >= _REPLY_CACHE_MAX:
            _REPLY_CACHE.popitem(last=False)
        # Insert at end (most-recently-used position); move_to_end handles update case.
        _REPLY_CACHE[key] = (reply, time.time())
        _REPLY_CACHE.move_to_end(key)

# ─── SSE RESUME / RECONNECT INFRASTRUCTURE ────────────────────────────────
# Lets clients survive transient network drops mid-stream. The server keeps a
# per-resumeId buffer of emitted SSE events (numbered 1..N). On reconnect the
# client sends the same resumeId plus the standard `Last-Event-ID` header; the
# server replays events past that id, then continues streaming new ones as
# generation proceeds. Generation itself keeps running even after the original
# socket dies, so nothing is lost.
class _StreamResumeBuf:
    __slots__ = ("tokens", "final", "done", "ts", "cond", "max_tokens")
    def __init__(self):
        self.tokens = []           # list[str] — each entry is one SSE "token" event payload
        self.final  = None         # str — final SSE event JSON payload (no id)
        self.done   = False
        self.ts     = time.time()
        self.cond   = threading.Condition()
        self.max_tokens = 4000     # hard cap; absurdly long generations stop being resumable

    def append_token(self, token_payload: str) -> int:
        with self.cond:
            if len(self.tokens) >= self.max_tokens:
                # Drop oldest to keep memory bounded; resume past this point will be lossy
                self.tokens.pop(0)
            self.tokens.append(token_payload)
            self.ts = time.time()
            self.cond.notify_all()
            return len(self.tokens)  # 1-based event id

    def set_final(self, final_payload: str) -> None:
        with self.cond:
            self.final = final_payload
            self.done  = True
            self.ts   = time.time()
            self.cond.notify_all()

    def snapshot_after(self, last_id: int):
        with self.cond:
            start = max(0, last_id)
            return list(self.tokens[start:]), self.final, self.done, len(self.tokens)

    def wait_for_change(self, last_id: int, timeout: float) -> bool:
        with self.cond:
            if self.done or len(self.tokens) > last_id:
                return True
            self.cond.wait(timeout=timeout)
            return self.done or len(self.tokens) > last_id

_STREAM_RESUME: dict = {}
_STREAM_RESUME_LOCK = threading.Lock()
_STREAM_RESUME_TTL = 120  # seconds — generous window for mobile network blips
_STREAM_RESUME_MAX = 64   # cap concurrent resumable streams

def _stream_resume_get(resume_id: str):
    # Bulletproof: never raise — None is the well-defined "nothing to resume" signal
    try:
        if not resume_id or not isinstance(resume_id, str): return None
        if len(resume_id) > 128: return None  # cap to prevent abuse
        with _STREAM_RESUME_LOCK:
            return _STREAM_RESUME.get(resume_id)
    except Exception:
        return None

def _stream_resume_create(resume_id: str) -> "_StreamResumeBuf":
    """Create-or-replace a resume buffer for this resumeId. Never raises."""
    try:
        if not isinstance(resume_id, str) or not resume_id:
            return _StreamResumeBuf()  # detached buffer (won't be tracked)
        if len(resume_id) > 128:
            return _StreamResumeBuf()
        with _STREAM_RESUME_LOCK:
            now = time.time()
            stale = [k for k, b in _STREAM_RESUME.items() if now - b.ts > _STREAM_RESUME_TTL]
            for k in stale: _STREAM_RESUME.pop(k, None)
            if len(_STREAM_RESUME) >= _STREAM_RESUME_MAX:
                try:
                    oldest = min(_STREAM_RESUME.items(), key=lambda kv: kv[1].ts)[0]
                    _STREAM_RESUME.pop(oldest, None)
                except Exception:
                    _STREAM_RESUME.clear()
            buf = _StreamResumeBuf()
            _STREAM_RESUME[resume_id] = buf
            return buf
    except Exception:
        return _StreamResumeBuf()

def _stream_resume_parse_last_id(handler) -> int:
    """Parse the `Last-Event-ID` request header (SSE standard) into an int."""
    try:
        raw = handler.headers.get("Last-Event-ID") or handler.headers.get("last-event-id") or "0"
        n = int(str(raw).strip() or "0")
        return n if n > 0 else 0
    except Exception:
        return 0


# Module-level chat executor — reused across requests to avoid 1s startup cost per chat
import concurrent.futures as _cf_init
_chat_pool = _cf_init.ThreadPoolExecutor(max_workers=4, thread_name_prefix="chat-worker")  # FIX BUG-C12 (audit): 2 workers + blocking waiters could starve HTTP threads
_learning_active  = False      # True while workers are actively crawling
_sigma_stats      = {"articles": 0, "last": "idle", "errors": 0, "session": 0}
_session_start    = 0          # Timestamp when learning session began

def _learn_worker(worker_id: int):
    """
    Continuous learning worker thread. Runs forever.
    Claims URLs from the persistent queue, crawls them, saves to KB.
    Saves a checkpoint every 15 minutes.
    Refills the queue when it runs low.
    """
    global _session_articles, _learning_active
    last_checkpoint = time.time()

    log.info(f"[ΣNET-WORKER-{worker_id}] BOTER Knowledge Engine started")

    while True:
        try:
            # ── CPU GUARD: pause crawling when AI chat is under load ──
            # Uses shared snapshot (updated every 5s) — no inline psutil call
            _cpu_snap = _get_cpu()
            _ram_snap  = _get_ram()
            if _cpu_snap > CPU_PAUSE_CRAWLERS:
                _wait = 45 if _cpu_snap > 80 else 20
                time.sleep(_wait)
                continue
            if _ram_snap > RAM_PAUSE_CRAWLERS:
                time.sleep(25)
                continue

            # ── Checkpoint every 15 minutes ─────────────────────
            if time.time() - last_checkpoint >= CHECKPOINT_SECS:
                _checkpoint_save()
                last_checkpoint = time.time()

            # ── Refill queue if running low ──────────────────────
            if _lq_size() < QUEUE_LOW_WATER:
                _queue_refill()
                # If still empty after refill, pause and retry
                if _lq_size() == 0:
                    time.sleep(30)
                    continue

            # ── Claim next URL ───────────────────────────────────
            item = _lq_next(worker_id)
            if not item:
                time.sleep(5)
                continue

            url      = item["url"]
            category = item["category"]
            try: kw = json.loads(item.get("keywords", "[]"))
            except: kw = []

            # ── CPU check right before crawl (uses snapshot) ─────
            if _get_cpu() > 55:
                _lq_done(url, ok=False)  # return URL to queue
                time.sleep(20)
                continue

            # ── Crawl and save ───────────────────────────────────
            _learning_active = True
            # v19.0.19: thread queue's source through so seed URLs are gated by license
            _src_type = "public-seed" if str(item.get("source","")).startswith("public-kb-seed") else "crawl"
            result = _crawl_and_save(url, category, kw, source_type=_src_type)

            if result.get("ok"):
                _lq_done(url, ok=True)
                _session_articles += 1
                _kb_count(force=True)
                # ΣNET proprietary growth tracking
                _sigma_log_growth(category, item.get("source", "SIGMA-NET"))

                # ── SMART SNOWBALL: follow relevant discovered links ──
                # Domains worth following for computer/automation knowledge
                GOOD_DOMAINS = {
                    "docs.python.org", "realpython.com", "docs.microsoft.com",
                    "learn.microsoft.com", "geeksforgeeks.org", "stackoverflow.com",
                    "github.com", "pypi.org", "readthedocs.io", "howtogeek.com",
                    "bleepingcomputer.com", "tenforums.com", "elevenforum.com",
                    "superuser.com", "answers.microsoft.com", "ss64.com",
                    "adamtheautomator.com", "devblogs.microsoft.com", "thewindowsclub.com",
                    "computerhope.com", "makeuseof.com", "lifewire.com", "pcmag.com",
                }
                SKIP_PATTERNS = {
                    "login", "signup", "register", "cart", "checkout",
                    "account", "billing", "pricing", "subscribe", "ads",
                    ".pdf", ".zip", ".exe", ".msi", "mailto:", "javascript:",
                }
                new_links = 0
                for link in result.get("links", [])[:20]:
                    if not link.startswith("http"): continue
                    if any(p in link.lower() for p in SKIP_PATTERNS): continue
                    domain = link.split("/")[2] if len(link.split("/")) > 2 else ""
                    # Only follow links from trusted knowledge domains
                    if not any(d in domain for d in GOOD_DOMAINS): continue
                    existing = _db_q("SELECT url FROM knowledge_base WHERE url=?", (link,))
                    queued   = _db_q("SELECT url FROM learn_queue WHERE url=?", (link,))
                    if not existing and not queued:
                        _lq_add(link, category, kw, priority=4, source="snowball")
                        new_links += 1
                        if new_links >= 8: break  # max 8 new links per page

                # ── TOPIC EXPANSION: search for more on this topic ───
                # Every 10th article triggers a DuckDuckGo search for related content
                if _session_articles % 10 == 0 and kw:
                    topic = " ".join(kw[:3])
                    _lq_add(
                        f"https://duckduckgo.com/html/?q={urllib.parse.quote(topic)}+python+automation",
                        category, kw, priority=5, source="topic-expand"
                    )

                # ── KB MILESTONES: log growth milestones ────────────
                total = _kb_count()
                milestones = [50, 100, 250, 500, 1000, 2500, 5000, 10000]
                for m in milestones:
                    if total == m:
                        _log(f"🎉 KB milestone: {m} articles! Butler AI keeps growing.", "ok")
                        break

                # ── AUTO-CATEGORIZE: update category if generic ──────
                if category in ("General", "Unknown") and kw:
                    # Re-categorize based on keywords
                    cat_map = {
                        "driver": "Drivers", "bsod": "BSOD", "blue screen": "BSOD",
                        "firewall": "Security", "virus": "Security", "malware": "Security",
                        "network": "Network", "wifi": "Network", "tcp": "Network",
                        "python": "Python", "script": "Scripts", "automate": "Automation",
                        "windows": "Windows", "registry": "Registry", "boot": "Boot",
                        "disk": "Storage", "ram": "RAM", "cpu": "System", "gpu": "GPU",
                        "error": "Errors", "fix": "Windows", "install": "Software",
                    }
                    for keyword, cat in cat_map.items():
                        if any(keyword in k.lower() for k in kw):
                            category = cat
                            break

            else:
                _lq_done(url, ok=False)
            _learning_active = _lq_size() > 0

            # ── CPU GUARD: Pause crawlers when system is under load ──
            # Priority: Ollama AI chat > User's apps > Crawlers
            # Crawlers are the LOWEST priority — they pause completely when needed
            adaptive_delay = CRAWL_DELAY_SECS

            # Battery mode = crawlers fully disabled
            if _perf_mode == "battery":
                time.sleep(60)
                continue

            # If Ollama is actively processing a chat → FULL STOP
            if _ollama_busy:
                time.sleep(15)
                continue

            try:
                if HAS_PSUTIL:
                    cpu = _get_cpu()
                    ram = _get_ram()

                    if cpu > 90 or ram > 95:
                        # CRITICAL: CPU maxed — FULL PAUSE, don't add ANY load
                        time.sleep(60)
                        continue
                    elif cpu > 75 or ram > 90:
                        adaptive_delay = 45   # Heavy load — very slow crawling
                    elif cpu > 50 or ram > 80:
                        adaptive_delay = 20   # Moderate load — slow down
                    elif cpu > 30:
                        adaptive_delay = 10   # Light load — gentle crawling
                    # CPU < 30% → use normal 5s delay (system is idle)
            except Exception:
                pass
            time.sleep(adaptive_delay)

        except Exception as e:
            log.debug(f"[LEARN-{worker_id}] Error: {e}")
            time.sleep(5)

