# ── Trick 19: slow chat persistent log ─────────────────────────────────────
_SLOW_LOG_PATH = Path(__file__).parent / "butler_slow_chats.log"

def _log_slow_chat(model, elapsed, msg, ctx, is_casual, cpu, ram):
    """Trick 19: append one-line slow chat record for offline debugging."""
    try:
        ts   = time.strftime("%Y-%m-%d %H:%M:%S")
        line = (f"{ts} | {elapsed:.1f}s | model={model} | ctx={ctx} | "
                f"casual={is_casual} | cpu={cpu:.0f}% | ram={ram:.0f}% | "
                f"msg={msg[:60]!r}\n")
        with open(_SLOW_LOG_PATH, "a", encoding="utf-8") as f:
            f.write(line)
    except Exception:
        pass

# ── Trick 18: per-device chat stats ────────────────────────────────────────
def _chat_stats_record(device_id: str, elapsed_ms: int, is_err: bool):
    """Trick 18: upsert one row per device with running totals."""
    try:
        _db_run("""
            INSERT INTO chat_stats(device_id, total_msgs, total_ms,
                                   avg_ms, last_msg_ts, errors)
            VALUES(?, 1, ?, ?, ?, ?)
            ON CONFLICT(device_id) DO UPDATE SET
                total_msgs  = total_msgs + 1,
                total_ms    = total_ms   + excluded.total_ms,
                avg_ms      = CAST(total_ms + excluded.total_ms AS REAL)
                              / (total_msgs + 1),
                last_msg_ts = excluded.last_msg_ts,
                errors      = errors + excluded.errors
        """, (device_id, elapsed_ms, elapsed_ms,
              time.time(), 1 if is_err else 0))
    except Exception as e:
        log.debug(f"[STATS] record error: {e}")

# ── Heal 15: model warm-up thread ──────────────────────────────────────────
def _warmup_model():
    """
    Heal 15: pre-loads the active model into VRAM after startup.
    Uses num_predict=1 so it generates almost nothing.
    Eliminates the 20-60s cold-start delay on the first real message.
    """
    time.sleep(8)    # wait for Ollama to stabilize after starting
    model = _get_active_model()
    if not model:
        log.info("[WARMUP] No model available yet — skipping warm-up")
        return
    try:
        payload = json.dumps({
            "model":      model,
            "messages":   [{"role": "user", "content": "hi"}],
            "stream":     False,
            "keep_alive": "30m",
            "options":    {"num_ctx": 512, "num_predict": 1,
                           "temperature": 0, "num_gpu": 99},
        }).encode()
        req = _urllib_req.Request(
            f"{OLLAMA_URL}/api/chat",
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with _urllib_req.urlopen(req, timeout=90) as r:
            r.read()
        _log(f"[WARMUP] ✅ {model} pre-loaded — first user message will be fast", "ok")
    except Exception as e:
        _log(f"[WARMUP] Warm-up skipped (non-critical): {e}", "warn")

# ── Perf E: GPU inference detection ────────────────────────────────────────
def _check_gpu_inference():
    """Perf E: detect if Ollama is using GPU or silently falling back to CPU."""
    time.sleep(10)   # wait for Ollama to stabilize
    try:
        with _urllib_req.urlopen(f"{OLLAMA_URL}/api/ps", timeout=5) as r:
            data = json.loads(r.read())
        for m in data.get("models", []):
            gpu_vram = m.get("size_vram", 0)
            name     = m.get("name", "unknown")
            if gpu_vram == 0:
                _log(f"[PERF] ⚠ Model '{name}' running on CPU only — "
                     f"GPU acceleration not available. Responses will be slow.", "warn")
            else:
                _log(f"[PERF] ✅ GPU active — {name} using {gpu_vram//1048576}MB VRAM", "ok")
    except Exception:
        pass

# ── Trick 20: scheduled model pre-load ─────────────────────────────────────
def _scheduled_preload():
    """Trick 20: pre-load model at 08:55 so 09:00 responses are instant."""
    last_preload_date = ""
    while True:
        time.sleep(60)
        now   = time.localtime()
        today = time.strftime("%Y-%m-%d")
        if now.tm_hour == 8 and now.tm_min == 55 and today != last_preload_date:
            last_preload_date = today
            threading.Thread(target=_warmup_model, daemon=True,
                             name="scheduled-warmup").start()
            _log("[AUTO] 🤖 Scheduled pre-load at 08:55 — model ready for 09:00", "ok")

def _watchdog():
    """
    BOTER System Watchdog — monitors and auto-restarts ALL critical threads.
    Self-healing: if any essential thread dies, it is restarted automatically.
    Checks every 60 seconds.
    
    Monitors: ollama-cache, ip-cache, learn workers, sigma loop, beacon,
              HTTP server, DB health, queue health, Ollama process, memory usage.
    """
    log.info("[WATCHDOG] BOTER self-healing watchdog started")
    _heal_count   = 0
    _heal_window  = []   # timestamps of heals in last 5 min — detect runaway restarts

    while True:
        try:
            time.sleep(60)
            running = {t.name for t in threading.enumerate()}

            # ── Heal: Ollama cache refresher ─────────────────────
            if "ollama-cache" not in running:
                log.warning("[WATCHDOG] ollama-cache thread died — restarting")
                threading.Thread(target=_ol_cache_refresh, daemon=True,
                                 name="ollama-cache").start()
                _heal_count += 1

            # ── Heal: IP cache refresher ──────────────────────────
            if "ip-cache" not in running:
                log.warning("[WATCHDOG] ip-cache thread died — restarting")
                threading.Thread(target=_refresh_ip_cache, daemon=True,
                                 name="ip-cache").start()
                _heal_count += 1

            # ── Heal: SIGMA-NET learning workers ──────────────────
            learn_workers = [t for t in threading.enumerate()
                             if t.name.startswith("learn-")]
            if len(learn_workers) < WORKER_THREADS:
                missing = WORKER_THREADS - len(learn_workers)
                log.warning(f"[WATCHDOG] {missing} learn worker(s) died — restarting")
                existing_ids = {int(t.name.split("-")[1]) for t in learn_workers
                                if t.name.split("-")[1].isdigit()}
                for wid in range(WORKER_THREADS):
                    if wid not in existing_ids:
                        # v9: guard against duplicate thread spawn
                        _alive_names = {t.name for t in threading.enumerate()}
                        if f"learn-{wid}" not in _alive_names:
                            threading.Thread(target=_learn_worker, args=(wid,),
                                             daemon=True, name=f"learn-{wid}").start()
                            log.info(f"[WATCHDOG] Restarted learn-{wid}")
                _heal_count += 1

            # ── Heal: SIGMA-NET main loop ─────────────────────────
            if "sigma" not in running:
                log.warning("[WATCHDOG] sigma loop died — restarting")
                threading.Thread(target=_sigma_loop, daemon=True, name="sigma").start()
                _heal_count += 1

            # ── Heal: Prune unbounded tables ──────────────────────
            # script_feedback, sigma_growth_log, user_topics grow forever without pruning
            try:
                # Keep only last 90 days of sigma growth log
                _db_run("DELETE FROM sigma_growth_log WHERE ts < ?", (time.time() - 90 * 86400,))
                # Keep only last 1000 script feedback rows per device (oldest first)
                _db_run(
                    "DELETE FROM script_feedback WHERE id NOT IN "
                    "(SELECT id FROM script_feedback ORDER BY id DESC LIMIT 1000)"
                )
                # Prune user_topics: keep top 500 by asks, drop stale long-tail entries
                _db_run(
                    "DELETE FROM user_topics WHERE id NOT IN "
                    "(SELECT id FROM user_topics ORDER BY asks DESC LIMIT 500)"
                )
            except Exception as _pe:
                log.debug(f"[WATCHDOG] Table prune error: {_pe}")

            # ── Guard: _CONN_COUNT drift ──────────────────────────
            _guard_conn_count_sanity()

            # ── Heal: PERF_GUARD watchdog ─────────────────────────
            if "perf-guard" not in running:
                log.warning("[WATCHDOG] perf-guard thread died — restarting")
                _guard_start_watchdog()
                _heal_count += 1

            # ── Heal: UDP beacon (auto-discovery) ─────────────────
            if "beacon" not in running:
                # Only restart if we have the IP and port
                try:
                    port = _gs("server_port")
                    ip = get_ip()
                    if port and ip:
                        log.warning("[WATCHDOG] beacon thread died — restarting")
                        threading.Thread(target=_beacon, args=(ip, int(port)),
                                         daemon=True, name="beacon").start()
                        _heal_count += 1
                except: pass

            # ── Heal: DB connection test ───────────────────────────
            try:
                test = _db_q("SELECT COUNT(*) n FROM knowledge_base")
                if not test:
                    raise Exception("empty result")
            except:
                log.warning("[WATCHDOG] DB health check failed — reinitializing")
                try: _db_init()
                except Exception as e: log.error(f"[WATCHDOG] DB reinit failed: {e}")
                _heal_count += 1

            # ── Heal: Queue empty but KB not full ─────────────────
            if _lq_size() == 0 and _kb_count() < 500:
                log.info("[WATCHDOG] Queue empty — refilling from MASTER_URLS")
                try: _queue_refill()
                except: pass

            # ── Heal: Stuck crawler items ─────────────────────────
            try:
                stuck = _db_q(
                    "SELECT COUNT(*) n FROM learn_queue WHERE status='processing' "
                    "AND started_at < ?", (time.time() - 300,)  # stuck for 5+ min
                )
                stuck_count = stuck[0]["n"] if stuck else 0
                if stuck_count > 0:
                    _db_run(
                        "UPDATE learn_queue SET status='pending', worker_id=0, attempts=attempts+1 "
                        "WHERE status='processing' AND started_at < ?",
                        (time.time() - 300,)
                    )
                    log.warning(f"[WATCHDOG] Recovered {stuck_count} stuck crawl items")
                    _heal_count += 1
            except: pass

            # ── Guard: Ollama service crashed — restart only, no pull ─────
            if not _ol_ok():
                restarting = any(t.name in ("ollama-auto","ollama-restart")
                                 for t in threading.enumerate())
                if not restarting and _find_ollama_exe():
                    if not _ollama_is_running():
                        log.warning("[WATCHDOG] Ollama offline — restarting service")
                        _log("[WATCHDOG] Ollama service down — restarting...", "heal")
                        threading.Thread(target=_start_ollama_service,
                                         daemon=True, name="ollama-restart").start()
                        _heal_count += 1
                    # else: running but no model installed — nothing we can do without pulling
                    else:
                        log.info("[WATCHDOG] Ollama running but no model installed — run: ollama pull <model>")

            # ── Monitor: Memory usage (warn if > 1GB) ─────────────
            if HAS_PSUTIL:
                try:
                    proc = psutil.Process(os.getpid())
                    mem_mb = proc.memory_info().rss / (1024 * 1024)
                    # v9: restart if server RAM exceeds 2 GB
                    if mem_mb > 2048 and proc.pid == os.getpid():
                        _log(f"[WATCHDOG] RSS {mem_mb:.0f} MB > 2 GB ceiling — restarting", "warn")
                        try:
                            s = _load_state(); _save_state(s)
                        except Exception:
                            pass
                        # v9: guard: sys.argv[0] may be "-c" or empty in some launchers
                        _script = os.path.abspath(sys.argv[0]) if sys.argv and sys.argv[0] not in ("", "-c") else __file__
                        os.execv(sys.executable, [sys.executable, _script] + sys.argv[1:])
                    if mem_mb > 1024:
                        log.warning(f"[WATCHDOG] Server using {mem_mb:.0f} MB RAM — consider restarting")
                        _log(f"[WATCHDOG] ⚠ High RAM: {mem_mb:.0f} MB", "warn")
                except: pass

            # ── Guard: HTTP port reachable ─────────────────────────────
            try:
                port = int(_gs("server_port") or 8766)
                # Check both 127.0.0.1 AND the LAN IP — server binds to LAN IP,
                # so 127.0.0.1 will always fail and produce false-positive warnings.
                _lan_ip = get_ip()
                if not _check_port(port, host="127.0.0.1") and not _check_port(port, host=_lan_ip):
                    log.warning("[WATCHDOG] HTTP port not responding — logging for diagnosis")
                    _log("[WATCHDOG] ⚠ HTTP port unreachable — server may need restart", "warn")
            except Exception: pass

            # ── Guard: State writer thread alive ───────────────────────
            if "state-writer" not in running:
                log.warning("[WATCHDOG] state-writer thread died — restarting")
                threading.Thread(target=_state_writer, daemon=True,
                                 name="state-writer").start()
                _heal_count += 1

            # ── Guard: Auto-unpair watchdog alive ──────────────────────
            if "auto-unpair" not in running:
                log.warning("[WATCHDOG] auto-unpair thread died — restarting")
                threading.Thread(target=_auto_unpair_watchdog, daemon=True,
                                 name="auto-unpair").start()
                _heal_count += 1

            # ── Guard: Stale pairing lock ───────────────────────────────
            # If device has been paired for >24h with no activity, clear it
            # FIX 4: robust parse — handles ISO string OR stored float, logs errors
            try:
                locked = _gs("locked_device")
                last_seen = _gs("last_seen")
                if locked and last_seen:
                    ref_ts = None
                    # Try float timestamp first (new storage format)
                    try:
                        ref_ts = float(last_seen)
                    except (TypeError, ValueError):
                        pass
                    # Fall back to ISO 8601 string
                    if ref_ts is None:
                        import datetime as _dt
                        try:
                            ref_ts = _dt.datetime.strptime(
                                str(last_seen), "%Y-%m-%dT%H:%M:%SZ"
                            ).replace(tzinfo=_dt.timezone.utc).timestamp()
                        except ValueError as _pe:
                            log.warning(f"[WATCHDOG] Could not parse last_seen={last_seen!r}: {_pe} — skipping stale-lock check")
                            ref_ts = None
                    if ref_ts is not None:
                        silence_h = (time.time() - ref_ts) / 3600
                        if silence_h > 24:
                            log.warning(
                                f"[WATCHDOG] Device silent for {silence_h:.0f}h — clearing stale lock"
                            )
                            _log(f"[WATCHDOG] Cleared stale pairing ({silence_h:.0f}h silent)", "heal")
                            _ss("locked_device", None)
                            _ss("paired_at",     None)
                            _ss("last_seen",     None)
                            _ss("pairing_code",  _gen_code())
                            _heal_count += 1
            except Exception: pass

            # ── Guard: Active streams memory leak ──────────────────────
            # FIX 3: log.warning and _heal_count were outside the if, firing every cycle
            try:
                with _STREAMS_LOCK:
                    _n_stale = len(_ACTIVE_STREAMS)
                    if _n_stale > 10:
                        _ACTIVE_STREAMS.clear()
                        log.warning(f"[WATCHDOG] Cleared {_n_stale} stale SSE stream entries")
                        _heal_count += 1
            except Exception: pass

            # ── Guard: DB integrity check (every 10 cycles ~10 min) ────
            if not hasattr(_watchdog, "_db_cycle"):
                _watchdog._db_cycle = 0
            _watchdog._db_cycle += 1
            if _watchdog._db_cycle % 10 == 0:
                try:
                    result = _db_q("PRAGMA integrity_check")
                    if result and result[0].get("integrity_check") != "ok":
                        log.error("[WATCHDOG] DB integrity check FAILED — backing up and reinitializing")
                        _log("[WATCHDOG] ⚠ DB corrupt — reinitializing", "err")
                        try:
                            import shutil as _sh
                            bak = DB_PATH.with_suffix(f".corrupt_{int(time.time())}.bak")
                            _sh.copy2(str(DB_PATH), str(bak))
                            _db_init()
                            log.info(f"[WATCHDOG] DB recovered — backup at {bak.name}")
                        except Exception as _dbe:
                            log.error(f"[WATCHDOG] DB recovery failed: {_dbe}")
                        _heal_count += 1
                except Exception: pass

            # ── Guard: KB size cap — prune if over 500 entries ─────────
            try:
                kb_size = _kb_count()
                if kb_size > 500:
                    prune = kb_size - 450
                    _db_run(
                        "DELETE FROM knowledge_base WHERE id IN "
                        "(SELECT id FROM knowledge_base ORDER BY id ASC LIMIT ?)",
                        (prune,)
                    )
                    log.info(f"[WATCHDOG] KB pruned {prune} oldest entries ({kb_size}→{kb_size-prune})")
                    _heal_count += 1
            except Exception: pass

            # ── Guard: Chat history size cap ───────────────────────────
            try:
                total = _db_q("SELECT COUNT(*) n FROM chat_history")
                total_n = total[0]["n"] if total else 0
                if total_n > 5000:
                    _db_run(
                        "DELETE FROM chat_history WHERE id NOT IN "
                        "(SELECT id FROM chat_history ORDER BY id DESC LIMIT 2000)"
                    )
                    log.info(f"[WATCHDOG] Chat history pruned: {total_n}→2000 rows")
                    _heal_count += 1
            except Exception: pass

            # ── Guard: CPU spiral — server process itself ───────────────
            if HAS_PSUTIL:
                try:
                    proc = psutil.Process(os.getpid())
                    mem_mb = proc.memory_info().rss / (1024 * 1024)
                    cpu_self = proc.cpu_percent(interval=0.2)
                    if mem_mb > 1200:
                        log.warning(f"[WATCHDOG] Server RAM: {mem_mb:.0f} MB — high usage")
                        _log(f"[WATCHDOG] ⚠ High RAM: {mem_mb:.0f} MB", "warn")
                    if cpu_self > 80:
                        log.warning(f"[WATCHDOG] Server CPU: {cpu_self:.0f}% — possible loop")
                        _log(f"[WATCHDOG] ⚠ High CPU: {cpu_self:.0f}%", "warn")
                except Exception: pass

            # ── Guard: PC scripts dir integrity ───────────────────────
            if not hasattr(_watchdog, "_scripts_cycle"):
                _watchdog._scripts_cycle = 0
            _watchdog._scripts_cycle += 1
            if _watchdog._scripts_cycle % 60 == 0:   # every ~60 min
                try:
                    if not _PC_SCRIPTS_DIR.exists():
                        _pc_scripts_init()
                        _log("[WATCHDOG] 🔧 PC scripts dir recreated (was missing)", "heal")
                        _heal_count += 1
                except Exception: pass

                # Heal 17: prune chat history if any device has > 500 messages
                try:
                    rows = _db_q(
                        "SELECT device_id, COUNT(*) n FROM chat_history "
                        "GROUP BY device_id HAVING n > 500"
                    )
                    for r in rows:
                        _log(f"[HEAL] 🔧 chat_history for {r['device_id']} has {r['n']} rows — "
                             f"pruning to 200", "heal")
                        _db_run(
                            "DELETE FROM chat_history WHERE device_id=? AND id NOT IN "
                            "(SELECT id FROM chat_history WHERE device_id=? "
                            "ORDER BY id DESC LIMIT 200)",
                            (r["device_id"], r["device_id"])
                        )
                except Exception as e:
                    log.debug(f"[WATCHDOG] history prune error: {e}")

            # ── Guard: Disk space warning ───────────────────────────────
            if HAS_PSUTIL:
                try:
                    disk = psutil.disk_usage(str(Path.home()))
                    free_gb = disk.free / (1024**3)
                    if free_gb < 1.0:
                        log.warning(f"[WATCHDOG] Low disk: {free_gb:.1f} GB free")
                        _log(f"[WATCHDOG] ⚠ Low disk space: {free_gb:.1f} GB free", "warn")
                        # Auto-prune KB more aggressively when disk is low
                        try:
                            kb_size2 = _kb_count()
                            if kb_size2 > 100:
                                _db_run(
                                    "DELETE FROM knowledge_base WHERE id IN "
                                    "(SELECT id FROM knowledge_base ORDER BY id ASC LIMIT ?)",
                                    (kb_size2 - 100,)
                                )
                                log.info(f"[WATCHDOG] Emergency KB prune: {kb_size2}→100")
                        except Exception: pass
                except Exception: pass

            # ── Guard: SQLite WAL checkpoint — prevent WAL file growing ─
            if not hasattr(_watchdog, "_wal_cycle"):
                _watchdog._wal_cycle = 0
            _watchdog._wal_cycle += 1
            if _watchdog._wal_cycle % 5 == 0:  # every 5 minutes
                try:
                    _db_run("PRAGMA wal_checkpoint(PASSIVE)")
                except Exception: pass
            # ── Guard: Deduplicate chat history every 10 cycles (~10 min) ─
            if _watchdog._wal_cycle % 10 == 0:
                try: _guard_dedupe_chat_history()
                except Exception: pass

            # ── Guard: Orphaned 'processing' queue items ───────────────
            try:
                _db_run(
                    "UPDATE learn_queue SET status='pending', worker_id=0 "
                    "WHERE status='processing' AND started_at < ?",
                    (time.time() - 600,)  # stuck >10 min
                )
            except Exception: pass

            # ── Guard: active_model self-heal ─────────────────────────────
            # If Ollama is running but saved active_model is gone, re-pick
            try:
                if _ol_ok():
                    installed = _ol_models()
                    saved_m   = _gs("active_model")
                    if installed and saved_m:
                        base  = saved_m.lower().split(":")[0]
                        still = any(n.lower() == saved_m.lower()
                                    or n.lower().startswith(base)
                                    for n in installed)
                        if not still:
                            new_m = _select_lightest(installed)
                            log.warning(
                                f"[WATCHDOG] active_model '{saved_m}' gone "
                                f"— switching to '{new_m}'"
                            )
                            _ss("active_model", new_m)
                            _log(f"[WATCHDOG] Model switched to {new_m}", "heal")
                            _heal_count += 1
                    elif installed and not saved_m:
                        # No model saved at all — pick one now
                        chosen = _select_lightest(installed)
                        _ss("active_model", chosen)
                        log.info(f"[WATCHDOG] Set missing active_model to {chosen}")
            except Exception: pass

            # ── Guard: _ol_ok staleness — force cache refresh if stale ─────
            try:
                with _ol_cache_lock:
                    cache_age = time.time() - _ol_cache.get("ts", 0)
                if cache_age > 45:   # cache should refresh every 10s
                    log.warning("[WATCHDOG] Ollama cache stale — ollama-cache thread may be stuck")
                    if "ollama-cache" not in {t.name for t in threading.enumerate()}:
                        threading.Thread(target=_ol_cache_refresh, daemon=True,
                                         name="ollama-cache").start()
                        log.info("[WATCHDOG] Restarted ollama-cache thread")
                        _heal_count += 1
            except Exception: pass

            # ── Guard: Chat pool backup ─────────────────────────────────────
            try:
                qsize = getattr(_chat_pool, "_work_queue", None)
                if qsize is not None:
                    qs = qsize.qsize()
                    if qs > 5:
                        log.warning(f"[WATCHDOG] Chat pool queue: {qs} backed up — Ollama may be stuck")
                        _log(f"[WATCHDOG] ⚠ {qs} chats queued — AI response slow", "warn")
            except Exception: pass

            # ── Guard: sys-snapshot thread alive ──────────────────────────
            if "sys-snapshot" not in running:
                log.warning("[WATCHDOG] sys-snapshot thread died — restarting")
                threading.Thread(target=_sys_snapshot_update, daemon=True,
                                 name="sys-snapshot").start()
                _heal_count += 1

            # ── Guard: NEXUS BRAIN threads alive ──────────────────────────
            if "nexus-sensor" not in running:
                log.warning("[WATCHDOG] nexus-sensor died — restarting")
                threading.Thread(target=_nb_sensor_loop, daemon=True, name="nexus-sensor").start()
                _heal_count += 1
            if "nexus-rules" not in running:
                log.warning("[WATCHDOG] nexus-rules died — restarting")
                threading.Thread(target=_nb_rules_loop, daemon=True, name="nexus-rules").start()
                _heal_count += 1
            if "nexus-insight" not in running:
                log.warning("[WATCHDOG] nexus-insight died — restarting")
                threading.Thread(target=_nb_insight_loop, daemon=True, name="nexus-insight").start()
                _heal_count += 1

            # ── Guard: Report poisoned URL count every 20 cycles (~20 min) ─
            if not hasattr(_watchdog, "_poison_cycle"):
                _watchdog._poison_cycle = 0
            _watchdog._poison_cycle += 1
            if _watchdog._poison_cycle % 20 == 0:
                try:
                    poisoned = _db_q("SELECT COUNT(*) n FROM learn_queue WHERE status='poisoned'")
                    n = poisoned[0]["n"] if poisoned else 0
                    if n > 0:
                        _log(f"[WATCHDOG] ℹ {n} URLs permanently poisoned (3+ failures each)", "info")
                except Exception: pass

            # ── Guard: CPU snapshot freshness ─────────────────────────────
            with _sys_snapshot_lock:
                snap_age = time.time() - _sys_snapshot.get("ts", 0)
            if snap_age > 30:
                log.warning("[WATCHDOG] sys-snapshot stale (>30s) — forcing restart")
                threading.Thread(target=_sys_snapshot_update, daemon=True,
                                 name="sys-snapshot").start()

            # ── Guard: Chat dedup map size (prevent memory leak) ──────────
            try:
                with _chat_dedup_lock:
                    stale_keys = [k for k, (h, t) in _chat_last_hash.items()
                                  if time.time() - t > 3600]
                    for k in stale_keys: del _chat_last_hash[k]
            except Exception: pass

            # ── Guard: preload-scheduler thread alive ──────────────────────
            if "preload-scheduler" not in running:
                log.warning("[WATCHDOG] preload-scheduler died — restarting")
                threading.Thread(target=_scheduled_preload, daemon=True,
                                 name="preload-scheduler").start()
                _heal_count += 1

            # ── Guard: Ollama conn pool — reset if cache is stale >60s ─────
            # Thread-local connections go dead when Ollama restarts but threads
            # keep the old socket alive. Proactively reset so next call reconnects.
            try:
                with _ol_cache_lock:
                    _pool_cache_age = time.time() - _ol_cache.get("ts", 0)
                if _pool_cache_age > 60 and not _ollama_is_running():
                    _ol_conn_local.conn = None
                    log.debug("[WATCHDOG] Ollama conn pool cleared (service down)")
            except Exception: pass

            # ── Guard: Model blacklist auto-expiry ─────────────────────────
            # If all models are blacklisted the AI goes silent. Clear expired
            # entries every watchdog cycle so recovery is automatic.
            try:
                _now_bl = time.time()
                with _model_fail_lock:
                    _expired_bl = [m for m, until in _model_blacklist.items()
                                   if until <= _now_bl]
                    for m in _expired_bl:
                        del _model_blacklist[m]
                        _model_fail_counts.pop(m, None)
                if _expired_bl:
                    log.info(f"[WATCHDOG] Cleared expired blacklist: {_expired_bl}")
                    _log(f"[WATCHDOG] 🔧 Model blacklist cleared: {_expired_bl}", "heal")
                    _heal_count += 1
            except Exception: pass

            # ── Guard: startup-api-guard one-shot thread ───────────────────
            # startup-api-guard is one-shot (runs once at boot). If it never
            # ran because a crash happened before 15s, re-spawn it once.
            if not hasattr(_watchdog, "_api_guard_done"):
                _watchdog._api_guard_done = False
            if not _watchdog._api_guard_done:
                if "startup-api-guard" not in running:
                    _watchdog._api_guard_done = True   # only retry once from watchdog
                    threading.Thread(target=_startup_api_guard, daemon=True,
                                     name="startup-api-guard").start()
                    log.info("[WATCHDOG] startup-api-guard re-launched (missed at boot)")

            # ── Guard: auth_fail_map memory leak (every cycle ~60s) ──────────
            try: _guard_auth_fail_map_leak()
            except Exception: pass

            # ── Guard: log buffer emergency trim (every cycle) ────────────────
            try: _guard_log_buffer_size()
            except Exception: pass

            # ── Slow-cycle guards (every 5 watchdog cycles ≈ 5 min) ──────────
            if not hasattr(_watchdog, "_slow_cycle"):
                _watchdog._slow_cycle = 0
            _watchdog._slow_cycle += 1

            if _watchdog._slow_cycle % 5 == 0:
                try: _guard_reply_cache_stale()
                except Exception: pass
                try: _guard_db_wal_size()
                except Exception: pass

            # ── Very slow guards (every 10 watchdog cycles ≈ 10 min) ─────────
            if _watchdog._slow_cycle % 10 == 0:
                try: _guard_share_dir()
                except Exception: pass
                try: _guard_state_backup()
                except Exception: pass
                try: _guard_state_file_integrity()
                except Exception: pass

            # ── Runaway heal detection ──────────────────────────────────────
            now_w = time.time()
            _heal_window = [t for t in _heal_window if now_w - t < 300]
            if _heal_count > 0:
                _heal_window.append(now_w)
                _heal_count = 0
            if len(_heal_window) > 10:
                log.error("[WATCHDOG] >10 heals in 5 min — something is critically unstable")
                _log("[WATCHDOG] ⚠ Repeated auto-heals — check Ollama and disk space", "warn")

        except Exception as e:
            log.debug(f"[WATCHDOG] Error in watchdog loop: {e}")

def _startup_preflight() -> None:
    """Run preflight checks at startup. Failures are logged but never fatal."""
    import importlib.util as _ilu, shutil as _sh
    issues, ok = [], []

    # Python version (main() requires 3.10)
    if sys.version_info < (3, 10):
        issues.append(f"Python {sys.version_info.major}.{sys.version_info.minor} detected — Butler AI requires 3.10+")
    else:
        ok.append(f"Python {platform.python_version()}")

    # Critical packages
    for pkg in ("psutil", "requests"):
        if _ilu.find_spec(pkg):
            ok.append(pkg)
        else:
            issues.append(f"Critical package missing: {pkg}  →  pip install {pkg}")

    # Optional packages (degrade gracefully)
    for pkg in ("qrcode", "PIL"):
        if not _ilu.find_spec(pkg):
            _log(f"[PREFLIGHT] Optional package absent: {pkg} — QR/image features disabled", "warn")

    # Writable home directory
    try:
        _tp = Path.home() / ".butler_preflight_test"
        _tp.write_text("ok"); _tp.unlink()
        ok.append("home dir writable")
    except OSError as e:
        issues.append(f"Home directory not writable: {e}")

    # Disk space — warn if < 500 MB free on the drive where butler lives
    try:
        _usage = _sh.disk_usage(Path(__file__).parent)
        _free_mb = _usage.free // (1024 * 1024)
        if _free_mb < 500:
            issues.append(f"Low disk space: {_free_mb} MB free on server drive")
        else:
            ok.append(f"{_free_mb:,} MB disk free")
    except Exception: pass

    # SQLite sanity
    try:
        import sqlite3 as _sq
        _c = _sq.connect(":memory:"); _c.execute("SELECT 1"); _c.close()
        ok.append("SQLite")
    except Exception as e:
        issues.append(f"SQLite not working: {e}")

    if issues:
        for issue in issues:
            _log(f"[PREFLIGHT] ⚠  {issue}", "warn")
    else:
        _log(f"[PREFLIGHT] All checks passed  ({', '.join(ok)})", "ok")

def _auto_heal_startup():
    """
    Run immediate healing checks on startup.
    Fixes common issues before server starts accepting requests.
    """
    # Ensure DB is healthy
    try:
        _db_init()
        # Reset any stuck 'processing' items from previous crash
        _db_run(
            "UPDATE learn_queue SET status='pending', worker_id=0 "
            "WHERE status='processing'"
        )
        stuck = _db_q(
            "SELECT COUNT(*) n FROM learn_queue WHERE status='processing'"
        )
        recovered = stuck[0]["n"] if stuck else 0
        if recovered > 0:
            log.info(f"[HEAL] Recovered {recovered} stuck queue items from previous crash")
    except Exception as e:
        log.warning(f"[HEAL] Startup heal error: {e}")

    # Generate pairing code if missing
    if not _gs("pairing_code"):
        _ss("pairing_code", _gen_code())
        log.info("[HEAL] Generated new pairing code")

    # PERF_GUARD: trim bloated chat history before first request
    _guard_chat_history_startup_trim()

    # Give poisoned URLs a second chance if they're >7 days old
    # (site may have been temporarily down when they were poisoned)
    try:
        _db_run(
            "UPDATE learn_queue SET status='pending', attempts=0 "
            "WHERE status='poisoned' AND finished_at < ?",
            (time.time() - 604800,)
        )
    except Exception: pass

    # Clear any chat dedup state from previous session (stale hashes)
    with _chat_dedup_lock:
        _chat_last_hash.clear()

    log.info("[HEAL] Startup self-heal complete")

# ══════════════════════════════════════════════════════════
#  STARTUP API GUARD — self-heal every API used at boot
# ══════════════════════════════════════════════════════════

def _startup_api_guard() -> None:
    """
    Probes every external/internal API that Butler uses at startup and
    self-heals any that are broken.  Runs in a daemon thread ~15 s after
    main() so all threads are already started before we evaluate them.

    Checked APIs / subsystems
    ─────────────────────────
    1. Ollama /api/tags   — is Ollama reachable and returning models?
    2. Ollama /api/ps     — is the inference engine responsive?
    3. Ollama /api/chat   — can we get a 1-token response? (warmup probe)
    4. SQLite DB          — can we read and write the main DB?
    5. Disk space         — is there enough room to operate?
    6. IP / network       — does get_ip() return a routable address?
    7. Pairing code       — is a valid pairing code stored?
    8. Thread census      — are all startup threads alive?  restart any dead.
    9. Ollama conn pool   — reset stale thread-local connections if broken.
   10. Model blacklist    — clear leftover blacklist entries from prev session.
    """
    time.sleep(15)   # let all startup threads stabilise first
    _log("[GUARD] 🔍 Startup API guard running…", "info")
    healed = []

    # ── 1. Ollama /api/tags ────────────────────────────────────────────────
    try:
        with _urllib_req.urlopen(f"{OLLAMA_URL}/api/tags", timeout=4) as _r:
            _d = json.loads(_r.read())
            _names = [x["name"] for x in _d.get("models", [])]
        _log(f"[GUARD] ✅ Ollama /api/tags OK — {len(_names)} model(s)", "ok")
    except Exception as _e:
        _log(f"[GUARD] ⚠ Ollama /api/tags unreachable: {_e}", "warn")
        # Attempt service restart if exe exists but service is down
        try:
            if _find_ollama_exe() and not _ollama_is_running():
                _log("[GUARD] 🔧 Restarting Ollama service…", "heal")
                threading.Thread(target=_start_ollama_service,
                                 daemon=True, name="ollama-guard-restart").start()
                healed.append("ollama-service")
            elif not _find_ollama_exe():
                _log("[GUARD] ⚠ Ollama not installed — triggering auto-install", "warn")
                threading.Thread(target=_start_ollama_auto,
                                 daemon=True, name="ollama-guard-install").start()
                healed.append("ollama-install")
        except Exception as _re:
            log.debug(f"[GUARD] Ollama restart error: {_re}")

    # ── 2. Ollama /api/ps ─────────────────────────────────────────────────
    try:
        with _urllib_req.urlopen(f"{OLLAMA_URL}/api/ps", timeout=4) as _r:
            json.loads(_r.read())  # FIX: _ps was unused; parse to validate JSON
        _log("[GUARD] ✅ Ollama /api/ps OK", "ok")
    except Exception as _e:
        _log(f"[GUARD] ⚠ Ollama /api/ps failed: {_e} (non-critical)", "warn")

    # ── 3. Ollama /api/chat — 1-token warmup probe ────────────────────────
    _active = _get_active_model()
    if _active and _ollama_is_running():
        try:
            _wp = json.dumps({
                "model": _active,
                "messages": [{"role": "user", "content": "ping"}],
                "stream": False,
                "keep_alive": "30m",
                "options": {"num_ctx": 256, "num_predict": 1,
                            "temperature": 0, "num_gpu": 99},
            }).encode()
            _wreq = _urllib_req.Request(
                f"{OLLAMA_URL}/api/chat", data=_wp,
                headers={"Content-Type": "application/json"}, method="POST"
            )
            with _urllib_req.urlopen(_wreq, timeout=60) as _wr:
                _wr.read()
            _log(f"[GUARD] ✅ Ollama /api/chat OK — {_active} responding", "ok")
        except Exception as _e:
            _log(f"[GUARD] ⚠ Ollama /api/chat probe failed: {_e}", "warn")
            # Record failure so blacklist knows; reset conn pool in case it's stale
            try:
                _guard_record_model_failure(_active)
                _ol_conn_local.conn = None
                healed.append("ollama-conn-pool-reset")
            except Exception: pass
    elif not _active:
        _log("[GUARD] ⚠ No active model — triggering _ensure_model", "warn")
        try:
            threading.Thread(target=_ensure_model, daemon=True,
                             name="guard-ensure-model").start()
            healed.append("ensure-model")
        except Exception: pass

    # ── 4. SQLite DB read + write ─────────────────────────────────────────
    try:
        _rows = _db_q("SELECT COUNT(*) n FROM knowledge_base")
        _n = _rows[0]["n"] if _rows else 0
        # Write probe: insert and immediately delete a canary row
        _db_run(
            "INSERT OR IGNORE INTO knowledge_base(title,url,content,category,word_count,crawled_at)"
            " VALUES(?,?,?,?,?,?)",
            ("__guard_probe__", "__guard__", "x", "test", 0, time.time())
        )
        _db_run("DELETE FROM knowledge_base WHERE url='__guard__'")
        _log(f"[GUARD] ✅ SQLite DB OK — {_n} KB articles", "ok")
    except Exception as _e:
        _log(f"[GUARD] ⚠ DB probe failed: {_e} — reinitialising", "warn")
        try:
            _db_init()
            healed.append("db-reinit")
        except Exception as _de:
            log.error(f"[GUARD] DB reinit failed: {_de}")

    # ── 5. Disk space ─────────────────────────────────────────────────────
    try:
        import shutil as _sh2
        _usage = _sh2.disk_usage(str(Path.home()))
        _free_gb = _usage.free / (1024 ** 3)
        if _free_gb < 0.5:
            _log(f"[GUARD] ⚠ CRITICAL: only {_free_gb:.2f} GB free — AI pull will fail", "warn")
        elif _free_gb < 2.0:
            _log(f"[GUARD] ⚠ Low disk: {_free_gb:.1f} GB free", "warn")
        else:
            _log(f"[GUARD] ✅ Disk OK — {_free_gb:.1f} GB free", "ok")
    except Exception as _e:
        _log(f"[GUARD] ⚠ Disk check failed: {_e}", "warn")

    # ── 6. IP / network ───────────────────────────────────────────────────
    try:
        _ip = get_ip()
        if not _ip or _ip == "127.0.0.1":
            _log(f"[GUARD] ⚠ No LAN IP detected (got '{_ip}') — beacon may not work", "warn")
        else:
            _log(f"[GUARD] ✅ Network OK — LAN IP: {_ip}", "ok")
    except Exception as _e:
        _log(f"[GUARD] ⚠ IP detection failed: {_e}", "warn")

    # ── 7. Pairing code ───────────────────────────────────────────────────
    try:
        _code = _gs("pairing_code")
        if not _code or len(_code) < 4:
            _new_code = _gen_code()
            _ss("pairing_code", _new_code)
            _log("[GUARD] 🔧 Pairing code missing — regenerated", "heal")
            healed.append("pairing-code")
        else:
            _log(f"[GUARD] ✅ Pairing code OK ({_code})", "ok")
    except Exception as _e:
        _log(f"[GUARD] ⚠ Pairing code check failed: {_e}", "warn")

    # ── 8. Thread census — every startup thread must be alive ────────────
    _alive = {t.name for t in threading.enumerate()}
    _required_threads = {
        "ollama-cache":      (_ol_cache_refresh,     [],       True),
        "ip-cache":          (_refresh_ip_cache,     [],       True),
        "sigma":             (_sigma_loop,            [],       True),
        "sys-snapshot":      (_sys_snapshot_update,  [],       True),
        "watchdog":          (_watchdog,              [],       True),
        "auto-unpair":       (_auto_unpair_watchdog,  [],      True),
        "state-writer":      (_state_writer,          [],      True),
        "preload-scheduler": (_scheduled_preload,     [],      True),
        "nexus-sensor":      (_nb_sensor_loop,        [],      True),
        "nexus-rules":       (_nb_rules_loop,         [],      True),
        "nexus-insight":     (_nb_insight_loop,       [],      True),
    }
    for _tname, (_tfunc, _targs, _tdaemon) in _required_threads.items():
        if _tname not in _alive:
            try:
                threading.Thread(target=_tfunc, args=_targs,
                                 daemon=_tdaemon, name=_tname).start()
                _log(f"[GUARD] 🔧 Restarted dead thread: {_tname}", "heal")
                healed.append(_tname)
            except Exception as _te:
                log.warning(f"[GUARD] Failed to restart {_tname}: {_te}")

    # warmup — one-shot, OK if gone; re-run if model now available but wasn't before
    if "warmup" not in _alive and _active and _ollama_is_running():
        try:
            threading.Thread(target=_warmup_model, daemon=True, name="warmup").start()
            _log("[GUARD] 🔧 Re-queued model warmup (was not alive)", "heal")
            healed.append("warmup")
        except Exception: pass

    # ── 9. Ollama connection pool — reset stale connections ──────────────
    try:
        # Thread-local connections survive process restarts but not Ollama restarts.
        # Proactively clear the pool so every thread gets a fresh connection.
        _ol_conn_local.conn = None
        _log("[GUARD] ✅ Ollama connection pool cleared (fresh connections on next use)", "ok")
    except Exception: pass

    # ── 10. Model blacklist — clear stale entries from previous session ───
    try:
        now_g = time.time()
        with _model_fail_lock:
            _expired = [m for m, until in _model_blacklist.items() if until <= now_g]
            for m in _expired:
                del _model_blacklist[m]
                _model_fail_counts.pop(m, None)
        if _expired:
            _log(f"[GUARD] 🔧 Cleared {len(_expired)} expired model blacklist entries: {_expired}", "heal")
            healed.append("blacklist-clear")
    except Exception: pass

    # ── Summary ───────────────────────────────────────────────────────────
    if healed:
        _log(f"[GUARD] ✅ Startup API guard complete — healed: {', '.join(healed)}", "ok")
    else:
        _log("[GUARD] ✅ Startup API guard complete — all systems healthy", "ok")

# ══════════════════════════════════════════════════════════

def _sigma_harvest():
    """
    Full SIGMA-NET harvest — recrawls master URLs and searches for new scripts.
    Called by _sigma_loop every HARVEST_SECS. Was referenced but never defined.
    """
    try:
        log.info("[SIGMA] Full harvest starting...")
        _queue_refill()  # top up queue with master URLs
        # Search for new Python automation scripts
        topics = []
        try:
            rows = _db_q(
                "SELECT topic FROM user_topics ORDER BY asks DESC LIMIT 10"
            )
            topics = [r["topic"] for r in rows]
        except Exception:
            pass
        for topic in topics[:5]:
            try:
                _search_and_crawl_scripts(topic, max_results=3)
            except Exception as e:
                log.debug(f"[SIGMA] Harvest topic error: {e}")
        log.info(f"[SIGMA] Harvest complete. Queue: {_lq_size()} URLs")
    except Exception as e:
        log.warning(f"[SIGMA] Harvest failed: {e}")

def _sigma_loop():
    """
    Continuous learning orchestrator. Replaces the old 45-min timer.
    - Starts worker threads immediately
    - Runs SIGMA-NET full harvest every 45 min (deep crawl of all master URLs)
    - Workers run 24/7 between harvests on the persistent queue
    - Everything saves to SQLite - restarts resume exactly where they left off
    """
    global _session_start
    _session_start = time.time()

    # Load checkpoint from last session
    cp = _checkpoint_load()
    if cp:
        _log(f"Learning resumed: {cp.get('articles_total',0)} articles from last session", "ok")

    # Pre-fill queue with master URLs on first run
    time.sleep(10)  # wait for DB to init
    _queue_refill()

    # Start continuous worker threads (they run 24/7)
    for i in range(WORKER_THREADS):
        t = threading.Thread(target=_learn_worker, args=(i,), daemon=True, name=f"learn-{i}")
        t.start()
        time.sleep(1)  # stagger starts

    log.info(f"[SIGMA] {WORKER_THREADS} continuous learning workers started")
    _log(f"Continuous AI learning started - {WORKER_THREADS} workers, queue: {_lq_size()} URLs", "ok")

    # Main loop: full SIGMA-NET harvest every 45 min + checkpoint
    while True:
        try:
            time.sleep(HARVEST_SECS)
            # Full harvest: recrawl all master URLs, search for new scripts
            _sigma_harvest()
            # Queue refill after harvest
            _queue_refill()
        except Exception as e:
            log.warning(f"[SIGMA] Harvest error: {e}")
            time.sleep(60)

# ══════════════════════════════════════════════════════
#  GUI HELPERS (forward refs - defined after build_gui)
# ══════════════════════════════════════════════════════
def _refresh_log():
    """
    Repaint the ACTIVITY LOG textview.

    v19.0.3: respects filter chip + search box, updates severity counters,
    honours the autoscroll toggle, and is thread-safe (marshals to the Tk
    main loop via .after(0, ...) when called from a background thread).
    """
    tv = _gui.get("log_tv")
    if not tv: return
    # Marshal to Tk main thread if we were called from a background thread.
    try:
        if threading.current_thread() is not threading.main_thread():
            try: tv.after(0, _refresh_log)
            except Exception: pass
            return
    except Exception: pass
    try:
        with _log_lock: lines = list(_log_lines[-500:])
        flt   = (_gui.get("log_filter") or "all").lower()
        q     = (_gui.get("log_search") or "").strip().lower()
        # Severity counters across the *visible buffer* (last 500).
        counts = {"all":0, "ok":0, "info":0, "warn":0, "err":0, "heal":0, "guard":0}
        shown  = []
        for tag, msg in lines:
            t = (tag or "info").lower()
            if t in ("warning",): t = "warn"
            if t in ("error",):   t = "err"
            counts["all"] += 1
            if t in counts: counts[t] += 1
            if flt != "all" and t != flt: continue
            if q and q not in msg.lower(): continue
            shown.append((t, msg))
        # Repaint
        tv.configure(state="normal"); tv.delete("1.0","end")
        for t, msg in shown[-300:]:
            tv.insert("end", msg + "\n", t)
        if _gui.get("log_autoscroll", True): tv.see("end")
        tv.configure(state="disabled")
        # Update chip counters
        for key, lbl in (_gui.get("log_chip_lbls") or {}).items():
            try:
                if not lbl.winfo_exists(): continue
                lbl.config(text=f"{key.upper()}  {counts.get(key,0)}")
            except Exception: pass
        # Footer stats
        ft = _gui.get("log_footer_lbl")
        if ft:
            try:
                if ft.winfo_exists():
                    ft.config(text=f"  {len(shown)} shown  ·  {counts['err']} err  ·  {counts['warn']} warn  ·  {counts['guard']} guard  ·  buffer {counts['all']}/500  ")
            except Exception: pass
    except Exception: pass

# ══════════════════════════════════════════════════════
#  UNDO SYSTEM + PC STATS + CLEAN SCRIPTS + LIBRARY
# ══════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════
# ── BUTLER TRASH / ROLLBACK SUBSYSTEM (v4_1_4) ──
# Every Python script the server executes is wrapped with a small prelude
# that monkeypatches deletion APIs to move targets into a per-session trash
# dir (~/.butler_trash/<sid>/tree/<original-abs-path>). A JSONL manifest
# records every move. The undo system replays the manifest in reverse to
# restore files exactly where they were. shutil.move is intentionally NOT
# patched — organise ops remain plain moves and stay reversible via the
# existing snapshot-diff path.
# ══════════════════════════════════════════════════════
import uuid as _butler_uuid

_BUTLER_TRASH_ROOT = Path.home() / ".butler_trash"

def _butler_new_session() -> str:
    sid = _butler_uuid.uuid4().hex[:16]
    try:
        (_BUTLER_TRASH_ROOT / sid).mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    return sid

def _butler_restore_session(sid: str) -> dict:
    """Replay a session manifest in reverse, restoring every trashed entry."""
    out = {"restored": 0, "failed": 0, "skipped": 0, "error": ""}
    if not sid:
        return out
    sdir = _BUTLER_TRASH_ROOT / sid
    man  = sdir / "manifest.jsonl"
    if not man.exists():
        return out
    entries = []
    try:
        with open(man, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    entries.append(json.loads(line))
                except Exception:
                    pass
    except Exception as e:
        out["error"] = f"manifest unreadable: {e}"
        return out

    for e in reversed(entries):
        try:
            src   = Path(e.get("src", ""))
            trash = Path(e.get("trash", ""))
            if not trash.exists():
                out["skipped"] += 1
                continue
            if src.exists():
                # Don't clobber — the user may have re-created something here.
                out["skipped"] += 1
                continue
            try:
                src.parent.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            try:
                os.rename(str(trash), str(src))
            except OSError:
                # Cross-device fallback: copy + remove original.
                if trash.is_dir():
                    shutil.copytree(str(trash), str(src))
                    shutil.rmtree(str(trash), ignore_errors=True)
                else:
                    shutil.copy2(str(trash), str(src))
                    try:
                        os.unlink(str(trash))
                    except Exception:
                        pass
            out["restored"] += 1
        except Exception:
            out["failed"] += 1

    # Best-effort cleanup of the now-empty session dir.
    try:
        shutil.rmtree(str(sdir), ignore_errors=True)
    except Exception:
        pass
    return out

def _butler_purge_old_sessions(max_age_days: int = 14) -> int:
    """GC: delete trash sessions older than max_age_days. Returns count purged."""
    n = 0
    try:
        if not _BUTLER_TRASH_ROOT.exists():
            return 0
        cutoff = time.time() - max_age_days * 86400
        for sdir in _BUTLER_TRASH_ROOT.iterdir():
            try:
                if sdir.is_dir() and sdir.stat().st_mtime < cutoff:
                    shutil.rmtree(str(sdir), ignore_errors=True)
                    n += 1
            except Exception:
                pass
    except Exception:
        pass
    return n

def _butler_exec_env(base_env: dict, session_id: str) -> dict:
    env = dict(base_env)
    if session_id:
        env["BUTLER_SESSION"]    = session_id
        env["BUTLER_TRASH_ROOT"] = str(_BUTLER_TRASH_ROOT)
        # v19.0.2: propagate configurable quotas / forbidden paths to subprocess
        import os as _os_envprop
        for _k in ("BUTLER_MAX_FILES", "BUTLER_MAX_BYTES", "BUTLER_FORBID_EXTRA"):
            _v = _os_envprop.environ.get(_k)
            if _v:
                env[_k] = _v
    return env

# The prelude is prepended to every Python script before subprocess execution.
# It is self-contained (no imports from the parent process), guards all
# destructive calls, and silently no-ops if BUTLER_SESSION is unset.
_BUTLER_RUN_PRELUDE = r"""# ─── BUTLER PRELUDE BEGIN ───
import os as _bos, sys as _bsys, shutil as _bshu, time as _btime, json as _bjson
import pathlib as _bpl, threading as _bthr
_BSID = _bos.environ.get('BUTLER_SESSION') or ''
_BROOT = _bpl.Path(_bos.environ.get('BUTLER_TRASH_ROOT') or (_bpl.Path.home() / '.butler_trash'))
_BSESDIR = (_BROOT / _BSID) if _BSID else None
_BMAN = (_BSESDIR / 'manifest.jsonl') if _BSESDIR else None
_BLOCK = _bthr.Lock()
_BSTATE = {'files': 0, 'bytes': 0, 'errors': 0}
_BMAX_FILES = 200000
_BMAX_BYTES = 100 * 1024 ** 3
# v19.0.2: configurable quotas via env (silently fall back to defaults on bad input)
try:
    _v = _bos.environ.get('BUTLER_MAX_FILES')
    if _v: _BMAX_FILES = max(1, int(_v))
except Exception: pass
try:
    _v = _bos.environ.get('BUTLER_MAX_BYTES')
    if _v: _BMAX_BYTES = max(1, int(_v))
except Exception: pass
_BFORBID_PARTS = (
    '/etc','/usr','/bin','/sbin','/boot','/sys','/proc','/dev','/lib','/var',
    '/System','/Library/System',
    'C:\\\\Windows','C:\\\\Program Files','C:\\\\Program Files (x86)',
    'C:\\\\ProgramData','C:\\\\Users\\\\Default',
)
# v19.0.2: extra forbidden paths via env (os.pathsep-separated)
try:
    _extra = _bos.environ.get('BUTLER_FORBID_EXTRA') or ''
    if _extra:
        _BFORBID_PARTS = _BFORBID_PARTS + tuple(p for p in _extra.split(_bos.pathsep) if p.strip())
except Exception: pass
_b_orig_unlink   = _bos.unlink
_b_orig_remove   = _bos.remove
_b_orig_rmdir    = _bos.rmdir
_b_orig_rmtree   = _bshu.rmtree
_b_orig_p_unlink = _bpl.Path.unlink
_b_orig_p_rmdir  = _bpl.Path.rmdir

def _b_active():
    if not _BSESDIR:
        return False
    try:
        _BSESDIR.mkdir(parents=True, exist_ok=True)
        (_BSESDIR / 'tree').mkdir(parents=True, exist_ok=True)
        if not _BMAN.exists():
            _BMAN.touch()
        return True
    except Exception:
        return False
_BACTIVE = _b_active()

def _b_safe(p):
    try:
        rp = _bpl.Path(p).resolve()
    except Exception:
        return None
    sp = str(rp)
    for bad in _BFORBID_PARTS:
        b = bad.rstrip('/\\\\')
        if sp == b or sp.startswith(b + _bos.sep):
            return None
    if '.butler_trash' in rp.parts:
        return None
    return rp

def _b_uniq(dest):
    if not dest.exists():
        return dest
    stem, suf, i = dest.stem, dest.suffix, 1
    while True:
        c = dest.with_name(stem + '__' + str(i) + suf)
        if not c.exists():
            return c
        i += 1

def _b_log(src, trash, kind, size):
    try:
        with _BLOCK:
            fh = open(str(_BMAN), 'a', encoding='utf-8')
            try:
                fh.write(_bjson.dumps({
                    'src': str(src), 'trash': str(trash),
                    'kind': kind, 'size': int(size), 'ts': _btime.time(),
                }) + '\n')
                fh.flush()
                try: _bos.fsync(fh.fileno())
                except Exception: pass
            finally:
                fh.close()
    except Exception:
        _BSTATE['errors'] += 1

def _b_quota_ok(extra):
    return (_BSTATE['files'] + 1 <= _BMAX_FILES
            and _BSTATE['bytes'] + extra <= _BMAX_BYTES)

def _b_size_of(rp):
    try:
        if rp.is_file():
            try: return rp.stat().st_size
            except Exception: return 0
        if rp.is_dir():
            t = 0
            for f in rp.rglob('*'):
                if f.is_file():
                    try: t += f.stat().st_size
                    except Exception: pass
            return t
    except Exception:
        pass
    return 0

def _b_to_trash(path):
    if not _BACTIVE:
        return False
    rp = _b_safe(path)
    if rp is None or not rp.exists():
        return False
    sz = _b_size_of(rp)
    if not _b_quota_ok(sz):
        return False
    try:
        # Mirror absolute path under the session's tree/ so restore is exact.
        rel = _bpl.Path(*rp.parts[1:]) if rp.is_absolute() and len(rp.parts) > 1 else rp
        dest = _b_uniq(_BSESDIR / 'tree' / rel)
        try:
            dest.parent.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        try:
            _bos.rename(str(rp), str(dest))
        except OSError:
            if rp.is_dir():
                _bshu.copytree(str(rp), str(dest))
                _b_orig_rmtree(str(rp), ignore_errors=True)
            else:
                _bshu.copy2(str(rp), str(dest))
                try: _b_orig_unlink(str(rp))
                except Exception: pass
        _BSTATE['files'] += 1
        _BSTATE['bytes'] += sz
        _b_log(rp, dest, 'dir' if dest.is_dir() else 'file', sz)
        return True
    except Exception:
        _BSTATE['errors'] += 1
        return False

def _b_patched_unlink(path, *a, **kw):
    if _b_to_trash(path): return None
    return _b_orig_unlink(path, *a, **kw)
def _b_patched_remove(path, *a, **kw):
    if _b_to_trash(path): return None
    return _b_orig_remove(path, *a, **kw)
def _b_patched_rmdir(path, *a, **kw):
    if _b_to_trash(path): return None
    return _b_orig_rmdir(path, *a, **kw)
def _b_patched_rmtree(path, *a, **kw):
    if _b_to_trash(path): return None
    return _b_orig_rmtree(path, *a, **kw)
def _b_patched_p_unlink(self, *a, **kw):
    if _b_to_trash(self): return None
    return _b_orig_p_unlink(self, *a, **kw)
def _b_patched_p_rmdir(self, *a, **kw):
    if _b_to_trash(self): return None
    return _b_orig_p_rmdir(self, *a, **kw)

if _BACTIVE:
    _bos.unlink      = _b_patched_unlink
    _bos.remove      = _b_patched_remove
    _bos.rmdir       = _b_patched_rmdir
    _bshu.rmtree     = _b_patched_rmtree
    _bpl.Path.unlink = _b_patched_p_unlink
    _bpl.Path.rmdir  = _b_patched_p_rmdir
# ─── BUTLER PRELUDE END ───
"""

def _butler_wrap_python(script: str) -> str:
    return _BUTLER_RUN_PRELUDE + "\n" + script

UNDO_WINDOW = 15 * 60  # 15 minutes

def _undo_create(script, language, user_req="", trash_session=""):
    """
    Creates an undo journal entry with a rich before-snapshot:
    - File lists for Desktop, Documents, Downloads (names + sizes + mtimes)
    - Sub-folder lists on Desktop (to detect organise operations)
    - Temp folder file count (to detect temp clean operations)
    """
    now = time.time()
    snapshot = {}
    try:
        home = Path.home()
        # File lists with metadata for diff detection
        for d in ["Desktop", "Documents", "Downloads"]:
            dp = home / d
            if dp.exists():
                try:
                    files = []
                    for f in dp.iterdir():
                        if f.is_file():
                            try:
                                st = f.stat()
                                files.append({
                                    "name": f.name,
                                    "size": st.st_size,
                                    "mtime": st.st_mtime,
                                })
                            except Exception:
                                files.append({"name": f.name, "size": 0, "mtime": 0})
                        if len(files) >= 200:
                            break
                    snapshot["__dir_" + d] = [f["name"] for f in files]
                    snapshot["__meta_" + d] = files
                except Exception:
                    pass

        # Sub-folder snapshot on Desktop (detects organise folders added)
        desktop = home / "Desktop"
        if desktop.exists():
            try:
                snapshot["__subdirs_Desktop"] = [
                    d.name for d in desktop.iterdir() if d.is_dir()
                ][:50]
            except Exception:
                pass

        # Temp file count (Windows)
        try:
            import tempfile
            tmp = Path(tempfile.gettempdir())
            snapshot["__temp_count"] = sum(1 for _ in tmp.iterdir() if _.is_file())
        except Exception:
            pass

    except Exception:
        pass

    try:
        snapshot["trash_session"] = trash_session
    except Exception:
        pass

    try:
        _db_run(
            "INSERT INTO undo_journal(ts,expires_at,script,language,user_req,snapshot,status) "
            "VALUES(?,?,?,?,?,?,?)",
            (now, now + UNDO_WINDOW, script, language, user_req,
             json.dumps(snapshot, default=str), "pending")
        )
        rows = _db_q("SELECT id FROM undo_journal ORDER BY id DESC LIMIT 1")
        return rows[0]["id"] if rows else None
    except Exception:
        return None

def _undo_complete(entry_id, output, success, outcome: dict = None):
    """v19.0.21: optionally persist outcome stats (JSON) alongside the
    truncated output. Bulletproof — never raises."""
    try:
        payload = str(output)[:5000]
        if isinstance(outcome, dict) and outcome:
            try:
                tag = "\n\n[OUTCOME]" + json.dumps(outcome, default=str)[:2000]
                if len(payload) + len(tag) <= 7000:
                    payload = payload + tag
            except Exception: pass
        _db_run("UPDATE undo_journal SET output=?, status=? WHERE id=?",
                (payload, "ok" if success else "error", entry_id))
        _pc_stat_inc("scripts_run")
    except: pass

# Undo concurrent rollback guard — prevents two simultaneous rollbacks of same entry
_undo_rollback_lock = threading.Lock()

def _undo_rollback(entry_id):
    """
    Rollback a script execution.
    Uses _undo_rollback_lock to prevent two simultaneous rollbacks of the same entry.
    """
    with _undo_rollback_lock:
        return _undo_rollback_inner(entry_id)

def _undo_rollback_inner(entry_id):
    """
    Real undo — actually restores deleted/moved files using the directory snapshot.
    Compares before-snapshot vs current state and deletes files that were created
    by the script (i.e. files present now but not in the snapshot).
    For cleaning scripts: re-creates temp files is not possible, but we can
    undo file moves/organise operations by reversing them from snapshot diff.
    """
    rows = _db_q("SELECT * FROM undo_journal WHERE id=? AND undone=0", (entry_id,))
    if not rows:
        return {"ok": False, "error": "Entry not found or already undone"}
    entry = rows[0]
    if time.time() > entry["expires_at"]:
        return {"ok": False, "error": "Undo window expired (15 minutes)"}

    restored  = 0
    removed   = 0
    details   = []
    snapshot  = {}
    try:
        snapshot = json.loads(entry["snapshot"] or "{}")
    except Exception:
        pass

    # ── UNDO: Restore everything the script trashed (bulletproof path) ──
    trash_sid = ""
    try:
        trash_sid = (snapshot.get("trash_session") or "").strip()
    except Exception:
        trash_sid = ""
    if trash_sid:
        try:
            tr = _butler_restore_session(trash_sid)
            restored += int(tr.get("restored", 0))
            details.append(
                f"Trash restore: {tr.get('restored',0)} restored, "
                f"{tr.get('failed',0)} failed, {tr.get('skipped',0)} skipped"
            )
            if tr.get("error"):
                details.append(f"Trash note: {tr['error']}")
        except Exception as _e:
            details.append(f"Trash restore error: {_e}")

    try:
        home = Path.home()
        # ── UNDO: File organisation / move operations ──────────────────
        # Strategy: any file NOW in Desktop/Documents/Downloads that was
        # NOT in the before-snapshot was placed there by the script → remove it.
        # Any file IN the snapshot but NOT there now was moved away → we log it
        # (actual recovery of deleted files isn't possible without a backup).
        for d in ["Desktop", "Documents", "Downloads"]:
            key   = "__dir_" + d
            dp    = home / d
            if not dp.exists():
                continue
            before = set(snapshot.get(key, []))
            try:
                after = {f.name for f in dp.iterdir() if f.is_file()}
            except Exception:
                continue

            # Files ADDED by script (present now, not in snapshot) — safe to remove.
            # FIX BUG-C6 (audit): route through butler trash so a user who dropped
            # files into the folder during the undo window can still recover them.
            added = after - before
            for fname in added:
                fp = dp / fname
                try:
                    _trashed = False
                    try:
                        _b_to_trash(fp)
                        _trashed = True
                    except Exception:
                        _trashed = False
                    if not _trashed:
                        fp.unlink()
                    removed += 1
                    details.append(f"Removed: {d}/{fname}" + (" (trash)" if _trashed else ""))
                    log.info(f"[UNDO] Removed file added by script: {fp} trash={_trashed}")
                except Exception as e:
                    details.append(f"Could not remove {d}/{fname}: {e}")

            # Files REMOVED by script (in snapshot, not now) — log only
            gone = before - after
            for fname in gone:
                details.append(f"Note: {d}/{fname} was deleted by script (cannot restore)")

        # ── UNDO: Organised sub-folders created by organise scripts ────
        # Look for folders like Images/, Videos/, Documents/ on Desktop
        organise_dirs = ["Images","Videos","Audio","Documents","Archives",
                         "Executables","Code","Spreadsheets","PDFs","Others"]
        desktop = home / "Desktop"
        if desktop.exists():
            snap_desktop = set(snapshot.get("__dir_Desktop", []))
            for org_dir in organise_dirs:
                od = desktop / org_dir
                if od.exists() and od.is_dir():
                    try:
                        # Move files back to Desktop if they weren't there before
                        for f in list(od.iterdir()):
                            if f.is_file() and f.name not in snap_desktop:
                                try:
                                    f.rename(desktop / f.name)
                                    restored += 1
                                    details.append(f"Restored: {f.name} → Desktop/")
                                except Exception:
                                    pass
                        # Remove the organise folder if now empty
                        if not any(od.iterdir()):
                            od.rmdir()
                            details.append(f"Removed empty folder: Desktop/{org_dir}/")
                    except Exception:
                        pass

        # ── UNDO: Temp/browser cache clean — log only ──────────────────
        # Deleted temp files genuinely can't be restored. We note this.
        script_lower = (entry["script"] or "").lower()
        if any(k in script_lower for k in ("temp", "cache", "recycle", "prefetch")):
            details.append("Note: Deleted temp/cache files cannot be restored (by design)")

    except Exception as e:
        log.warning(f"[UNDO] Rollback error: {e}")
        details.append(f"Partial undo — error: {e}")

    # Mark as undone regardless
    _db_run("UPDATE undo_journal SET undone=1 WHERE id=?", (entry_id,))
    _pc_stat_inc("scripts_undone")

    action_count = restored + removed
    if action_count == 0:
        msg = "Script marked as undone. No file changes to reverse (no tracked files or trash was empty)."
    else:
        msg = f"Undo complete — {restored} file(s) restored, {removed} file(s) removed."

    return {
        "ok":       True,
        "restored": restored,
        "removed":  removed,
        "message":  msg,
        "details":  details[:20],
    }

def _run_script(code: str, language: str = "python", timeout: int = 60,
                trash_session: str = "") -> dict:
    """
    Execute a script and return {output, success, exit_code, trashSession, outcome, durationMs}.
    Used by /api/pc_scripts/run and NEXUS BRAIN script execution.
    v19.0.21: timing + outcome verification (stats parsed from stdout/stderr).
    Bulletproof — never raises; always returns a dict.
    """
    _t0 = time.time()
    sid = trash_session or _butler_new_session()
    try:
        if language == "python":
            wrapped = _butler_wrap_python(code)
            cmd = [sys.executable, "-c", wrapped]
        elif language == "powershell":
            cmd = ["powershell", "-NoProfile", "-NonInteractive", "-Command", code]
        elif language in ("bash", "sh"):
            cmd = ["bash", "-c", code] if platform.system() != "Windows" else ["cmd", "/c", code]
        elif language in ("cmd", "batch"):
            cmd = ["cmd", "/c", code]
        else:
            cmd = [sys.executable, "-c", code]

        kw = {}
        if IS_WINDOWS:
            kw["creationflags"] = subprocess.CREATE_NO_WINDOW

        exec_env = _butler_exec_env(os.environ.copy(), sid)
        exec_env["PYTHONIOENCODING"] = "utf-8"
        exec_env["PYTHONUTF8"]       = "1"

        r = subprocess.run(
            cmd, capture_output=True, text=True,
            encoding="utf-8", errors="replace",
            timeout=timeout, cwd=str(Path.home()),
            env=exec_env, **kw
        )
        out = (r.stdout or "").strip()
        err = (r.stderr or "").strip()
        combined = (out + ("\n" + err if err else "")).strip()
        duration_ms = int((time.time() - _t0) * 1000)
        outcome = _verify_script_outcome(code, out, err, r.returncode, duration_ms, language)
        return {
            "output":       combined[:100000] if combined else "[No output]",
            "stdout":       out[:50000],
            "stderr":       err[:10000],
            "exit_code":    r.returncode,
            "exitCode":     r.returncode,
            "success":      r.returncode == 0,
            "trashSession": sid,
            "durationMs":   duration_ms,
            "startedAt":    int(_t0),
            "outcome":      outcome,
        }
    except subprocess.TimeoutExpired:
        duration_ms = int((time.time() - _t0) * 1000)
        return {"output": f"[Timeout] Script exceeded {timeout}s limit",
                "stdout": "", "stderr": "", "exit_code": 124, "exitCode": 124,
                "success": False, "trashSession": sid,
                "durationMs": duration_ms, "startedAt": int(_t0),
                "outcome": {"verified": False, "reason": "timeout",
                            "timeoutSecs": timeout, "errorLines": []}}
    except Exception as e:
        duration_ms = int((time.time() - _t0) * 1000)
        return {"output": f"[Error] {type(e).__name__}: {e}",
                "stdout": "", "stderr": str(e), "exit_code": 1, "exitCode": 1,
                "success": False, "trashSession": sid,
                "durationMs": duration_ms, "startedAt": int(_t0),
                "outcome": {"verified": False, "reason": "exception",
                            "error": f"{type(e).__name__}: {e}"[:300], "errorLines": []}}

# ── v19.0.21: outcome verification + statistics extraction ─────────────────
import re as _re_outcome
_OUTCOME_PATTERNS = {
    "files_cleaned":   _re_outcome.compile(r"(\d{1,9})\s*(?:files?|items?)\s*(?:cleaned|deleted|removed|wiped)", _re_outcome.IGNORECASE),
    "files_moved":     _re_outcome.compile(r"(?:moved|relocated|organi[sz]ed)\s*(\d{1,9})\s*(?:files?|items?)?", _re_outcome.IGNORECASE),
    "files_organized": _re_outcome.compile(r"(?:organi[sz]ed)\s*(\d{1,9})", _re_outcome.IGNORECASE),
    "duplicates":      _re_outcome.compile(r"(\d{1,9})\s*(?:duplicates?|dupes?)\s*(?:found|detected)?", _re_outcome.IGNORECASE),
    "bytes_freed_mb":  _re_outcome.compile(r"(\d{1,9}(?:\.\d+)?)\s*MB\s*(?:freed|recovered|saved|cleared)", _re_outcome.IGNORECASE),
    "bytes_freed_gb":  _re_outcome.compile(r"(\d{1,9}(?:\.\d+)?)\s*GB\s*(?:freed|recovered|saved|cleared)", _re_outcome.IGNORECASE),
    "folders_created": _re_outcome.compile(r"(?:created|made)\s*(\d{1,9})\s*(?:folders?|directories)", _re_outcome.IGNORECASE),
    "folders_removed": _re_outcome.compile(r"(?:removed|deleted)\s*(\d{1,9})\s*(?:empty\s*)?(?:folders?|directories)", _re_outcome.IGNORECASE),
    "errors_logged":   _re_outcome.compile(r"(?:^|\n)\s*(?:error|exception|failed)\s*[:!]", _re_outcome.IGNORECASE | _re_outcome.MULTILINE),
    "warnings":        _re_outcome.compile(r"(?:^|\n)\s*warning\s*[:!]", _re_outcome.IGNORECASE | _re_outcome.MULTILINE),
    "skipped":         _re_outcome.compile(r"(\d{1,9})\s*(?:skipped|ignored)", _re_outcome.IGNORECASE),
}
_SUCCESS_SIGNALS = ("done", "complete", "completed", "finished", "success",
                    "ok", "✓", "✔", "no issues", "all good", "nothing to do")
_FAILURE_SIGNALS = ("traceback", "permission denied", "winerror", "access is denied",
                    "not recognized", "no such file", "fatal", "modulenotfounderror")

def _verify_script_outcome(code: str, stdout: str, stderr: str,
                            exit_code: int, duration_ms: int, language: str = "python") -> dict:
    """Parse stdout/stderr to verify what the script actually did.
    Returns a stats dict — bulletproof, never raises."""
    out = {
        "verified":      True,
        "exitCode":      int(exit_code),
        "durationMs":    int(duration_ms),
        "language":      language or "python",
        "stdoutLines":   0,
        "stderrLines":   0,
        "successSignals": 0,
        "failureSignals": 0,
        "errorLines":    [],
        "warnings":      0,
        "stats":         {},
    }
    try:
        s = stdout or ""; e = stderr or ""
        out["stdoutLines"] = s.count("\n") + (1 if s else 0)
        out["stderrLines"] = e.count("\n") + (1 if e else 0)
        low = (s + "\n" + e).lower()
        out["successSignals"] = sum(low.count(sig) for sig in _SUCCESS_SIGNALS)
        out["failureSignals"] = sum(low.count(sig) for sig in _FAILURE_SIGNALS)
        # parse stats
        bytes_total = 0
        for key, pat in _OUTCOME_PATTERNS.items():
            try:
                m = pat.findall(s + "\n" + e)
                if not m: continue
                if key in ("errors_logged", "warnings"):
                    out["warnings" if key == "warnings" else "errorLines"] = (
                        len(m) if key == "warnings" else
                        [ln.strip()[:200] for ln in (s+"\n"+e).splitlines()
                         if "error" in ln.lower() or "exception" in ln.lower()][:10]
                    )
                    continue
                # numeric extractions
                try: nums = [float(x) for x in m]
                except Exception: nums = []
                total = sum(nums) if nums else 0
                if total:
                    out["stats"][key] = round(total, 2) if "." in str(total) else int(total)
                    if key == "bytes_freed_mb": bytes_total += total * 1024 * 1024
                    if key == "bytes_freed_gb": bytes_total += total * 1024 * 1024 * 1024
            except Exception: continue
        if bytes_total: out["stats"]["bytesFreed"] = int(bytes_total)
        # heuristic verdict
        if exit_code != 0:
            out["verdict"] = "failed"
        elif out["failureSignals"] > out["successSignals"] and exit_code == 0:
            out["verdict"] = "completed-with-issues"
        elif out["stats"] or out["successSignals"]:
            out["verdict"] = "success"
        elif not s and not e:
            out["verdict"] = "no-output"
        else:
            out["verdict"] = "completed"
    except Exception as _oe:
        out["verified"] = False
        out["reason"] = f"parse-error: {type(_oe).__name__}"
    return out

# ── v19.0.21: loop / silent-crash guard for crawler, KB, AI chat ──────────
_LOOP_GUARD: dict = {}            # fn_name -> [timestamps]
_LOOP_GUARD_LOCK = threading.Lock()
_LOOP_GUARD_WINDOW = 5.0          # seconds
_LOOP_GUARD_MAX_CALLS = 40        # >40 calls in 5s = runaway loop
_LOOP_GUARD_TRIPPED: dict = {}    # fn -> until_ts

def _loop_guard_check(fn: str) -> bool:
    """Return False if the named function is in a runaway loop (caller should
    short-circuit). Bulletproof — never raises."""
    try:
        now = time.time()
        with _LOOP_GUARD_LOCK:
            trip = _LOOP_GUARD_TRIPPED.get(fn, 0)
            if trip and now < trip: return False
            elif trip: _LOOP_GUARD_TRIPPED.pop(fn, None)
            ts = _LOOP_GUARD.setdefault(fn, [])
            ts.append(now)
            # trim outside the window
            cutoff = now - _LOOP_GUARD_WINDOW
            while ts and ts[0] < cutoff: ts.pop(0)
            if len(ts) > _LOOP_GUARD_MAX_CALLS:
                _LOOP_GUARD_TRIPPED[fn] = now + 30  # 30s cooldown
                ts.clear()
                try: _log(f"[GUARD] 🛑 Loop guard tripped on '{fn}' ({_LOOP_GUARD_MAX_CALLS}+ calls in {_LOOP_GUARD_WINDOW}s) — cooling 30s", "guard")
                except Exception: pass
                return False
        return True
    except Exception:
        return True   # fail-open: never block on guard bugs

def _kb_fuzz_check(query) -> str:
    """Sanitize KB query — strip control chars, clamp length, reject binary.
    Returns a safe string (possibly empty). Never raises."""
    try:
        if query is None: return ""
        if isinstance(query, bytes):
            try: query = query.decode("utf-8", "ignore")
            except Exception: return ""
        if not isinstance(query, str): query = str(query)
        # strip control chars except whitespace
        q = "".join(ch for ch in query if ch == "\n" or ch == "\t" or ord(ch) >= 32)
        q = q.strip()[:500]
        # reject pure-binary or pure-punctuation noise
        if not q: return ""
        letters = sum(1 for c in q if c.isalnum())
        if letters < 1: return ""
        return q
    except Exception: return ""



def _undo_list():
    """v19.0.21: parses persisted [OUTCOME] JSON and exposes summary stats."""
    now = time.time()
    try: _db_run("DELETE FROM undo_journal WHERE expires_at < ?", (now - 3600,))
    except: pass
    try:
        rows = _db_q("SELECT id,ts,expires_at,script,language,user_req,output,status,undone FROM undo_journal WHERE expires_at > ? ORDER BY ts DESC LIMIT 20", (now,))
    except Exception:
        rows = []
    result = []
    for r in rows:
        try:
            remaining = max(0, int(r["expires_at"] - now))
            out = r.get("output") or ""
            oc  = None; summary = ""
            if "[OUTCOME]" in out:
                try:
                    oc = json.loads(out.split("[OUTCOME]",1)[1])
                except Exception: oc = None
            if isinstance(oc, dict):
                st = oc.get("stats") or {}
                parts = []
                if st.get("files_cleaned"):    parts.append(f"{st['files_cleaned']} files cleaned")
                if st.get("files_organized"):  parts.append(f"{st['files_organized']} organized")
                if st.get("bytesFreed"):
                    mb = round(st["bytesFreed"]/(1024*1024), 1)
                    parts.append(f"{mb} MB freed")
                if oc.get("verdict"):          parts.append(str(oc["verdict"]))
                summary = " · ".join(parts)
            result.append({"id": r["id"], "timestamp": r["ts"], "remainingSec": remaining,
                            "remainingMin": "%d:%02d" % (remaining // 60, remaining % 60),
                            "script": (r.get("script") or "")[:200], "language": r["language"],
                            "userRequest": (r.get("user_req") or "")[:100], "status": r["status"],
                            "undone": bool(r["undone"]), "canUndo": remaining > 0 and not r["undone"],
                            "outcome": oc, "summary": summary,
                            "verdict": (oc or {}).get("verdict") if oc else None,
                            "durationMs": (oc or {}).get("durationMs") if oc else None})
        except Exception: continue
    return result

def _pc_stat_get(key):
    try:
        rows = _db_q("SELECT value FROM pc_stats WHERE key=?", (key,))
        return rows[0]["value"] if rows else 0
    except: return 0

def _pc_stat_inc(key, amount=1):
    try:
        _db_run("INSERT INTO pc_stats(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=value+?", (key, amount, amount))
        _db_run("INSERT INTO pc_stats_log(ts,key,value) VALUES(?,?,?)", (time.time(), key, amount))
        _db_run("DELETE FROM pc_stats_log WHERE ts < ?", (time.time() - 30*86400,))
    except: pass

def _pc_growth_data(days=7):
    try:
        cutoff = time.time() - days * 86400
        rows = _db_q("SELECT date(ts,'unixepoch','localtime') as day, key, SUM(value) as total FROM pc_stats_log WHERE ts > ? GROUP BY day, key ORDER BY day", (cutoff,))
        by_day = {}
        for r in rows:
            d = r["day"]
            if d not in by_day: by_day[d] = {"day": d, "cleaned": 0, "organized": 0, "recovered_mb": 0}
            if r["key"] == "files_cleaned": by_day[d]["cleaned"] += int(r["total"])
            elif r["key"] == "files_organized": by_day[d]["organized"] += int(r["total"])
            elif r["key"] == "space_recovered_bytes": by_day[d]["recovered_mb"] += round(r["total"]/(1024*1024), 1)
        return list(by_day.values())[-days:]
    except: return []

def _pc_scan_stats():
    stats = {"temp_files": 0, "temp_size_bytes": 0, "temp_size_mb": 0, "large_files": [], "browser_cache_mb": 0, "startup_items": 0}
    if not HAS_PSUTIL: return stats
    home = Path.home()
    for td in [Path(os.environ.get("TEMP", "")), Path(os.environ.get("TMP", "")), home / "AppData" / "Local" / "Temp"]:
        if not td.exists(): continue
        try:
            for f in td.rglob("*"):
                if f.is_file():
                    try: stats["temp_files"] += 1; stats["temp_size_bytes"] += f.stat().st_size
                    except: pass
        except: pass
    stats["temp_size_mb"] = round(stats["temp_size_bytes"] / (1024*1024), 1)
    desktop = home / "Desktop"
    if desktop.exists():
        try:
            for f in desktop.rglob("*"):
                if f.is_file():
                    try:
                        sz = f.stat().st_size
                        if sz > 100_000_000: stats["large_files"].append({"name": f.name, "size_mb": round(sz/(1024*1024), 1)})
                    except: pass
        except: pass
    stats["large_files"] = sorted(stats["large_files"], key=lambda x: -x["size_mb"])[:10]
    for bc in [home/"AppData"/"Local"/"Google"/"Chrome"/"User Data"/"Default"/"Cache", home/"AppData"/"Local"/"Microsoft"/"Edge"/"User Data"/"Default"/"Cache"]:
        if bc.exists():
            try: stats["browser_cache_mb"] += round(sum(f.stat().st_size for f in bc.rglob("*") if f.is_file()) / (1024*1024), 1)
            except: pass
    if IS_WINDOWS:
        sd = home / "AppData" / "Roaming" / "Microsoft" / "Windows" / "Start Menu" / "Programs" / "Startup"
        if sd.exists():
            try: stats["startup_items"] = len(list(sd.iterdir()))
            except: pass
    return stats

