BG    = "#010C14"   # Deep void — near-black with oceanic tint
BG2   = "#061522"   # Panel surface — structural depth
BG3   = "#0C2035"   # Raised state — interactive surfaces
BG4   = "#081A28"   # Input wells — slightly sunken
ACCENT= "#00C8F5"   # Primary cyan — clear, purposeful
ACCT2 = "#00EAFF"   # Highlight cyan — maximum luminosity
GREEN = "#00E87A"   # Status green — alive & healthy
AMBER = "#FFC244"   # Warning amber — warm, readable
RED   = "#FF3D5C"   # Error red — vivid, unmissable
BLUE  = "#3D82FF"   # Info blue — cool, informational
TEXT  = "#C8E8FA"   # Body text — soft cool white
MUTED = "#1C3D52"   # Quiet labels — recede gracefully
DIM   = "#102232"   # Hairline separators — barely visible
GLOW  = "#004466"   # Hover glow layer
_FM   = "Consolas"
F_TINY = (_FM, 8);  F_SM  = (_FM, 9);  F_MONO = (_FM, 10)
F_MED  = (_FM, 11, "bold");  F_BIG = (_FM, 13, "bold")
F_HUGE = (_FM, 15, "bold");  F_CODE = (_FM, 9)

class NxBtn(tk.Canvas):
    """Flat button — thin accent bar, glowing border on hover, click flash."""
    _RADIUS = 4

    def __init__(self, parent, text, cmd, w=130, h=28, col=None, font=F_MONO, **kw):
        col = col or ACCENT
        super().__init__(parent, width=w, height=h, bg=parent["bg"],
                         bd=0, highlightthickness=0, cursor="hand2", **kw)
        self._d = dict(cmd=cmd, w=w, h=h, col=col, font=font,
                       text=text, hover=False, pressed=False)
        self._draw()
        self.bind("<Enter>",           lambda _: self._set(hover=True))
        self.bind("<Leave>",           lambda _: self._set(hover=False, pressed=False))
        self.bind("<Button-1>",        lambda _: self._press())
        self.bind("<ButtonRelease-1>", lambda _: self._release())

    def _set(self, **kw):
        self._d.update(kw); self._draw()

    def _press(self):
        self._d["pressed"] = True; self._draw()

    def _release(self):
        if self._d["pressed"]:
            self._d["pressed"] = False; self._draw()
            try: self._d["cmd"]()
            except Exception: pass

    def _rounded_rect(self, x1, y1, x2, y2, r, **kw):
        pts = [
            x1+r, y1,   x2-r, y1,
            x2,   y1+r, x2,   y2-r,
            x2-r, y2,   x1+r, y2,
            x1,   y2-r, x1,   y1+r,
        ]
        self.create_polygon(pts, smooth=False, **kw)

    def _draw(self):
        d = self._d; self.delete("all")
        w, h, col = d["w"], d["h"], d["col"]
        hover, pressed = d["hover"], d["pressed"]
        if pressed:
            fill_bg, text_col, border_col = col, "#000000", col
        elif hover:
            fill_bg, text_col, border_col = GLOW, col, col
        else:
            fill_bg, text_col, border_col = BG3, col, DIM
        self._rounded_rect(0, 0, w-1, h-1, self._RADIUS,
                           fill=fill_bg, outline=border_col, width=1)
        if not pressed:
            self.create_rectangle(0, 0, 2, h, fill=col, outline="")
        self.create_text(w//2 + 1, h//2, text=d["text"],
                         fill=text_col, font=d["font"], anchor="center")

    def set_text(self, t): self._d["text"] = t; self._draw()

class PulseDot(tk.Canvas):
    """Status dot with smooth 4-step breathe animation."""
    _STEPS   = [1.0, 0.7, 0.35, 0.7]   # alpha cycle (simulated via mix with BG)
    _DELAYS  = [600, 400, 600, 400]      # ms per step

    def __init__(self, parent, size=10, color=GREEN, **kw):
        super().__init__(parent, width=size, height=size,
                         bg=parent["bg"], bd=0, highlightthickness=0, **kw)
        self._sz    = size
        self._col   = color
        self._alive = True
        self._step  = 0
        self._draw(1.0)
        self._pulse()

    @staticmethod
    def _lerp_hex(hex_col: str, alpha: float) -> str:
        """Blend hex_col toward #010C14 (BG) by 1-alpha."""
        try:
            hc = hex_col.lstrip("#")
            r, g, b = int(hc[0:2],16), int(hc[2:4],16), int(hc[4:6],16)
            br, bg_, bb = 1, 12, 20   # BG = #010C14
            r2 = int(r*alpha + br*(1-alpha))
            g2 = int(g*alpha + bg_*(1-alpha))
            b2 = int(b*alpha + bb*(1-alpha))
            return f"#{r2:02x}{g2:02x}{b2:02x}"
        except Exception:
            return hex_col

    def _draw(self, alpha: float):
        try:
            self.delete("all")
            p = 1
            c = self._lerp_hex(self._col, alpha)
            self.create_oval(p, p, self._sz-p, self._sz-p, fill=c, outline="")
        except Exception:
            pass

    def _pulse(self):
        if not self._alive: return
        try:
            i = self._step % len(self._STEPS)
            self._draw(self._STEPS[i])
            self._step += 1
            self.after(self._DELAYS[i], self._pulse)
        except Exception:
            self._alive = False

    def set_color(self, c): self._col = c; self._draw(1.0)

    def destroy(self):
        self._alive = False
        try: super().destroy()
        except Exception: pass

