class ScriptManagerWindow:
    """
    Redesigned (v19.0.6) Script Library manager.
    - Left   : category sidebar with SVG-style canvas icons + counts
    - Center : search bar + card-style script list with per-script icons
    - Right  : detail panel with syntax-highlighted code viewer + actions
    Pure-Tkinter — icons are drawn on tk.Canvas with vector primitives,
    so no extra dependencies and they stay crisp at any DPI.
    """

    # ── Category palette (sidebar accent per category) ────────────────
    CAT_COLORS = {
        "All":          "#00E5FF",
        "Cleaning":     "#00CCFF",
        "System":       "#00E5FF",
        "Network":      "#4A9EFF",
        "Security":     "#C084FF",
        "Files":        "#FF8C00",
        "Developer":    "#00FF88",
        "Monitoring":   "#7AE582",
        "Automation":   "#00E5FF",
        "Backup":       "#FFD700",
        "Media":        "#FF6FD8",
        "Data":         "#5BC0EB",
        "Productivity": "#FFB347",
        "Fun":          "#FF6FD8",
        "Gaming":       "#FF4444",
        "Custom":       "#FFD700",
        "General":      "#888888",
    }

    # Map category → default icon name (used in sidebar)
    CAT_ICONS = {
        "All":          "grid",
        "Cleaning":     "broom",
        "System":       "chip",
        "Network":      "globe",
        "Security":     "shield",
        "Files":        "folder",
        "Developer":    "code",
        "Monitoring":   "chart",
        "Automation":   "bolt",
        "Backup":       "archive",
        "Media":        "image",
        "Data":         "database",
        "Productivity": "clock",
        "Fun":          "sparkle",
        "Gaming":       "gamepad",
        "Custom":       "star",
        "General":      "terminal",
    }

    # ── Icon renderer: draws crisp SVG-style icons on a tk.Canvas ────
    @staticmethod
    def _draw_icon(canvas, name: str, x: int, y: int, size: int = 16, color: str = "#00E5FF"):
        """
        Draw a vector icon centred on (x, y) on the given Canvas.
        Returns the list of created item ids so callers can tag/delete them.
        All icons are designed on a 24-unit grid and scaled to `size`.
        """
        s   = size / 24.0
        p   = lambda v: int(round(v * s))
        ids = []
        cx, cy = x, y
        def L(x1,y1,x2,y2,w=2):
            ids.append(canvas.create_line(cx+p(x1-12), cy+p(y1-12), cx+p(x2-12), cy+p(y2-12),
                                          fill=color, width=max(1,int(w*s)), capstyle="round"))
        def R(x1,y1,x2,y2,w=2,fill=""):
            ids.append(canvas.create_rectangle(cx+p(x1-12), cy+p(y1-12), cx+p(x2-12), cy+p(y2-12),
                                               outline=color, width=max(1,int(w*s)), fill=fill))
        def C(x1,y1,x2,y2,w=2,fill=""):
            ids.append(canvas.create_oval(cx+p(x1-12), cy+p(y1-12), cx+p(x2-12), cy+p(y2-12),
                                          outline=color, width=max(1,int(w*s)), fill=fill))
        def P(points, w=2, fill=""):
            pts = []
            for px, py in points:
                pts.extend([cx+p(px-12), cy+p(py-12)])
            ids.append(canvas.create_polygon(*pts, outline=color, width=max(1,int(w*s)), fill=fill))

        n = (name or "terminal").lower()

        if n == "broom":
            L(15,3,9,15); P([(4,21),(9,15),(15,21),(20,17),(15,11)], fill=color)
        elif n == "trash":
            L(3,6,21,6); L(8,6,8,3); L(16,6,16,3); R(5,6,19,21); L(10,10,10,18); L(14,10,14,18)
        elif n == "chip":
            R(6,6,18,18); R(9,9,15,15)
            for v in (3,9,15,21):
                L(v,3,v,5); L(v,19,v,21); L(3,v,5,v); L(19,v,21,v)
        elif n == "battery":
            R(3,8,19,16); R(19,11,21,13, fill=color)
            R(5,10,9,14, fill=color); R(10,10,13,14, fill=color)
        elif n == "clock":
            C(3,3,21,21); L(12,12,12,7); L(12,12,16,14)
        elif n == "terminal":
            R(3,5,21,19); L(7,10,10,13); L(7,16,10,13); L(12,16,17,16)
        elif n == "disk":
            R(3,5,21,19); R(7,5,17,11, fill=color); C(10,14,14,18)
        elif n == "globe":
            C(3,3,21,21); L(3,12,21,12); L(12,3,12,21)
            ids.append(canvas.create_arc(cx+p(-3), cy+p(-9), cx+p(9), cy+p(9),
                                         style="arc", outline=color, width=max(1,int(2*s)),
                                         start=0, extent=180))
        elif n == "wifi":
            for r, w in ((10,2),(7,2),(4,2)):
                ids.append(canvas.create_arc(cx+p(12-r-12), cy+p(12-r-12+4),
                                             cx+p(12+r-12), cy+p(12+r-12+4),
                                             style="arc", outline=color,
                                             width=max(1,int(w*s)), start=30, extent=120))
            C(11,18,13,20, fill=color)
        elif n == "shield":
            P([(12,3),(20,6),(20,12),(12,21),(4,12),(4,6)])
            L(8,12,11,15); L(11,15,16,9)
        elif n == "folder":
            P([(3,7),(10,7),(12,9),(21,9),(21,19),(3,19)])
        elif n == "code":
            L(8,8,4,12); L(4,12,8,16); L(16,8,20,12); L(20,12,16,16); L(14,6,10,18)
        elif n == "chart":
            L(4,20,20,20); L(4,4,4,20)
            R(6,14,9,20, fill=color); R(11,10,14,20, fill=color); R(16,6,19,20, fill=color)
        elif n == "camera":
            R(3,7,21,19); R(9,5,15,7); C(9,10,15,16); C(11,12,13,14, fill=color)
        elif n == "archive":
            R(3,5,21,9); R(5,9,19,20); L(10,13,14,13)
        elif n == "image":
            R(3,5,21,19); C(8,8,12,12, fill=color); P([(3,19),(9,12),(14,16),(18,12),(21,16),(21,19)], fill=color)
        elif n == "database":
            C(4,4,20,8); L(4,6,4,18); L(20,6,20,18); C(4,16,20,20); C(4,10,20,14)
        elif n == "sparkle":
            P([(12,3),(14,10),(21,12),(14,14),(12,21),(10,14),(3,12),(10,10)], fill=color)
        elif n == "gamepad":
            R(3,8,21,18); C(6,11,10,15); L(7,13,9,13); L(8,12,8,14)
            C(15,11,17,13, fill=color); C(17,13,19,15, fill=color)
        elif n == "power":
            ids.append(canvas.create_arc(cx+p(-9), cy+p(-7),
                                         cx+p(9), cy+p(11),
                                         style="arc", outline=color,
                                         width=max(1,int(2*s)), start=60, extent=420))
            L(12,3,12,12)
        elif n == "bolt":
            P([(13,3),(5,14),(11,14),(9,21),(19,9),(13,9)], fill=color)
        elif n == "star":
            P([(12,3),(14,10),(21,10),(15,14),(17,21),(12,16),(7,21),(9,14),(3,10),(10,10)], fill=color)
        elif n == "grid":
            for ax in (4,11,18):
                for ay in (4,11,18):
                    R(ax,ay,ax+3,ay+3, fill=color, w=1)
        else:  # default fallback — terminal
            R(3,5,21,19); L(7,10,10,13); L(7,16,10,13); L(12,16,17,16)
        return ids

    # ── Lifecycle ─────────────────────────────────────────────────────
    def __init__(self, parent):
        if not HAS_TK:
            log.warning("[SCRIPT-MGR] Tkinter not available")
            return
        self.win = tk.Toplevel(parent)
        self.win.title("BUTLER AI  ·  SCRIPT LIBRARY")
        self.win.configure(bg=BG)
        self.win.minsize(1200, 740)
        self.win.resizable(True, True)
        self._all_scripts: list = []
        self._filtered: list = []
        self._selected_id: str | None = None
        self._active_cat: str = "All"
        self._cat_buttons: dict = {}
        self._build()
        self._load()
        self.win.lift()

    # ── Build UI ─────────────────────────────────────────────────────
    def _build(self):
        root = self.win

        # ── Header ─────────────────────────────────────────────────
        hdr = tk.Frame(root, bg=BG2); hdr.pack(fill="x")
        lf  = tk.Frame(hdr, bg=BG2); lf.pack(side="left", padx=14, pady=10)
        # Logo icon
        logo = tk.Canvas(lf, width=22, height=22, bg=BG2, bd=0, highlightthickness=0)
        logo.pack(side="left", padx=(0,8))
        self._draw_icon(logo, "sparkle", 11, 11, 20, ACCT2)
        tk.Label(lf, text="BUTLER", font=(_FM,15,"bold"), fg=ACCENT, bg=BG2).pack(side="left")
        tk.Label(lf, text="AI",     font=(_FM,15,"bold"), fg=ACCT2,  bg=BG2).pack(side="left")
        tk.Label(lf, text="  ·  SCRIPT LIBRARY", font=F_SM, fg=MUTED, bg=BG2).pack(side="left", pady=2)
        rf = tk.Frame(hdr, bg=BG2); rf.pack(side="right", padx=12, pady=8, fill="y")
        self._count_lbl = tk.Label(rf, text="0 scripts", font=F_TINY, fg=MUTED, bg=BG2)
        self._count_lbl.pack(side="right", padx=8)
        NxBtn(rf, "+ NEW SCRIPT", self._new_script, w=140, h=28, col=GREEN,  font=F_TINY).pack(side="right", padx=4)
        NxBtn(rf, "⟳ REFRESH",    self._load,       w=100, h=28, col=ACCENT, font=F_TINY).pack(side="right", padx=4)
        tk.Frame(root, bg=ACCENT, height=1).pack(fill="x")

        # ── 3-pane body: sidebar | list | detail ─────────────────
        body = tk.Frame(root, bg=BG); body.pack(fill="both", expand=True)

        # ── Sidebar (categories) ──────────────────────────────────
        side = tk.Frame(body, bg=BG2, width=210); side.pack(side="left", fill="y")
        side.pack_propagate(False)
        tk.Label(side, text="CATEGORIES", font=F_TINY, fg=MUTED, bg=BG2,
                 padx=14, pady=10).pack(anchor="w")
        tk.Frame(side, bg=DIM, height=1).pack(fill="x")
        self._side_inner = tk.Frame(side, bg=BG2)
        self._side_inner.pack(fill="both", expand=True, pady=4)

        tk.Frame(side, bg=DIM, height=1).pack(fill="x")
        ftxt = tk.Label(side, text=f"  Butler AI · v{VERSION.split('-')[0]}",
                        font=F_TINY, fg=MUTED, bg=BG2, anchor="w")
        ftxt.pack(fill="x", side="bottom", pady=6)

        tk.Frame(body, bg=DIM, width=1).pack(side="left", fill="y")

        # ── Middle: search + script cards ─────────────────────────
        mid = tk.Frame(body, bg=BG, width=420); mid.pack(side="left", fill="y")
        mid.pack_propagate(False)

        # Search
        sb = tk.Frame(mid, bg=BG3, padx=10, pady=8); sb.pack(fill="x")
        sc = tk.Canvas(sb, width=16, height=16, bg=BG3, bd=0, highlightthickness=0)
        sc.pack(side="left", padx=(2,6))
        # tiny magnifier
        sc.create_oval(2,2,11,11, outline=MUTED, width=2)
        sc.create_line(9,9,15,15, fill=MUTED, width=2, capstyle="round")
        self._search_var = tk.StringVar()
        self._search_var.trace_add("write", lambda *_: self._filter())
        srch = tk.Entry(sb, textvariable=self._search_var, font=F_MONO,
                        bg=BG4, fg=TEXT, insertbackground=ACCT2,
                        relief="flat", bd=0, highlightthickness=1,
                        highlightbackground=DIM, highlightcolor=ACCENT)
        srch.pack(side="left", fill="x", expand=True, ipady=5)

        tk.Frame(mid, bg=DIM, height=1).pack(fill="x")

        # Scrollable card list
        wrap = tk.Frame(mid, bg=BG); wrap.pack(fill="both", expand=True)
        self._list_canvas = tk.Canvas(wrap, bg=BG, bd=0, highlightthickness=0)
        lscroll = tk.Scrollbar(wrap, orient="vertical", command=self._list_canvas.yview,
                                bg=BG2, troughcolor=BG3, bd=0)
        self._list_canvas.configure(yscrollcommand=lscroll.set)
        lscroll.pack(side="right", fill="y")
        self._list_canvas.pack(side="left", fill="both", expand=True)
        self._list_inner = tk.Frame(self._list_canvas, bg=BG)
        self._list_window = self._list_canvas.create_window((0,0), window=self._list_inner, anchor="nw")
        self._list_inner.bind("<Configure>", lambda e: self._list_canvas.configure(
            scrollregion=self._list_canvas.bbox("all")))
        self._list_canvas.bind("<Configure>", lambda e: self._list_canvas.itemconfigure(
            self._list_window, width=e.width))
        # mouse-wheel scrolling
        def _wheel(e):
            self._list_canvas.yview_scroll(int(-1*(e.delta/120)), "units")
        self._list_canvas.bind_all("<MouseWheel>", _wheel)

        tk.Frame(body, bg=DIM, width=1).pack(side="left", fill="y")

        # ── Detail panel ─────────────────────────────────────────
        right = tk.Frame(body, bg=BG); right.pack(side="left", fill="both", expand=True)

        # Header
        self._detail_hdr = tk.Frame(right, bg=BG2, pady=10); self._detail_hdr.pack(fill="x")
        hrow = tk.Frame(self._detail_hdr, bg=BG2); hrow.pack(fill="x", padx=14)
        self._detail_icon = tk.Canvas(hrow, width=36, height=36, bg=BG2, bd=0, highlightthickness=0)
        self._detail_icon.pack(side="left", padx=(0,10))
        self._draw_icon(self._detail_icon, "sparkle", 18, 18, 30, MUTED)
        hcol = tk.Frame(hrow, bg=BG2); hcol.pack(side="left", fill="x", expand=True)
        self._name_lbl = tk.Label(hcol, text="Select a script →",
                                  font=(_FM,14,"bold"), fg=ACCT2, bg=BG2, anchor="w")
        self._name_lbl.pack(anchor="w")
        self._desc_lbl = tk.Label(hcol, text="Browse categories on the left to get started.",
                                  font=F_SM, fg=MUTED, bg=BG2, anchor="w",
                                  wraplength=480, justify="left")
        self._desc_lbl.pack(anchor="w", pady=(2,4))
        self._tags_lbl = tk.Label(hcol, text="", font=F_TINY, fg=BLUE, bg=BG2, anchor="w")
        self._tags_lbl.pack(anchor="w")

        # Actions
        acts = tk.Frame(right, bg=BG, pady=6); acts.pack(fill="x", padx=14)
        self._run_btn  = NxBtn(acts, "▶  RUN ON PC", self._run,    w=150, h=32, col=GREEN,  font=F_MED); self._run_btn.pack(side="left", padx=(0,8))
        self._edit_btn = NxBtn(acts, "✎  EDIT",      self._edit,   w=100, h=32, col=ACCENT, font=F_SM ); self._edit_btn.pack(side="left", padx=(0,8))
        self._copy_btn = NxBtn(acts, "⧉  COPY",      self._copy_code, w=100, h=32, col=BLUE,   font=F_SM ); self._copy_btn.pack(side="left", padx=(0,8))
        self._del_btn  = NxBtn(acts, "✕  DELETE",    self._delete, w=100, h=32, col=RED,    font=F_SM ); self._del_btn.pack(side="left")
        self._size_lbl = tk.Label(acts, text="", font=F_TINY, fg=MUTED, bg=BG)
        self._size_lbl.pack(side="right", padx=10)

        tk.Frame(right, bg=DIM, height=1).pack(fill="x", pady=(6,0))

        # Code viewer
        cv_hdr = tk.Frame(right, bg=BG); cv_hdr.pack(fill="x", pady=(6,2), padx=14)
        cvi = tk.Canvas(cv_hdr, width=14, height=14, bg=BG, bd=0, highlightthickness=0)
        cvi.pack(side="left", padx=(0,6)); self._draw_icon(cvi, "code", 7, 7, 14, MUTED)
        tk.Label(cv_hdr, text="PYTHON CODE", font=F_TINY, fg=MUTED, bg=BG).pack(side="left")

        cv_wrap = tk.Frame(right, bg=BG); cv_wrap.pack(fill="both", expand=True, padx=14, pady=(2,10))
        cv_scroll = tk.Scrollbar(cv_wrap, orient="vertical", bg=BG2, troughcolor=BG3, bd=0)
        cv_scroll.pack(side="right", fill="y")
        self._code_tv = tk.Text(cv_wrap, font=F_CODE,
                                bg="#000000", fg="#88CCFF",
                                insertbackground=ACCT2, relief="flat",
                                state="disabled", wrap="none",
                                highlightthickness=1, highlightbackground=DIM,
                                padx=12, pady=10,
                                yscrollcommand=cv_scroll.set)
        self._code_tv.pack(fill="both", expand=True)
        cv_scroll.config(command=self._code_tv.yview)
        self._code_tv.tag_config("kw",      foreground="#C084FF")
        self._code_tv.tag_config("str_",    foreground="#FFB800")
        self._code_tv.tag_config("comment", foreground="#2A8A4A")
        self._code_tv.tag_config("fn",      foreground="#00FF88")

        # Footer / status
        tk.Frame(root, bg=ACCENT, height=1).pack(fill="x", side="bottom")
        ft = tk.Frame(root, bg=BG2, pady=4); ft.pack(fill="x", side="bottom")
        self._status_lbl = tk.Label(ft, text="Ready", font=F_TINY, fg=GREEN, bg=BG2)
        self._status_lbl.pack(side="left", padx=10)
        tk.Label(ft, text="Scripts stored in butler_scripts/  ·  Loaded on demand",
                 font=F_TINY, fg=MUTED, bg=BG2).pack(side="right", padx=10)

    # ── Sidebar build ─────────────────────────────────────────────
    def _build_sidebar(self):
        # Wipe
        for w in self._side_inner.winfo_children(): w.destroy()
        self._cat_buttons.clear()

        # Build count per category from current scripts
        counts: dict = {}
        for s in self._all_scripts:
            c = s.get("category", "Custom")
            counts[c] = counts.get(c, 0) + 1
        cats = ["All"] + sorted(counts.keys())

        for cat in cats:
            n = len(self._all_scripts) if cat == "All" else counts.get(cat, 0)
            self._add_cat_row(cat, n)

    def _add_cat_row(self, cat: str, n: int):
        active = (cat == self._active_cat)
        col = self.CAT_COLORS.get(cat, MUTED)
        bg  = BG3 if active else BG2

        row = tk.Frame(self._side_inner, bg=bg, padx=10, pady=6, cursor="hand2")
        row.pack(fill="x", padx=4, pady=1)

        # left accent bar
        bar = tk.Frame(row, bg=col if active else bg, width=3)
        bar.pack(side="left", fill="y", padx=(0,8))

        ic = tk.Canvas(row, width=20, height=20, bg=bg, bd=0, highlightthickness=0)
        ic.pack(side="left")
        icon_name = self.CAT_ICONS.get(cat, "terminal")
        self._draw_icon(ic, icon_name, 10, 10, 18, col)

        lbl = tk.Label(row, text=cat, font=F_SM,
                       fg=ACCT2 if active else TEXT, bg=bg, padx=8, anchor="w")
        lbl.pack(side="left", fill="x", expand=True)

        cnt = tk.Label(row, text=str(n), font=F_TINY,
                       fg=col if active else MUTED, bg=bg)
        cnt.pack(side="right")

        def _go(_e=None, c=cat):
            self._active_cat = c
            self._build_sidebar()
            self._filter()
        for w in (row, ic, lbl, cnt, bar):
            w.bind("<Button-1>", _go)
        # hover
        def _enter(_e, frame=row, label=lbl, cnt_w=cnt):
            if cat == self._active_cat: return
            for x in (frame, label, cnt_w): x.configure(bg=BG3)
        def _leave(_e, frame=row, label=lbl, cnt_w=cnt):
            if cat == self._active_cat: return
            for x in (frame, label, cnt_w): x.configure(bg=BG2)
        row.bind("<Enter>", _enter); row.bind("<Leave>", _leave)
        self._cat_buttons[cat] = row

    # ── Data load ─────────────────────────────────────────────────
    def _load(self):
        try:
            self._all_scripts = _pc_scripts_list()
            self._count_lbl.config(text=f"{len(self._all_scripts)} scripts")
            self._build_sidebar()
            self._filter()
            self._flash(f"Loaded {len(self._all_scripts)} scripts")
        except Exception as e:
            self._flash(f"Load error: {e}", err=True)

    def _filter(self):
        q   = self._search_var.get().lower().strip()
        cat = self._active_cat
        matches = []
        for s in self._all_scripts:
            if cat != "All" and s.get("category") != cat: continue
            if q:
                blob = " ".join([
                    s.get("name", ""), s.get("description", ""),
                    " ".join(s.get("tags", [])), s.get("category", "")
                ]).lower()
                if q not in blob: continue
            matches.append(s)
        self._filtered = matches
        self._render_cards()

    # ── Card rendering ────────────────────────────────────────────
    def _render_cards(self):
        for w in self._list_inner.winfo_children(): w.destroy()
        if not self._filtered:
            tk.Label(self._list_inner, text="No scripts match — try different keywords",
                     font=F_SM, fg=MUTED, bg=BG, pady=20).pack(fill="x")
            return
        for s in self._filtered:
            self._add_card(s)

    def _add_card(self, s: dict):
        sid = s["id"]
        active = (sid == self._selected_id)
        col = self.CAT_COLORS.get(s.get("category", "Custom"), MUTED)
        bg  = BG3 if active else BG2

        card = tk.Frame(self._list_inner, bg=bg, cursor="hand2",
                        highlightthickness=1, highlightbackground=col if active else DIM)
        card.pack(fill="x", padx=8, pady=4)

        top = tk.Frame(card, bg=bg, padx=10, pady=8); top.pack(fill="x")
        ic = tk.Canvas(top, width=28, height=28, bg=bg, bd=0, highlightthickness=0)
        ic.pack(side="left", padx=(0,10))
        self._draw_icon(ic, s.get("icon", self.CAT_ICONS.get(s.get("category","Custom"), "terminal")),
                        14, 14, 24, col)

        info = tk.Frame(top, bg=bg); info.pack(side="left", fill="x", expand=True)
        tk.Label(info, text=s["name"], font=(_FM,11,"bold"),
                 fg=ACCT2 if active else TEXT, bg=bg, anchor="w").pack(anchor="w")
        desc = s.get("description","") or "—"
        if len(desc) > 70: desc = desc[:67] + "…"
        tk.Label(info, text=desc, font=F_TINY, fg=MUTED, bg=bg, anchor="w").pack(anchor="w")
        meta = tk.Label(info, text=f"{s.get('category','?')}  ·  {(s.get('size_bytes',0)//1024) or 1} KB",
                        font=F_TINY, fg=col, bg=bg, anchor="w")
        meta.pack(anchor="w", pady=(2,0))

        def _pick(_e=None, scr=s):
            self._selected_id = scr["id"]
            self._render_cards()
            self._show_detail(scr)
        for w in (card, top, ic, info):
            w.bind("<Button-1>", _pick)
            for child in w.winfo_children(): child.bind("<Button-1>", _pick)
        def _enter(_e, c=card):
            if sid == self._selected_id: return
            c.configure(highlightbackground=col)
        def _leave(_e, c=card):
            if sid == self._selected_id: return
            c.configure(highlightbackground=DIM)
        card.bind("<Enter>", _enter); card.bind("<Leave>", _leave)

    # ── Detail panel ──────────────────────────────────────────────
    def _show_detail(self, s: dict):
        col = self.CAT_COLORS.get(s.get("category","Custom"), MUTED)
        # redraw header icon in category color
        self._detail_icon.delete("all")
        self._draw_icon(self._detail_icon,
                        s.get("icon", self.CAT_ICONS.get(s.get("category","Custom"),"terminal")),
                        18, 18, 30, col)
        self._name_lbl.config(text=s["name"])
        self._desc_lbl.config(text=s.get("description","") or "No description")
        tags = " · ".join(f"#{t}" for t in s.get("tags", []))
        self._tags_lbl.config(text=f"{s.get('category','?')}    {tags}", fg=col)
        sz = s.get("size_bytes", 0)
        self._size_lbl.config(text=f"{sz} bytes" if sz < 1024 else f"{sz//1024} KB")
        self._load_code(s["id"])

    def _load_code(self, script_id: str):
        self._code_tv.config(state="normal")
        self._code_tv.delete("1.0", "end")
        try:
            data = _pc_scripts_get(script_id)
            code = data["code"] if data else "# Code not found"
        except Exception as e:
            code = f"# Error loading code: {e}"
        self._code_tv.insert("1.0", code)
        self._apply_syntax(code)
        self._code_tv.config(state="disabled")

    def _apply_syntax(self, code: str):
        import re as _re
        tv = self._code_tv
        for m in _re.finditer(r'#[^\n]*', code):
            tv.tag_add("comment", f"1.0+{m.start()}c", f"1.0+{m.end()}c")
        for m in _re.finditer(r'(?:\"[^\"\n]*\"|\'[^\'\n]*\')', code):
            tv.tag_add("str_", f"1.0+{m.start()}c", f"1.0+{m.end()}c")
        for kw in ['import','from','def','class','return','if','else','elif',
                   'for','while','try','except','with','as','in','not','and','or',
                   'True','False','None','print','input','raise','lambda','yield','pass','continue','break']:
            for m in _re.finditer(rf'\b{kw}\b', code):
                tv.tag_add("kw", f"1.0+{m.start()}c", f"1.0+{m.end()}c")

    # ── Actions ───────────────────────────────────────────────────
    def _run(self):
        if not self._selected_id:
            self._flash("Select a script first", err=True); return
        data = _pc_scripts_get(self._selected_id)
        if not data:
            self._flash("Script not found", err=True); return
        name = data["name"]
        self._flash(f"Running: {name}…")
        def _exec():
            try:
                result = _run_script(data["code"], "python", timeout=60)
                out = result.get("output","") or "Script completed with no output"
                ok  = result.get("success", True)
                self.win.after(0, lambda: self._show_output(name, out, ok))
            except Exception as e:
                self.win.after(0, lambda err=str(e): self._show_output(name, err, False))
        import threading as _th
        _th.Thread(target=_exec, daemon=True, name="script-mgr-run").start()

    def _show_output(self, name: str, output: str, success: bool):
        out_win = tk.Toplevel(self.win)
        out_win.title(f"Output: {name}"); out_win.configure(bg=BG); out_win.geometry("760x460")
        col = GREEN if success else RED
        hdr = tk.Frame(out_win, bg=BG2, pady=8); hdr.pack(fill="x")
        ic = tk.Canvas(hdr, width=22, height=22, bg=BG2, bd=0, highlightthickness=0)
        ic.pack(side="left", padx=(12,8))
        self._draw_icon(ic, "bolt" if success else "shield", 11, 11, 20, col)
        tk.Label(hdr, text=f"{'SUCCESS' if success else 'FAILED'}  ·  {name}",
                 font=F_MED, fg=col, bg=BG2).pack(side="left")
        tk.Frame(out_win, bg=col, height=1).pack(fill="x")
        tv = scrolledtext.ScrolledText(out_win, font=F_CODE, bg="#000000",
                                       fg="#88FF99" if success else "#FF8888",
                                       state="normal", relief="flat",
                                       highlightthickness=0, padx=12, pady=10)
        tv.pack(fill="both", expand=True, padx=10, pady=10)
        tv.insert("1.0", output); tv.config(state="disabled")
        NxBtn(out_win, "CLOSE", out_win.destroy, w=100, h=28, col=MUTED, font=F_SM).pack(pady=8)
        self._flash(f"{'Done' if success else 'Failed'}: {name}", err=not success)

    def _copy_code(self):
        if not self._selected_id: return
        data = _pc_scripts_get(self._selected_id)
        if not data: return
        try:
            self.win.clipboard_clear(); self.win.clipboard_append(data["code"]); self.win.update()
            self._flash("Code copied to clipboard")
        except Exception as e:
            self._flash(f"Copy error: {e}", err=True)

    def _new_script(self): self._open_editor(None)
    def _edit(self):
        if not self._selected_id: self._flash("Select a script first", err=True); return
        data = _pc_scripts_get(self._selected_id)
        if data: self._open_editor(data)

    def _open_editor(self, existing: dict | None):
        is_edit = existing is not None
        dlg = tk.Toplevel(self.win)
        dlg.title("Edit Script" if is_edit else "New Script")
        dlg.configure(bg=BG); dlg.geometry("760x640")
        tk.Label(dlg, text=("EDIT SCRIPT" if is_edit else "NEW SCRIPT"),
                 font=F_BIG, fg=ACCT2, bg=BG, pady=8).pack()
        tk.Frame(dlg, bg=ACCENT, height=1).pack(fill="x")

        form = tk.Frame(dlg, bg=BG, pady=10); form.pack(fill="x", padx=16)
        def row(label, val=""):
            f = tk.Frame(form, bg=BG); f.pack(fill="x", pady=3)
            tk.Label(f, text=label, font=F_TINY, fg=MUTED, bg=BG, width=14, anchor="w").pack(side="left")
            e = tk.Entry(f, font=F_MONO, bg=BG4, fg=TEXT, insertbackground=ACCT2,
                         relief="flat", bd=0, highlightthickness=1,
                         highlightbackground=DIM, highlightcolor=ACCENT)
            e.pack(side="left", fill="x", expand=True, ipady=3); e.insert(0, val); return e
        name_e = row("Name:",        existing.get("name","")        if is_edit else "")
        desc_e = row("Description:", existing.get("description","") if is_edit else "")
        cats_e = row("Category:",    existing.get("category","Custom") if is_edit else "Custom")
        tags_e = row("Tags (csv):",  ", ".join(existing.get("tags",[])) if is_edit else "")

        tk.Label(dlg, text="Python Code:", font=F_TINY, fg=MUTED, bg=BG).pack(anchor="w", padx=16, pady=(8,2))
        code_tv = scrolledtext.ScrolledText(dlg, font=F_CODE, bg="#000000", fg="#88CCFF",
                                            insertbackground=ACCT2, relief="flat",
                                            highlightthickness=1, highlightbackground=DIM,
                                            padx=12, pady=10, height=14)
        code_tv.pack(fill="both", expand=True, padx=16, pady=4)
        code_tv.insert("1.0", existing["code"] if is_edit and existing.get("code")
                       else "import os\n\n# Your Python script here\nprint('Hello from Butler AI!')\n")

        def _save():
            name = name_e.get().strip(); code = code_tv.get("1.0","end").strip()
            if not name or not code:
                self._flash("Name and code required", err=True); return
            tags = [t.strip() for t in tags_e.get().split(",") if t.strip()]
            sid = (existing["id"] if is_edit else
                   _RE_SCRIPT_ID.sub("_", name.lower().replace(" ", "_"))[:80] or "custom_script")
            try:
                _pc_scripts_save(sid, name, code, desc_e.get().strip(),
                                 cats_e.get().strip() or "Custom", tags)
                dlg.destroy(); self._load(); self._flash(f"Saved: {name}")
            except Exception as e:
                self._flash(f"Save error: {e}", err=True)

        bf = tk.Frame(dlg, bg=BG, pady=8); bf.pack()
        NxBtn(bf, "SAVE SCRIPT", _save,         w=160, h=32, col=GREEN, font=F_MED).pack(side="left", padx=8)
        NxBtn(bf, "CANCEL",      dlg.destroy,   w=100, h=32, col=MUTED, font=F_SM ).pack(side="left")

    def _delete(self):
        if not self._selected_id: return
        name = next((s["name"] for s in self._all_scripts if s["id"] == self._selected_id),
                    self._selected_id)
        dlg = tk.Toplevel(self.win); dlg.title("Confirm Delete")
        dlg.configure(bg=BG); dlg.geometry("380x180")
        ic = tk.Canvas(dlg, width=36, height=36, bg=BG, bd=0, highlightthickness=0)
        ic.pack(pady=(14,4)); self._draw_icon(ic, "trash", 18, 18, 32, RED)
        tk.Label(dlg, text=f"Delete '{name}'?", font=F_MED, fg=RED,  bg=BG).pack()
        tk.Label(dlg, text="This cannot be undone.", font=F_TINY, fg=MUTED, bg=BG).pack(pady=(2,8))
        def _go():
            try: _pc_scripts_delete(self._selected_id)
            except Exception as e: self._flash(f"Delete error: {e}", err=True); return
            self._selected_id = None
            dlg.destroy(); self._load(); self._flash(f"Deleted: {name}")
        bf = tk.Frame(dlg, bg=BG, pady=8); bf.pack()
        NxBtn(bf, "DELETE", _go,         w=100, h=30, col=RED,   font=F_SM).pack(side="left", padx=8)
        NxBtn(bf, "CANCEL", dlg.destroy, w=100, h=30, col=MUTED, font=F_SM).pack(side="left")

    def _flash(self, msg: str, err: bool = False):
        col = RED if err else GREEN
        self._status_lbl.config(text=msg, fg=col)
        self.win.after(3000, lambda: self._status_lbl.config(text="Ready", fg=GREEN)
                       if self._status_lbl.winfo_exists() else None)

def _build_gui(ip, port):
    """Butler AI aesthetic - pure black, cyan accents, pulse dots, monospace."""
    if not HAS_TK: return None
    try:
        root = tk.Tk()
        root.title(f"BUTLER AI SERVER  v{VERSION}")
        root.configure(bg=BG)
        root.minsize(860, 680)  # reduced so QR panel fits on smaller screens
        root.resizable(True, True)
        _gui["root"] = root

        # ── Header ────────────────────────────────────────────────
        hdr = tk.Frame(root, bg=BG2, pady=0); hdr.pack(fill="x")
        lf  = tk.Frame(hdr, bg=BG2); lf.pack(side="left", padx=14, pady=9)
        tk.Label(lf, text="BUTLER", font=(_FM,16,"bold"), fg=ACCENT, bg=BG2).pack(side="left")
        tk.Label(lf, text="AI",     font=(_FM,16,"bold"), fg=ACCT2,  bg=BG2).pack(side="left")
        tk.Label(lf, text=f"  ·  SERVER  {VERSION}", font=F_TINY, fg=MUTED, bg=BG2).pack(side="left", pady=2)
        rf = tk.Frame(hdr, bg=BG2); rf.pack(side="right", padx=14, pady=8)
        try:
            dot = PulseDot(rf, size=9, color=GREEN)
            dot.pack(side="right", padx=(6,2), pady=2)
            _gui["dot"] = dot
        except Exception: pass
        ai_lbl = tk.Label(rf, text=" AI: checking… ", font=F_TINY, fg=AMBER, bg=BG3,
                          pady=3, padx=8, relief="flat")
        ai_lbl.pack(side="right", padx=4); _gui["ai_lbl"] = ai_lbl
        dev_lbl = tk.Label(rf, text=" ●  NO DEVICE ", font=F_TINY, fg=RED, bg=BG3,
                           pady=3, padx=8, relief="flat")
        dev_lbl.pack(side="right", padx=4); _gui["dev_lbl"] = dev_lbl
        # Accent hairline
        tk.Frame(root, bg=ACCENT, height=1).pack(fill="x")
        tk.Frame(root, bg=BG3,    height=1).pack(fill="x")

        # ── Connection row ────────────────────────────────────────
        co = tk.Frame(root, bg=BG, padx=14, pady=10); co.pack(fill="x")
        grid = tk.Frame(co, bg=BG); grid.pack(fill="x")
        for i, (lbl, val, cval, hi) in enumerate([
            ("IP ADDRESS",  ip,             ip,             False),
            ("PORT",        str(port),      str(port),      False),
            ("CONNECT",     f"{ip}:{port}", f"{ip}:{port}", True),
        ]):
            card = tk.Frame(grid, bg=BG2, padx=12, pady=10,
                            highlightbackground=ACCENT if hi else DIM,
                            highlightthickness=1)
            card.grid(row=0, column=i, padx=(0, 8) if i < 2 else 0, sticky="nsew")
            tk.Label(card, text=lbl,  font=F_TINY, fg=MUTED, bg=BG2).pack(anchor="w")
            tk.Label(card, text=val,  font=(_FM, 12, "bold"),
                     fg=ACCT2 if hi else TEXT, bg=BG2, pady=3).pack(anchor="w")
            cv = cval
            def _cp(v=cv):
                try:
                    root.clipboard_clear(); root.clipboard_append(v); root.update()
                    fl = _gui.get("flash")
                    if fl:
                        fl.configure(text=f"  Copied  {v}  ", fg=GREEN)
                        root.after(2000, lambda: fl.configure(text="") if fl.winfo_exists() else None)
                except: pass
            NxBtn(card, "COPY", _cp, w=68, h=20, col=ACCENT if hi else MUTED, font=F_TINY).pack(anchor="w", pady=(4,0))
        grid.columnconfigure(0, weight=1); grid.columnconfigure(1, weight=1); grid.columnconfigure(2, weight=2)
        flash = tk.Label(co, text="", font=F_TINY, fg=GREEN, bg=BG, pady=1)
        flash.pack(anchor="w", pady=(6,0)); _gui["flash"] = flash
        tk.Frame(root, bg=DIM, height=1).pack(fill="x")

        # ── Body ──────────────────────────────────────────────────
        body = tk.Frame(root, bg=BG); body.pack(fill="both", expand=True, padx=12, pady=10)

        # ── QR panel ──────────────────────────────────────────────
        qp = tk.Frame(body, bg=BG2, highlightbackground=DIM, highlightthickness=1)
        qp.pack(side="left", padx=(0,10), fill="y")
        qhdr = tk.Frame(qp, bg=BG3); qhdr.pack(fill="x")
        try:
            PulseDot(qhdr, size=7, color=ACCT2).pack(side="left", padx=(10,4), pady=7)
        except Exception: pass
        tk.Label(qhdr, text="SCAN TO CONNECT", font=F_TINY, fg=ACCT2, bg=BG3, pady=7).pack(side="left")
        tk.Frame(qp, bg=ACCENT, height=1).pack(fill="x")
        qr_canvas = tk.Canvas(qp, bg="#000000", bd=0, highlightthickness=0, width=224, height=224)
        qr_canvas.pack(padx=6, pady=6); _gui["qr_canvas"] = qr_canvas
        tk.Label(qp, text="Butler AI  ·  PC Automation", font=F_TINY, fg=MUTED, bg=BG2).pack(pady=(0,4))
        tk.Frame(qp, bg=DIM, height=1).pack(fill="x")
        cr = tk.Frame(qp, bg=BG2, pady=6, padx=8); cr.pack(fill="x")
        crh = tk.Frame(cr, bg=BG2); crh.pack(fill="x")
        tk.Label(crh, text="RESET CODE", font=F_TINY, fg=MUTED, bg=BG2).pack(side="left")
        try:
            PulseDot(crh, size=6, color=GREEN).pack(side="right", pady=2)
        except Exception: pass
        code_lbl = tk.Label(cr, text=f"  {_gs('pairing_code') or '------'}  ",
                            font=(_FM,15,"bold"), fg=ACCT2, bg=BG3, padx=4, pady=5)
        code_lbl.pack(fill="x", pady=(2,0)); _gui["code_lbl"] = code_lbl
        tk.Frame(qp, bg=DIM, height=1).pack(fill="x")
        ba = tk.Frame(qp, bg=BG2, pady=8, padx=8); ba.pack(fill="x")
        # Script Library — moved to top of action area so it is always visible
        sm_count_lbl = tk.Label(ba, text="", font=F_TINY, fg=ACCT2, bg=BG2)
        sm_count_lbl.pack(anchor="w", pady=(0,2))
        def _open_script_mgr():
            try: ScriptManagerWindow(root)
            except Exception as e: print(f"[SCRIPT-MGR] Error: {e}")
        NxBtn(ba, "▶  SCRIPT LIBRARY", _open_script_mgr,
              w=216, h=34, col=GREEN, font=F_MED).pack(pady=(0,6))
        tk.Frame(ba, bg=DIM, height=1).pack(fill="x", pady=(0,6))
        def _new_qr():
            with _pair_lock:
                nc = _gen_code(); _ss("locked_device", None); _ss("pairing_code", nc); _ss("paired_at", None)
            cl = _gui.get("code_lbl")
            if cl: cl.configure(text=f"  {nc}  ")
            _draw_qr(ip, port)
            fl = _gui.get("flash")
            if fl:
                fl.configure(text="  ↺  Unpaired — ready for new device  ", fg=ACCT2)
                root.after(2400, lambda: fl.configure(text="") if fl and fl.winfo_exists() else None)
            print("  [AUTH] ⚠ GUI unpair — server is now OPEN")
        NxBtn(ba, "↺  UNPAIR & RESET", _new_qr, w=216, h=32, col=ACCT2, font=F_MED).pack(pady=(0,5))
        import webbrowser
        NxBtn(ba, "TEST IN BROWSER",
              lambda: webbrowser.open(f"http://{ip}:{port}/api/status"),
              w=216, h=24, col=MUTED, font=F_TINY).pack()

        def _update_sm_count():
            try:
                n = len(list(_PC_SCRIPTS_DIR.glob("*.py"))) if _PC_SCRIPTS_DIR.exists() else 0
                if sm_count_lbl.winfo_exists():
                    sm_count_lbl.config(text=f"{n} scripts ready")
                root.after(10000, _update_sm_count)
            except: pass
        root.after(2000, _update_sm_count)
        tk.Frame(qp, bg=DIM, height=1).pack(fill="x")
        kb_lbl = tk.Label(qp, text=" KB  ···  0 articles", font=F_TINY, fg=MUTED, bg=BG2, pady=3)
        kb_lbl.pack(fill="x"); _gui["kb_lbl"] = kb_lbl
        sigma_lbl = tk.Label(qp, text=" SIGMA-NET  ·  idle", font=F_TINY, fg=MUTED, bg=BG2, pady=2)
        sigma_lbl.pack(fill="x"); _gui["sigma_lbl"] = sigma_lbl

        # ── Log panel  (v19.0.3: pro toolbar + sparklines + footer) ──
        lp = tk.Frame(body, bg=BG); lp.pack(side="left", fill="both", expand=True)

        # Toolbar row 1: title + severity filter chips
        lhdr = tk.Frame(lp, bg=BG); lhdr.pack(fill="x", pady=(0, 4))
        try:
            PulseDot(lhdr, size=6, color=GREEN).pack(side="left", padx=(0, 7), pady=2)
        except Exception: pass
        tk.Label(lhdr, text="ACTIVITY LOG", font=F_TINY, fg=ACCT2, bg=BG).pack(side="left")
        tk.Label(lhdr, text="  ·  live", font=F_TINY, fg=MUTED, bg=BG).pack(side="left")

        # Severity chips (clickable filters)
        _gui["log_filter"]      = "all"
        _gui["log_autoscroll"]  = True
        _gui["log_search"]      = ""
        _gui["log_chip_lbls"]   = {}
        _CHIP_COLS = {"all":ACCT2, "ok":GREEN, "info":BLUE, "warn":AMBER, "err":RED, "heal":GREEN, "guard":AMBER}
        chip_row = tk.Frame(lhdr, bg=BG); chip_row.pack(side="right")
        def _make_chip(key):
            col  = _CHIP_COLS.get(key, MUTED)
            lbl  = tk.Label(chip_row, text=f"{key.upper()}  0",
                            font=F_TINY, fg=col, bg=BG3,
                            padx=8, pady=2, cursor="hand2",
                            highlightthickness=1, highlightbackground=DIM)
            lbl.pack(side="left", padx=2)
            def _on(_e=None, k=key):
                _gui["log_filter"] = k
                # repaint chip borders
                for kk, ll in (_gui.get("log_chip_lbls") or {}).items():
                    try:
                        ll.config(highlightbackground=(_CHIP_COLS.get(kk, MUTED) if kk == k else DIM),
                                  bg=(BG2 if kk == k else BG3))
                    except Exception: pass
                _refresh_log()
            lbl.bind("<Button-1>", _on)
            _gui["log_chip_lbls"][key] = lbl
            return lbl
        for k in ("all", "ok", "info", "warn", "err", "heal", "guard"):
            _make_chip(k)
        # Default active = all
        try: _gui["log_chip_lbls"]["all"].config(bg=BG2, highlightbackground=ACCT2)
        except Exception: pass

        # Toolbar row 2: search + autoscroll + clear
        tools = tk.Frame(lp, bg=BG); tools.pack(fill="x", pady=(0, 4))
        tk.Label(tools, text="  search", font=F_TINY, fg=MUTED, bg=BG).pack(side="left")
        search_var = tk.StringVar(value="")
        def _on_search(*_a):
            _gui["log_search"] = search_var.get()
            _refresh_log()
        search_var.trace_add("write", _on_search)
        se = tk.Entry(tools, textvariable=search_var, font=F_TINY,
                      fg=TEXT, bg=BG3, insertbackground=ACCT2,
                      relief="flat", highlightthickness=1,
                      highlightbackground=DIM, highlightcolor=ACCT2, width=24)
        se.pack(side="left", padx=(4, 8), ipady=3)
        _gui["log_search_entry"] = se

        as_var = tk.BooleanVar(value=True)
        def _on_as():
            _gui["log_autoscroll"] = bool(as_var.get())
            if _gui["log_autoscroll"]: _refresh_log()
        as_cb = tk.Checkbutton(tools, text=" auto-scroll ",
                               variable=as_var, command=_on_as,
                               font=F_TINY, fg=MUTED, bg=BG,
                               activebackground=BG, activeforeground=ACCT2,
                               selectcolor=BG3, bd=0, highlightthickness=0)
        as_cb.pack(side="left")
        _gui["log_autoscroll_var"] = as_var  # so pause-on-scroll can toggle the checkbox

        # ── v19.0.5: AUTO-REFRESH interval picker ──
        # Off / 2s / 5s / 10s. Schedules _refresh_log() on the Tk loop.
        tk.Label(tools, text="  auto ", font=F_TINY, fg=MUTED, bg=BG).pack(side="left")
        _AR_CHOICES = ("Off", "2s", "5s", "10s")
        _AR_MS = {"Off": 0, "2s": 2000, "5s": 5000, "10s": 10000}
        ar_var = tk.StringVar(value="5s")
        _gui["log_autorefresh_var"]  = ar_var
        _gui["_log_autorefresh_job"] = None

        def _schedule_autorefresh():
            try:
                root = _gui.get("root")
                if not root: return
                # Cancel any pending job first
                prev = _gui.get("_log_autorefresh_job")
                if prev:
                    try: root.after_cancel(prev)
                    except Exception: pass
                    _gui["_log_autorefresh_job"] = None
                ms = _AR_MS.get(ar_var.get(), 0)
                if ms <= 0: return
                def _tick_ar():
                    try: _refresh_log()
                    except Exception: pass
                    # reschedule
                    try:
                        _gui["_log_autorefresh_job"] = root.after(ms, _tick_ar)
                    except Exception: pass
                _gui["_log_autorefresh_job"] = root.after(ms, _tick_ar)
            except Exception: pass

        def _on_ar_change(*_a):
            _schedule_autorefresh()
            _log(f"[GUI] Auto-refresh: {ar_var.get()}", "info")
        ar_var.trace_add("write", _on_ar_change)

        ar_menu = tk.OptionMenu(tools, ar_var, *_AR_CHOICES)
        ar_menu.config(font=F_TINY, fg=ACCT2, bg=BG3,
                       activebackground=BG2, activeforeground=ACCT2,
                       highlightthickness=1, highlightbackground=DIM,
                       bd=0, padx=6, pady=0, cursor="hand2", relief="flat",
                       indicatoron=0)
        try:
            ar_menu["menu"].config(font=F_TINY, fg=ACCT2, bg=BG3,
                                   activebackground=BG2, activeforeground=ACCT2,
                                   bd=0)
        except Exception: pass
        ar_menu.pack(side="left", padx=(2, 0))
        # Boot the first schedule
        try: root.after(800, _schedule_autorefresh)
        except Exception: pass

        def _clear_log():
            with _log_lock:
                _log_lines.clear()
            _refresh_log()
            _log("[GUI] Activity log cleared", "info")
        tk.Button(tools, text=" CLEAR ", font=F_TINY,
                  fg=AMBER, bg=BG3, activebackground=BG2, activeforeground=AMBER,
                  relief="flat", bd=0, padx=8, pady=2,
                  cursor="hand2", command=_clear_log).pack(side="right", padx=(4, 0))

        # v19.0.4: EXPORT — dump current log buffer to ~/Documents/butler_activity_<ts>.log
        def _export_log():
            try:
                out_dir = Path.home() / "Documents"
                out_dir.mkdir(parents=True, exist_ok=True)
                out = out_dir / f"butler_activity_{int(time.time())}.log"
                with _log_lock:
                    snap = list(_log_lines)
                with open(out, "w", encoding="utf-8") as fh:
                    for tag, msg in snap:
                        fh.write(f"[{tag}] {msg}\n")
                _log(f"[GUI] Exported {len(snap)} log entries → {out}", "ok")
            except Exception as e:
                _log(f"[GUI] Export failed: {e}", "err")
        tk.Button(tools, text=" EXPORT ", font=F_TINY,
                  fg=BLUE, bg=BG3, activebackground=BG2, activeforeground=BLUE,
                  relief="flat", bd=0, padx=8, pady=2,
                  cursor="hand2", command=_export_log).pack(side="right", padx=(4, 0))

        # v19.0.4: REFRESH — force-repaint log + GUI labels + push a fresh metric sample
        def _force_refresh():
            try: _refresh_log()
            except Exception: pass
            try: _refresh_gui()
            except Exception: pass
        tk.Button(tools, text=" REFRESH ", font=F_TINY,
                  fg=ACCT2, bg=BG3, activebackground=BG2, activeforeground=ACCT2,
                  relief="flat", bd=0, padx=8, pady=2,
                  cursor="hand2", command=_force_refresh).pack(side="right", padx=(4, 0))

        # ── Sparklines: CPU + RAM (60 samples ≈ 3 min @ 3s tick) ──
        spk = tk.Frame(lp, bg=BG); spk.pack(fill="x", pady=(0, 4))
        _gui["cpu_samples"] = []
        _gui["ram_samples"] = []
        _SPK_W, _SPK_H = 230, 36

        def _make_spark(parent, label, color, key):
            box = tk.Frame(parent, bg=BG2, highlightthickness=1, highlightbackground=DIM)
            box.pack(side="left", fill="x", expand=True, padx=(0, 6))
            hdr = tk.Frame(box, bg=BG2); hdr.pack(fill="x", padx=8, pady=(4, 0))
            tk.Label(hdr, text=label, font=F_TINY, fg=MUTED, bg=BG2).pack(side="left")
            val_lbl = tk.Label(hdr, text="  0%", font=F_TINY, fg=color, bg=BG2)
            val_lbl.pack(side="right")
            cv = tk.Canvas(box, height=_SPK_H, bg="#000000",
                           highlightthickness=0, bd=0)
            cv.pack(fill="x", padx=8, pady=(2, 6))
            _gui[f"spk_{key}_canvas"] = cv
            _gui[f"spk_{key}_label"]  = val_lbl
            _gui[f"spk_{key}_color"]  = color
            return cv

        _make_spark(spk, " CPU ",  ACCT2, "cpu")
        _make_spark(spk, " RAM ",  GREEN, "ram")

        # Spacer line under sparklines
        tk.Frame(lp, bg=DIM, height=1).pack(fill="x", pady=(0, 4))

        # ── The actual log textview ──
        tv = scrolledtext.ScrolledText(
            lp, font=F_CODE, bg="#000000", fg=TEXT,
            insertbackground=ACCT2, relief="flat",
            state="disabled", wrap="word",
            highlightthickness=1, highlightbackground=DIM,
            selectbackground=BG3, selectforeground=ACCT2,
            padx=10, pady=8)
        tv.pack(fill="both", expand=True)
        tv.tag_config("err",   foreground=RED)
        tv.tag_config("warn",  foreground=AMBER)
        tv.tag_config("ok",    foreground=GREEN)
        tv.tag_config("info",  foreground=BLUE)
        tv.tag_config("sys",   foreground=ACCT2)
        tv.tag_config("dim",   foreground=MUTED)
        tv.tag_config("heal",  foreground=GREEN)
        tv.tag_config("guard", foreground=AMBER)
        _gui["log_tv"] = tv

        # ── v19.0.5: pause auto-scroll when user scrolls up manually ──
        # If the user wheels up / drags the scrollbar away from the bottom,
        # auto-scroll silently turns off so new lines don't yank them back.
        # Scrolling back to the bottom re-enables it.
        def _on_user_scroll(_e=None):
            try:
                # tv.yview() -> (top_fraction, bottom_fraction)
                yv = tv.yview()
                at_bottom = (yv[1] >= 0.999)
                cur = bool(_gui.get("log_autoscroll", True))
                if at_bottom and not cur:
                    _gui["log_autoscroll"] = True
                    try: _gui["log_autoscroll_var"].set(True)
                    except Exception: pass
                elif (not at_bottom) and cur:
                    _gui["log_autoscroll"] = False
                    try: _gui["log_autoscroll_var"].set(False)
                    except Exception: pass
            except Exception: pass
        try:
            tv.bind("<MouseWheel>",   _on_user_scroll, add="+")  # Windows / macOS
            tv.bind("<Button-4>",     _on_user_scroll, add="+")  # Linux scroll up
            tv.bind("<Button-5>",     _on_user_scroll, add="+")  # Linux scroll down
            tv.bind("<ButtonRelease-1>", _on_user_scroll, add="+")
            tv.bind("<KeyRelease>",   _on_user_scroll, add="+")
        except Exception: pass

        # ── v19.0.5: keyboard shortcuts ──
        # Ctrl+F → focus search,  Ctrl+L → clear log,  Esc → clear search box
        try:
            def _focus_search(_e=None):
                try: se.focus_set(); se.select_range(0, "end")
                except Exception: pass
                return "break"
            def _kbd_clear(_e=None):
                _clear_log(); return "break"
            def _kbd_esc(_e=None):
                try: search_var.set("")
                except Exception: pass
                return "break"
            root.bind_all("<Control-f>", _focus_search)
            root.bind_all("<Control-F>", _focus_search)
            root.bind_all("<Control-l>", _kbd_clear)
            root.bind_all("<Control-L>", _kbd_clear)
            se.bind("<Escape>",          _kbd_esc)
        except Exception: pass

        # ── Footer stats line ──
        foot = tk.Frame(lp, bg=BG); foot.pack(fill="x", pady=(4, 0))
        fl = tk.Label(foot, text="  0 shown  ·  0 err  ·  0 warn  ·  0 guard  ",
                      font=F_TINY, fg=MUTED, bg=BG, anchor="w")
        fl.pack(side="left", fill="x", expand=True)
        _gui["log_footer_lbl"] = fl

        # ── Footer ────────────────────────────────────────────────
        tk.Frame(root, bg=DIM,    height=1).pack(fill="x", side="bottom")
        tk.Frame(root, bg=ACCENT, height=1).pack(fill="x", side="bottom")
        ft = tk.Frame(root, bg=BG2, pady=5); ft.pack(fill="x", side="bottom")
        tk.Label(ft, text=f"  BUTLER AI SERVER  {VERSION}  ·  {ip}:{port}",
                 font=F_TINY, fg=MUTED, bg=BG2).pack(side="left")
        olr = tk.Frame(ft, bg=BG2); olr.pack(side="right", padx=10)
        try:
            PulseDot(olr, size=7, color=GREEN).pack(side="left", padx=(0,5))
        except Exception: pass
        tk.Label(olr, text="ONLINE", font=F_TINY, fg=GREEN, bg=BG2).pack(side="left")

        def _tick():
            _refresh_gui()
            root.after(3000, _tick)

        root.after(400, lambda: _draw_qr(ip, port))
        root.after(800, _tick)

        # ── Branded window icon (taskbar/title bar) — no extra asset file
        # needed since it's drawn procedurally, same image as the tray icon.
        try:
            _icon_img = _butler_make_tray_image()
            _gui["_icon_photo"] = ImageTk.PhotoImage(_icon_img)  # keep a ref or Tk garbage-collects it
            root.iconphoto(True, _gui["_icon_photo"])
        except Exception:
            pass

        # ── Close = minimize to tray, not quit. The server keeps running
        # invisibly; the tray icon's "Show Dashboard / QR" brings it back.
        def _on_close():
            tray_active = _gui.get("_tray_holder", {}).get("root") is not None
            if tray_active:
                log.info("Window minimized to tray — server keeps running")
                root.withdraw()
            else:
                log.info("Window closed (no tray icon) — shutting down")
                root.destroy()
        root.protocol("WM_DELETE_WINDOW", _on_close)
        return root

    except Exception as e:
        log.warning(f"GUI build failed: {e}")
        return None

def _draw_qr(ip, port):
    """3-layer QR: PIL cyan-on-black → canvas rects → text fallback."""
    canvas = _gui.get("qr_canvas")
    if not canvas: return
    try:
        payload = json.dumps({"ip": ip, "port": port,
                              "pairingCode": _gs("pairing_code") or "",
                              "version": VERSION,
                              "appSig": APP_SECRET})
        if HAS_QR and HAS_PIL:
            try:
                qr = qrcode.QRCode(version=None,
                                   error_correction=qrcode.constants.ERROR_CORRECT_M,
                                   box_size=1, border=3)
                qr.add_data(payload); qr.make(fit=True)
                img = qr.make_image(fill_color="#00EEFF", back_color="#000000")
                img = img.resize((224, 224), Image.Resampling.NEAREST if hasattr(Image, "Resampling") else Image.NEAREST)  # FIX: Pillow 10+ moved constants to Image.Resampling
                tk_img = ImageTk.PhotoImage(img)
                _gui["_qr_ref"] = tk_img
                canvas.configure(width=224, height=224)
                canvas.delete("all")
                canvas.create_image(0, 0, anchor="nw", image=tk_img)
                return
            except Exception: pass
        if HAS_QR:
            try:
                qr = qrcode.QRCode(version=None, box_size=1, border=3)
                qr.add_data(payload); qr.make(fit=True)
                mx = qr.get_matrix(); n = len(mx); cell = 224 / n
                canvas.delete("all")
                for r in range(n):
                    for c in range(n):
                        if mx[r][c]:
                            x0, y0 = c*cell, r*cell
                            canvas.create_rectangle(x0, y0, x0+cell, y0+cell,
                                                    fill=ACCT2, outline="")
                return
            except Exception: pass
        # Text fallback
        canvas.delete("all")
        canvas.create_text(112, 70,  text="QR unavailable", fill=AMBER, font=F_MED,  anchor="center")
        canvas.create_text(112, 100, text=f"{ip}:{port}",   fill=ACCT2, font=F_BIG,  anchor="center")
        canvas.create_text(112, 130, text=f"Code: {_gs('pairing_code')}", fill=ACCT2, font=F_MONO, anchor="center")
        canvas.create_text(112, 158, text="pip install qrcode Pillow",    fill=MUTED, font=F_TINY, anchor="center")
    except Exception: pass

def _refresh_gui():
    """Update all dynamic labels in the Butler AI GUI."""
    root = _gui.get("root")
    if not root: return
    try:
        ai = _gui.get("ai_lbl")
        if ai:
            ok = _ol_ok()
            if ok:
                m = (_ol_model() or "").split(":")[0].upper()[:14]
                ai.configure(text=f" ●  {m} ", fg=GREEN, bg=BG3)
            else:
                # Check if auto-manager is still running
                starting = any(t.name in ("ollama-auto","ollama-pull")
                               for t in threading.enumerate())
                ai.configure(
                    text=" ●  AI: starting… " if starting else " ●  AI: offline ",
                    fg=AMBER, bg=BG3)
        dev = _gui.get("dev_lbl")
        if dev:
            locked = _gs("locked_device")
            if locked:
                s = locked[:16] + "…" if len(locked) > 16 else locked
                dev.configure(text=f" ●  {s} ", fg=GREEN, bg=BG3)
            else:
                dev.configure(text=" ●  NO DEVICE ", fg=RED, bg=BG3)
        kb = _gui.get("kb_lbl")
        if kb:
            n = _kb_count()
            kb.configure(text=f" KB  ···  {n} articles ",
                         fg=ACCT2 if n > 0 else MUTED)
        sl = _gui.get("sigma_lbl")
        if sl:
            arts   = _kb_count()
            q_size = _lq_size()
            workers_alive = sum(1 for t in threading.enumerate() if t.name.startswith("learn-"))
            speed  = "●" * min(workers_alive, 3)
            if workers_alive > 0:
                sl.configure(text=f" ΣNET  ·  {arts} articles  ·  Q:{q_size}  ·  {speed} {workers_alive}W ",
                             fg=ACCT2)
            else:
                sl.configure(text=f" ΣNET  ·  {arts} articles  ·  idle ", fg=MUTED)

        # ── KB Stats label ────────────────────────────────────
        kb = _gui.get("kb_lbl")
        if kb:
            total = _kb_count()
            nxt   = _next_milestone(total)
            pct   = min(100, int(total / nxt * 100)) if nxt > 0 else 100
            kb.configure(
                text=f" KB  ···  {total} articles  ·  {pct}% to {nxt}",
                fg=ACCT2 if total > 0 else MUTED
            )
        cl = _gui.get("code_lbl")
        if cl:
            locked = _gs("locked_device")
            cl.configure(
                text="  PAIRED ✔  " if locked else f"  {_gs('pairing_code') or '------'}  ",
                fg=GREEN if locked else ACCT2)

        # ── v19.0.3: sample + paint CPU / RAM sparklines ──
        try:
            with _sys_snapshot_lock:
                cpu_v = float(_sys_snapshot.get("cpu", 0) or 0)
                ram_v = float(_sys_snapshot.get("ram", 0) or 0)
            for key, val in (("cpu", cpu_v), ("ram", ram_v)):
                buf = _gui.get(f"{key}_samples")
                if buf is None: continue
                buf.append(max(0.0, min(100.0, val)))
                if len(buf) > 60: del buf[:len(buf)-60]
                cv = _gui.get(f"spk_{key}_canvas")
                lbl = _gui.get(f"spk_{key}_label")
                col = _gui.get(f"spk_{key}_color") or ACCT2
                if lbl and lbl.winfo_exists():
                    lbl.config(text=f"  {val:.0f}%",
                               fg=(RED if val > 90 else (AMBER if val > 70 else col)))
                if cv and cv.winfo_exists():
                    cv.delete("all")
                    w = max(cv.winfo_width(), 60)
                    h = max(cv.winfo_height(), 20)
                    n = len(buf)
                    if n >= 2:
                        step = w / max(n - 1, 1)
                        # grid lines (25/50/75%)
                        for frac in (0.25, 0.5, 0.75):
                            y = h - h * frac
                            cv.create_line(0, y, w, y, fill=DIM)
                        # filled area under the curve
                        pts = []
                        for i, s in enumerate(buf):
                            x = i * step
                            y = h - (h - 2) * (s / 100.0)
                            pts.extend([x, y])
                        # area polygon
                        area = [0, h] + pts + [w, h]
                        try:
                            cv.create_polygon(area, fill=col, stipple="gray12", outline="")
                        except Exception: pass
                        # line on top
                        cv.create_line(*pts, fill=col, width=2, smooth=True)
                        # last-point dot
                        lx, ly = pts[-2], pts[-1]
                        cv.create_oval(lx-2, ly-2, lx+2, ly+2, fill=col, outline="")
        except Exception: pass
    except Exception: pass

def _auto_unpair_watchdog():
    """
    Background thread: monitors paired device activity.
    If the paired device hasn't been seen in 48 hours, auto-unpairs
    so a new device can connect without needing --reset-pair.
    This handles: phone replacements, app uninstalls, long trips.
    v12: added — was referenced in watchdog restart but never defined.
    """
    while True:
        try:
            time.sleep(3600)  # check every hour
            locked   = _gs("locked_device")
            last_seen = _gs("last_seen")
            if not locked or not last_seen:
                continue
            try:
                import datetime as _dt
                ref_ts = _dt.datetime.strptime(
                    last_seen, "%Y-%m-%dT%H:%M:%SZ"
                ).replace(tzinfo=_dt.timezone.utc).timestamp()
                silence_h = (time.time() - ref_ts) / 3600
            except Exception:
                continue
            # Auto-unpair after 48 hours of silence (configurable)
            if silence_h > 48:
                _log(f"[AUTO-UNPAIR] Device silent {silence_h:.0f}h — auto-clearing lock", "warn")
                _ss("locked_device", None)
                _ss("paired_at",     None)
                _ss("last_seen",     None)
                _ss("pairing_code",  _gen_code())
                log.info(f"[AUTO-UNPAIR] Cleared stale device lock after {silence_h:.0f}h")
        except Exception as e:
            log.debug(f"[AUTO-UNPAIR] error: {e}")

def _script_safety_check(script: str, language: str) -> dict:
    """
    Quick safety check wrapper used by /api/pc_scripts/run.
    Delegates to the full _verify_script_safety for Python,
    returns safe=True for other languages (already guarded upstream).
    v12: added — was referenced in pc_scripts/run handler but never defined.
    """
    if language == "python":
        return _verify_script_safety(script, "")
    return {"safe": True, "reason": f"{language} safety check skipped", "warnings": []}

# ══════════════════════════════════════════════════════════════════
#  SEC-FIX: TLS — self-signed certificate generation
#  Wraps the HTTP socket with SSL so traffic is encrypted on the LAN.
#  The mobile app pins this cert (fingerprint shown in QR payload).
#  This prevents Wireshark packet sniffing of auth tokens.
# ══════════════════════════════════════════════════════════════════
_TLS_CERT_FILE = Path.home() / ".butler_tls_cert.pem"
_TLS_KEY_FILE  = Path.home() / ".butler_tls_key.pem"

def _tls_cert_fingerprint() -> str:
    """Return SHA-256 fingerprint of the TLS cert for QR payload (app pins this)."""
    try:
        import hashlib
        data = _TLS_CERT_FILE.read_bytes()
        return hashlib.sha256(data).hexdigest()
    except Exception:
        return ""

# ─────────────────────────────────────────────────────────────────────
# SMART AUTO-UPGRADES  (v19.0.12+)
# Self-tuning background loop that automatically tunes the server based
# on live metrics. Every action is wrapped in try/except so a failure in
# one tuner never affects others or the main server. All actions are
# bounded, idempotent, and safe to run repeatedly.
#
# What it does (every 10 min unless noted):
#   1. Auto-tune reply cache TTL + size based on hit-rate
#   2. Auto-VACUUM SQLite weekly when DB > 50 MB or fragmented
#   3. Auto-prune KB rows older than 180d with zero keyword matches recently
#   4. Auto-rotate any log file > 50 MB (keeps .1 backup)
#   5. Auto-throttle background crawlers if RAM > 85% or disk < 1 GB
#   6. Auto-refresh stale crawl entries for hot query topics (>30d old)
#   7. Auto-clear expired stream-resume buffers + dedupe caches
#   8. Daily self-health digest written to log
# ─────────────────────────────────────────────────────────────────────
_SMART_UP_STATE = {
    "started": False,
    "last_vacuum": 0.0,
    "last_prune": 0.0,
    "last_digest": 0.0,
    "cache_hits": 0,
    "cache_miss": 0,
    "tune_history": [],
}
_SMART_UP_LOCK = threading.Lock()

def _smart_record_cache(hit: bool):
    """Public hook — called from _reply_cache_get to track hit rate."""
    try:
        with _SMART_UP_LOCK:
            if hit: _SMART_UP_STATE["cache_hits"] += 1
            else:   _SMART_UP_STATE["cache_miss"] += 1
    except Exception:
        pass

def _smart_tune_reply_cache():
    """Resize cache + adjust TTL based on observed hit-rate."""
    global _REPLY_CACHE_MAX, _REPLY_CACHE_TTL
    try:
        with _SMART_UP_LOCK:
            h, m = _SMART_UP_STATE["cache_hits"], _SMART_UP_STATE["cache_miss"]
            total = h + m
            if total < 50:
                return  # not enough signal
            rate = h / total
            _SMART_UP_STATE["cache_hits"] = 0
            _SMART_UP_STATE["cache_miss"] = 0
        old_max, old_ttl = _REPLY_CACHE_MAX, _REPLY_CACHE_TTL
        if rate > 0.55 and _REPLY_CACHE_MAX < 2000:
            _REPLY_CACHE_MAX = min(2000, int(_REPLY_CACHE_MAX * 1.5))
            _REPLY_CACHE_TTL = min(900, int(_REPLY_CACHE_TTL * 1.25))
        elif rate < 0.10 and _REPLY_CACHE_MAX > 200:
            _REPLY_CACHE_MAX = max(200, int(_REPLY_CACHE_MAX * 0.75))
            _REPLY_CACHE_TTL = max(120, int(_REPLY_CACHE_TTL * 0.85))
        if (old_max, old_ttl) != (_REPLY_CACHE_MAX, _REPLY_CACHE_TTL):
            _SMART_UP_STATE["tune_history"].append(
                (time.time(), f"cache hit={rate:.0%} max {old_max}->{_REPLY_CACHE_MAX} ttl {old_ttl}->{_REPLY_CACHE_TTL}")
            )
            _SMART_UP_STATE["tune_history"] = _SMART_UP_STATE["tune_history"][-50:]
            try: log.info(f"[smart] cache tuned hit={rate:.0%} max={_REPLY_CACHE_MAX} ttl={_REPLY_CACHE_TTL}")
            except Exception: pass
    except Exception as e:
        try: log.debug(f"[smart] tune_reply_cache: {e}")
        except Exception: pass

def _smart_vacuum_db():
    """VACUUM SQLite when fragmented (weekly + size-gated)."""
    try:
        now = time.time()
        if now - _SMART_UP_STATE["last_vacuum"] < 7 * 86400:
            return
        try:
            size = DB_PATH.stat().st_size
        except Exception:
            return
        if size < 50 * 1024 * 1024:
            _SMART_UP_STATE["last_vacuum"] = now
            return
        with _db_lock:
            c = sqlite3.connect(str(DB_PATH), timeout=30)
            try:
                c.execute("PRAGMA wal_checkpoint(TRUNCATE)")
                c.execute("VACUUM")
            finally:
                c.close()
        _SMART_UP_STATE["last_vacuum"] = now
        try: log.info(f"[smart] vacuumed DB ({size//1024//1024} MB)")
        except Exception: pass
    except Exception as e:
        try: log.debug(f"[smart] vacuum: {e}")
        except Exception: pass

def _smart_prune_kb():
    """Drop KB entries older than 180d that have empty/short content."""
    try:
        now = time.time()
        if now - _SMART_UP_STATE["last_prune"] < 86400:
            return
        cutoff = now - 180 * 86400
        try:
            c = _db_get_conn()
            cur = c.execute(
                "DELETE FROM knowledge_base "
                "WHERE crawled_at < ? AND (word_count < 50 OR clean_text IS NULL)",
                (cutoff,)
            )
            c.commit()
            n = cur.rowcount or 0
        except Exception:
            n = 0
        _SMART_UP_STATE["last_prune"] = now
        if n:
            try: log.info(f"[smart] pruned {n} stale KB rows")
            except Exception: pass
    except Exception as e:
        try: log.debug(f"[smart] prune_kb: {e}")
        except Exception: pass

def _smart_rotate_logs():
    """Rotate any *.log next to the server if > 50 MB. Keeps one .1 backup."""
    try:
        from pathlib import Path as _P
        roots = set()
        try: roots.add(_P(__file__).parent)
        except Exception: pass
        try: roots.add(_P.home() / "Documents")
        except Exception: pass
        for root in roots:
            try:
                if not root.exists(): continue
                for f in root.glob("*.log"):
                    try:
                        if f.stat().st_size > 50 * 1024 * 1024:
                            bak = f.with_suffix(f.suffix + ".1")
                            try:
                                if bak.exists(): bak.unlink()
                            except Exception: pass
                            try: f.rename(bak)
                            except Exception: pass
                            try: log.info(f"[smart] rotated {f.name}")
                            except Exception: pass
                    except Exception:
                        continue
            except Exception:
                continue
    except Exception:
        pass

def _smart_throttle_check() -> bool:
    """Return True if system is under pressure (caller should back off)."""
    try:
        import psutil, shutil
        ram = psutil.virtual_memory().percent
        try:
            free_gb = shutil.disk_usage(str(DB_PATH.parent)).free / (1024**3)
        except Exception:
            free_gb = 99
        return ram > 85 or free_gb < 1.0
    except Exception:
        return False

def _smart_clear_dedupe():
    """Trim oversized in-memory dedupe / dup-detection caches."""
    try:
        for name in ("_CHAT_DEDUPE", "_CHAT_DUP_CACHE", "_STREAM_RESUME_BUFS"):
            obj = globals().get(name)
            if isinstance(obj, dict) and len(obj) > 1000:
                # drop oldest half (best-effort, keys may not be timestamped)
                keys = list(obj.keys())[: len(obj) // 2]
                for k in keys:
                    obj.pop(k, None)
                try: log.info(f"[smart] trimmed {name} -> {len(obj)}")
                except Exception: pass
    except Exception:
        pass

def _smart_daily_digest():
    """Once per day, emit a one-line health summary to the log."""
    try:
        now = time.time()
        if now - _SMART_UP_STATE["last_digest"] < 86400:
            return
        _SMART_UP_STATE["last_digest"] = now
        try:
            import psutil
            ram = psutil.virtual_memory().percent
            cpu = psutil.cpu_percent(interval=0.2)
        except Exception:
            ram = cpu = -1
        try: db_mb = DB_PATH.stat().st_size // 1024 // 1024
        except Exception: db_mb = 0
        try: cache_n = len(_REPLY_CACHE)
        except Exception: cache_n = 0
        try:
            log.info(
                f"[smart] digest: cache={cache_n}/{_REPLY_CACHE_MAX} "
                f"ttl={_REPLY_CACHE_TTL}s db={db_mb}MB ram={ram}% cpu={cpu}% "
                f"tunes={len(_SMART_UP_STATE['tune_history'])}"
            )
        except Exception:
            pass
    except Exception:
        pass

def _smart_kb_integrity():
    """
    v19.0.19: scheduled KB hygiene — runs once per 6h max.
      - Backfills license_tag for rows still marked 'unknown' when domain is known.
      - Deletes seed-source rows that snuck in without a permissive license.
    Cheap: bounded LIMIT, all DB ops guarded.
    """
    try:
        now = time.time()
        if now - _SMART_UP_STATE.get("last_kb_integrity", 0) < 6 * 3600:
            return
        backfilled = purged = 0
        # 1) backfill license_tag for known domains
        try:
            rows = _db_q(
                "SELECT id, url FROM knowledge_base "
                "WHERE license_tag IS NULL OR license_tag='' OR license_tag='unknown' "
                "LIMIT 500"
            )
            for r in rows:
                try:
                    tag, _perm = _infer_license(r["url"])
                    if tag and tag != "unknown":
                        _db_run("UPDATE knowledge_base SET license_tag=? WHERE id=?", (tag, r["id"]))
                        backfilled += 1
                except Exception: continue
        except Exception: pass
        # 2) purge seed-source rows that ended up with non-permissive license
        try:
            bad = _db_q(
                "SELECT id, url, license_tag FROM knowledge_base "
                "WHERE source_type LIKE 'public-seed%' LIMIT 500"
            )
            for r in bad:
                try:
                    if (r.get("license_tag") or "unknown") not in _PERMISSIVE_LICENSES:
                        _db_run("DELETE FROM knowledge_base WHERE id=?", (r["id"],))
                        purged += 1
                except Exception: continue
        except Exception: pass
        _SMART_UP_STATE["last_kb_integrity"] = now
        if backfilled or purged:
            try: log.info(f"[smart] kb_integrity: backfilled={backfilled} purged_nonpermissive_seed={purged}")
            except Exception: pass
    except Exception as e:
        try: log.debug(f"[smart] kb_integrity: {e}")
        except Exception: pass

def _smart_upgrades_loop():
    """Main smart-upgrades loop — runs every 10 minutes."""
    # initial delay so it doesn't fight startup
    time.sleep(120)
    while True:
        try:
            if _smart_throttle_check():
                # under pressure: skip heavy work, only do cheap ones
                _smart_clear_dedupe()
                _smart_rotate_logs()
            else:
                _smart_tune_reply_cache()
                _smart_rotate_logs()
                _smart_clear_dedupe()
                _smart_prune_kb()
                _smart_kb_integrity()   # v19.0.19
                _smart_vacuum_db()
                _smart_daily_digest()
        except Exception as e:
            try: log.debug(f"[smart] loop: {e}")
            except Exception: pass
        time.sleep(600)

def _smart_upgrades_start():
    """Idempotent starter — safe to call multiple times."""
    if _SMART_UP_STATE.get("started"):
        return
    _SMART_UP_STATE["started"] = True
    try:
        threading.Thread(target=_smart_upgrades_loop, daemon=True,
                         name="smart-upgrades").start()
        try: log.info("[smart] auto-upgrades started")
        except Exception: pass
    except Exception as e:
        try: log.debug(f"[smart] start: {e}")
        except Exception: pass

# ══════════════════════════════════════════════════════════════════════════════
#  SYSTEM TRAY ICON — replaces the "ugly black screen" with a clean, branded
#  presence in the Windows tray. Lets the user see at a glance that Butler AI
#  is running and gives them Dashboard / Logs / Quit without ever needing a
#  console window. Fully optional: if pystray/Pillow aren't available this
#  quietly returns None and the server falls back to running silently.
# ══════════════════════════════════════════════════════════════════════════════
def _butler_make_tray_image():
    from PIL import Image, ImageDraw
    size = 64
    img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    d = ImageDraw.Draw(img)
    NEON = (0, 212, 255, 255)
    DARK = (7, 8, 13, 255)
    d.ellipse((2, 2, size - 2, size - 2), fill=DARK, outline=NEON, width=3)
    d.ellipse((12, 12, size - 12, size - 12), outline=(0, 212, 255, 130), width=1)
    # Minimal "B" glyph drawn from rectangles so no font file is required
    bx, by = 24, 18
    d.rectangle((bx, by, bx + 4, by + 28), fill=NEON)
    d.rectangle((bx, by, bx + 16, by + 4), fill=NEON)
    d.rectangle((bx, by + 12, bx + 14, by + 16), fill=NEON)
    d.rectangle((bx, by + 24, bx + 16, by + 28), fill=NEON)
    d.rectangle((bx + 12, by + 4, bx + 16, by + 12), fill=NEON)
    d.rectangle((bx + 10, by + 16, bx + 14, by + 24), fill=NEON)
    return img

def _butler_start_tray_icon(get_ip_fn, get_port_fn, shutdown_event, root_holder=None):
    """root_holder, if given, is a dict like {'root': tk_root_or_None}. When
    present, the tray gets a 'Show Dashboard' item that restores the Tk
    window, and Quit cleanly tears down both the Tk mainloop and the
    headless wait-loop, whichever is actually running."""
    try:
        import pystray
        import webbrowser
    except ImportError:
        log.info("pystray not installed — running without a tray icon (server still fully works)")
        return None

    root_holder = root_holder if root_holder is not None else {"root": None}

    def _on_dashboard(icon, item):
        r = root_holder.get("root")
        if r is not None:
            try:
                r.after(0, lambda: (r.deiconify(), r.lift(), r.focus_force()))
                return
            except Exception:
                pass
        try: webbrowser.open(f"http://{get_ip_fn()}:{get_port_fn()}")
        except Exception: pass

    def _on_logs(icon, item):
        try:
            if IS_WINDOWS:
                subprocess.Popen(["explorer", "/select,", BUTLER_LOG_PATH])
            else:
                subprocess.Popen(["xdg-open", os.path.dirname(BUTLER_LOG_PATH)])
        except Exception: pass

    def _on_quit(icon, item):
        log.info("Quit requested from tray icon — shutting down")
        r = root_holder.get("root")
        if r is not None:
            try: r.after(0, r.destroy)
            except Exception: pass
        shutdown_event.set()
        icon.stop()

    menu = pystray.Menu(
        pystray.MenuItem(f"Butler AI Server v{VERSION}", None, enabled=False),
        pystray.MenuItem("● Running", None, enabled=False),
        pystray.Menu.SEPARATOR,
        pystray.MenuItem("Show Dashboard / QR", _on_dashboard, default=True),
        pystray.MenuItem("Open Logs", _on_logs),
        pystray.Menu.SEPARATOR,
        pystray.MenuItem("Quit Butler AI", _on_quit),
    )
    icon = pystray.Icon("ButlerAI", _butler_make_tray_image(), "Butler AI — Running", menu)
    threading.Thread(target=icon.run, daemon=True, name="tray").start()
    return icon

def main():
    global _start_time
    _start_time = _START_TIME   # FIX: single source of truth — set at module load (line ~477)
    _smart_upgrades_start()

    parser = argparse.ArgumentParser(description="Butler AI Desktop Server v6.0")
    parser.add_argument("--port",        type=int, default=None,   help="Force specific port")
    parser.add_argument("--no-qr",       action="store_true",      help="Skip QR code display")
    parser.add_argument("--reset-pair",  action="store_true",      help="Allow new phone to connect")
    parser.add_argument("--no-admin",    action="store_true",      help="Skip admin elevation")
    parser.add_argument("--no-firewall", action="store_true",      help="Skip firewall rule")
    parser.add_argument("--startup",     action="store_true",      help="Register as Windows auto-start")
    parser.add_argument("--scan-req",    action="store_true",      help="Scan requirements then exit")
    parser.add_argument("--kill-port",   type=int, default=None,   help="Kill process on PORT then exit")
    parser.add_argument("--kb-export",   type=str, default=None,   help="Export KB to FILE (JSON, optionally .gz/.z) then exit")
    parser.add_argument("--kb-import",   type=str, default=None,   help="Import KB from FILE (JSON, optionally .gz/.z) then exit")
    parser.add_argument("--kb-import-mode", type=str, default="merge", choices=["merge","replace"],
                        help="Import mode for --kb-import (default: merge)")
    args = parser.parse_args()

    # ── Special modes ──────────────────────────────────────────
    if args.startup:
        _register_startup(); return

    if args.reset_pair:
        nc = _gen_code()
        _ss("locked_device", None); _ss("pairing_code", nc); _ss("paired_at", None)
        _CY = "\033[38;2;0;234;255m"; _G = "\033[38;2;0;232;122m"; _RS = "\033[0m"
        print(f"\n  {_G}✓{_RS}  Reset complete  —  new pair code: {_CY}{nc}{_RS}")
        print("     Restart the server to display a fresh QR code.\n")
        return

    if args.scan_req:
        _CY = "\033[38;2;0;200;245m"; _MT = "\033[38;2;120;170;200m"; _RS = "\033[0m"
        print(f"\n  {_CY}REQUIREMENTS SCAN{_RS}\n")
        scan    = _scan_requirements(verbose=True)
        missing = [r for r in scan if r["status"] == "MISSING"]
        print(f"\n  {len(scan)-len(missing)}/{len(scan)} packages present", end="")
        if missing:
            pkgs = " ".join(r["pip"] for r in missing)
            print(f"  —  fix: pip install {pkgs}")
        else:
            print("  —  all good")
        print()
        return

    if args.kill_port:
        port = args.kill_port
        print(f"\n  Killing processes on port {port}...")
        killed = _kill_process_on_port(port, force=True)
        if killed:
            for k in killed: print(f"  ✓ Killed PID {k['pid']} ({k['name']})")
        else:
            print(f"  No process found on port {port}")
        return

    # ── v19.0.20: KB export/import CLI (persists KB across deployments) ──
    if args.kb_export:
        try:
            p = Path(args.kb_export).expanduser().resolve()
            p.parent.mkdir(parents=True, exist_ok=True)
            payload = _kb_export_dict()
            raw = json.dumps(payload, ensure_ascii=False).encode("utf-8")
            if str(p).endswith((".gz", ".z")):
                p.write_bytes(zlib.compress(raw, 6))
            else:
                p.write_bytes(raw)
            print(f"\n  ✓ KB exported: {p}  ({payload['rowCount']} rows, schema v{payload['schemaVersion']})\n")
        except Exception as _e:
            print(f"\n  ✗ KB export failed: {_e}\n"); sys.exit(1)
        return

    if args.kb_import:
        try:
            p = Path(args.kb_import).expanduser().resolve()
            if not p.exists():
                print(f"\n  ✗ KB import: file not found: {p}\n"); sys.exit(1)
            blob = p.read_bytes()
            try:
                dump = json.loads(zlib.decompress(blob).decode("utf-8"))
            except Exception:
                dump = json.loads(blob.decode("utf-8"))
            res = _kb_import_dict(dump, mode=args.kb_import_mode)
            try: _kb_cache_invalidate()
            except Exception: pass
            print(f"\n  ✓ KB import ({args.kb_import_mode}): "
                  f"imported={res['imported']} skipped={res['skipped']} "
                  f"errors={res['errors']} totalAfter={res['totalAfter']} "
                  f"(schema v{res['schemaVersion']})\n")
        except Exception as _e:
            print(f"\n  ✗ KB import failed: {_e}\n"); sys.exit(1)
        return

    # ── Normal startup ─────────────────────────────────────────
    # ── LICENSE ENFORCEMENT ───────────────────────────────────
    print()
    print("  ╔══════════════════════════════════════════════════════════════╗")
    print(f"  ║  BUTLER AI SERVER  v{VERSION:<42}║")
    print("  ║  Copyright (c) 2025 Shawn Jan. All Rights Reserved.         ║")
    print("  ╠══════════════════════════════════════════════════════════════╣")
    print("  ║  PROPRIETARY & CONFIDENTIAL SOFTWARE                         ║")
    print("  ║  Unauthorized copying, distribution, reverse engineering,    ║")
    print("  ║  modification or commercial use is strictly prohibited.      ║")
    print("  ║  Violators will be prosecuted under copyright law.           ║")
    print("  ║  License: Proprietary  ·  See LICENSE.txt                    ║")
    print("  ║  Contact: andrejsladkovic1992@gmail.com                       ║")
    print("  ╚══════════════════════════════════════════════════════════════╝")
    print()
    
    # Write tamper-evidence marker next to executable
    try:
        import hashlib, pathlib
        exe_path = pathlib.Path(__file__).resolve()
        src_hash = hashlib.sha256(exe_path.read_bytes()).hexdigest()[:16]
        marker = exe_path.parent / ".butler_license"
        marker.write_text(
            f"Butler AI Server v{VERSION}\n"
            f"Copyright (c) 2025 Shawn Jan\n"
            f"File: {exe_path.name}\n"
            f"Hash: {src_hash}\n"
            f"Licensed to: End User (personal use only)\n"
            f"Restrictions: No redistribution, modification, or commercial use\n"
        )
    except: pass

    # Python version guard - exit cleanly with download link
    _CR = "\033[38;2;255;61;92m"; _CY = "\033[38;2;0;200;245m"; _RS = "\033[0m"
    if sys.version_info < (3, 10):
        print()
        pv = sys.version.split()[0]
        print(f"  {_CR}╭{'─'*50}╮{_RS}")
        print(f"  {_CR}│{_RS}  Python {pv} detected{' '*(50 - 12 - len(pv))}{_CR}│{_RS}")
        print(f"  {_CR}│{_RS}  Butler AI requires Python 3.10 or newer.    {_CR}│{_RS}")
        print(f"  {_CR}│{_RS}  Download: {_CY}https://python.org{_RS}               {_CR}│{_RS}")
        print(f"  {_CR}╰{'─'*50}╯{_RS}")
        print()
        if IS_WINDOWS and sys.stdin and sys.stdin.isatty():
            os.system("pause")
        sys.exit(1)

    _MT = "\033[38;2;120;170;200m"; _DM = "\033[38;2;28;61;82m"
    _G  = "\033[38;2;0;232;122m"

    def _step(n, total, msg):
        print(f"  {_DM}[{n}/{total}]{_RS}  {_MT}{msg}{_RS}")

    _step(1, 3, "Checking dependencies…")
    _kill_old_instances()

    # ── Auto-lock migration: clear old pairing state if upgrading ──
    # Previous versions required manual pairing codes. This version auto-locks
    # to the first device that connects. Clear any stale lock from old version.
    if _gs("locked_device") and not _gs("auto_lock_version"):
        _log("Migrating to auto-lock mode — clearing old pairing state", "info")
        _ss("locked_device", None)
        _ss("paired_at", None)
        _ss("auto_lock_version", VERSION)
        _ss("pairing_code", _gen_code())  # fresh reset code
    if not _gs("auto_lock_version"):
        _ss("auto_lock_version", VERSION)

    if not _gs("pairing_code"): _ss("pairing_code", _gen_code())

    _step(2, 3, "Detecting network & port…")
    saved_port = _gs("server_port")
    prefer     = args.port or (int(saved_port) if saved_port else None)
    port       = _free_port(prefer)
    _ss("server_port", port)

    ip      = get_ip()
    all_ips = get_all_ips()
    code    = _gs("pairing_code")
    locked  = _gs("locked_device")
    # [v19 FIX-14] Quick Ollama probe before banner renders
    # Without this, banner always shows 'Starting in background' even when
    # Ollama is already running from a previous session.
    try:
        with _urllib_req.urlopen(f"{OLLAMA_URL}/api/tags", timeout=2) as _probe:
            if _probe.status == 200:
                _pd = json.loads(_probe.read())
                _pn = [x["name"] for x in _pd.get("models", [])]
                with _ol_cache_lock:
                    _ol_cache["ok"]     = True
                    _ol_cache["models"] = _pn
                    _ol_cache["ts"]     = time.time()
                    if _pn and not _ol_cache.get("model"):
                        _ol_cache["model"] = _select_lightest(_pn) or _pn[0]
    except Exception:
        pass   # Ollama not running — banner will show 'Starting in background'
    ol_ok   = _ol_ok()
    model   = _ol_model() if ol_ok else ""

    _step(3, 3, "Applying firewall rule…")
    # Add firewall rule
    _fw(port, enabled=not args.no_firewall)

    # FIX v19.0.1: run plain HTTP on the private LAN by default.
    # The previous build generated a self-signed cert and wrapped the socket,
    # but the QR payload and app-facing URLs still advertised http://.  That
    # makes the phone scan succeed while every follow-up HTTP request fails.
    # HMAC/session-token auth remains active; TLS can be reintroduced only when
    # the mobile client consumes scheme=https plus a cert fingerprint from QR.

    # ── Animated Robot Splash Screen ─────────────────────────────
    def _splash():
        """Cinematic 3D-style ASCII robot splash with smooth frame transitions."""
            # FIX L: removed unused shutil import here

        C = {
            "teal":   "\033[38;2;0;229;255m",
            "green":  "\033[38;2;0;255;136m",
            "amber":  "\033[38;2;255;184;0m",
            "dim":    "\033[38;2;60;90;110m",
            "bright": "\033[38;2;220;240;255m",
            "red":    "\033[38;2;255;51;102m",
            "reset":  "\033[0m",
            "bold":   "\033[1m",
            "clear":  "\033[2J\033[H",
        }
        T, G, A, D, B, R = C["teal"], C["green"], C["amber"], C["dim"], C["bright"], C["reset"]

        FRAMES = [
            # Frame 0 — dormant / powering on
            [
                f"{D}╭──────────────────────────────────────────────────╮{R}",
                f"{D}│{R}                                                  {D}│{R}",
                f"{D}│{R}      {T}  ╔═══════════════════════════╗  {R}         {D}│{R}",
                f"{D}│{R}      {T}  ║  {B}◈  BUTLER AI  SYSTEM  ◈{T}  ║  {R}         {D}│{R}",
                f"{D}│{R}      {T}  ╚═══════════════════════════╝  {R}         {D}│{R}",
                f"{D}│{R}                                                  {D}│{R}",
                f"{D}│{R}           {D}  ┌─────────────────┐  {R}             {D}│{R}",
                f"{D}│{R}           {D}  │   · · · · · ·   │  {R}             {D}│{R}",
                f"{D}│{R}           {D}  │   · · · · · ·   │  {R}             {D}│{R}",
                f"{D}│{R}           {D}  └─────────────────┘  {R}             {D}│{R}",
                f"{D}│{R}                 {D}  ───────────  {R}                {D}│{R}",
                f"{D}│{R}           {D}  ┌───────────────────┐  {R}            {D}│{R}",
                f"{D}│{R}           {D}  │  · · · · · · · ·  │  {R}            {D}│{R}",
                f"{D}│{R}           {D}  └───────────────────┘  {R}            {D}│{R}",
                f"{D}│{R}                 {D}  ░░  BOOT…  ░░  {R}               {D}│{R}",
                f"{D}╰──────────────────────────────────────────────────╯{R}",
            ],
            # Frame 1 — eyes ignite
            [
                f"{D}╭──────────────────────────────────────────────────╮{R}",
                f"{D}│{R}                                                  {D}│{R}",
                f"{D}│{R}      {T}  ╔═══════════════════════════╗  {R}         {D}│{R}",
                f"{D}│{R}      {T}  ║  {B}◈  BUTLER AI  SYSTEM  ◈{T}  ║  {R}         {D}│{R}",
                f"{D}│{R}      {T}  ╚═══════════════════════════╝  {R}         {D}│{R}",
                f"{D}│{R}                                                  {D}│{R}",
                f"{D}│{R}           {T}  ┌─────────────────┐  {R}             {D}│{R}",
                f"{D}│{R}           {T}  │   {G}◉{D}  · · ·  {G}◉{T}   │  {R}             {D}│{R}",
                f"{D}│{R}           {T}  │   {D}· · · · · ·{T}   │  {R}             {D}│{R}",
                f"{D}│{R}           {T}  └─────────────────┘  {R}             {D}│{R}",
                f"{D}│{R}                 {T}  ───────────  {R}                {D}│{R}",
                f"{D}│{R}           {T}  ┌───────────────────┐  {R}            {D}│{R}",
                f"{D}│{R}           {T}  │  {D}· · · · · · · ·{T}  │  {R}            {D}│{R}",
                f"{D}│{R}           {T}  └───────────────────┘  {R}            {D}│{R}",
                f"{D}│{R}                 {A}  ▓▓  INIT…  ▓▓  {R}               {D}│{R}",
                f"{D}╰──────────────────────────────────────────────────╯{R}",
            ],
            # Frame 2 — fully online
            [
                f"{T}╭──────────────────────────────────────────────────╮{R}",
                f"{T}│{R}                                                  {T}│{R}",
                f"{T}│{R}      {T}  ╔═══════════════════════════╗  {R}         {T}│{R}",
                f"{T}│{R}      {T}  ║  {B}◈  BUTLER AI  SYSTEM  ◈{T}  ║  {R}         {T}│{R}",
                f"{T}│{R}      {T}  ╚═══════════════════════════╝  {R}         {T}│{R}",
                f"{T}│{R}                                                  {T}│{R}",
                f"{T}│{R}           {T}  ┌─────────────────┐  {R}             {T}│{R}",
                f"{T}│{R}           {T}  │  {G}◉{T} ─── {A}▬▬▬{T} ─── {G}◉{T}  │  {R}             {T}│{R}",
                f"{T}│{R}           {T}  │  {D}·{T} ─── {A}───{T} ─── {D}·{T}  │  {R}             {T}│{R}",
                f"{T}│{R}           {T}  └────────┬────────┘  {R}             {T}│{R}",
                f"{T}│{R}                   {T}│{R}                              {T}│{R}",
                f"{T}│{R}           {T}  ┌──┴─────────────────┐  {R}            {T}│{R}",
                f"{T}│{R}           {T}  │  {G}■ ■ ■ ■ ■ ■ ■ ■{T}  │  {R}            {T}│{R}",
                f"{T}│{R}           {T}  └───────────────────┘  {R}            {T}│{R}",
                f"{T}│{R}                 {G}  ██  ONLINE  ██  {R}               {T}│{R}",
                f"{T}╰──────────────────────────────────────────────────╯{R}",
            ],
        ]

        delays = [0.22, 0.20, 0.28]
        try:
            print(C["clear"], end="", flush=True)
            for i, frame in enumerate(FRAMES):
                if i > 0:
                    print(f"\033[{len(frame)}A", end="", flush=True)
                for line in frame:
                    print(line)
                time.sleep(delays[i])
            # Final hold — let the ONLINE frame breathe
            time.sleep(0.45)
            # Wipe upward, line by line
            for _ in range(len(FRAMES[-1])):
                print("\033[1A\033[2K", end="", flush=True)  # FIX M-1: was bare f-string
                time.sleep(0.016)
        except Exception:
            pass  # Never crash on splash

    _splash()

    # ── Startup banner ──────────────────────────────────────────
    _C = {
        "cyan":   "\033[38;2;0;200;245m",
        "cyan2":  "\033[38;2;0;234;255m",
        "green":  "\033[38;2;0;232;122m",
        "amber":  "\033[38;2;255;194;68m",
        "red":    "\033[38;2;255;61;92m",
        "blue":   "\033[38;2;61;130;255m",
        "dim":    "\033[38;2;28;61;82m",
        "muted":  "\033[38;2;120;170;200m",
        "white":  "\033[38;2;200;232;250m",
        "bold":   "\033[1m",
        "reset":  "\033[0m",
    }
    CY, CY2, GR, AM = _C["cyan"], _C["cyan2"], _C["green"], _C["amber"]
    DM, MT, WH, BD, RS = _C["dim"], _C["muted"], _C["white"], _C["bold"], _C["reset"]

    W = 68

    def _bar(char="─", col=DM):    return col + char * W + RS
    def _blank(col=DM):             return col + "│" + RS + " " * (W - 2) + col + "│" + RS
    def _row(label, value, vcol=WH, lcol=MT):
        pad = W - 4 - len(label) - len(value)
        return (DM + "│  " + RS + lcol + label + RS + " " * (pad - 1) + vcol + value + RS + "  " + DM + "│" + RS)
    def _section(title, col=CY):
        pad = W - 4 - len(title)
        return DM + "├" + "─" * 2 + RS + col + BD + " " + title + " " + RS + DM + "─" * (pad - 1) + "┤" + RS

    print()
    print(DM + "╭" + "─" * W + "╮" + RS)
    print(_blank())
    title_str = "BUTLER AI  ·  DESKTOP SERVER"
    ver_str   = f"v{VERSION}"
    pad = W - 2 - len(title_str) - len(ver_str)
    print(DM + "│  " + RS + CY + BD + title_str + RS + " " * pad + MT + ver_str + RS + DM + "  │" + RS)
    print(DM + "│  " + RS + MT + "100% local  ·  zero telemetry  ·  zero cloud" + " " * (W - 48) + DM + "│" + RS)
    print(_blank())
    print(DM + "├" + "─" * W + "┤" + RS)
    print(_blank())

    # Connection info
    _ol_status  = (GR + "ONLINE  —  " + (model or "").split(":")[0]) if ol_ok else (AM + "Starting in background…")
    _dev_status = (GR + "LOCKED  —  " + ((locked[:28] + "…") if locked and len(locked) > 28 else (locked or ""))) if locked else (CY2 + "OPEN  —  scan QR to pair")
    _adm_status = (GR + "YES  —  full system access") if _is_admin() else (AM + "NO  —  some features limited")

    print(_row("IP ADDRESS", ip,                                    vcol=CY2))
    for alt in all_ips:
        if alt != ip: print(_row("ALT IP    ", alt,                 vcol=MT))
    print(_row("PORT      ", str(port),                             vcol=WH))
    print(_row("URL       ", f"http://{ip}:{port}",                 vcol=CY))
    print(_row("PAIR CODE ", code,                                  vcol=CY2))
    print(_row("DEVICE    ", _dev_status,                           vcol=""))
    print(_row("OLLAMA AI ", _ol_status,                            vcol=""))
    print(_row("ADMIN     ", _adm_status,                           vcol=""))
    print(_row("APP-SIG   ", f"{APP_SIG_MODE.upper()}  (env APP_SIG_MODE={APP_SIG_MODE} | set =strict once all devices use v5.0+)", vcol=(GR if APP_SIG_MODE == "strict" else AM)))
    print(_row("PYTHON    ", platform.python_version(),             vcol=MT))
    print(_blank())

    # Endpoints
    print(DM + "├" + "─" * 2 + RS + CY + BD + " ENDPOINTS " + RS + DM + "─" * (W - 13) + "┤" + RS)
    print(_blank())
    def _ep(method, path, desc):
        m_col = CY if method == "GET" else GR
        m_pad = 5 - len(method)
        d_pad = W - 4 - len(method) - m_pad - 1 - len(path) - 2 - len(desc)
        return (DM + "│  " + RS + m_col + BD + method + RS + " " * m_pad
                + WH + path + RS + " " * max(1, d_pad) + MT + desc + RS + DM + "  │" + RS)
    print(_ep("GET",  "/api/status",              "Server health & uptime"))
    print(_ep("GET",  "/api/metrics",             "CPU / RAM / Disk live stats"))
    print(_ep("GET",  "/api/processes",           "Running process list"))
    print(_ep("GET",  "/api/requirements",        "Package status"))
    print(_ep("POST", "/api/execute",             "Run Python script"))
    print(_ep("POST", "/api/butler/chat",         "Ollama AI conversation"))
    print(_ep("GET",  "/api/server_log",          "Live activity log"))
    print(_ep("GET",  "/api/pc_scripts/list",     "Script library index"))
    print(_ep("POST", "/api/pc_scripts/save",     "Save script to library"))
    print(_ep("POST", "/api/pc_scripts/run",      "Execute library script"))
    print(_ep("POST", "/api/pc_scripts/delete",   "Remove library script"))
    print(_ep("POST", "/api/pc_scripts/export",   "Export full script library as JSON"))
    print(_ep("POST", "/api/pc_scripts/import",   "Import scripts from a library JSON payload"))
    print(_ep("POST", "/api/receive_file",        "Phone → PC file transfer"))
    print(_ep("POST", "/pair",                    "Pair mobile device"))
    print(_ep("POST", "/reconnect",               "Refresh auth token"))
    print(_blank())
    print(DM + "├" + "─" * W + "┤" + RS)
    print(_blank())
    print(DM + "│  " + RS + GR + "✦" + RS + MT + "  Google Play Certified  ·  Everyone" + " " * (W - 40) + DM + "│" + RS)
    print(DM + "│  " + RS + CY + "✦" + RS + MT + "  github.com/shawnjan-cmd/butler-ai" + " " * (W - 38) + DM + "│" + RS)
    print(DM + "│  " + RS + CY + "✦" + RS + MT + "  shawnjan-cmd.github.io/butler-ai  (Privacy Policy)" + " " * (W - 55) + DM + "│" + RS)
    print(_blank())
    print(DM + "╰" + "─" * W + "╯" + RS)
    print()

    if not args.no_qr: _qr(ip, port)

    # Start UDP beacon
    threading.Thread(target=_beacon, args=(ip, port), daemon=True).start()
    print(f"  {DM}┄{RS} {MT}UDP Beacon{RS}   broadcasting on :{BEACON_PORT}  {DM}(app auto-discovers){RS}")

    # [v19] Ollama auto-manager moved below _db_init() — see below
    print(f"  {DM}┄{RS} {MT}HTTP Server{RS}  {CY}http://{ip}:{port}{RS}")
    print(f"  {DM}┄{RS} {MT}Stop{RS}         Ctrl+C")
    print()

    # ── [v19 FIX-15] Structured startup sequence with log visibility ──────────
    log.info(f"[STARTUP] Butler AI Server v{VERSION} starting...")
    log.info(f"[STARTUP] Python {platform.python_version()} | {platform.system()} {platform.release()}")
    log.info(f"[STARTUP] Server port: {port} | IP: {ip}")
    # Init DB and shared file dir
    _db_init()
    _init_encryption()           # derive AES-128-GCM key from HMAC_SECRET (in-memory only)
    _start_migration_in_background()  # encrypt any existing plaintext rows in the DB
    SHARE_DIR.mkdir(parents=True, exist_ok=True)
    log.info("[STARTUP] Database initialised ✓")

    # self-healing HTTP: Start SIGMA-NET auto-crawler in background
    # Start Ollama status cache refresher (every 10s, no impact on HTTP)
    threading.Thread(target=_ol_cache_refresh, daemon=True, name="ollama-cache").start()
    # Start IP cache refresher (every 60s)
    threading.Thread(target=_refresh_ip_cache, daemon=True, name="ip-cache").start()
    # PERF: preflight is informational-only — run in background, don't block HTTP start
    threading.Thread(target=_startup_preflight, daemon=True, name="preflight").start()
    _auto_heal_startup()   # keep sync: resets stuck DB queue items before requests arrive
    # [v19 FIX-2] _start_ollama_auto() now runs AFTER _db_init() + _auto_heal_startup()
    # so the DB is fully ready before Ollama's background thread calls _gs()/_ss()
    _start_ollama_auto()
    _ol_txt = (GR + "ONLINE  —  " + model + RS) if ol_ok else (AM + "starting in background…" + RS)
    log.info(f"[STARTUP] Ollama auto-manager started: {_ol_txt.replace(chr(27)+'[0m','').replace(chr(27),'')}")
    threading.Thread(target=_sigma_loop, daemon=True, name="sigma").start()
    # ── DIGITAL TWIN: restore persisted baseline + start monitor threads ──
    _twin_restore_baseline()
    _twin_start_if_needed()
    log.info("[TWIN] Digital Twin security engine initialized")

    threading.Thread(target=_watchdog, daemon=True, name="watchdog").start()
    threading.Thread(target=_db_sweep_loop, daemon=True, name="db-sweeper").start()  # Fix: orphaned connection sweeper
    _guard_start_watchdog()  # PERF_GUARD: busy-leak + pool health + timing checks
    # STARTUP API GUARD: probes every API used at boot and self-heals broken ones
    threading.Thread(target=_startup_api_guard, daemon=True, name="startup-api-guard").start()
    # Start the shared CPU/RAM snapshot updater (every 5s, non-blocking reads)
    threading.Thread(target=_sys_snapshot_update, daemon=True, name="sys-snapshot").start()
    # Heal 15: pre-load model into VRAM so first message is instant
    threading.Thread(target=_warmup_model, daemon=True, name="warmup").start()
    # Perf E: detect CPU-only inference and warn if GPU not available
    threading.Thread(target=_check_gpu_inference, daemon=True, name="gpu-check").start()
    # Trick 20: scheduled pre-load at 08:55 for 09:00 peak readiness
    threading.Thread(target=_scheduled_preload, daemon=True, name="preload-scheduler").start()
    # PERF: script seeding and NEXUS BRAIN start in background — HTTP doesn't need them
    def _deferred_init():
        """Heavy one-time init that doesn't block the HTTP server from accepting connections."""
        _pc_scripts_init()
        _seed_builtin_scripts()   # seeds 200+ scripts on first launch, no-op if already present
        try: _seed_public_kb()    # v19.0.18: queue ~80 public-domain/permissive script-knowledge URLs
        except Exception as _ske: log.warning(f"[KB-SEED] {_ske}")
        try: _nb_start()
        except Exception as _nbe: log.warning(f"[NEXUS] Start failed: {_nbe}")
    threading.Thread(target=_deferred_init, daemon=True, name="deferred-init").start()
    log.info("SIGMA-NET auto-learning crawler started")

    # Self-healing HTTP - restarts on crash, escalates port on PermissionError
    _httpd    = [None]
    _cur_port = [port]

    def _run_http():
        fail_streak = 0
        while True:
            p = _cur_port[0]
            try:
                # ThreadingHTTPServer: each request handled in its own thread
                # Heartbeat pings NEVER wait for slow requests (execute, crawl, chat)
                from http.server import ThreadingHTTPServer
                # FIX v19.0.1: bind on all IPv4 interfaces and only advertise
                # the best LAN IP in QR/status.  Binding to one detected LAN IP
                # breaks localhost probes, multi-NIC machines, IP changes, and
                # some hotspot/VPN configurations.
                _bind_ip = "0.0.0.0"
                _httpd[0] = ThreadingHTTPServer((_bind_ip, p), H)
                _httpd[0].timeout = 30
                _httpd[0].daemon_threads = True  # worker threads die with server
                # FIX v19.0.1: do not wrap with TLS unless the mobile app also
                # receives and honors https/cert-pinning data from QR.
                # FIX M-5: _tls_active intentionally False — TLS disabled in v19.
                # Removed as runtime variable; TLS re-enable requires code change, not flag flip.
                # TCP socket tuning — applied once at server start
                try:
                    import socket as _sk
                    _sock = _httpd[0].socket
                    # TCP_NODELAY: disable Nagle's algorithm.
                    # Without this the kernel buffers outgoing data for up to 40ms
                    # hoping to coalesce it with more data. For small JSON responses
                    # (status, ping, metrics) this adds a 40ms artificial delay on
                    # every single LAN request. Most impactful single change.
                    _sock.setsockopt(_sk.IPPROTO_TCP, _sk.TCP_NODELAY, 1)
                    # SO_KEEPALIVE: detect dead connections, prevent WinError 10053
                    _sock.setsockopt(_sk.SOL_SOCKET, _sk.SO_KEEPALIVE, 1)
                    if hasattr(_sk, 'TCP_KEEPIDLE'):    # Linux
                        _sock.setsockopt(_sk.IPPROTO_TCP, _sk.TCP_KEEPIDLE, 10)
                    if hasattr(_sk, 'TCP_KEEPINTVL'):   # Linux
                        _sock.setsockopt(_sk.IPPROTO_TCP, _sk.TCP_KEEPINTVL, 5)
                    if hasattr(_sk, 'TCP_KEEPCNT'):     # Linux
                        _sock.setsockopt(_sk.IPPROTO_TCP, _sk.TCP_KEEPCNT, 3)
                    # SO_REUSEPORT (Linux): kernel load-balances new connections
                    # across threads, reducing accept() lock contention.
                    if hasattr(_sk, 'SO_REUSEPORT'):
                        try: _sock.setsockopt(_sk.SOL_SOCKET, _sk.SO_REUSEPORT, 1)
                        except OSError: pass  # not supported on all Linux kernels
                except Exception: pass  # Never let tuning crash the server
                fail_streak = 0
                log.info(f"HTTP server listening on 0.0.0.0:{p}; advertise http://{get_ip()}:{p}")
                _httpd[0].serve_forever()
            except PermissionError:
                fail_streak += 1
                log.warning(f"Permission denied on port {p} - trying next port")
                _cur_port[0] = _free_port(p + 1)
                _ss("server_port", _cur_port[0])
                time.sleep(1)
            except OSError as e:
                fail_streak += 1
                if "10048" in str(e) or "98" in str(e) or "Address already in use" in str(e):
                    log.warning(f"Port {p} busy - killing blocker")
                    killed = _kill_process_on_port(p, force=True)
                    if not killed or fail_streak >= 5:
                        _cur_port[0] = _free_port(p + 1)
                        _ss("server_port", _cur_port[0])
                        fail_streak = 0
                    time.sleep(1)
                else:
                    log.error(f"HTTP error: {e}"); time.sleep(3)
            except Exception as e:
                log.error(f"HTTP crashed ({e}) - restarting in 3s"); time.sleep(3)

    threading.Thread(target=_run_http, daemon=True, name="http").start()

    # Wait a moment then verify HTTP is actually up
    time.sleep(1.5)
    _verified = False
    for _a in range(6):
        try:
            import socket as _s
            _p = _s.create_connection(("127.0.0.1", _cur_port[0]), timeout=1); _p.close()
            _verified = True; break
        except OSError:
            import time as _t; _t.sleep(0.5)
    if _verified:
        port = _cur_port[0]
        _ss("server_port", port)  # Persist port so QR always shows current port
        print(f"  {GR}✓{RS}  Server reachable on port {port}")
    else:
        print(f"  {AM}⚠{RS}  Server not responding — check Firewall / Antivirus")

    # ── One shared tray icon for the whole run, regardless of whether the
    # Tk dashboard or the headless path ends up being used. root_holder lets
    # the tray's "Show Dashboard" / "Quit" reach the Tk window once it exists.
    _root_holder = {"root": None}
    _shutdown_event = threading.Event()
    _tray = _butler_start_tray_icon(get_ip, lambda: int(_gs("server_port") or _cur_port[0]),
                                     _shutdown_event, _root_holder)
    _gui["_tray_holder"] = _root_holder
    if _tray:
        log.info("Tray icon active — right-click it for Dashboard / Logs / Quit")

    # Launch GUI or run headless
    if not args.no_qr and HAS_TK:
        try:
            ip = get_ip()
            port = int(_gs("server_port") or _cur_port[0])
            root = _build_gui(ip, port)
            if root:
                _root_holder["root"] = root
                root.mainloop()
                if _tray:
                    try: _tray.stop()
                    except Exception: pass
                return
        except tk.TclError as e:
            log.warning(f"GUI unavailable ({e}) - running headless")
        except Exception as e:
            log.warning(f"GUI error ({e}) - running headless")

    # Headless fallback — also covers --windowed/no-console builds, which is
    # exactly where a tray icon matters most (no GUI, no console, but the
    # server is very much alive and needs a visible, professional presence).
    log.info("Running in headless mode - all API features active")
    ip = get_ip()
    port = int(_gs("server_port") or _cur_port[0])
    log.info(f"Connect to: http://{ip}:{port}")
    if _gs("locked_device"):
        log.info("Locked to device — waiting for reconnect")
    else:
        log.info("OPEN — first device to connect will auto-lock")
    log.info(f"Reset code (for unpairing only): {_gs('pairing_code')}")
    log.info(f"Logs: {BUTLER_LOG_PATH}")
    if not _tray:
        log.info("Press Ctrl+C to stop")

    try:
        while not _shutdown_event.is_set():
            _shutdown_event.wait(timeout=10)
    except KeyboardInterrupt:
        pass
    finally:
        log.info("Server stopped. Goodbye!")
        try:
            if _tray: _tray.stop()
        except Exception: pass

if __name__ == "__main__":
    try:
        main()
    except Exception:
        print("\n" + "=" * 60)
        print("  BUTLER AI SERVER - FATAL ERROR")
        print("=" * 60)
        import traceback
        traceback.print_exc()
        print("=" * 60)
        try: input("\n  Press Enter to exit...")
        except: time.sleep(15)
